// NATE & HVAC Excellence -- 749 Preguntas -- Maestro HVACR | maestrohvacr.com
// Categorias: NATE_FUNDAMENTOS (100), NATE_AIRE_HEATPUMP (100), NATE_COMERCIAL (100), NATE_DIAGNOSTICO (99), NATE_INDUSTRIAL (350)
// ~38 preguntas por quiz (150/4)

var NATE_QUESTIONS = [

  // -- Fundamentos y Electricidad (1-100) --
  { id:"nate_1", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuántos BTU se requieren para cambiar 5 libras de hielo a 32°F en agua a 32°F?", opciones:["144 BTU", "720 BTU", "480 BTU", "1200 BTU"], respuesta_correcta:1, explicacion:"El calor latente de fusión es 144 BTU por libra. 144 BTU/lb * 5 lbs = 720 BTU." , question: "How many BTUs are required to change 5 pounds of ice at 32 degrees F into water at 32 degrees F?", options: ["144 BTU", "720 BTU", "480 BTU", "1200 BTU"], explanation: "The latent heat of fusion is 144 BTU per pound. 144 BTU/lb x 5 lbs = 720 BTU." },
  { id:"nate_2", categoria:"NATE_FUNDAMENTOS", pregunta:"Después de colocar un candado y etiqueta en el desconectador principal, ¿cuál es el paso obligatorio según OSHA antes de tocar un componente eléctrico?", opciones:["Verificar con un detector de proximidad", "Intentar arrancar el equipo para confirmar energía cero", "Llamar al supervisor", "Cortar los cables con pinzas aisladas"], respuesta_correcta:1, explicacion:"El protocolo LOTO exige la 'verificación de aislamiento', intentando encender el equipo para asegurar que no hay circuitos derivados alimentándolo." , question: "After placing a lock and tag on the main disconnect, what is the mandatory step per OSHA before touching any electrical component?", options: ["Verify with a proximity detector", "Attempt to start the equipment to confirm zero energy", "Call the supervisor", "Cut the wires with insulated pliers"], explanation: "The LOTO protocol requires 'isolation verification' by attempting to energize the equipment to ensure no bypass circuits are feeding it." },
  { id:"nate_3", categoria:"NATE_FUNDAMENTOS", pregunta:"En un sistema con R-410A, si la temperatura de saturación en el evaporador es de 45°F y la línea de succión marca 47°F, ¿qué indica este sobrecalentamiento (Superheat)?", opciones:["Sistema operando con alta eficiencia", "Inundación de líquido hacia el compresor (Liquid Slugging)", "Carga insuficiente de refrigerante", "Restricción en la línea de succión"], respuesta_correcta:1, explicacion:"Un sobrecalentamiento de solo 2°F es peligrosamente bajo; cualquier fluctuación enviará refrigerante líquido al compresor." , question: "In an R-410A system, if the saturation temperature at the evaporator is 45 degrees F and the suction line reads 47 degrees F, what does this superheat indicate?", options: ["System operating at high efficiency", "Liquid slugging toward the compressor", "Insufficient refrigerant charge", "Restriction in the suction line"], explanation: "A superheat of only 2 degrees F is dangerously low; any fluctuation will send liquid refrigerant to the compressor." },
  { id:"nate_4", categoria:"NATE_FUNDAMENTOS", pregunta:"Al realizar vacío, el vacuómetro se detiene en 1200 micrones y, tras cerrar las válvulas de la bomba, la presión sube rápidamente a 2500 micrones y se estabiliza. ¿Qué indica esto?", opciones:["Hay una fuga en el sistema", "Hay humedad o contaminantes en el sistema", "La bomba de vacío necesita cambio de aceite", "El vacuómetro está descalibrado"], respuesta_correcta:1, explicacion:"Si sube y se estabiliza, es humedad evaporándose. Si subiera sin detenerse hasta la presión atmosférica, sería una fuga." , question: "While pulling a vacuum, the micron gauge stops at 1200 microns and, after closing the pump valves, the pressure rises quickly to 2500 microns and stabilizes. What does this indicate?", options: ["There is a leak in the system", "There is moisture or contaminants in the system", "The vacuum pump needs an oil change", "The micron gauge is out of calibration"], explanation: "If the pressure rises and stabilizes, it is moisture evaporating. If it rose continuously to atmospheric pressure, it would be a leak." },
  { id:"nate_5", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Por qué no se debe usar oxígeno para presurizar un sistema en busca de fugas?", opciones:["Porque el oxígeno es muy caro", "Porque las moléculas de oxígeno son muy grandes", "Porque puede causar una explosión al mezclarse con aceite", "Porque el oxígeno daña el cobre"], respuesta_correcta:2, explicacion:"El oxígeno a alta presión mezclado con aceite mineral o POE es altamente inflamable y explosivo." , question: "Why should oxygen never be used to pressurize a system when searching for leaks?", options: ["Because oxygen is very expensive", "Because oxygen molecules are too large", "Because it can cause an explosion when mixed with oil", "Because oxygen damages copper"], explanation: "Oxygen at high pressure mixed with mineral oil or POE is highly flammable and explosive." },
  { id:"nate_6", categoria:"NATE_FUNDAMENTOS", pregunta:"Un motor de condensador PSC (Permanent Split Capacitor) intenta arrancar, zumba y se apaga por térmico. El capacitor mide su capacitancia nominal. ¿Qué debe revisar después?", opciones:["Cambiar el contactor", "Resistencia de los devanados y libertad de giro del eje", "Aumentar el tamaño del capacitor", "Revisar el termostato"], respuesta_correcta:1, explicacion:"Si el capacitor está bien, el problema es mecánico (baleros trabados) o eléctrico (bobinado abierto o en corto)." , question: "A PSC (Permanent Split Capacitor) condenser fan motor tries to start, hums, and shuts off on thermal overload. The capacitor measures at its rated capacitance. What should you check next?", options: ["Replace the contactor", "Winding resistance and freedom of shaft rotation", "Increase the capacitor size", "Check the thermostat"], explanation: "If the capacitor is good, the problem is mechanical (seized bearings) or electrical (open or shorted winding)." },
  { id:"nate_7", categoria:"NATE_FUNDAMENTOS", pregunta:"Un motor trifásico de 230V presenta las siguientes lecturas de voltaje entre fases: L1-L2: 228V, L2-L3: 232V, L1-L3: 220V. ¿Cuál es el porcentaje de desbalance de voltaje?", opciones:["1.2%", "2.3%", "3.5%", "5.0%"], respuesta_correcta:1, explicacion:"Promedio = 226.6V. Desviación máxima = 226.6 - 220 = 6.6V. (6.6 / 226.6) * 100 = 2.9%. Nota: Un desbalance mayor al 2% puede causar sobrecalentamiento excesivo." , question: "A three-phase 230V motor shows the following voltage readings between phases: L1-L2: 228V, L2-L3: 232V, L1-L3: 220V. What is the voltage imbalance percentage?", options: ["1.2%", "2.3%", "3.5%", "5.0%"], explanation: "Average = 226.6V. Maximum deviation = 226.6 - 220 = 6.6V. (6.6 / 226.6) x 100 = 2.9%. Note: An imbalance greater than 2% can cause excessive overheating." },
  { id:"nate_8", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es el método de recuperación más rápido para un sistema que contiene 80 libras de refrigerante?", opciones:["Vapor recovery", "Liquid recovery", "Push-Pull method", "Passive recovery"], respuesta_correcta:2, explicacion:"El método Push-Pull es el más eficiente para cargas grandes (más de 15 lbs) donde hay acceso fácil a las líneas de líquido y vapor." , question: "What is the fastest recovery method for a system containing 80 pounds of refrigerant?", options: ["Vapor recovery", "Liquid recovery", "Push-pull method", "Passive recovery"], explanation: "The push-pull method is the most efficient for large charges (over 15 lbs) where there is easy access to the liquid and vapor lines." },
  { id:"nate_9", categoria:"NATE_FUNDAMENTOS", pregunta:"En un diagrama de Mollier (Presión-Entalpía), ¿qué representa una línea perfectamente horizontal que se mueve de derecha a izquierda dentro de la campana de saturación?", opciones:["Compresión isentrópica", "Condensación a presión constante", "Expansión en la TXV", "Evaporación a temperatura constante"], respuesta_correcta:1, explicacion:"El movimiento horizontal hacia la izquierda indica pérdida de calor (entalpía) a presión constante, típico del proceso en el condensador." , question: "On a Mollier diagram (Pressure-Enthalpy), what does a perfectly horizontal line moving from right to left within the saturation dome represent?", options: ["Isentropic compression", "Condensation at constant pressure", "Expansion through the TXV", "Evaporation at constant temperature"], explanation: "Horizontal movement to the left indicates heat (enthalpy) rejection at constant pressure, typical of the process in the condenser." },
  { id:"nate_10", categoria:"NATE_FUNDAMENTOS", pregunta:"Si tus mangueras de manómetro no tienen válvulas de baja pérdida (low-loss fittings), ¿qué riesgo principal corres al desconectar la manguera de alta presión con el equipo encendido?", opciones:["Cargar aire al sistema", "Quemaduras por congelación (frostbite) y pérdida significativa de refrigerante", "Dañar las válvulas Schrader", "Provocar un cortocircuito en el presostato"], respuesta_correcta:1, explicacion:"La alta presión expulsa líquido a baja temperatura instantáneamente. Es una violación de seguridad y de normatividad ambiental." , question: "If your gauge hoses do not have low-loss fittings, what is the main risk when disconnecting the high-pressure hose with the equipment running?", options: ["Introducing air into the system", "Frostbite and significant refrigerant loss", "Damaging the Schrader valves", "Causing a short circuit in the pressure switch"], explanation: "The high pressure expels liquid at extremely low temperature instantly. This is a safety violation and an environmental regulation violation." },
  { id:"nate_11", categoria:"NATE_FUNDAMENTOS", pregunta:"Al cargar un sistema con una mezcla azeotrópica (serie 400), ¿por qué debe hacerse siempre en estado líquido?", opciones:["Porque el líquido es más pesado", "Para evitar el fraccionamiento de los componentes del refrigerante", "Porque el compresor lo comprime más fácil", "Para enfriar el aceite del compresor más rápido"], respuesta_correcta:1, explicacion:"Las mezclas tienen diferentes puntos de ebullición; si se carga vapor, se altera la composición química de la mezcla restante en el cilindro." , question: "When charging a system with a zeotropic blend (400 series), why must it always be charged in the liquid state?", options: ["Because liquid is heavier", "To prevent fractionation of the refrigerant components", "Because the compressor compresses it more easily", "To cool the compressor oil faster"], explanation: "Blends have different boiling points; if vapor is charged, the chemical composition of the remaining mixture in the cylinder is altered." },
  { id:"nate_12", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es el color estándar de un tanque de recuperación de refrigerante según la normativa internacional?", opciones:["Verde con hombros blancos", "Gris con la parte superior amarilla", "Azul claro", "Totalmente naranja"], respuesta_correcta:1, explicacion:"El cuerpo gris y tapa amarilla identifica universalmente un cilindro diseñado para recuperación, no para refrigerante virgen." , question: "What is the standard color of a refrigerant recovery cylinder per international standards?", options: ["Green with white shoulders", "Gray body with yellow top", "Light blue", "Entirely orange"], explanation: "The gray body and yellow top universally identify a cylinder designed for recovery, not for virgin refrigerant." },
  { id:"nate_13", categoria:"NATE_FUNDAMENTOS", pregunta:"Mides continuidad en un motor de ventilador y obtienes 'O.L' entre todos los cables y la carcasa, pero también 'O.L' entre el cable común y el de marcha. ¿Qué sucede?", opciones:["El motor está aterrizado", "El protector térmico interno está abierto", "El motor está en perfectas condiciones", "El multímetro está en la escala de Volts"], respuesta_correcta:1, explicacion:"Un 'O.L' entre bobinados (sin estar aterrizado) indica que el circuito interno está interrumpido, usualmente por el protector térmico por sobrecalentamiento." , question: "You measure continuity on a fan motor and get 'OL' between all wires and the housing, but also 'OL' between the common wire and the run wire. What is happening?", options: ["The motor is grounded", "The internal thermal protector is open", "The motor is in perfect condition", "The multimeter is set to the Volts scale"], explanation: "An 'OL' reading between windings (without being grounded) indicates that the internal circuit is interrupted, usually by the thermal protector due to overheating." },
  { id:"nate_14", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la ventaja principal de usar Nitrógeno con una traza de Helio o Hidrógeno para buscar fugas?", opciones:["Es más barato que el aire", "Las moléculas son más pequeñas y detectables por sensores electrónicos sensibles", "Limpia el aceite del sistema automáticamente", "Aumenta la capacidad de enfriamiento"], respuesta_correcta:1, explicacion:"El nitrógeno solo detecta fugas grandes por presión; el gas traza permite usar detectores electrónicos para fugas microscópicas." , question: "What is the main advantage of using nitrogen with a trace of helium or hydrogen to search for leaks?", options: ["It is cheaper than air", "The molecules are smaller and detectable by sensitive electronic sensors", "It automatically cleans the oil from the system", "It increases the cooling capacity"], explanation: "Nitrogen alone only detects large leaks by pressure; trace gas allows the use of electronic detectors for microscopic leaks." },
  { id:"nate_15", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Quién es la única persona autorizada para retirar un candado y etiqueta de seguridad (LOTO) en un centro de carga?", opciones:["El supervisor de obra", "El dueño del edificio", "La persona que instaló el candado", "Cualquier técnico con licencia"], respuesta_correcta:2, explicacion:"Por norma OSHA, solo el técnico que bloqueó el equipo puede desbloquearlo para garantizar su propia vida." , question: "Who is the only person authorized to remove a lockout/tagout (LOTO) lock and tag from a power panel?", options: ["The job supervisor", "The building owner", "The person who installed the lock", "Any licensed technician"], explanation: "Per OSHA standards, only the technician who locked out the equipment can remove the lock to ensure their own safety." },
  { id:"nate_16", categoria:"NATE_FUNDAMENTOS", pregunta:"Al medir una resistencia de 0.5 Ohms en un bobinado de motor grande, ¿por qué es crítico usar un multímetro con función de 'Relativo' (Delta)?", opciones:["Para medir voltios al mismo tiempo", "Para restar la resistencia de los cables de prueba", "Para aumentar el voltaje de la batería", "Para evitar choques eléctricos"], respuesta_correcta:1, explicacion:"En resistencias muy bajas, los cables del multímetro pueden marcar 0.2-0.3 Ohms, falseando la lectura real del bobinado." , question: "When measuring a resistance of 0.5 Ohms on a large motor winding, why is it critical to use a multimeter with a 'Relative' (Delta) function?", options: ["To measure volts at the same time", "To subtract the resistance of the test leads", "To increase the battery voltage", "To avoid electric shock"], explanation: "At very low resistances, the multimeter leads themselves can read 0.2-0.3 Ohms, falsifying the actual winding reading." },
  { id:"nate_17", categoria:"NATE_FUNDAMENTOS", pregunta:"En un sistema con TXV, si la carga térmica en el evaporador aumenta repentinamente, ¿qué acción toma la válvula?", opciones:["Se cierra para mantener la presión", "Se abre para aumentar el flujo de masa", "Se congela por el cambio de presión", "No hace nada, es fija"], respuesta_correcta:1, explicacion:"Al subir la carga, sube el Superheat; la TXV detecta esto y abre para inundar más el evaporador y mantener el SH constante." , question: "In a system with a TXV, if the thermal load on the evaporator suddenly increases, what action does the valve take?", options: ["It closes to maintain pressure", "It opens to increase mass flow", "It freezes due to the pressure change", "It does nothing; it is a fixed device"], explanation: "When the load increases, superheat rises; the TXV senses this and opens to flood more of the evaporator and maintain constant superheat." },
  { id:"nate_18", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la consecuencia de instalar un capacitor de 440V en un sistema que originalmente usaba uno de 370V (misma capacitancia)?", opciones:["El motor se quema por exceso de voltaje", "El capacitor explotará", "El sistema funcionará con mayor margen de seguridad", "El motor consumirá más amperaje"], respuesta_correcta:2, explicacion:"El voltaje en un capacitor es su capacidad de aislamiento. Puedes subir el voltaje, pero nunca bajarlo (ej. no poner uno de 370V donde va uno de 440V)." , question: "What is the consequence of installing a 440V capacitor in a system that originally used a 370V one (same capacitance)?", options: ["The motor will burn from excess voltage", "The capacitor will explode", "The system will operate with a greater safety margin", "The motor will draw more amperage"], explanation: "The voltage rating on a capacitor is its dielectric insulation capacity. You can go higher in voltage but never lower (e.g., never put a 370V where a 440V is needed)." },
  { id:"nate_19", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué sucede con la presión de un cilindro de R-410A si se deja en la caja de una camioneta a 110°F de temperatura ambiente?", opciones:["La presión baja", "La presión se mantiene igual", "La presión sube a aproximadamente 365 psig", "El refrigerante se descompone"], respuesta_correcta:2, explicacion:"Siguiendo la tabla PT, el R-410A es un refrigerante de alta presión; a 110°F la presión es crítica y peligrosa." , question: "What happens to the pressure of an R-410A cylinder if it is left in a truck bed at 110 degrees F ambient temperature?", options: ["The pressure drops", "The pressure stays the same", "The pressure rises to approximately 365 psig", "The refrigerant decomposes"], explanation: "Following the P-T chart, R-410A is a high-pressure refrigerant; at 110 degrees F the pressure is critical and dangerous." },
  { id:"nate_20", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Por qué no se debe llenar un tanque de recuperación a más del 80% de su capacidad volumétrica?", opciones:["Para ahorrar espacio", "Para permitir la expansión hidrostática del líquido con cambios de temperatura", "Para que no pese tanto", "Para cumplir con el seguro de la camioneta"], respuesta_correcta:1, explicacion:"El líquido no se comprime. Si el tanque está lleno al 100% y se calienta, la presión hidrostática lo hará explotar." , question: "Why should a recovery cylinder never be filled beyond 80% of its volumetric capacity?", options: ["To save space", "To allow for hydrostatic expansion of the liquid with temperature changes", "So it doesn't weigh too much", "To comply with truck insurance requirements"], explanation: "Liquid is incompressible. If the cylinder is 100% full and heats up, the hydrostatic pressure will cause it to explode." },
  { id:"nate_21", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un manómetro marca 0 psig a nivel del mar, ¿cuál es la presión absoluta (psia)?", opciones:["0 psia", "14.7 psia", "-14.7 psia", "29.92 psia"], respuesta_correcta:1, explicacion:"La presión absoluta es la presión manométrica + la presión atmosférica (14.7 psi a nivel del mar)." , question: "If a gauge reads 0 psig at sea level, what is the absolute pressure (psia)?", options: ["0 psia", "14.7 psia", "-14.7 psia", "29.92 psia"], explanation: "Absolute pressure equals gauge pressure plus atmospheric pressure (14.7 psi at sea level)." },
  { id:"nate_22", categoria:"NATE_FUNDAMENTOS", pregunta:"¿En qué parte del sistema es más probable encontrar una fuga si detectas manchas de aceite en el aislamiento de la línea de succión?", opciones:["En el condensador", "En las tuercas flare o soldaduras del evaporador", "En el filtro deshidratador", "En el presostato de alta"], respuesta_correcta:1, explicacion:"El refrigerante viaja con aceite; donde hay una fuga de gas, suele haber rastro de aceite." , question: "Where in the system is a leak most likely if you find oil stains on the suction line insulation?", options: ["At the condenser", "At the flare nuts or solder joints near the evaporator", "At the filter drier", "At the high-pressure switch"], explanation: "Refrigerant travels with oil; where there is a refrigerant leak, there is usually an oil residue trail." },
  { id:"nate_23", categoria:"NATE_FUNDAMENTOS", pregunta:"Un motor de 1/2 HP consume 5 Amperios a 120V con un factor de potencia de 0.85. ¿Cuál es la potencia real consumida en Watts?", opciones:["600 W", "510 W", "440 W", "705 W"], respuesta_correcta:1, explicacion:"Watts = Volts * Amps * Factor de Potencia. 120 * 5 * 0.85 = 510 Watts." , question: "A 1/2 HP motor draws 5 Amps at 120V with a power factor of 0.85. What is the actual power consumed in Watts?", options: ["600 W", "510 W", "440 W", "705 W"], explanation: "Watts = Volts x Amps x Power Factor. 120 x 5 x 0.85 = 510 Watts." },
  { id:"nate_24", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la función principal de un acumulador de succión?", opciones:["Almacenar líquido para la TXV", "Evitar que el refrigerante líquido llegue al compresor", "Filtrar la humedad", "Enfriar el aceite"], respuesta_correcta:1, explicacion:"El acumulador permite que el líquido se evapore antes de entrar al compresor, protegiéndolo de golpes de líquido." , question: "What is the primary function of a suction accumulator?", options: ["Store liquid for the TXV", "Prevent liquid refrigerant from reaching the compressor", "Filter moisture", "Cool the oil"], explanation: "The accumulator allows liquid to evaporate before entering the compressor, protecting it from liquid slugging." },
  { id:"nate_25", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Por qué es recomendable conectar el vacuómetro lo más lejos posible de la bomba de vacío?", opciones:["Para que no se llene de aceite", "Para medir la presión real del sistema y no la de la bomba", "Para evitar interferencia eléctrica", "Para que el técnico lo vea mejor"], respuesta_correcta:1, explicacion:"Cerca de la bomba siempre marcará menos micrones de los que realmente tiene el sistema debido a la succión inmediata." , question: "Why is it recommended to connect the micron gauge as far as possible from the vacuum pump?", options: ["So it doesn't fill with oil", "To measure the actual system pressure and not the pump's pressure", "To avoid electrical interference", "So the technician can see it better"], explanation: "Near the pump, it will always read fewer microns than the system actually has due to the immediate suction." },
  { id:"nate_26", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un sistema tiene un Superheat alto (30°F) y un Subcooling bajo (2°F), ¿cuál es el diagnóstico?", opciones:["Sobrecarga de refrigerante", "Falta de refrigerante", "Filtro tapado", "Evaporador sucio"], respuesta_correcta:1, explicacion:"Bajo refrigerante causa poco líquido en el condensador (Bajo SC) y vapor muy caliente al final del evaporador (Alto SH)." , question: "If a system has high superheat (30 degrees F) and low subcooling (2 degrees F), what is the diagnosis?", options: ["Refrigerant overcharge", "Low refrigerant charge", "Clogged filter", "Dirty evaporator"], explanation: "Low refrigerant causes insufficient liquid in the condenser (low subcooling) and very hot vapor at the end of the evaporator (high superheat)." },
  { id:"nate_27", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué gas se produce cuando el refrigerante R-22 se quema en presencia de una llama abierta?", opciones:["Dióxido de Carbono", "Gas Fosgeno", "Nitrógeno puro", "Metano"], respuesta_correcta:1, explicacion:"El fosgeno es un gas altamente tóxico y letal producido por la descomposición térmica de refrigerantes halogenados." , question: "What gas is produced when R-22 refrigerant burns in the presence of an open flame?", options: ["Carbon dioxide", "Phosgene gas", "Pure nitrogen", "Methane"], explanation: "Phosgene is a highly toxic and lethal gas produced by the thermal decomposition of halogenated refrigerants." },
  { id:"nate_28", categoria:"NATE_FUNDAMENTOS", pregunta:"Si mides 24V en la bobina de un contactor pero los contactos principales no cierran, ¿cuál es el problema?", opciones:["El termostato está dañado", "La bobina del contactor está abierta (quemada)", "El compresor está en corto", "Falta voltaje de línea"], respuesta_correcta:1, explicacion:"Si llega voltaje de control pero no hay acción mecánica, el solenoide interno falló." , question: "If you measure 24V at the contactor coil but the main contacts do not close, what is the problem?", options: ["The thermostat is damaged", "The contactor coil is open (burned out)", "The compressor is shorted", "Line voltage is missing"], explanation: "If control voltage is present but there is no mechanical action, the internal solenoid has failed." },
  { id:"nate_29", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué componente diferencia a un sistema de refrigeración 'Paquete' de un sistema 'Split'?", opciones:["El tipo de refrigerante", "Que todos los componentes están en una sola unidad/gabinete", "El uso de termostato", "El diámetro de la tubería"], respuesta_correcta:1, explicacion:"Un sistema paquete (RTU) contiene el evaporador y condensador en un solo mueble de fábrica." , question: "What component differentiates a 'package' refrigeration system from a 'split' system?", options: ["The type of refrigerant", "All components are housed in a single unit/cabinet", "The use of a thermostat", "The pipe diameter"], explanation: "A package system (RTU) contains both the evaporator and condenser in a single factory-built enclosure." },
  { id:"nate_30", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la temperatura crítica del R-410A, punto a partir del cual no puede condensarse sin importar la presión?", opciones:["110°F", "162°F", "212°F", "150°F"], respuesta_correcta:1, explicacion:"La temperatura crítica del R-410A es baja comparada con otros, lo que limita su uso en ambientes extremadamente calientes." , question: "What is the critical temperature of R-410A, above which it cannot be condensed regardless of pressure?", options: ["110 degrees F", "162 degrees F", "212 degrees F", "150 degrees F"], explanation: "The critical temperature of R-410A is low compared to other refrigerants, which limits its use in extremely hot environments." },
  { id:"nate_31", categoria:"NATE_FUNDAMENTOS", pregunta:"Un motor de soplador (blower) consume el doble de su amperaje nominal (RLA) cuando se quitan los filtros y se abren todas las rejillas. ¿Por qué?", opciones:["El motor se está forzando por falta de aire", "El motor está moviendo más masa de aire (más trabajo)", "El motor está dañado", "El voltaje bajó"], respuesta_correcta:1, explicacion:"A diferencia de lo que muchos creen, un ventilador centrífugo trabaja más (consume más amps) cuando NO tiene restricción de aire." , question: "A blower motor draws double its rated load amps (RLA) when the filters are removed and all registers are fully open. Why?", options: ["The motor is straining due to lack of air", "The motor is moving more air mass (more work)", "The motor is damaged", "The voltage dropped"], explanation: "Contrary to common belief, a centrifugal fan does more work (draws more amps) when there is NO airflow restriction." },
  { id:"nate_32", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué nivel de vacío se requiere para recuperar refrigerante en un sistema de alta presión con menos de 200 lbs de carga usando equipo fabricado después de 1993?", opciones:["0 psig", "10 pulgadas de Hg", "15 pulgadas de Hg", "4 pulgadas de Hg"], respuesta_correcta:1, explicacion:"Norma EPA: Se debe alcanzar un vacío de 10'' Hg para asegurar que no quede refrigerante líquido o vapor denso." , question: "What vacuum level is required to recover refrigerant from a high-pressure system with less than 200 lbs of charge using equipment manufactured after 1993?", options: ["0 psig", "10 inches of Hg", "15 inches of Hg", "4 inches of Hg"], explanation: "EPA regulation: A vacuum of 10 inches Hg must be reached to ensure no liquid or dense vapor refrigerant remains." },
  { id:"nate_33", categoria:"NATE_FUNDAMENTOS", pregunta:"¿En qué parte del ciclo de refrigeración se añade la mayor cantidad de 'Calor Latente' al refrigerante?", opciones:["En el compresor", "En el condensador", "En el evaporador", "En la línea de líquido"], respuesta_correcta:2, explicacion:"Es donde el refrigerante cambia de estado de líquido a vapor absorbiendo calor del espacio." , question: "In which part of the refrigeration cycle is the greatest amount of latent heat added to the refrigerant?", options: ["In the compressor", "In the condenser", "In the evaporator", "In the liquid line"], explanation: "This is where the refrigerant changes state from liquid to vapor, absorbing heat from the conditioned space." },
  { id:"nate_34", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Para qué sirve el pin de tierra en un enchufe de una herramienta eléctrica?", opciones:["Para completar el circuito", "Para desviar corriente de fuga hacia tierra en caso de falla", "Para ahorrar energía", "Para estabilizar el voltaje"], respuesta_correcta:1, explicacion:"Protege al usuario evitando que su cuerpo sea el camino a tierra en un corto circuito a la carcasa." , question: "What is the purpose of the ground pin on a power tool plug?", options: ["To complete the circuit", "To divert fault current to ground in the event of a failure", "To save energy", "To stabilize voltage"], explanation: "It protects the user by preventing their body from becoming the path to ground in a short circuit to the tool housing." },
  { id:"nate_35", categoria:"NATE_FUNDAMENTOS", pregunta:"Un termostato digital marca 'Cool On' pero el equipo exterior no arranca. Mides 24V entre Y y C en el manejador de aire. ¿Dónde está el problema?", opciones:["En el termostato", "En el cableado hacia la unidad exterior o componentes de la unidad exterior", "En el transformador", "En el soplador"], respuesta_correcta:1, explicacion:"Si hay 24V en la terminal Y del equipo, el termostato está haciendo su trabajo; la falla es 'aguas abajo'." , question: "A digital thermostat displays 'Cool On' but the outdoor unit does not start. You measure 24V between Y and C at the air handler. Where is the problem?", options: ["In the thermostat", "In the wiring to the outdoor unit or in the outdoor unit components", "In the transformer", "In the blower"], explanation: "If there is 24V at the Y terminal of the indoor equipment, the thermostat is doing its job; the fault is downstream." },
  { id:"nate_36", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Por qué se debe fluir nitrógeno a baja presión (1-2 psi) mientras se suelda tubería de cobre?", opciones:["Para enfriar el cobre", "Para evitar la formación de escamas de óxido cúprico (hollín) internas", "Para que la soldadura corra más rápido", "Para probar fugas al mismo tiempo"], respuesta_correcta:1, explicacion:"El nitrógeno desplaza el oxígeno, evitando que el interior del tubo se oxide y tape dispositivos de expansión u orificios de aceite." , question: "Why should nitrogen be flowed at low pressure (1-2 psi) through the piping while brazing copper?", options: ["To cool the copper", "To prevent the formation of internal copper oxide scale (soot)", "To make the solder flow faster", "To test for leaks at the same time"], explanation: "Nitrogen displaces oxygen, preventing the inside of the tubing from oxidizing and clogging expansion devices or oil ports." },
  { id:"nate_37", categoria:"NATE_FUNDAMENTOS", pregunta:"En un Relay de Potencial, ¿cuáles son las terminales que normalmente están cerradas (NC) para conectar el capacitor de arranque?", opciones:["1 y 2", "2 y 3", "5 y 2", "1 y 5"], respuesta_correcta:0, explicacion:"La terminal 1 y 2 del relay de potencial mantienen el capacitor de arranque en el circuito hasta que el motor genera suficiente fuerza contra-electromotriz (VEMF)." , question: "On a potential relay, which terminals are normally closed (NC) to connect the start capacitor?", options: ["1 and 2", "2 and 3", "5 and 2", "1 and 5"], explanation: "Terminals 1 and 2 of the potential relay keep the start capacitor in the circuit until the motor generates enough back-EMF (BEMF)." },
  { id:"nate_38", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es el 'GWP' (Global Warming Potential) de referencia para comparar otros gases?", opciones:["Metano", "R-22", "Dióxido de Carbono (CO2)", "Oxígeno"], respuesta_correcta:2, explicacion:"El CO2 tiene un GWP de 1, sirviendo como base de comparación para todos los demás gases de efecto invernadero." , question: "What is the reference GWP (Global Warming Potential) used to compare other gases?", options: ["Methane", "R-22", "Carbon dioxide (CO2)", "Oxygen"], explanation: "CO2 has a GWP of 1, serving as the baseline for comparing all other greenhouse gases." },
  { id:"nate_39", categoria:"NATE_FUNDAMENTOS", pregunta:"Estás cargando una unidad con R-410A por Superheat. El SH objetivo es 12°F, pero mides 25°F. ¿Qué debes hacer?", opciones:["Remover refrigerante", "Agregar refrigerante", "Cambiar el filtro", "Limpiar el condensador"], respuesta_correcta:1, explicacion:"Un Superheat alto indica que el evaporador está 'hambriento' (falta gas); agregar gas bajará el SH al saturar más el serpentín." , question: "You are charging a unit with R-410A by superheat. The target superheat is 12 degrees F, but you measure 25 degrees F. What should you do?", options: ["Remove refrigerant", "Add refrigerant", "Change the filter", "Clean the condenser"], explanation: "A high superheat indicates the evaporator is starved (low on refrigerant); adding refrigerant will lower the superheat by flooding more of the coil." },
  { id:"nate_40", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué significa la categoría CAT III 600V en un multímetro?", opciones:["Que puede medir hasta 600 Watts", "Que está diseñado para resistir picos de voltaje en paneles de distribución eléctrica", "Que solo sirve para corriente directa", "Que es resistente al agua"], respuesta_correcta:1, explicacion:"La categoría define la seguridad del equipo ante transitorios de alto voltaje en instalaciones fijas." , question: "What does the CAT III 600V rating on a multimeter mean?", options: ["It can measure up to 600 Watts", "It is designed to withstand voltage spikes in electrical distribution panels", "It is only for DC current", "It is water resistant"], explanation: "The category rating defines the instrument's safety against high-voltage transients in fixed electrical installations." },
  { id:"nate_41", categoria:"NATE_FUNDAMENTOS", pregunta:"¿En qué punto del sistema el refrigerante está en su presión más alta y temperatura más baja?", opciones:["Salida del condensador", "Entrada del evaporador", "Succión del compresor", "Descarga del compresor"], respuesta_correcta:0, explicacion:"Aquí el refrigerante ya fue comprimido (alta presión) y ya liberó calor (temperatura baja comparada con la descarga)." , question: "At which point in the system is the refrigerant at its highest pressure and lowest temperature?", options: ["Condenser outlet", "Evaporator inlet", "Compressor suction", "Compressor discharge"], explanation: "Here the refrigerant has already been compressed (high pressure) and has already rejected its heat (lower temperature compared to the discharge)." },
  { id:"nate_42", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un calentador eléctrico de 240V tiene una resistencia de 20 Ohms, ¿cuántos amperios circularán por él?", opciones:["10 A", "12 A", "24 A", "4.8 A"], respuesta_correcta:1, explicacion:"I = V / R. 240 / 20 = 12 Amperios." , question: "If a 240V electric heater has a resistance of 20 Ohms, how many amps will flow through it?", options: ["10 A", "12 A", "24 A", "4.8 A"], explanation: "I = V / R. 240 / 20 = 12 Amps." },
  { id:"nate_43", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué tipo de aceite es altamente higroscópico (absorbe mucha humedad) y se usa con R-410A?", opciones:["Aceite Mineral", "Alquilbenceno", "POE (Polioilester)", "Aceite de cocina"], respuesta_correcta:2, explicacion:"El aceite POE es extremadamente sensible a la humedad, por lo que nunca se debe dejar el sistema abierto al aire por mucho tiempo." , question: "What type of oil is highly hygroscopic (absorbs significant moisture) and is used with R-410A?", options: ["Mineral oil", "Alkylbenzene", "POE (Polyolester)", "Cooking oil"], explanation: "POE oil is extremely sensitive to moisture, which is why the system should never be left open to the atmosphere for extended periods." },
  { id:"nate_44", categoria:"NATE_FUNDAMENTOS", pregunta:"Si calibras tus manómetros analógicos a 0 psig pero no tomas en cuenta la altitud (ej. en Denver, CO), ¿qué error estarás cometiendo?", opciones:["Error de lectura de aproximadamente 2-3 psi", "Ninguno, el manómetro es automático", "Dañarás el sensor", "El vacío será más rápido"], respuesta_correcta:0, explicacion:"La presión atmosférica cambia con la altura; los manómetros analógicos deben ajustarse al '0' local." , question: "If you zero your analog gauges at 0 psig but do not account for altitude (e.g., in Denver, CO), what error will you be making?", options: ["A reading error of approximately 2-3 psi", "None; the gauge is automatic", "You will damage the sensor", "The vacuum will be faster"], explanation: "Atmospheric pressure changes with elevation; analog gauges must be zeroed to the local atmospheric pressure." },
  { id:"nate_45", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es el propósito de un 'Crankcase Heater' (Calentador de Cárter)?", opciones:["Mantener el refrigerante caliente para el cliente", "Evitar la migración de refrigerante líquido al aceite durante el ciclo de apagado", "Ayudar al compresor a arrancar más rápido", "Prevenir que el agua se congele"], respuesta_correcta:1, explicacion:"Mantiene el aceite más caliente que el resto del sistema para que el refrigerante no se condense dentro del compresor." , question: "What is the purpose of a crankcase heater?", options: ["Keep the refrigerant warm for the customer", "Prevent liquid refrigerant from migrating into the oil during the off cycle", "Help the compressor start faster", "Prevent water from freezing"], explanation: "It keeps the oil warmer than the rest of the system so that refrigerant does not condense inside the compressor." },
  { id:"nate_46", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué sucede con la capacidad de enfriamiento de un sistema si la humedad relativa en el espacio aumenta drásticamente?", opciones:["La capacidad sensible aumenta", "La capacidad latente aumenta pero la sensible disminuye", "El compresor se apaga", "El condensador se calienta menos"], respuesta_correcta:1, explicacion:"El sistema gasta más energía condensando agua del aire (calor latente) y le queda menos energía para bajar la temperatura (calor sensible)." , question: "What happens to the cooling capacity of a system if the relative humidity in the space increases drastically?", options: ["Sensible capacity increases", "Latent capacity increases but sensible capacity decreases", "The compressor shuts off", "The condenser heats up less"], explanation: "The system uses more energy condensing water from the air (latent heat), leaving less capacity to lower the temperature (sensible heat)." },
  { id:"nate_47", categoria:"NATE_FUNDAMENTOS", pregunta:"Un técnico encuentra que la presión de succión es muy baja y la presión de descarga también es baja. El Superheat es alto. ¿Qué falla es?", opciones:["Compresor ineficiente", "Restricción en el dispositivo de expansión", "Condensador sucio", "Motor de soplador fallando"], respuesta_correcta:1, explicacion:"Una restricción 'atrapa' el gas en el lado de alta, bajando la succión. La descarga también baja porque el compresor no tiene masa que mover." , question: "A technician finds that suction pressure is very low and discharge pressure is also low. Superheat is high. What is the fault?", options: ["Inefficient compressor", "Restriction in the metering device", "Dirty condenser", "Failing blower motor"], explanation: "A restriction traps refrigerant on the high side, lowering suction pressure. Discharge pressure also drops because the compressor has no mass to move." },
  { id:"nate_48", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la función del 'Tag' (Etiqueta) en un procedimiento LOTO?", opciones:["Indicar quién puso el candado y por qué", "Servir como llave de repuesto", "Decorar el panel eléctrico", "Indicar el costo de la reparación"], respuesta_correcta:0, explicacion:"La etiqueta proporciona información de contacto y advertencias críticas sobre el trabajo que se está realizando." , question: "What is the function of the 'tag' in a LOTO procedure?", options: ["Indicate who placed the lock and why", "Serve as a spare key", "Decorate the electrical panel", "Indicate the cost of the repair"], explanation: "The tag provides contact information and critical warnings about the work being performed." },
  { id:"nate_49", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un transformador de 40VA entrega 24V, ¿cuánta corriente (Amperios) máxima puede soportar antes de quemarse?", opciones:["0.5 A", "1.6 A", "2.4 A", "40 A"], respuesta_correcta:1, explicacion:"Amps = VA / Volts. 40 / 24 = 1.66 Amperios." , question: "If a 40VA transformer delivers 24V, how much maximum current (Amps) can it support before burning out?", options: ["0.5 A", "1.6 A", "2.4 A", "40 A"], explanation: "Amps = VA / Volts. 40 / 24 = 1.66 Amps." },
  { id:"nate_50", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la causa principal de la falla de un compresor por 'Inundación' (Flooding)?", opciones:["Exceso de voltaje", "Retorno constante de refrigerante líquido durante el funcionamiento", "Falta de aceite", "Presión de descarga muy alta"], respuesta_correcta:1, explicacion:"El líquido diluye el aceite, eliminando la lubricación y causando desgaste mecánico prematuro." , question: "What is the primary cause of compressor failure due to flooding?", options: ["Excess voltage", "Constant return of liquid refrigerant during operation", "Lack of oil", "Extremely high discharge pressure"], explanation: "The liquid dilutes the oil, eliminating lubrication and causing premature mechanical wear." },
  { id:"nate_51", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la principal diferencia diagnóstica al probar un motor ECM (Electronically Commutated Motor) frente a un motor PSC?", opciones:["El ECM no usa capacitor de marcha", "El ECM requiere una señal de comunicación (PWM o VDC) además del voltaje de línea", "El ECM gira más lento si el filtro está sucio", "Todas las anteriores son correctas"], respuesta_correcta:3, explicacion:"Los motores ECM son inteligentes: no usan capacitores, requieren señales de control para arrancar y ajustan su torque/velocidad según la presión estática." , question: "What is the main diagnostic difference when testing an ECM (Electronically Commutated Motor) versus a PSC motor?", options: ["The ECM does not use a run capacitor", "The ECM requires a communication signal (PWM or VDC) in addition to line voltage", "The ECM slows down if the filter is dirty", "All of the above are correct"], explanation: "ECM motors are intelligent: they do not use capacitors, require control signals to start, and adjust their torque/speed based on static pressure." },
  { id:"nate_52", categoria:"NATE_FUNDAMENTOS", pregunta:"Si conectas dos capacitores de 10 microfaradios (µF) en PARALELO, ¿cuál es la capacitancia total resultante?", opciones:["5 µF", "10 µF", "20 µF", "15 µF"], respuesta_correcta:2, explicacion:"En paralelo, las capacitancias se suman (C1 + C2). En serie, la capacitancia total disminuye." , question: "If you connect two 10 microfarad capacitors in PARALLEL, what is the total resulting capacitance?", options: ["5 uF", "10 uF", "20 uF", "15 uF"], explanation: "In parallel, capacitances add up (C1 + C2). In series, total capacitance decreases." },
  { id:"nate_53", categoria:"NATE_FUNDAMENTOS", pregunta:"Mides continuidad en un compresor trifásico. Entre T1-T2 hay 3 Ohms, entre T2-T3 hay 3 Ohms, y entre T1-T3 hay 6 Ohms. ¿Cuál es el problema?", opciones:["El motor está balanceado y sano", "Hay un bobinado abierto en T3", "Hay un corto circuito entre T1 y T2", "El multímetro está fallando"], respuesta_correcta:1, explicacion:"En un motor trifásico, todas las lecturas entre terminales deben ser iguales. Si T1-T3 suma el doble y las otras son iguales, una fase no está cerrando el circuito correctamente." , question: "You measure continuity on a three-phase compressor. Between T1-T2 there are 3 Ohms, between T2-T3 there are 3 Ohms, and between T1-T3 there are 6 Ohms. What is the problem?", options: ["The motor is balanced and healthy", "There is an open winding at T3", "There is a short circuit between T1 and T2", "The multimeter is malfunctioning"], explanation: "In a three-phase motor, all readings between terminals should be equal. If T1-T3 reads double and the others are equal, one phase is not completing the circuit properly." },
  { id:"nate_54", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué fuerza abre los contactos de un Relay de Potencial?", opciones:["La gravedad", "El magnetismo generado por la bobina al detectar la VEMF", "Un resorte térmico", "La presión del refrigerante"], respuesta_correcta:1, explicacion:"Cuando el motor alcanza cerca del 75-80% de su velocidad, la Fuerza Contra-Electromotriz (VEMF) es suficiente para que la bobina del relay abra los contactos y saque el capacitor de arranque." , question: "What force opens the contacts of a potential relay?", options: ["Gravity", "The magnetism generated by the coil upon detecting the BEMF", "A thermal spring", "Refrigerant pressure"], explanation: "When the motor reaches about 75-80% of its speed, the back-EMF (BEMF) is sufficient for the relay coil to open the contacts and remove the start capacitor from the circuit." },
  { id:"nate_55", categoria:"NATE_FUNDAMENTOS", pregunta:"Un técnico instala un contactor con una bobina de mayor VA de lo especificado. ¿Qué componente es más probable que falle?", opciones:["El compresor", "El termostato", "El transformador de 24V", "El breaker principal"], respuesta_correcta:2, explicacion:"Si el consumo de los accesorios de control supera los VA del transformador, este se sobrecalentará y se quemará el fusible primario o el devanado." , question: "A technician installs a contactor with a coil of higher VA than specified. Which component is most likely to fail?", options: ["The compressor", "The thermostat", "The 24V transformer", "The main breaker"], explanation: "If the VA demand of the control accessories exceeds the transformer's rating, the transformer will overheat and blow its primary fuse or burn the winding." },
  { id:"nate_56", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la función de un 'GFCI' (Ground Fault Circuit Interrupter) en el equipo de servicio de un técnico?", opciones:["Evitar sobrecargas de amperaje", "Detectar una diferencia de corriente entre la línea y el neutro para evitar electrocución", "Mejorar el factor de potencia", "Filtrar el ruido de la línea"], respuesta_correcta:1, explicacion:"Un GFCI dispara si detecta que parte de la corriente está regresando por un camino no deseado (como el cuerpo de una persona)." , question: "What is the function of a GFCI (Ground Fault Circuit Interrupter) in a technician's service equipment?", options: ["Prevent amperage overloads", "Detect a current difference between line and neutral to prevent electrocution", "Improve the power factor", "Filter line noise"], explanation: "A GFCI trips if it detects that part of the current is returning through an unintended path (such as a person's body)." },
  { id:"nate_57", categoria:"NATE_FUNDAMENTOS", pregunta:"En un sistema con refrigerante zeotrópico (como el R-407C), ¿qué significa el término 'Glide' de temperatura?", opciones:["La velocidad a la que fluye el gas", "La diferencia de temperatura entre el punto de burbuja y el punto de rocío a una presión constante", "El tiempo que tarda en enfriar el cuarto", "La caída de presión en el filtro"], respuesta_correcta:1, explicacion:"Las mezclas zeotrópicas se evaporan y condensan en rangos de temperatura, no en un punto fijo." , question: "In a system with a zeotropic refrigerant (such as R-407C), what does the term temperature 'glide' mean?", options: ["The speed at which the gas flows", "The temperature difference between the bubble point and the dew point at a constant pressure", "The time it takes to cool the room", "The pressure drop across the filter"], explanation: "Zeotropic blends evaporate and condense over a range of temperatures, not at a single fixed point." },
  { id:"nate_58", categoria:"NATE_FUNDAMENTOS", pregunta:"Mides 24V en el solenoide de la válvula inversora en modo calefacción, pero la válvula no cambia de posición. Golpeas suavemente el cuerpo de la válvula y ésta cambia. ¿Cuál es el diagnóstico?", opciones:["Falla eléctrica en el termostato", "Válvula físicamente trabada (falla mecánica)", "Baja carga de refrigerante", "El solenoide está quemado"], respuesta_correcta:1, explicacion:"Si hay voltaje y el cambio ocurre por vibración/golpe, el deslizador interno está atascado por contaminantes o deformación." , question: "You measure 24V at the reversing valve solenoid in heating mode, but the valve does not change position. You gently tap the valve body and it shifts. What is the diagnosis?", options: ["Electrical failure in the thermostat", "Valve is physically stuck (mechanical failure)", "Low refrigerant charge", "The solenoid is burned out"], explanation: "If voltage is present and the valve shifts upon vibration/tapping, the internal slider is stuck due to contaminants or deformation." },
  { id:"nate_59", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un motor soplador consume 4 Amperios a 240V, pero el voltaje cae a 208V, ¿qué sucederá con el amperaje si la carga mecánica permanece igual?", opciones:["El amperaje bajará", "El amperaje subirá", "El amperaje será el mismo", "El motor girará más rápido"], respuesta_correcta:1, explicacion:"En motores de inducción, si el voltaje baja, el amperaje debe subir para compensar y mantener el trabajo (Ley de Watt: P = V * I)." , question: "If a blower motor draws 4 Amps at 240V, but the voltage drops to 208V, what will happen to the amperage if the mechanical load remains the same?", options: ["Amperage will decrease", "Amperage will increase", "Amperage will stay the same", "The motor will spin faster"], explanation: "In induction motors, if voltage drops, amperage must increase to compensate and maintain the workload (Watt's Law: P = V x I)." },
  { id:"nate_60", categoria:"NATE_FUNDAMENTOS", pregunta:"Encuentras un evaporador congelado. El filtro está limpio, el motor del soplador funciona bien y el Superheat es de 0°F. ¿Cuál es la causa más probable?", opciones:["Falta de refrigerante", "Sobrecalentamiento excesivo", "Restricción en la línea de líquido", "TXV inundando el evaporador (traba abierta)"], respuesta_correcta:3, explicacion:"Un SH de 0°F significa que hay líquido regresando. Si no es flujo de aire, la TXV está dejando pasar demasiado refrigerante, bajando la temperatura de saturación al punto de congelación." , question: "You find a frozen evaporator. The filter is clean, the blower motor works fine, and the superheat is 0 degrees F. What is the most likely cause?", options: ["Low refrigerant charge", "Excessive superheat", "Restriction in the liquid line", "TXV flooding the evaporator (stuck open)"], explanation: "A superheat of 0 degrees F means liquid is returning. If airflow is not the issue, the TXV is allowing too much refrigerant through, lowering the saturation temperature to the freezing point." },
  { id:"nate_61", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué sucede si un compresor Scroll trifásico se conecta con las fases invertidas?", opciones:["No arranca", "Gira en reversa, hace mucho ruido y no comprime", "Se quema instantáneamente", "Funciona normalmente"], respuesta_correcta:1, explicacion:"Los Scroll son direccionales. En reversa no desplazan gas, las presiones se igualan y el ruido es metálico y fuerte." , question: "What happens if a three-phase scroll compressor is connected with the phases reversed?", options: ["It does not start", "It runs in reverse, makes loud noise, and does not compress", "It burns out instantly", "It operates normally"], explanation: "Scroll compressors are directional. In reverse, they do not displace gas, pressures equalize, and the noise is loud and metallic." },
  { id:"nate_62", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Por qué los manómetros digitales son preferibles sobre los analógicos para medir Subcooling en sistemas críticos?", opciones:["Porque son más bonitos", "Porque eliminan el error de paralaje y calculan la saturación en tiempo real", "Porque no usan mangueras", "Porque cargan el sistema más rápido"], respuesta_correcta:1, explicacion:"La precisión digital evita errores de interpretación visual (paralaje) y da datos exactos basados en tablas PT internas actualizadas." , question: "Why are digital manifold gauges preferred over analog gauges for measuring subcooling in critical systems?", options: ["Because they look nicer", "Because they eliminate parallax error and calculate saturation in real time", "Because they don't use hoses", "Because they charge the system faster"], explanation: "Digital precision avoids visual interpretation errors (parallax) and provides exact data based on updated internal P-T tables." },
  { id:"nate_63", categoria:"NATE_FUNDAMENTOS", pregunta:"Un sistema de 3 toneladas de refrigeración tiene una capacidad nominal de:", opciones:["12,000 BTU/h", "24,000 BTU/h", "36,000 BTU/h", "48,000 BTU/h"], respuesta_correcta:2, explicacion:"1 tonelada = 12,000 BTU/h. Por lo tanto, 3 * 12,000 = 36,000 BTU/h." , question: "A 3-ton refrigeration system has a nominal capacity of:", options: ["12,000 BTU/h", "24,000 BTU/h", "36,000 BTU/h", "48,000 BTU/h"], explanation: "1 ton = 12,000 BTU/h. Therefore, 3 x 12,000 = 36,000 BTU/h." },
  { id:"nate_64", categoria:"NATE_FUNDAMENTOS", pregunta:"En un diagrama esquemático de HVAC, ¿cómo se representa normalmente un interruptor de seguridad (como un presostato de alta) que debe detener el equipo si falla?", opciones:["Normalmente Abierto (NO) en paralelo con la carga", "Normalmente Cerrado (NC) en serie con la carga", "Normalmente Abierto (NO) en serie con el neutro", "No se representa"], respuesta_correcta:1, explicacion:"Los dispositivos de seguridad se ponen en serie y son NC para que, al activarse, abran el circuito y corten la energía." , question: "On an HVAC schematic diagram, how is a safety switch (such as a high-pressure switch) that must stop the equipment upon failure normally represented?", options: ["Normally Open (NO) in parallel with the load", "Normally Closed (NC) in series with the load", "Normally Open (NO) in series with the neutral", "It is not represented"], explanation: "Safety devices are placed in series and are NC so that when they activate, they open the circuit and cut power." },
  { id:"nate_65", categoria:"NATE_FUNDAMENTOS", pregunta:"¿En qué línea del sistema se debe instalar un acumulador de succión?", opciones:["En la línea de descarga", "En la línea de líquido", "En la línea de succión, antes del compresor", "En el medio del condensador"], respuesta_correcta:2, explicacion:"Su función es atrapar líquido antes de que entre al compresor, protegiendo las válvulas o los scrolls." , question: "On which line of the system should a suction accumulator be installed?", options: ["On the discharge line", "On the liquid line", "On the suction line, before the compressor", "In the middle of the condenser"], explanation: "Its function is to trap liquid before it enters the compressor, protecting the valves or scroll elements." },
  { id:"nate_66", categoria:"NATE_FUNDAMENTOS", pregunta:"Estás cargando una unidad con TXV por Subcooling. El SC medido es 15°F y el fabricante pide 10°F. ¿Qué debes hacer?", opciones:["Agregar refrigerante", "Remover refrigerante", "Abrir la TXV", "Limpiar el evaporador"], respuesta_correcta:1, explicacion:"Un subenfriamiento alto indica que hay demasiado líquido acumulado en el condensador (sobra refrigerante)." , question: "You are charging a unit with a TXV by subcooling. The measured subcooling is 15 degrees F and the manufacturer calls for 10 degrees F. What should you do?", options: ["Add refrigerant", "Remove refrigerant", "Open the TXV", "Clean the evaporator"], explanation: "High subcooling indicates too much liquid accumulated in the condenser (system is overcharged)." },
  { id:"nate_67", categoria:"NATE_FUNDAMENTOS", pregunta:"Un motor de soplador hace un ruido agudo (chirrido) que desaparece cuando el motor se apaga y el eje sigue girando por inercia. ¿Cuál es el problema?", opciones:["Rodamientos (baleros) dañados", "Fricción magnética o problemas de frecuencia en el inversor", "El aspa está rozando", "Falta de lubricación en el eje"], respuesta_correcta:1, explicacion:"Si el ruido desaparece *instantáneamente* al cortar la luz, es un problema eléctrico/magnético. Si fuera mecánico (baleros), el ruido seguiría mientras el eje gire." , question: "A blower motor makes a high-pitched squealing noise that disappears when the motor is de-energized and the shaft continues to spin by inertia. What is the problem?", options: ["Damaged bearings", "Magnetic friction or inverter frequency issues", "The blade is rubbing", "Lack of shaft lubrication"], explanation: "If the noise disappears *instantly* when power is cut, it is an electrical/magnetic problem. If it were mechanical (bearings), the noise would continue while the shaft spins." },
  { id:"nate_68", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué gas se debe usar para 'empujar' el refrigerante líquido durante una recuperación Push-Pull?", opciones:["Aire comprimido", "Oxígeno", "Vapor del mismo refrigerante del sistema", "Helio"], respuesta_correcta:2, explicacion:"Se usa el propio vapor del sistema (succionado por la máquina de recuperación) para presurizar el tanque y empujar el líquido." , question: "What gas should be used to 'push' the liquid refrigerant during a push-pull recovery?", options: ["Compressed air", "Oxygen", "Vapor from the same system refrigerant", "Helium"], explanation: "The system's own vapor (drawn by the recovery machine) is used to pressurize the cylinder and push the liquid out." },
  { id:"nate_69", categoria:"NATE_FUNDAMENTOS", pregunta:"Si mides resistencia en un componente y el multímetro marca '0.00 Ohms', ¿qué significa?", opciones:["El componente está abierto", "El componente tiene una resistencia infinita", "El componente está en cortocircuito (sin resistencia)", "El multímetro está apagado"], respuesta_correcta:2, explicacion:"Resistencia 0 significa flujo libre de corriente (corto). 'O.L' significa circuito abierto o resistencia infinita." , question: "If you measure resistance across a component and the multimeter reads '0.00 Ohms', what does it mean?", options: ["The component is open", "The component has infinite resistance", "The component is short-circuited (zero resistance)", "The multimeter is turned off"], explanation: "A resistance of 0 means unrestricted current flow (short). 'OL' means an open circuit or infinite resistance." },
  { id:"nate_70", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es el flujo de aire estándar (CFM) por tonelada de refrigeración para un sistema de aire acondicionado residencial?", opciones:["200 CFM", "400 CFM", "600 CFM", "800 CFM"], respuesta_correcta:1, explicacion:"El estándar de la industria es 400 CFM de aire por cada 12,000 BTU/h (1 tonelada)." , question: "What is the standard airflow (CFM) per ton of cooling for a residential air conditioning system?", options: ["200 CFM", "400 CFM", "600 CFM", "800 CFM"], explanation: "The industry standard is 400 CFM of air per 12,000 BTU/h (1 ton)." },
  { id:"nate_71", categoria:"NATE_FUNDAMENTOS", pregunta:"Cuando se suelda cobre con cobre usando una varilla de Fósforo-Cobre (como Sil-Fos 5% o 15%), ¿por qué no es estrictamente necesario el uso de fundente (flux)?", opciones:["Porque el cobre es muy limpio", "Porque el fósforo en la varilla actúa como agente desoxidante (autofundente)", "Porque el nitrógeno lo sustituye", "Porque el calor es suficiente"], respuesta_correcta:1, explicacion:"El contenido de fósforo limpia los óxidos del cobre durante el proceso. Nota: Si sueldas cobre con bronce/latón, SÍ necesitas fundente." , question: "When brazing copper to copper using a phosphorus-copper alloy rod (such as Sil-Fos 5% or 15%), why is flux not strictly necessary?", options: ["Because copper is very clean", "Because the phosphorus in the rod acts as a deoxidizing (self-fluxing) agent", "Because the nitrogen substitutes for it", "Because the heat is sufficient"], explanation: "The phosphorus content cleans the copper oxides during the process. Note: If brazing copper to brass/bronze, flux IS required." },
  { id:"nate_72", categoria:"NATE_FUNDAMENTOS", pregunta:"Un sistema tiene presiones de succión y descarga normales, pero el aire que sale por las rejillas no está suficientemente frío. Encuentras que el bulbo de la TXV está suelto y colgando. ¿Qué está pasando?", opciones:["La TXV está restringiendo el flujo", "La TXV está totalmente abierta, inundando el evaporador y subiendo el SH", "El compresor está fallando", "El filtro está sucio"], respuesta_correcta:1, explicacion:"Si el bulbo está suelto, siente la temperatura ambiente (calor), lo que obliga a la TXV a abrirse al máximo, causando una inundación que arruina la eficiencia de evaporación." , question: "A system has normal suction and discharge pressures, but the air coming out of the registers is not cold enough. You find that the TXV sensing bulb is loose and hanging. What is happening?", options: ["The TXV is restricting flow", "The TXV is fully open, flooding the evaporator and raising the superheat", "The compressor is failing", "The filter is dirty"], explanation: "If the bulb is loose, it senses ambient temperature (heat), which forces the TXV to open fully, causing a flood that ruins evaporation efficiency." },
  { id:"nate_73", categoria:"NATE_FUNDAMENTOS", pregunta:"¿En qué parte del sistema se instala el separador de aceite en refrigeración comercial?", opciones:["En la línea de succión", "En la línea de descarga, entre el compresor y el condensador", "En la línea de líquido", "Dentro del cárter"], respuesta_correcta:1, explicacion:"Debe atrapar el aceite justo después de que sale del compresor para devolverlo al cárter antes de que entre al condensador." , question: "In commercial refrigeration, where is the oil separator installed?", options: ["On the suction line", "On the discharge line, between the compressor and the condenser", "On the liquid line", "Inside the crankcase"], explanation: "It must capture oil right after it leaves the compressor to return it to the crankcase before it enters the condenser." },
  { id:"nate_74", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué sucede si intercambias accidentalmente los cables de las terminales 2 y 5 en un Relay de Potencial?", opciones:["El motor arranca más rápido", "La bobina del relay no detectará el voltaje y los contactos nunca se abrirán, quemando el capacitor de arranque", "El breaker se dispara inmediatamente", "No pasa nada, son terminales comunes"], respuesta_correcta:1, explicacion:"La bobina está conectada entre 2 y 5. Si cambias los cables, el relay no 'siente' el voltaje del devanado de arranque y mantiene el capacitor conectado hasta que explota o se quema." , question: "What happens if you accidentally swap the wires on terminals 2 and 5 of a potential relay?", options: ["The motor starts faster", "The relay coil will not detect the voltage and the contacts will never open, burning the start capacitor", "The breaker trips immediately", "Nothing happens; they are common terminals"], explanation: "The coil is connected between terminals 2 and 5. If the wires are swapped, the relay does not sense the start winding voltage and keeps the capacitor connected until it explodes or burns." },
  { id:"nate_75", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es el rango aceptable de 'Delta T' (diferencia de temperatura entre retorno y suministro) para un sistema de A/C estándar?", opciones:["5°F a 10°F", "16°F a 22°F", "25°F a 30°F", "30°F a 40°F"], respuesta_correcta:1, explicacion:"Un Delta T de 18-20°F es ideal. Menos indica problemas de flujo o carga; más indica flujo de aire restringido." , question: "What is the acceptable range of Delta T (temperature difference between return and supply air) for a standard A/C system?", options: ["5 to 10 degrees F", "16 to 22 degrees F", "25 to 30 degrees F", "30 to 40 degrees F"], explanation: "A Delta T of 18-20 degrees F is ideal. Less indicates airflow or charge problems; more indicates restricted airflow." },
  { id:"nate_76", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la clasificación de seguridad de ASHRAE para el refrigerante R-123?", opciones:["A1 (Baja toxicidad, no inflamable)", "B1 (Alta toxicidad, no inflamable)", "A2L (Baja toxicidad, baja inflamabilidad)", "B3 (Alta toxicidad, alta inflamabilidad)"], respuesta_correcta:1, explicacion:"El R-123 es usado en Chillers centrífugos y es tóxico, requiriendo sensores de sala y ventilación especial." , question: "What is the ASHRAE safety classification for R-123 refrigerant?", options: ["A1 (Low toxicity, non-flammable)", "B1 (Higher toxicity, non-flammable)", "A2L (Low toxicity, mildly flammable)", "B3 (Higher toxicity, highly flammable)"], explanation: "R-123 is used in centrifugal chillers and is toxic, requiring room sensors and special ventilation." },
  { id:"nate_77", categoria:"NATE_FUNDAMENTOS", pregunta:"Si ves burbujas en la mirilla (sight glass) de la línea de líquido, ¿qué es lo primero que debes verificar antes de agregar refrigerante?", opciones:["Si el condensador está sucio", "Si el filtro deshidratador está parcialmente obstruido", "Si el compresor tiene aceite", "Si el termostato está en modo Auto"], respuesta_correcta:1, explicacion:"Una caída de presión en el filtro puede causar burbujas (flash gas) aunque la carga sea correcta. Agregar gas en este caso sobrecargaría el sistema." , question: "If you see bubbles in the liquid line sight glass, what is the first thing you should verify before adding refrigerant?", options: ["If the condenser is dirty", "If the filter drier is partially restricted", "If the compressor has oil", "If the thermostat is set to Auto"], explanation: "A pressure drop across the filter drier can cause bubbles (flash gas) even though the charge is correct. Adding refrigerant in this case would overcharge the system." },
  { id:"nate_78", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué sucede con el deslizamiento (slip) de un motor de inducción si la carga mecánica aumenta?", opciones:["El deslizamiento disminuye", "El deslizamiento aumenta", "Se mantiene igual", "El motor se convierte en generador"], respuesta_correcta:1, explicacion:"A mayor carga, el rotor se retrasa más respecto al campo magnético giratorio (estator), aumentando el deslizamiento para generar más torque." , question: "What happens to the slip of an induction motor if the mechanical load increases?", options: ["Slip decreases", "Slip increases", "It stays the same", "The motor becomes a generator"], explanation: "Under greater load, the rotor falls further behind the rotating magnetic field of the stator, increasing slip to generate more torque." },
  { id:"nate_79", categoria:"NATE_FUNDAMENTOS", pregunta:"Estás usando un detector electrónico de fugas corona. El detector suena cerca de un frasco de limpiador de tuberías abierto. ¿Qué indica esto?", opciones:["Hay una fuga de refrigerante en el aire", "El detector está detectando falsamente los químicos (interferencia)", "El limpiador contiene R-22", "El detector necesita baterías"], respuesta_correcta:1, explicacion:"Muchos detectores electrónicos reaccionan a alcoholes, solventes y gases de limpieza. Siempre ventila el área antes de diagnosticar." , question: "You are using an electronic corona leak detector. The detector alarms near an open can of pipe cleaner. What does this indicate?", options: ["There is a refrigerant leak in the area", "The detector is giving a false reading due to the chemicals (interference)", "The cleaner contains R-22", "The detector needs new batteries"], explanation: "Many electronic detectors react to alcohols, solvents, and cleaning gases. Always ventilate the area before diagnosing." },
  { id:"nate_80", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Por qué es incorrecto usar las mangueras estándar de 1/4\" para hacer vacío en sistemas grandes?", opciones:["Porque se rompen", "Porque restringen el flujo de moléculas de aire, aumentando drásticamente el tiempo de vacío", "Porque el aceite de la bomba las daña", "Porque no aguantan la presión negativa"], respuesta_correcta:1, explicacion:"El diámetro de la manguera dicta la velocidad de evacuación. Mangueras de 3/8\" o 1/2\" son necesarias para un vacío eficiente." , question: "Why is it incorrect to use standard 1/4-inch hoses to evacuate large systems?", options: ["Because they break", "Because they restrict the flow of air molecules, drastically increasing evacuation time", "Because pump oil damages them", "Because they cannot handle negative pressure"], explanation: "The hose diameter dictates the evacuation speed. 3/8-inch or 1/2-inch hoses are necessary for an efficient vacuum." },
  { id:"nate_81", categoria:"NATE_FUNDAMENTOS", pregunta:"Un presostato de baja está configurado con un 'Cut-out' de 20 psig y un 'Differential' de 15 psig. ¿A qué presión volverá a arrancar el equipo (Cut-in)?", opciones:["15 psig", "20 psig", "35 psig", "5 psig"], respuesta_correcta:2, explicacion:"Cut-in = Cut-out + Differential. 20 + 15 = 35 psig." , question: "A low-pressure switch is set with a cut-out of 20 psig and a differential of 15 psig. At what pressure will the equipment restart (cut-in)?", options: ["15 psig", "20 psig", "35 psig", "5 psig"], explanation: "Cut-in = Cut-out + Differential. 20 + 15 = 35 psig." },
  { id:"nate_82", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un técnico recupera refrigerante de un sistema con el compresor quemado, ¿qué precaución adicional debe tomar?", opciones:["Usar guantes de hule", "Revisar si hay ácidos en el aceite y usar filtros deshidratadores de succión adicionales", "No recuperar el gas porque es ilegal", "Mezclarlo con refrigerante nuevo"], respuesta_correcta:1, explicacion:"Las quemaduras de compresor crean ácidos que pueden dañar la máquina de recuperación y contaminar el cilindro." , question: "If a technician recovers refrigerant from a system with a burned compressor, what additional precaution must be taken?", options: ["Wear rubber gloves", "Check for acids in the oil and use additional suction line filter driers", "Do not recover the gas because it is illegal", "Mix it with new refrigerant"], explanation: "Compressor burnouts create acids that can damage the recovery machine and contaminate the recovery cylinder." },
  { id:"nate_83", categoria:"NATE_FUNDAMENTOS", pregunta:"Escuchas un zumbido fuerte (chatter) en el contactor de la unidad exterior. Mides el voltaje en la bobina y oscila entre 18V y 22V. ¿Cuál es el problema?", opciones:["El contactor está viejo", "Caída de voltaje en el circuito de control o transformador subdimensionado", "El compresor está en corto", "Falta una fase de 240V"], respuesta_correcta:1, explicacion:"Si el voltaje de control cae por debajo de 20-22V, la bobina no tiene fuerza para mantener los contactos cerrados, causando el zumbido." , question: "You hear a loud buzzing (chatter) at the outdoor unit contactor. You measure the coil voltage and it oscillates between 18V and 22V. What is the problem?", options: ["The contactor is old", "Voltage drop in the control circuit or an undersized transformer", "The compressor is shorted", "A phase of 240V is missing"], explanation: "If the control voltage drops below 20-22V, the coil does not have enough force to hold the contacts closed, causing the buzzing." },
  { id:"nate_84", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué es el 'Subenfriamiento' (Subcooling)?", opciones:["La temperatura del vapor por encima de su punto de saturación", "La diferencia entre la temperatura de saturación del líquido y la temperatura real de la línea de líquido", "El hielo que se forma en el evaporador", "La temperatura del aceite"], respuesta_correcta:1, explicacion:"Es el calor sensible que se le quita al refrigerante líquido después de haberse condensado totalmente." , question: "What is subcooling?", options: ["The temperature of the vapor above its saturation point", "The difference between the liquid saturation temperature and the actual liquid line temperature", "The ice that forms on the evaporator", "The temperature of the oil"], explanation: "It is the sensible heat removed from the liquid refrigerant after it has fully condensed." },
  { id:"nate_85", categoria:"NATE_FUNDAMENTOS", pregunta:"En un Mini Split Inverter, ¿por qué no se puede medir el amperaje del compresor con una pinza amperimétrica estándar de AC?", opciones:["Porque el amperaje es muy bajo", "Porque el compresor funciona con corriente DC de frecuencia variable generada por el módulo IPM", "Porque los cables tienen mucho aislamiento", "Porque el motor es de imanes permanentes"], respuesta_correcta:1, explicacion:"Las pinzas estándar miden 60Hz. El Inverter varía la frecuencia y el voltaje, requiriendo equipos de medición True RMS o específicos para DC." , question: "In a mini-split inverter, why can't you measure compressor amperage with a standard AC clamp meter?", options: ["Because the amperage is too low", "Because the compressor runs on variable-frequency DC current generated by the IPM module", "Because the cables have too much insulation", "Because the motor uses permanent magnets"], explanation: "Standard clamp meters measure 60Hz. Inverter systems vary the frequency and voltage, requiring True RMS or DC-specific measurement instruments." },
  { id:"nate_86", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué sucede químicamente cuando la humedad reacciona con el aceite POE dentro de un sistema?", opciones:["Se crea agua pura", "Se crea ácido orgánico (proceso de hidrólisis)", "El aceite se vuelve más viscoso y mejor lubricante", "No pasa nada, el aceite lo absorbe"], respuesta_correcta:1, explicacion:"La humedad rompe las moléculas del aceite POE, creando ácidos que atacan el barniz de los bobinados del compresor." , question: "What happens chemically when moisture reacts with POE oil inside a system?", options: ["Pure water is created", "Organic acid is created (hydrolysis process)", "The oil becomes more viscous and a better lubricant", "Nothing happens; the oil absorbs it"], explanation: "Moisture breaks down the POE oil molecules, creating acids that attack the varnish on the compressor motor windings." },
  { id:"nate_87", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la causa más común de una fractura por vibración en las líneas de refrigerante cerca del compresor?", opciones:["Mala calidad del cobre", "Falta de bucles de vibración (vibration loops) o soportes inadecuados", "Presión de descarga muy alta", "Uso excesivo de soldadura"], respuesta_correcta:1, explicacion:"El compresor vibra al arrancar y parar. Sin flexibilidad en la tubería, el cobre se fatiga y se rompe." , question: "What is the most common cause of a vibration fatigue fracture in refrigerant lines near the compressor?", options: ["Poor copper quality", "Lack of vibration loops or inadequate supports", "Very high discharge pressure", "Excessive use of solder"], explanation: "The compressor vibrates during start-up and shutdown. Without flexibility in the piping, the copper fatigues and cracks." },
  { id:"nate_88", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la función de la resistencia que a veces se encuentra soldada entre las terminales de un capacitor de arranque?", opciones:["Aumentar el torque", "Descargar el capacitor para proteger los contactos del relay", "Limitar el amperaje de arranque", "Evitar que el capacitor se congele"], respuesta_correcta:1, explicacion:"La resistencia de 'bleeder' descarga el capacitor lentamente para evitar que salte un arco eléctrico en los contactos del relay de potencial la próxima vez que cierren." , question: "What is the function of the resistor sometimes found soldered across the terminals of a start capacitor?", options: ["Increase torque", "Discharge the capacitor to protect the relay contacts", "Limit starting amperage", "Prevent the capacitor from freezing"], explanation: "The bleeder resistor slowly discharges the capacitor to prevent an electrical arc across the potential relay contacts the next time they close." },
  { id:"nate_89", categoria:"NATE_FUNDAMENTOS", pregunta:"Un sistema tiene: Succión Alta, Descarga Baja, Superheat Alto y Subcooling Bajo. ¿Cuál es el diagnóstico?", opciones:["Falta de refrigerante", "Válvulas del compresor dañadas (compresor ineficiente)", "Restricción en la TXV", "Condensador sucio"], respuesta_correcta:1, explicacion:"Cuando el compresor no 'bombea' bien, no succiona fuerte (sube presión de succión) y no comprime fuerte (baja presión de descarga)." , question: "A system has: high suction, low discharge, high superheat, and low subcooling. What is the diagnosis?", options: ["Low refrigerant charge", "Damaged compressor valves (inefficient compressor)", "Restriction in the TXV", "Dirty condenser"], explanation: "When the compressor is not pumping properly, it cannot draw down suction (suction pressure rises) and cannot build adequate discharge (discharge pressure drops)." },
  { id:"nate_90", categoria:"NATE_FUNDAMENTOS", pregunta:"Al presurizar un sistema con nitrógeno para buscar fugas, ¿cuál es el límite de presión seguro para el lado de baja de un sistema residencial típico?", opciones:["150 psig", "300 psig", "500 psig", "800 psig"], respuesta_correcta:0, explicacion:"Siempre revisa la placa del evaporador. Muchos serpentines de aluminio o cobre delgado tienen un límite de diseño de 150-250 psi en el lado de baja." , question: "When pressurizing a system with nitrogen to search for leaks, what is the safe pressure limit for the low side of a typical residential system?", options: ["150 psig", "300 psig", "500 psig", "800 psig"], explanation: "Always check the evaporator nameplate. Many thin aluminum or copper coils have a design limit of 150-250 psi on the low side." },
  { id:"nate_91", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un circuito tiene dos resistencias de 10 Ohms cada una conectadas en SERIE, ¿cuál es la resistencia total?", opciones:["5 Ohms", "10 Ohms", "20 Ohms", "100 Ohms"], respuesta_correcta:2, explicacion:"En serie las resistencias se suman directamente (R1 + R2)." , question: "If a circuit has two 10-Ohm resistors connected in SERIES, what is the total resistance?", options: ["5 Ohms", "10 Ohms", "20 Ohms", "100 Ohms"], explanation: "In series, resistances add directly (R1 + R2)." },
  { id:"nate_92", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué indica una diferencia de temperatura de más de 3°F entre la entrada y la salida de un filtro deshidratador de la línea de líquido?", opciones:["El filtro está funcionando perfectamente", "El filtro está parcialmente obstruido (tapado)", "El refrigerante está muy caliente", "La carga es baja"], respuesta_correcta:1, explicacion:"Un filtro no debe tener caída de presión significativa. Si hay diferencia de temperatura, hay caída de presión y el refrigerante está empezando a evaporarse ahí mismo." , question: "What does a temperature difference of more than 3 degrees F between the inlet and outlet of a liquid line filter drier indicate?", options: ["The filter drier is working perfectly", "The filter drier is partially restricted (clogged)", "The refrigerant is too hot", "The charge is low"], explanation: "A filter drier should not cause a significant pressure drop. If there is a temperature difference, there is a pressure drop and the refrigerant is beginning to flash into vapor right there." },
  { id:"nate_93", categoria:"NATE_FUNDAMENTOS", pregunta:"Un motor de soplador PSC funciona pero se siente extremadamente caliente al tacto y se apaga después de 15 minutos. El capacitor es nuevo y correcto. ¿Qué revisarías?", opciones:["Si el motor está girando en sentido contrario", "Si los ductos están demasiado abiertos (baja presión estática)", "Si el voltaje es demasiado alto", "Todas las anteriores"], respuesta_correcta:3, explicacion:"Giro inverso, falta de carga de aire (que enfría el motor) o sobrevoltaje pueden causar sobrecalentamiento térmico." , question: "A PSC blower motor runs but feels extremely hot to the touch and shuts off after 15 minutes. The capacitor is new and correctly sized. What would you check?", options: ["If the motor is spinning in the wrong direction", "If the ductwork is too open (low static pressure)", "If the voltage is too high", "All of the above"], explanation: "Reverse rotation, insufficient air load (which cools the motor), or overvoltage can all cause thermal overheating." },
  { id:"nate_94", categoria:"NATE_FUNDAMENTOS", pregunta:"Para un sistema comercial con más de 50 lbs de carga, ¿cuál es el porcentaje de fuga anual máximo permitido antes de que sea obligatoria la reparación?", opciones:["10%", "20%", "30%", "50%"], respuesta_correcta:1, explicacion:"Bajo las nuevas reglas de la EPA, el umbral de reparación para refrigeración comercial es del 20% anual." , question: "For a commercial system with more than 50 lbs of charge, what is the maximum annual leak rate allowed before repair is mandatory?", options: ["10%", "20%", "30%", "50%"], explanation: "Under updated EPA rules, the repair trigger threshold for commercial refrigeration is 20% annually." },
  { id:"nate_95", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cómo afecta un filtro de aire muy sucio a la presión de descarga del sistema?", opciones:["La presión de descarga sube", "La presión de descarga baja", "La presión de descarga no cambia", "El condensador se congela"], respuesta_correcta:1, explicacion:"Filtro sucio = menos calor absorbido en el evaporador = menos calor para rechazar en el condensador = menor presión de descarga." , question: "How does a very dirty air filter affect the system's discharge pressure?", options: ["Discharge pressure rises", "Discharge pressure drops", "Discharge pressure does not change", "The condenser freezes"], explanation: "Dirty filter = less heat absorbed in the evaporator = less heat to reject in the condenser = lower discharge pressure." },
  { id:"nate_96", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Qué terminal del termostato controla generalmente el ventilador (fan) de la manejadora de aire?", opciones:["R", "Y", "G", "W"], respuesta_correcta:2, explicacion:"La terminal G (Green) es la encargada de activar el relevador del soplador." , question: "Which thermostat terminal generally controls the air handler fan (blower)?", options: ["R", "Y", "G", "W"], explanation: "The G terminal (Green) is responsible for activating the blower relay." },
  { id:"nate_97", categoria:"NATE_FUNDAMENTOS", pregunta:"¿Cuál es la función del filtro deshidratador que se pone a la entrada de la máquina de recuperación?", opciones:["Enfriar el gas", "Proteger la máquina de recuperación de partículas y humedad del sistema viejo", "Aumentar la velocidad de recuperación", "Separar el aceite"], respuesta_correcta:1, explicacion:"Evita que basuras o ácidos del sistema que estás vaciando dañen los pistones de tu máquina." , question: "What is the function of the filter drier installed at the inlet of the recovery machine?", options: ["Cool the gas", "Protect the recovery machine from particles and moisture in the old system", "Increase the recovery speed", "Separate the oil"], explanation: "It prevents debris and acids from the system being evacuated from damaging the recovery machine's pistons." },
  { id:"nate_98", categoria:"NATE_FUNDAMENTOS", pregunta:"Un técnico limpia el condensador con agua pero olvida apagar el equipo. Nota que mientras echa agua, la presión de descarga cae drásticamente. ¿Es esto un diagnóstico de carga?", opciones:["Sí, indica que le falta gas", "No, es un efecto temporal de enfriamiento forzado por el agua (evaporación)", "Sí, indica que el compresor está fuerte", "Indica que el condensador está dañado"], respuesta_correcta:1, explicacion:"El agua absorbe calor mucho mejor que el aire. Nunca se debe diagnosticar carga mientras se está lavando o mojando el condensador." , question: "A technician cleans the condenser with water but forgets to shut off the equipment. He notices that while spraying water, the discharge pressure drops dramatically. Is this a valid charge diagnosis?", options: ["Yes, it indicates low charge", "No, it is a temporary effect of forced cooling by evaporating water", "Yes, it indicates the compressor is strong", "It indicates the condenser is damaged"], explanation: "Water absorbs heat much more effectively than air. System charge should never be diagnosed while the condenser is being washed or wet." },
  { id:"nate_99", categoria:"NATE_FUNDAMENTOS", pregunta:"Si un equipo tiene múltiples fuentes de energía (ej. 240V para el compresor y un circuito separado de 120V para el control), ¿cuántos bloqueos LOTO se requieren?", opciones:["Solo el del breaker principal", "Uno por cada fuente de energía capaz de causar daño", "Ninguno si el técnico es rápido", "Solo apagar el termostato"], respuesta_correcta:1, explicacion:"OSHA exige bloquear TODAS las fuentes de energía peligrosas antes de intervenir el equipo." , question: "If a piece of equipment has multiple energy sources (e.g., 240V for the compressor and a separate 120V circuit for controls), how many LOTO lockouts are required?", options: ["Only the main breaker", "One for each energy source capable of causing harm", "None if the technician is quick", "Just turn off the thermostat"], explanation: "OSHA requires locking out ALL hazardous energy sources before working on the equipment." },
  { id:"nate_100", categoria:"NATE_FUNDAMENTOS", pregunta:"Un compresor arranca pero hace un ruido metálico y el amperaje es muy bajo. Las presiones de succión y descarga son casi iguales. ¿Cuál es el diagnóstico?", opciones:["Falta de refrigerante", "Sobrecalentamiento excesivo", "Compresor con falla mecánica interna (biela rota o válvulas destruidas)", "Capacitor de marcha dañado"], respuesta_correcta:2, explicacion:"Si el motor gira pero no hay diferencia de presión, el mecanismo de compresión no está acoplado o está roto." , question: "A compressor starts but makes a metallic noise and the amperage is very low. Suction and discharge pressures are nearly equal. What is the diagnosis?", options: ["Low refrigerant charge", "Excessive superheat", "Compressor with internal mechanical failure (broken connecting rod or destroyed valves)", "Damaged run capacitor"], explanation: "If the motor turns but there is no pressure differential, the compression mechanism is either not engaged or is broken." },

  // -- Aire, Psicrometría y Heat Pumps (101-200) --
  { id:"nate_101", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede con la Entalpía del aire si la temperatura de Bulbo Seco aumenta pero la de Bulbo Húmedo se mantiene constante?", opciones:["La entalpía aumenta", "La entalpía disminuye", "La entalpía se mantiene igual", "La humedad relativa sube"], respuesta_correcta:2, explicacion:"La entalpía (contenido total de calor) está directamente ligada a la temperatura de Bulbo Húmedo. Si el Bulbo Húmedo no cambia, el calor total del aire es el mismo." , question: "What happens to the enthalpy of air if the dry-bulb temperature increases but the wet-bulb temperature remains constant?", options: ["Enthalpy increases", "Enthalpy decreases", "Enthalpy stays the same", "Relative humidity rises"], explanation: "Enthalpy (total heat content) is directly tied to the wet-bulb temperature. If the wet-bulb does not change, the total heat of the air remains the same." },
  { id:"nate_102", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si duplicas la velocidad del aire en un ducto, ¿qué sucede con la Presión Estática?", opciones:["Se duplica", "Se triplica", "Se cuadruplica", "Se reduce a la mitad"], respuesta_correcta:2, explicacion:"Según las leyes de los ventiladores, la presión estática varía con el cuadrado del cambio de velocidad (o CFM)." , question: "If you double the air velocity in a duct, what happens to the static pressure?", options: ["It doubles", "It triples", "It quadruples", "It is cut in half"], explanation: "According to the fan laws, static pressure varies with the square of the change in velocity (or CFM)." },
  { id:"nate_103", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es el propósito de un 'EPR' (Evaporator Pressure Regulator) en un sistema de múltiples evaporadores?", opciones:["Mantener una presión mínima en el evaporador para evitar que el producto se congele", "Controlar la velocidad del compresor", "Evitar que el aceite regrese al compresor", "Sustituir a la TXV"], respuesta_correcta:0, explicacion:"El EPR mantiene una presión constante en el evaporador independientemente de la presión de succión común del rack de compresores." , question: "What is the purpose of an EPR (Evaporator Pressure Regulator) in a multiple-evaporator system?", options: ["Maintain a minimum pressure in the evaporator to prevent the product from freezing", "Control compressor speed", "Prevent oil from returning to the compressor", "Replace the TXV"], explanation: "The EPR maintains a constant evaporator pressure regardless of the common suction pressure of the compressor rack." },
  { id:"nate_104", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué punto en la carta psicrométrica indica que el aire está al 100% de saturación?", opciones:["Punto de rocío", "Bulbo seco", "Calor sensible", "Relación de humedad"], respuesta_correcta:0, explicacion:"En el punto de rocío, el aire no puede retener más vapor de agua y comienza la condensación; las temperaturas de bulbo seco y húmedo son iguales." , question: "What point on the psychrometric chart indicates that the air is at 100% saturation?", options: ["Dew point", "Dry bulb", "Sensible heat", "Humidity ratio"], explanation: "At the dew point, the air cannot hold any more water vapor and condensation begins; the dry-bulb and wet-bulb temperatures are equal." },
  { id:"nate_105", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un cliente se queja de que su casa está húmeda (70% RH) aunque el termostato marca 72°F. El equipo es de 5 toneladas para una casa de 1,200 sq ft. ¿Cuál es el problema?", opciones:["El equipo es muy pequeño", "El equipo está sobredimensionado (short-cycling)", "Falta refrigerante", "El filtro está sucio"], respuesta_correcta:1, explicacion:"Un equipo muy grande enfría el aire tan rápido que se apaga antes de tener tiempo de remover la humedad (calor latente)." , question: "A customer complains that the house is humid (70% RH) even though the thermostat reads 72 degrees F. The system is 5 tons for a 1,200 sq ft home. What is the problem?", options: ["The equipment is too small", "The equipment is oversized (short-cycling)", "Low refrigerant charge", "The filter is dirty"], explanation: "An oversized unit cools the air so quickly that it shuts off before having enough time to remove moisture (latent heat)." },
  { id:"nate_106", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función de una resistencia de 'Anticipación de Calor' (Heat Anticipator) en un termostato mecánico?", opciones:["Calentar la casa más rápido", "Evitar que la temperatura de la habitación suba más allá del setpoint (overshooting)", "Proteger el transformador", "Encender el ventilador"], respuesta_correcta:1, explicacion:"Genera un calor falso dentro del termostato para que este apague la calefacción un poco antes de llegar a la temperatura, usando el calor remanente en los ductos para finalizar el ciclo." , question: "What is the function of a heat anticipator in a mechanical thermostat?", options: ["Heat the house faster", "Prevent the room temperature from rising above the setpoint (overshooting)", "Protect the transformer", "Turn on the fan"], explanation: "It generates false heat inside the thermostat so it shuts off the furnace slightly before reaching the setpoint, using residual heat in the ductwork to finish the cycle." },
  { id:"nate_107", categoria:"NATE_AIRE_HEATPUMP", pregunta:"En un sistema de congelación con deshielo por gas caliente, ¿qué válvula se abre para permitir que el vapor de descarga entre al evaporador?", opciones:["TXV", "Válvula solenoide de deshielo", "Check valve", "EPR"], respuesta_correcta:1, explicacion:"Esta válvula desvía gas caliente directamente del compresor al evaporador para derretir el hielo desde adentro hacia afuera." , question: "In a freezer system with hot gas defrost, which valve opens to allow discharge vapor into the evaporator?", options: ["TXV", "Defrost solenoid valve", "Check valve", "EPR"], explanation: "This valve diverts hot gas directly from the compressor to the evaporator to melt ice from the inside out." },
  { id:"nate_108", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Para medir la Presión Total en un ducto usando un Tubo Pitot, ¿hacia dónde debe apuntar la punta del tubo?", opciones:["Hacia la pared del ducto", "En contra del flujo de aire (hacia donde viene el aire)", "A favor del flujo de aire", "Hacia afuera del ducto"], respuesta_correcta:1, explicacion:"El orificio frontal del Tubo Pitot captura la presión de impacto (velocidad) más la presión estática, dando la Presión Total." , question: "To measure total pressure in a duct using a Pitot tube, which direction should the tip of the tube face?", options: ["Toward the duct wall", "Against the airflow (facing where the air is coming from)", "In the direction of airflow", "Outside the duct"], explanation: "The front opening of the Pitot tube captures the impact pressure (velocity) plus the static pressure, giving the total pressure." },
  { id:"nate_109", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es el efecto de una línea de succión sin aislamiento en un ático a 130°F?", opciones:["Aumenta el Superheat y reduce la eficiencia/capacidad del sistema", "Mejora el enfriamiento del compresor", "Baja la presión de descarga", "No afecta en nada"], respuesta_correcta:0, explicacion:"El gas frío absorbe calor del ático, expandiéndose. El compresor ahora debe bombear gas menos denso, moviendo menos masa de refrigerante." , question: "What is the effect of an uninsulated suction line in an attic at 130 degrees F?", options: ["Increases superheat and reduces system efficiency/capacity", "Improves compressor cooling", "Lowers discharge pressure", "Has no effect"], explanation: "The cold gas absorbs heat from the attic, expanding. The compressor must then pump less-dense gas, moving less refrigerant mass." },
  { id:"nate_110", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué material está ESTRICTAMENTE prohibido usar en tuberías de sistemas que operan con Amoníaco (R-717)?", opciones:["Acero negro", "Acero inoxidable", "Cobre y sus aleaciones", "Aluminio"], respuesta_correcta:2, explicacion:"El amoníaco corroe agresivamente el cobre en presencia de humedad, destruyendo las tuberías y componentes rápidamente." , question: "What material is STRICTLY prohibited for use in piping for ammonia (R-717) systems?", options: ["Black steel", "Stainless steel", "Copper and its alloys", "Aluminum"], explanation: "Ammonia aggressively corrodes copper in the presence of moisture, rapidly destroying piping and components." },
  { id:"nate_111", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si reduces la velocidad del soplador (blower) de 400 CFM/ton a 325 CFM/ton, ¿qué sucede con la remoción de humedad?", opciones:["La remoción de humedad disminuye", "La remoción de humedad aumenta", "Se mantiene igual", "El compresor se sobrecalienta"], respuesta_correcta:1, explicacion:"Al pasar el aire más lento por el serpentín, este se enfría más (baja el punto de rocío del serpentín), condensando más agua del aire." , question: "If you reduce the blower speed from 400 CFM/ton to 325 CFM/ton, what happens to moisture removal?", options: ["Moisture removal decreases", "Moisture removal increases", "It stays the same", "The compressor overheats"], explanation: "With air passing more slowly over the coil, it cools further (lowering the coil's dew point), condensing more water from the air." },
  { id:"nate_112", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si una polea del motor tiene 4 pulgadas de diámetro y gira a 1725 RPM, y la polea del ventilador tiene 8 pulgadas, ¿a qué velocidad gira el ventilador?", opciones:["3450 RPM", "862.5 RPM", "1725 RPM", "1000 RPM"], respuesta_correcta:1, explicacion:"Relación de transmisión: (D1 * RPM1) = (D2 * RPM2). (4 * 1725) / 8 = 862.5 RPM." , question: "If a motor pulley is 4 inches in diameter and turns at 1725 RPM, and the fan pulley is 8 inches, at what speed does the fan turn?", options: ["3450 RPM", "862.5 RPM", "1725 RPM", "1000 RPM"], explanation: "Pulley ratio: (D1 x RPM1) = (D2 x RPM2). (4 x 1725) / 8 = 862.5 RPM." },
  { id:"nate_113", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un visor de líquido está lleno (limpio) y el Subcooling es de 12°F, pero el evaporador se congela en la entrada. ¿Causa probable?", opciones:["Falta de refrigerante", "Filtro de aire sucio o falta de flujo", "Restricción parcial en el distribuidor del evaporador", "Compresor ineficiente"], respuesta_correcta:2, explicacion:"Si la carga es correcta (buen SC y visor lleno), pero solo una parte del evaporador se congela, el problema es una mala distribución del líquido." , question: "A sight glass is full (clear) and subcooling is 12 degrees F, but the evaporator freezes at the inlet. What is the probable cause?", options: ["Low refrigerant charge", "Dirty air filter or lack of airflow", "Partial restriction in the evaporator distributor", "Inefficient compressor"], explanation: "If the charge is correct (good subcooling and clear sight glass) but only part of the evaporator freezes, the problem is poor liquid distribution." },
  { id:"nate_114", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué instrumento se usa manualmente para medir las temperaturas de bulbo seco y húmedo simultáneamente?", opciones:["Anemómetro", "Psicrómetro de honda (Sling Psychrometer)", "Manómetro", "Termómetro infrarrojo"], respuesta_correcta:1, explicacion:"Consiste en dos termómetros que se giran en el aire para obtener ambas lecturas mediante la evaporación en la mecha húmeda." , question: "What instrument is used manually to measure dry-bulb and wet-bulb temperatures simultaneously?", options: ["Anemometer", "Sling psychrometer", "Manifold gauge", "Infrared thermometer"], explanation: "It consists of two thermometers that are whirled in the air to obtain both readings through the evaporation of the wet wick." },
  { id:"nate_115", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede si el tubo capilar del bulbo de una TXV toca un cable eléctrico con voltaje?", opciones:["Nada, el capilar es de cobre", "El arco eléctrico puede perforar el capilar, perdiendo la carga y cerrando la válvula", "Mejora la lectura de temperatura", "La válvula se abre más"], respuesta_correcta:1, explicacion:"El capilar es muy delgado. Un corto circuito lo perfora instantáneamente, dejando escapar el gas de potencia y dejando el sistema sin flujo de refrigerante." , question: "What happens if the capillary tube of a TXV sensing bulb touches a live electrical wire?", options: ["Nothing; the capillary is copper", "An electrical arc can puncture the capillary, losing its charge and closing the valve", "It improves the temperature reading", "The valve opens wider"], explanation: "The capillary tube is very thin. A short circuit can puncture it instantly, allowing the power element charge to escape and leaving the system without refrigerant flow." },
  { id:"nate_116", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un motor de 208V tiene una potencia de salida de 3 HP y una eficiencia del 85%. ¿Cuál es el consumo en Watts de entrada?", opciones:["2238 W", "2633 W", "1902 W", "3000 W"], respuesta_correcta:1, explicacion:"1 HP = 746W. Salida = 3 * 746 = 2238W. Entrada = Salida / Eficiencia = 2238 / 0.85 = 2632.9W." , question: "A 208V motor has an output of 3 HP and an efficiency of 85%. What is the input power in Watts?", options: ["2238 W", "2633 W", "1902 W", "3000 W"], explanation: "1 HP = 746W. Output = 3 x 746 = 2238W. Input = Output / Efficiency = 2238 / 0.85 = 2632.9W." },
  { id:"nate_117", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Por qué el aceite mineral no se mezcla (no es miscible) con el refrigerante R-410A?", opciones:["Porque el R-410A es muy frío", "Debido a la diferencia de polaridad química entre el refrigerante HFC y el aceite mineral", "Porque el aceite mineral es más espeso", "Porque el R-410A contiene cloro"], respuesta_correcta:1, explicacion:"Los HFCs no tienen cloro y son polares, requiriendo aceites sintéticos como el POE para poder transportar el aceite de regreso al compresor." , question: "Why is mineral oil not miscible with R-410A refrigerant?", options: ["Because R-410A is very cold", "Due to the difference in chemical polarity between the HFC refrigerant and mineral oil", "Because mineral oil is thicker", "Because R-410A contains chlorine"], explanation: "HFCs have no chlorine and are polar, requiring synthetic oils like POE to transport oil back to the compressor." },
  { id:"nate_118", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la lectura de Presión Estática Externa (ESP) máxima recomendada para la mayoría de las manejadoras de aire residenciales?", opciones:["0.10\" iwc", "0.50\" iwc", "1.5\" iwc", "2.0\" iwc"], respuesta_correcta:1, explicacion:"La mayoría de los ventiladores PSC están diseñados para mover 400 CFM/ton a 0.5 pulgadas de columna de agua. Arriba de eso, el flujo cae drásticamente." , question: "What is the maximum recommended external static pressure (ESP) for most residential air handlers?", options: ["0.10 inches WC", "0.50 inches WC", "1.5 inches WC", "2.0 inches WC"], explanation: "Most PSC blowers are designed to move 400 CFM/ton at 0.5 inches of water column. Above that, airflow drops drastically." },
  { id:"nate_119", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función de un control de 'Head Pressure' (presión de alta) en unidades que operan en invierno?", opciones:["Apagar el compresor", "Reducir la velocidad del ventilador del condensador para mantener la presión de alta", "Encender la calefacción", "Abrir la TXV al máximo"], respuesta_correcta:1, explicacion:"En climas fríos, el condensador es demasiado eficiente y la presión de alta cae tanto que la TXV no recibe suficiente presión para alimentar el evaporador." , question: "What is the function of a head pressure control on units that operate in winter?", options: ["Shut off the compressor", "Reduce the condenser fan speed to maintain adequate head pressure", "Turn on the heat", "Open the TXV fully"], explanation: "In cold weather, the condenser is too efficient and head pressure drops so low that the TXV does not receive enough pressure to properly feed the evaporator." },
  { id:"nate_120", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Mides un compresor y encuentras 2.0 Ohms entre C-R y 5.0 Ohms entre C-S. El total entre S-R es 7.0 Ohms. ¿Cuál es el diagnóstico?", opciones:["Bobinado en corto", "Bobinado abierto", "Motor eléctricamente sano", "Bobinado aterrizado"], respuesta_correcta:2, explicacion:"En motores monofásicos (PSC/CSCR), la suma de C-R + C-S debe ser igual a S-R. 2 + 5 = 7. El motor está bien." , question: "You measure a compressor and find 2.0 Ohms between C-R and 5.0 Ohms between C-S. The total between S-R is 7.0 Ohms. What is the diagnosis?", options: ["Shorted winding", "Open winding", "Motor is electrically sound", "Grounded winding"], explanation: "In single-phase motors (PSC/CSCR), the sum of C-R + C-S must equal S-R. 2 + 5 = 7. The motor is good." },
  { id:"nate_121", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si un serpentín de evaporador está operando por ENCIMA de la temperatura de punto de rocío del aire que entra, ¿qué tipo de enfriamiento ocurre?", opciones:["Enfriamiento latente solamente", "Enfriamiento sensible solamente (serpentín seco)", "Deshumidificación total", "Congelación inmediata"], respuesta_correcta:1, explicacion:"Si el metal no está más frío que el punto de rocío, el agua no se condensa. Solo baja la temperatura del aire sin quitarle humedad." , question: "If an evaporator coil is operating ABOVE the dew point temperature of the incoming air, what type of cooling occurs?", options: ["Latent cooling only", "Sensible cooling only (dry coil)", "Total dehumidification", "Immediate freezing"], explanation: "If the coil surface is not colder than the dew point, water does not condense. Only the air temperature drops without removing humidity." },
  { id:"nate_122", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Al verificar un sensor de temperatura tipo NTC (Negative Temperature Coefficient), ¿qué lectura esperas obtener al calentar el sensor?", opciones:["La resistencia aumenta", "La resistencia disminuye", "La resistencia se mantiene igual", "El voltaje desaparece"], respuesta_correcta:1, explicacion:"NTC significa que la resistencia baja cuando la temperatura sube. Es el tipo de sensor más común en HVAC." , question: "When testing an NTC (Negative Temperature Coefficient) temperature sensor, what reading do you expect when heating the sensor?", options: ["Resistance increases", "Resistance decreases", "Resistance stays the same", "Voltage disappears"], explanation: "NTC means resistance goes down as temperature goes up. It is the most common sensor type in HVAC." },
  { id:"nate_123", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué función cumple la 'Trampa de Aceite' (P-trap) en una línea de succión vertical de más de 20 pies?", opciones:["Detener la basura", "Atrapar aceite para que el gas pueda succionarlo y subirlo por la tubería", "Evitar inundaciones", "Bajar la presión"], respuesta_correcta:1, explicacion:"El aceite tiende a caer por gravedad. La trampa lo acumula en un punto hasta que el flujo de gas es lo suficientemente rápido para arrastrarlo hacia arriba." , question: "What function does an oil trap (P-trap) serve in a vertical suction line of more than 20 feet?", options: ["Stop debris", "Trap oil so that the gas velocity can pick it up and carry it up the riser", "Prevent flooding", "Lower the pressure"], explanation: "Oil tends to fall by gravity. The trap accumulates it at a point until the gas flow velocity is fast enough to carry it upward." },
  { id:"nate_124", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función de un 'Economizer' en una unidad de paquete (RTU)?", opciones:["Ahorrar gas en la calefacción", "Usar aire exterior fresco para enfriar el edificio cuando el clima externo es favorable (Free Cooling)", "Reducir el voltaje del compresor", "Limpiar el aire con ozono"], respuesta_correcta:1, explicacion:"Si afuera hace frío y hay baja humedad, el economizador abre compuertas para enfriar sin encender el compresor." , question: "What is the function of an economizer on a rooftop unit (RTU)?", options: ["Save gas on heating", "Use outside fresh air to cool the building when outdoor conditions are favorable (free cooling)", "Reduce compressor voltage", "Clean the air with ozone"], explanation: "If outside air is cool and low in humidity, the economizer opens dampers to provide cooling without running the compressor." },
  { id:"nate_125", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Después de reparar una fuga y antes de cargar, el vacío llega a 500 micrones pero sube a 4000 micrones en 5 minutos y se detiene ahí. ¿Qué significa?", opciones:["Todavía hay una fuga", "Hay humedad o refrigerante atrapado en el aceite", "La bomba de vacío falló", "El sistema está listo para cargar"], respuesta_correcta:1, explicacion:"Un aumento que se estabiliza indica 'outgassing' (evaporación de contaminantes). Si subiera sin detenerse hasta la atmósfera, sería una fuga." , question: "After repairing a leak, the vacuum reaches 500 microns before charging, but rises to 4000 microns within 5 minutes and stops there. What does this mean?", options: ["There is still a leak", "There is moisture or trapped refrigerant in the oil", "The vacuum pump failed", "The system is ready to charge"], explanation: "A rise that stabilizes indicates outgassing (evaporation of contaminants). If it rose continuously to atmospheric pressure, it would be a leak." },
  { id:"nate_126", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la fórmula para calcular el calor sensible total en el aire?", opciones:["BTU = CFM * 0.68 * ΔGr", "BTU = CFM * 1.08 * ΔT", "BTU = CFM * 4.5 * ΔH", "BTU = Volts * Amps"], respuesta_correcta:1, explicacion:"Es la fórmula estándar para calor sensible a nivel del mar (1.08 es el factor que incluye densidad del aire y calor específico)." , question: "What is the formula for calculating total sensible heat in air?", options: ["BTU = CFM x 0.68 x Delta Grains", "BTU = CFM x 1.08 x Delta T", "BTU = CFM x 4.5 x Delta H", "BTU = Volts x Amps"], explanation: "This is the standard sensible heat formula at sea level (1.08 is the factor that includes air density and specific heat)." },
  { id:"nate_127", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuándo es obligatorio instalar un filtro deshidratador de succión?", opciones:["En cada instalación nueva", "Después de que un compresor se ha quemado (burnout)", "Cuando falta refrigerante", "Cuando el cliente lo pida"], respuesta_correcta:1, explicacion:"Se usa para atrapar ácidos y carbón residual que el filtro de la línea de líquido no puede capturar antes de que dañen el nuevo compresor." , question: "When is it mandatory to install a suction line filter drier?", options: ["On every new installation", "After a compressor burnout", "When the system is low on refrigerant", "When the customer requests it"], explanation: "It is used to capture acids and carbon residue that the liquid line filter drier cannot trap before they damage the new compressor." },
  { id:"nate_128", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Mides un capacitor de 45/5 µF. Entre la terminal HERM y C mides 20 µF. ¿Qué efecto tiene esto en el compresor?", opciones:["El compresor consumirá menos amperios", "El compresor se sobrecalentará y probablemente se apagará por protector térmico", "El compresor girará más rápido", "No pasa nada, 20 µF es suficiente"], respuesta_correcta:1, explicacion:"Una capacitancia baja reduce el torque y aumenta el desbalance de corriente en los bobinados, causando calor excesivo." , question: "You measure a 45/5 uF dual capacitor. Between the HERM terminal and C you read 20 uF. What effect does this have on the compressor?", options: ["The compressor will draw less amps", "The compressor will overheat and likely shut off on thermal overload", "The compressor will run faster", "No effect; 20 uF is sufficient"], explanation: "Low capacitance reduces torque and increases the current imbalance in the windings, causing excessive heat." },
  { id:"nate_129", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué refrigerante es un reemplazo común para el R-22 en sistemas existentes, pero requiere cambio de aceite a POE?", opciones:["R-410A", "R-407C", "R-123", "R-134a"], respuesta_correcta:1, explicacion:"El R-407C tiene presiones similares al R-22, pero al ser un HFC, requiere aceite POE para lubricar correctamente." , question: "What refrigerant is a common drop-in replacement for R-22 in existing systems but requires an oil change to POE?", options: ["R-410A", "R-407C", "R-123", "R-134a"], explanation: "R-407C has operating pressures similar to R-22, but as an HFC, it requires POE oil for proper lubrication." },
  { id:"nate_130", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la velocidad máxima recomendada del aire en un ducto de retorno residencial para evitar ruidos excesivos?", opciones:["400 fpm", "600 fpm", "1200 fpm", "2000 fpm"], respuesta_correcta:1, explicacion:"Ductos de suministro pueden aguantar hasta 800-900 fpm, pero los retornos deben ser más lentos (600 fpm) para ser silenciosos." , question: "What is the maximum recommended air velocity in a residential return air duct to avoid excessive noise?", options: ["400 fpm", "600 fpm", "1200 fpm", "2000 fpm"], explanation: "Supply ducts can handle up to 800-900 fpm, but return ducts should be slower (600 fpm) to remain quiet." },
  { id:"nate_131", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función del 'Termostato de Fin de Deshielo' (Defrost Termination Switch)?", opciones:["Encender los ventiladores", "Terminar el ciclo de deshielo cuando el serpentín alcanza una temperatura segura (ej. 55°F) para evitar calentar el cuarto innecesariamente", "Apagar el compresor", "Iniciar el reloj de deshielo"], respuesta_correcta:1, explicacion:"Evita que las resistencias sigan calentando una vez que ya no hay hielo, protegiendo el equipo y el producto." , question: "What is the function of the defrost termination switch?", options: ["Turn on the fans", "Terminate the defrost cycle when the coil reaches a safe temperature (e.g., 55 degrees F) to prevent unnecessarily heating the space", "Shut off the compressor", "Start the defrost timer"], explanation: "It prevents the heaters from continuing to heat once the ice is gone, protecting both the equipment and the stored product." },
  { id:"nate_132", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un sistema de bomba de calor (Heat Pump) sopla aire frío en modo calefacción. La presión de descarga es baja y la de succión es alta. ¿Cuál es el problema?", opciones:["Falta de refrigerante", "Válvula inversora (reversing valve) con fuga interna", "Compresor trabado", "Filtro sucio"], respuesta_correcta:1, explicacion:"Si la válvula no sella bien, el gas caliente de descarga se fuga directamente a la succión (bypassing), igualando las presiones y perdiendo capacidad." , question: "A heat pump system blows cold air in heating mode. Discharge pressure is low and suction pressure is high. What is the problem?", options: ["Low refrigerant charge", "Reversing valve with internal leak", "Locked compressor", "Dirty filter"], explanation: "If the valve does not seal properly, hot discharge gas leaks directly to suction (bypassing), equalizing pressures and losing capacity." },
  { id:"nate_133", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si mides una temperatura de suministro de 55°F y el punto de rocío del aire de retorno es 58°F, ¿qué sucederá en el serpentín?", opciones:["El aire saldrá muy seco", "Habrá condensación masiva de agua (deshumidificación)", "El serpentín se congelará", "No pasará nada"], respuesta_correcta:1, explicacion:"Como la superficie está más fría que el punto de rocío del aire, el agua pasará obligatoriamente de vapor a líquido." , question: "If you measure a supply air temperature of 55 degrees F and the return air dew point is 58 degrees F, what will happen at the coil?", options: ["The air will come out very dry", "There will be heavy condensation (dehumidification)", "The coil will freeze", "Nothing will happen"], explanation: "Since the coil surface is colder than the dew point of the air, water must change from vapor to liquid." },
  { id:"nate_134", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede si conectas un transformador de 240V/24V a una línea de 208V?", opciones:["Se quema el transformador", "El voltaje de salida será de aproximadamente 20.8V", "El voltaje de salida seguirá siendo 24V", "El transformador explotará"], respuesta_correcta:1, explicacion:"Los transformadores operan por relación de vueltas. Si bajas el voltaje de entrada en un 13%, la salida bajará en la misma proporción." , question: "What happens if you connect a 240V/24V transformer to a 208V supply line?", options: ["The transformer burns out", "The output voltage will be approximately 20.8V", "The output voltage will remain 24V", "The transformer will explode"], explanation: "Transformers operate by turns ratio. If you reduce the input voltage by 13%, the output drops by the same proportion." },
  { id:"nate_135", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Al cargar refrigerante líquido en un sistema, ¿cuál es el equipo de protección personal (PPE) más importante?", opciones:["Botas de punta de acero", "Guantes térmicos y protección ocular (goggles)", "Casco", "Chaleco reflectante"], respuesta_correcta:1, explicacion:"El refrigerante líquido puede causar ceguera instantánea o quemaduras por congelación severas en contacto con la piel." , question: "When charging liquid refrigerant into a system, what is the most important piece of personal protective equipment (PPE)?", options: ["Steel-toed boots", "Thermal gloves and eye protection (safety goggles)", "Hard hat", "Reflective vest"], explanation: "Liquid refrigerant can cause instant blindness or severe frostbite burns on contact with skin." },
  { id:"nate_136", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿En qué dirección debe instalarse una válvula solenoide en la línea de líquido?", opciones:["En cualquier dirección", "Con la flecha apuntando hacia el dispositivo de expansión", "Con la flecha apuntando hacia el condensador", "Verticalmente hacia abajo siempre"], respuesta_correcta:1, explicacion:"Las solenoides son válvulas direccionales; si se instalan al revés, la presión del sistema puede abrirlas aunque la bobina esté apagada." , question: "In which direction should a solenoid valve be installed on the liquid line?", options: ["In any direction", "With the arrow pointing toward the metering device", "With the arrow pointing toward the condenser", "Vertically downward always"], explanation: "Solenoid valves are directional; if installed backwards, system pressure can force them open even when the coil is de-energized." },
  { id:"nate_137", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un sistema tiene un Superheat de 5°F y un Subcooling de 5°F. ¿Cuál es el diagnóstico?", opciones:["Carga correcta", "Falta de refrigerante con flujo de aire bajo en el evaporador", "Sobrecarga de refrigerante", "TXV trabada abierta"], respuesta_correcta:1, explicacion:"El bajo SC indica falta de gas, pero el bajo SH indica que el evaporador no está recibiendo suficiente aire para evaporar incluso esa poca cantidad de gas." , question: "A system has a superheat of 5 degrees F and a subcooling of 5 degrees F. What is the diagnosis?", options: ["Correct charge", "Low refrigerant charge with low airflow across the evaporator", "Refrigerant overcharge", "TXV stuck open"], explanation: "Low subcooling indicates low charge, but low superheat indicates the evaporator is not receiving enough airflow to evaporate even that small amount of refrigerant." },
  { id:"nate_138", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Después de limpiar un condensador muy sucio, ¿qué cambios esperarías ver en el amperaje del compresor?", opciones:["El amperaje subirá", "El amperaje bajará", "El amperaje se mantendrá igual", "El amperaje oscilará"], respuesta_correcta:1, explicacion:"Menor presión de descarga = menos trabajo para el compresor = menor consumo eléctrico." , question: "After cleaning a very dirty condenser, what changes would you expect to see in compressor amperage?", options: ["Amperage will rise", "Amperage will drop", "Amperage will stay the same", "Amperage will fluctuate"], explanation: "Lower discharge pressure = less work for the compressor = lower electrical consumption." },
  { id:"nate_139", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función de un 'Phase Monitor' en un sistema trifásico comercial?", opciones:["Ahorrar energía", "Proteger contra pérdida de fase, inversión de fase o desbalance de voltaje", "Aumentar el torque de arranque", "Medir el consumo en Watts"], respuesta_correcta:1, explicacion:"Desconecta el circuito de control si la energía de entrada es peligrosa para los motores trifásicos." , question: "What is the function of a phase monitor in a three-phase commercial system?", options: ["Save energy", "Protect against phase loss, phase reversal, or voltage imbalance", "Increase starting torque", "Measure power consumption in Watts"], explanation: "It disconnects the control circuit if the incoming power is dangerous to three-phase motors." },
  { id:"nate_140", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Dónde debe colocarse un 'Vibration Eliminator' (eliminador de vibración flexible) en un sistema comercial?", opciones:["En la línea de líquido", "En las líneas de succión y descarga, paralelo al eje del cigüeñal del compresor", "En el medio del serpentín", "Cerca del termostato"], respuesta_correcta:1, explicacion:"Deben absorber el movimiento del compresor para que no se transmita a la tubería rígida y cause grietas." , question: "Where should a vibration eliminator (flexible connector) be placed in a commercial system?", options: ["On the liquid line", "On the suction and discharge lines, parallel to the compressor crankshaft axis", "In the middle of the coil", "Near the thermostat"], explanation: "They must absorb the compressor's movement to prevent it from transmitting to the rigid piping and causing cracks." },
  { id:"nate_141", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿A qué profundidad de vacío (micrones) se considera que se ha eliminado toda la humedad del sistema según la mayoría de los fabricantes?", opciones:["1000 micrones", "500 micrones", "50 micrones", "0 micrones"], respuesta_correcta:1, explicacion:"500 micrones es el estándar de la industria para asegurar un sistema seco y libre de gases no condensables." , question: "At what vacuum depth (microns) is it considered that all moisture has been removed from the system, according to most manufacturers?", options: ["1000 microns", "500 microns", "50 microns", "0 microns"], explanation: "500 microns is the industry standard to ensure a dry system free of non-condensable gases." },
  { id:"nate_142", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Por qué un acumulador de succión tiene un pequeño orificio (metering orifice) en el tubo de salida interno?", opciones:["Para que el refrigerante pase rápido", "Para permitir el retorno de aceite al compresor de forma controlada", "Para medir la presión", "Para filtrar basura"], respuesta_correcta:1, explicacion:"El aceite se queda en el fondo del acumulador; el orificio permite que el compresor lo succione poco a poco sin succionar líquido masivo." , question: "Why does a suction accumulator have a small metering orifice in the internal outlet tube?", options: ["To let refrigerant pass quickly", "To allow controlled oil return to the compressor", "To measure pressure", "To filter debris"], explanation: "Oil settles at the bottom of the accumulator; the orifice allows the compressor to draw it back gradually without ingesting a massive slug of liquid." },
  { id:"nate_143", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cómo afecta la gran altitud (ej. 5000 pies sobre el nivel del mar) al volumen de aire requerido por tonelada?", opciones:["Se requiere menos CFM", "Se requiere más CFM para compensar el aire menos denso", "Se requiere el mismo CFM", "El compresor no arranca"], respuesta_correcta:1, explicacion:"Como el aire es menos denso, tiene menos moléculas para transportar calor; por lo tanto, necesitas mover un mayor volumen (CFM) para obtener la misma capacidad de enfriamiento." , question: "How does high altitude (e.g., 5000 feet above sea level) affect the volume of air required per ton?", options: ["Less CFM is required", "More CFM is required to compensate for thinner air", "The same CFM is required", "The compressor won't start"], explanation: "Because the air is less dense, it carries fewer molecules to transport heat; therefore, a greater volume (CFM) must be moved to achieve the same cooling capacity." },
  { id:"nate_144", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Encuentras hielo solo en las primeras dos vueltas del serpentín del evaporador. El resto está seco y caliente. ¿Qué indica esto?", opciones:["Exceso de refrigerante", "Sistema severamente bajo en refrigerante", "Motor del soplador quemado", "Filtro sucio"], respuesta_correcta:1, explicacion:"El poco refrigerante que hay se evapora inmediatamente al entrar al serpentín, enfriando solo el inicio y dejando el resto del evaporador sin efecto." , question: "You find ice only on the first two passes of the evaporator coil. The rest is dry and warm. What does this indicate?", options: ["Excess refrigerant", "System is severely low on refrigerant", "Burned blower motor", "Dirty filter"], explanation: "The small amount of refrigerant present evaporates immediately upon entering the coil, cooling only the beginning and leaving the rest of the evaporator with no effect." },
  { id:"nate_145", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un motor de soplador de 1/2 HP marca 'O.L' entre la terminal de marcha y común, pero tiene continuidad entre marcha y arranque. ¿Cuál es el diagnóstico?", opciones:["Motor bueno", "Bobinado común abierto internamente", "Motor en corto a tierra", "Capacitor dañado"], respuesta_correcta:1, explicacion:"Si no hay continuidad hacia la terminal común, el circuito no se puede completar. El motor no funcionará." , question: "A 1/2 HP blower motor reads 'OL' between the run terminal and common, but has continuity between run and start. What is the diagnosis?", options: ["Motor is good", "Common winding is open internally", "Motor is shorted to ground", "Capacitor is damaged"], explanation: "If there is no continuity to the common terminal, the circuit cannot be completed. The motor will not operate." },
  { id:"nate_146", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la principal restricción para usar el método Push-Pull en una recuperación?", opciones:["No se puede usar en sistemas con menos de 15 libras de refrigerante", "No se puede usar si el compresor no funciona", "Requiere usar nitrógeno", "Solo funciona con R-22"], respuesta_correcta:0, explicacion:"En sistemas pequeños, el tiempo de configuración y la pérdida de gas en las mangueras anulan la ventaja de velocidad del método." , question: "What is the main limitation of the push-pull recovery method?", options: ["It cannot be used on systems with less than 15 pounds of refrigerant", "It cannot be used if the compressor does not work", "It requires using nitrogen", "It only works with R-22"], explanation: "On small systems, the setup time and refrigerant loss in the hoses negate the speed advantage of the method." },
  { id:"nate_147", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la secuencia de operación en un ciclo de 'Pump Down' automático?", opciones:["El termostato apaga el compresor", "El termostato cierra la solenoide de líquido, el compresor sigue operando hasta que el presostato de baja detecta el vacío y lo apaga", "El presostato de alta apaga el sistema", "La TXV se cierra sola"], respuesta_correcta:1, explicacion:"Esto asegura que todo el refrigerante se almacene en el condensador/recibidor durante el apagado, evitando arranques inundados." , question: "What is the sequence of operation in an automatic pump-down cycle?", options: ["The thermostat shuts off the compressor", "The thermostat closes the liquid line solenoid; the compressor continues running until the low-pressure switch detects vacuum and shuts it off", "The high-pressure switch shuts off the system", "The TXV closes by itself"], explanation: "This ensures all refrigerant is stored in the condenser/receiver during shutdown, preventing flooded starts." },
  { id:"nate_148", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué significa 'Azeótropo'?", opciones:["Una mezcla de refrigerantes que se comporta como un solo refrigerante puro (sin glide)", "Un refrigerante inflamable", "Un gas que destruye la capa de ozono", "Un aceite sintético"], respuesta_correcta:0, explicacion:"Ejemplo: El R-502. Sus componentes se evaporan y condensan a la misma temperatura, por lo que no tiene Glide." , question: "What does 'azeotrope' mean?", options: ["A refrigerant blend that behaves like a single pure refrigerant (no glide)", "A flammable refrigerant", "A gas that destroys the ozone layer", "A synthetic oil"], explanation: "Example: R-502. Its components evaporate and condense at the same temperature, so it has no glide." },
  { id:"nate_149", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si un compresor tiene un nivel de aceite bajo pero no hay fugas, ¿qué debes revisar primero?", opciones:["Agregar 1 litro de aceite", "Verificar la velocidad del gas en las líneas de succión y trampas de aceite", "Cambiar el compresor", "Limpiar el condensador"], respuesta_correcta:1, explicacion:"El aceite probablemente está 'atrapado' en el evaporador o líneas debido a tuberías de diámetro incorrecto o falta de trampas." , question: "If a compressor has a low oil level but there are no leaks, what should you check first?", options: ["Add 1 liter of oil", "Check the gas velocity in suction lines and oil traps", "Replace the compressor", "Clean the condenser"], explanation: "The oil is likely trapped in the evaporator or piping due to incorrect pipe sizing or missing oil traps." },
  { id:"nate_150", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un sistema comercial usa una TXV con igualación EXTERNA. ¿Dónde debe conectarse la línea de igualación?", opciones:["En la línea de líquido", "En la línea de succión, inmediatamente después del bulbo sensor de la TXV", "En la descarga del compresor", "Antes del bulbo sensor"], respuesta_correcta:1, explicacion:"Debe medir la presión justo a la salida del evaporador para compensar la caída de presión interna del serpentín y que la TXV abra correctamente." , question: "A commercial system uses a TXV with an EXTERNAL equalizer. Where should the equalizer line be connected?", options: ["On the liquid line", "On the suction line, immediately after the TXV sensing bulb", "On the compressor discharge", "Before the sensing bulb"], explanation: "It must measure the pressure right at the evaporator outlet to compensate for the internal pressure drop across the coil so the TXV opens correctly." },
  { id:"nate_151", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función del 'Roll-out Switch' en una calefacción a gas?", opciones:["Encender el quemador", "Detectar si las llamas se están saliendo del intercambiador de calor hacia el gabinete", "Medir el flujo de aire", "Controlar la presión del gas"], respuesta_correcta:1, explicacion:"Es un dispositivo de seguridad térmica que corta el gas si hay una obstrucción en el intercambiador o falta de tiro, evitando un incendio." , question: "What is the function of a roll-out switch on a gas furnace?", options: ["Ignite the burner", "Detect if flames are rolling out of the heat exchanger into the furnace cabinet", "Measure airflow", "Control gas pressure"], explanation: "It is a thermal safety device that shuts off the gas if there is an obstruction in the heat exchanger or a lack of draft, preventing a fire." },
  { id:"nate_152", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Durante el ciclo de 'Defrost' en una bomba de calor, ¿qué sucede con el ventilador de la unidad exterior?", opciones:["Gira a máxima velocidad", "Se apaga para acelerar el calentamiento del serpentín", "Gira en reversa", "Cambia a velocidad baja"], respuesta_correcta:1, explicacion:"Al apagar el ventilador exterior, el calor del refrigerante se concentra en derretir el hielo del serpentín en lugar de perderse en el aire ambiente." , question: "During the defrost cycle on a heat pump, what happens to the outdoor unit fan?", options: ["It runs at maximum speed", "It shuts off to accelerate coil heating", "It runs in reverse", "It switches to low speed"], explanation: "By shutting off the outdoor fan, the refrigerant's heat is concentrated on melting the ice from the coil rather than being lost to the ambient air." },
  { id:"nate_153", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cómo verifica la tarjeta de control (IFC) la presencia de llama mediante la varilla de ionización (Flame Sensor)?", opciones:["Midiendo la temperatura de la varilla", "Mediante la rectificación de una pequeña corriente AC a DC a través de la llama", "Midiendo la resistencia lumínica", "Por un contacto bimetálico"], respuesta_correcta:1, explicacion:"La llama actúa como un conductor que permite que la corriente fluya en un solo sentido. Si la IFC no detecta microamperios DC, cierra la válvula de gas." , question: "How does the integrated furnace control (IFC) board verify flame presence using the flame sensor (ionization rod)?", options: ["By measuring the rod's temperature", "By rectifying a small AC current to DC through the flame", "By measuring light resistance", "Through a bimetallic contact"], explanation: "The flame acts as a conductor that allows current to flow in one direction only. If the IFC does not detect microamps of DC, it closes the gas valve." },
  { id:"nate_154", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un cliente reporta olor a gas y el detector de CO se activa cuando arranca el soplador. ¿Cuál es el diagnóstico más probable?", opciones:["Fuga en la tubería de entrada", "Intercambiador de calor agrietado o perforado", "Piloto sucio", "Termostato mal calibrado"], respuesta_correcta:1, explicacion:"Cuando el soplador enciende, la presión del aire empuja los gases de combustión (y CO) a través de las grietas hacia el flujo de aire de la casa." , question: "A customer reports a gas smell and the CO detector activates when the blower starts. What is the most likely diagnosis?", options: ["Leak in the inlet gas piping", "Cracked or perforated heat exchanger", "Dirty pilot", "Miscalibrated thermostat"], explanation: "When the blower turns on, air pressure pushes combustion gases (including CO) through the cracks and into the home's airstream." },
  { id:"nate_155", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Para qué sirve el cable 'W2' o 'AUX' en un termostato de Heat Pump?", opciones:["Para el aire acondicionado", "Para activar la calefacción eléctrica de respaldo (Heat Strips) cuando la bomba de calor no es suficiente", "Para invertir la válvula", "Para la luz de emergencia"], respuesta_correcta:1, explicacion:"Es la 'segunda etapa' de calor que entra cuando la temperatura exterior es muy baja para que la bomba de calor sea eficiente." , question: "What is the purpose of the W2 or AUX wire on a heat pump thermostat?", options: ["For air conditioning", "To activate the backup electric heat strips when the heat pump alone is not sufficient", "To energize the reversing valve", "For the emergency light"], explanation: "It is the second stage of heat that engages when the outdoor temperature is too low for the heat pump to be efficient." },
  { id:"nate_156", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la presión de gas estándar requerida en el manifold para Gas Natural?", opciones:["11\" iwc", "3.5\" iwc", "0.5\" iwc", "1.5\" iwc"], respuesta_correcta:1, explicacion:"El Gas Natural opera normalmente a 3.5 pulgadas de columna de agua después del regulador. El Propano (LP) opera a 11\" iwc." , question: "What is the standard gas pressure required at the manifold for natural gas?", options: ["11 inches WC", "3.5 inches WC", "0.5 inches WC", "1.5 inches WC"], explanation: "Natural gas normally operates at 3.5 inches of water column after the regulator. Propane (LP) operates at 11 inches WC." },
  { id:"nate_157", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si el motor inductor de tiro (Draft Inducer) enciende, pero el quemador no, y el interruptor de presión (Pressure Switch) permanece abierto, ¿qué revisarías?", opciones:["El sensor de llama", "Obstrucciones en la chimenea o mangueras de condensado tapadas", "El voltaje del termostato", "La presión del tanque de gas"], respuesta_correcta:1, explicacion:"El Switch de Presión no cerrará si no detecta el vacío correcto, lo cual ocurre si hay nidos de pájaros, nieve o agua bloqueando el escape." , question: "If the draft inducer motor starts but the burner does not ignite and the pressure switch remains open, what would you check?", options: ["The flame sensor", "Obstructions in the flue or clogged condensate hoses", "The thermostat voltage", "The gas tank pressure"], explanation: "The pressure switch will not close if it does not detect the correct vacuum, which occurs if bird nests, snow, or water are blocking the exhaust." },
  { id:"nate_158", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué componente evita que el refrigerante líquido regrese al compresor cuando el sistema cambia bruscamente de modo frío a modo calor?", opciones:["TXV", "Acumulador de succión", "Separador de aceite", "Filtro deshidratador"], respuesta_correcta:1, explicacion:"Es vital en Heat Pumps porque el cambio de ciclo puede mover grandes cantidades de líquido atrapado." , question: "What component prevents liquid refrigerant from returning to the compressor when the system abruptly switches from cooling to heating mode?", options: ["TXV", "Suction accumulator", "Oil separator", "Filter drier"], explanation: "It is vital in heat pumps because the mode change can move large amounts of trapped liquid." },
  { id:"nate_159", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué característica principal define a una calefacción de 'Alta Eficiencia' (90% AFUE o más)?", opciones:["Usa más gas", "Tiene un intercambiador de calor secundario para condensar el vapor de agua de los gases de escape", "No usa soplador", "Usa tubería de cobre para el escape"], respuesta_correcta:1, explicacion:"Al condensar el vapor, recupera el calor latente que las unidades estándar tiran por la chimenea." , question: "What key feature defines a high-efficiency furnace (90% AFUE or higher)?", options: ["It uses more gas", "It has a secondary heat exchanger to condense water vapor from the exhaust gases", "It does not use a blower", "It uses copper pipe for the exhaust"], explanation: "By condensing the vapor, it recovers the latent heat that standard-efficiency units vent out through the chimney." },
  { id:"nate_160", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Mides la resistencia de un Hot Surface Ignitor (HSI) y obtienes 'Infinidad' (O.L). ¿Cuál es el estado del componente?", opciones:["Está en perfecto estado", "Está quemado/abierto y debe reemplazarse", "Necesita limpieza", "Está en corto circuito"], respuesta_correcta:1, explicacion:"Un ignitor es una resistencia; si marca O.L, el filamento de nitruro de silicio o carburo está roto." , question: "You measure the resistance of a hot surface ignitor (HSI) and get 'Infinity' (OL). What is the condition of the component?", options: ["It is in perfect condition", "It is burned out/open and must be replaced", "It needs cleaning", "It is short-circuited"], explanation: "An ignitor is a resistance; if it reads OL, the silicon nitride or silicon carbide filament is broken." },
  { id:"nate_161", categoria:"NATE_AIRE_HEATPUMP", pregunta:"En la mayoría de los sistemas (excepto Rheem/Ruud), ¿qué sucede con la válvula inversora si se pierde la señal de 24V del cable 'O'?", opciones:["Se queda en modo calor (posición default)", "Se queda en modo frío", "Se bloquea el compresor", "Explota"], respuesta_correcta:0, explicacion:"La terminal 'O' energiza la válvula para modo frío. Sin energía, el resorte la regresa a modo calefacción (fail-safe para invierno)." , question: "On most systems (except Rheem/Ruud), what happens to the reversing valve if the 24V signal on the 'O' wire is lost?", options: ["It defaults to heating mode (de-energized position)", "It stays in cooling mode", "The compressor locks out", "It explodes"], explanation: "The 'O' terminal energizes the valve for cooling mode. Without power, the spring returns it to heating mode (fail-safe for winter)." },
  { id:"nate_162", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Una calefacción eléctrica (Heat Strip) de 10 kW opera a 240V. ¿Cuál es su consumo aproximado en amperios?", opciones:["20 A", "42 A", "60 A", "100 A"], respuesta_correcta:1, explicacion:"I = P / V. 10,000 Watts / 240 Volts = 41.66 Amperios." , question: "A 10 kW electric heat strip operates at 240V. What is its approximate current draw in amps?", options: ["20 A", "42 A", "60 A", "100 A"], explanation: "I = P / V. 10,000 Watts / 240 Volts = 41.66 Amps." },
  { id:"nate_163", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si sospechas de una fuga de gas en una unión roscada, ¿qué método es el más seguro para verificarla?", opciones:["Usar un encendedor", "Usar una solución jabonosa aprobada o un detector electrónico de gas combustible", "Escuchar el silbido", "Oler de cerca"], respuesta_correcta:1, explicacion:"Nunca uses llamas abiertas. El jabón crea burbujas visibles incluso en fugas mínimas." , question: "If you suspect a gas leak at a threaded connection, what is the safest method to verify it?", options: ["Use a lighter", "Use an approved soap bubble solution or an electronic combustible gas detector", "Listen for the hiss", "Smell up close"], explanation: "Never use open flames. Soap solution creates visible bubbles even on minimal leaks." },
  { id:"nate_164", categoria:"NATE_AIRE_HEATPUMP", pregunta:"El quemador enciende, pero después de 2 minutos se apaga, y el soplador sigue funcionando. Esto ocurre repetidamente. ¿Causa probable?", opciones:["Falta de gas", "El sensor de límite (High Limit) se está abriendo por falta de flujo de aire", "El termostato está dañado", "Falla del sensor de llama"], respuesta_correcta:1, explicacion:"Si el aire no retira el calor del intercambiador rápido (filtro sucio o motor lento), el sensor de límite apaga los quemadores para evitar daños." , question: "The burner ignites, but shuts off after 2 minutes, and the blower keeps running. This happens repeatedly. What is the probable cause?", options: ["Insufficient gas", "The high limit switch is opening due to lack of airflow", "The thermostat is damaged", "Flame sensor failure"], explanation: "If the air does not remove heat from the heat exchanger fast enough (dirty filter or slow motor), the high limit switch shuts off the burners to prevent damage." },
  { id:"nate_165", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué color de llama indica una combustión completa y segura de Gas Natural?", opciones:["Amarillo brillante", "Azul con puntas ligeramente anaranjadas", "Rojo", "Verde"], respuesta_correcta:1, explicacion:"Una llama azul indica que hay suficiente oxígeno. Una llama amarilla indica monóxido de carbono (CO) por falta de aire primario." , question: "What flame color indicates complete and safe combustion of natural gas?", options: ["Bright yellow", "Blue with slightly orange tips", "Red", "Green"], explanation: "A blue flame indicates adequate oxygen. A yellow flame indicates carbon monoxide (CO) production due to insufficient primary air." },
  { id:"nate_166", categoria:"NATE_AIRE_HEATPUMP", pregunta:"En modo calefacción, ¿qué sucede si la válvula check del serpentín exterior se queda trabada en posición cerrada?", opciones:["El sistema enfría más", "El refrigerante se bloquea, la presión de alta sube y el sistema se apaga por seguridad", "No pasa nada", "El compresor gira al revés"], respuesta_correcta:1, explicacion:"La válvula check debe abrirse en calor para que el refrigerante circule por el dispositivo de expansión exterior." , question: "In heating mode, what happens if the outdoor coil check valve is stuck in the closed position?", options: ["The system cools better", "Refrigerant is blocked, high-side pressure rises, and the system trips on the high-pressure safety", "Nothing happens", "The compressor runs in reverse"], explanation: "The check valve must open in heating mode to allow refrigerant to flow through the outdoor metering device." },
  { id:"nate_167", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función del cable común (C) en un termostato digital moderno?", opciones:["Es el cable de enfriamiento", "Proporciona el retorno de 24V para alimentar la pantalla y el Wi-Fi del termostato", "Es una tierra física", "Apaga el equipo en emergencias"], respuesta_correcta:1, explicacion:"Sin el cable C, el termostato tendría que depender de baterías o de 'robar' energía de otros cables, lo cual falla a menudo." , question: "What is the function of the common (C) wire on a modern digital thermostat?", options: ["It is the cooling wire", "It provides the 24V return path to power the display and Wi-Fi module", "It is a physical ground", "It shuts off the equipment in emergencies"], explanation: "Without the C wire, the thermostat would have to rely on batteries or steal power from other wires, which often fails." },
  { id:"nate_168", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Al revisar una calefacción, notas que el fusible de 3A de la tarjeta de control está quemado. ¿Qué componente revisarías primero por un posible corto?", opciones:["El compresor", "El solenoide de la válvula de gas o el cableado del termostato", "El motor del soplador", "Las resistencias eléctricas"], respuesta_correcta:1, explicacion:"El fusible protege el circuito de 24V. Un corto en el cableado o en una bobina de relé/válvula es la causa más común." , question: "While troubleshooting a furnace, you find the 3A fuse on the control board is blown. What component would you check first for a possible short?", options: ["The compressor", "The gas valve solenoid or the thermostat wiring", "The blower motor", "The electric heat strips"], explanation: "The fuse protects the 24V circuit. A short in the wiring or in a relay/valve coil is the most common cause." },
  { id:"nate_169", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si conviertes una calefacción de Gas Natural a Propano (LP), ¿qué debes hacer con los orificios de los quemadores?", opciones:["Hacerlos más grandes", "Cambiarlos por orificios más pequeños", "Dejar los mismos", "Quitarlos totalmente"], respuesta_correcta:1, explicacion:"El propano tiene mucho más contenido calórico por pie cúbico y mayor presión; requiere un orificio más pequeño para no sobrecalentar el equipo." , question: "If you convert a furnace from natural gas to propane (LP), what must you do with the burner orifices?", options: ["Make them larger", "Replace them with smaller orifices", "Leave them the same", "Remove them entirely"], explanation: "Propane has much higher heat content per cubic foot and higher supply pressure; it requires a smaller orifice to prevent overheating the equipment." },
  { id:"nate_170", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cómo afecta un intercambiador de calor sucio (con hollín) al flujo de aire?", opciones:["Aumenta la presión estática y disminuye el flujo de aire (CFM)", "Mejora la eficiencia", "Baja el amperaje del motor", "No afecta"], respuesta_correcta:0, explicacion:"La acumulación de suciedad actúa como una restricción en el paso del aire, forzando al ventilador y reduciendo el confort." , question: "How does a soot-covered heat exchanger affect airflow?", options: ["Increases static pressure and reduces airflow (CFM)", "Improves efficiency", "Lowers motor amperage", "Has no effect"], explanation: "The buildup of soot acts as a restriction in the air path, straining the blower and reducing comfort." },
  { id:"nate_171", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es el primer componente que debe energizarse en una calefacción de gas moderna tras el llamado de calor (W)?", opciones:["Válvula de gas", "Motor soplador (Blower)", "Motor inductor de tiro", "Ignitor"], respuesta_correcta:2, explicacion:"Primero se debe limpiar la cámara de combustión (pre-purge) y verificar que el escape esté libre antes de intentar encender." , question: "What is the first component that must be energized in a modern gas furnace after a call for heat (W)?", options: ["Gas valve", "Blower motor", "Draft inducer motor", "Ignitor"], explanation: "The combustion chamber must first be purged (pre-purge) and the flue verified clear before any attempt to ignite." },
  { id:"nate_172", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un sistema Heat Pump funciona bien en Frío pero en Calor se apaga por 'Alta Presión' después de 5 minutos. ¿Causa probable?", opciones:["Falta de gas", "Filtro de aire interior sucio o soplador fallando", "Condensador exterior sucio", "Válvula inversora trabada"], respuesta_correcta:1, explicacion:"En modo calor, el serpentín interior es el condensador. Si no tiene flujo de aire para retirar el calor, la presión de alta se dispara." , question: "A heat pump works well in cooling mode but trips on high pressure after 5 minutes in heating mode. What is the probable cause?", options: ["Low refrigerant charge", "Dirty indoor air filter or failing blower", "Dirty outdoor condenser", "Stuck reversing valve"], explanation: "In heating mode, the indoor coil is the condenser. If airflow is insufficient to remove the heat, the high-pressure safety trips." },
  { id:"nate_173", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede si el relay del soplador (Blower Relay) se queda pegado en posición cerrada?", opciones:["El soplador nunca enciende", "El soplador funcionará continuamente aunque el termostato esté en OFF", "El motor se quemará inmediatamente", "El aire saldrá más caliente"], respuesta_correcta:1, explicacion:"Los contactos pegados mantienen el paso de energía al motor sin importar las órdenes del control." , question: "What happens if the blower relay gets stuck in the closed position?", options: ["The blower never turns on", "The blower will run continuously even though the thermostat is set to OFF", "The motor will burn out immediately", "The air will come out hotter"], explanation: "Stuck contacts maintain power to the motor regardless of control commands." },
  { id:"nate_174", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué riesgo existe si una calefacción de gas de categoría I (tiro natural) se instala en un cuarto muy pequeño sin rejillas de ventilación?", opciones:["La unidad enfriará el cuarto", "Combustión incompleta y producción de monóxido de carbono por falta de oxígeno", "El gas se congelará", "Aumentará el recibo de agua"], respuesta_correcta:1, explicacion:"El fuego consume oxígeno; si el cuarto es hermético, la llama se 'ahoga' y genera gases letales." , question: "What risk exists if a Category I (natural draft) gas furnace is installed in a very small room without ventilation openings?", options: ["The unit will cool the room", "Incomplete combustion and carbon monoxide production due to oxygen depletion", "The gas will freeze", "The water bill will increase"], explanation: "The fire consumes oxygen; if the room is airtight, the flame is starved and produces lethal gases." },
  { id:"nate_175", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿A qué se refiere el término 'Balance Point' en un sistema de bomba de calor?", opciones:["El punto donde el peso del equipo está nivelado", "La temperatura exterior a la cual la capacidad de la bomba de calor iguala exactamente la pérdida de calor de la casa", "Cuando las presiones se igualan", "El nivel de aceite correcto"], respuesta_correcta:1, explicacion:"Por debajo de este punto, la bomba de calor necesita ayuda de la calefacción auxiliar (strips) para mantener la temperatura." , question: "What does the term 'balance point' refer to in a heat pump system?", options: ["The point where the equipment weight is level", "The outdoor temperature at which the heat pump's capacity exactly equals the heat loss of the building", "When pressures equalize", "The correct oil level"], explanation: "Below this temperature, the heat pump needs supplemental auxiliary heat (strips) to maintain the indoor temperature." },
  { id:"nate_176", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cómo genera voltaje un termopar (thermocouple) en una calefacción antigua?", opciones:["Por magnetismo", "Por la unión de dos metales distintos expuestos al calor (Efecto Seebeck)", "Usa una batería interna", "Por fricción del gas"], respuesta_correcta:1, explicacion:"El calor genera unos 20-30 milivoltios DC, suficientes para mantener abierta la válvula de seguridad del piloto." , question: "How does a thermocouple generate voltage in an older furnace?", options: ["By magnetism", "By the junction of two dissimilar metals exposed to heat (Seebeck effect)", "It uses an internal battery", "By gas friction"], explanation: "The heat generates approximately 20-30 millivolts DC, enough to hold open the pilot safety valve." },
  { id:"nate_177", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Por qué el aire dentro de una casa se siente muy seco durante el invierno cuando la calefacción está encendida?", opciones:["Porque la calefacción quema el agua del aire", "Porque al calentar el aire frío exterior (que entra por infiltración), su Humedad Relativa cae drásticamente", "Porque el soplador absorbe el agua", "Es una ilusión óptica"], respuesta_correcta:1, explicacion:"El aire caliente puede retener mucha más agua que el frío. Si calientas aire sin añadirle agua, la RH baja, causando sequedad en piel y nariz." , question: "Why does the air inside a house feel very dry during winter when the heating is on?", options: ["Because the furnace burns the water out of the air", "Because heating cold outside air (that enters through infiltration) causes its relative humidity to drop drastically", "Because the blower absorbs the water", "It is an optical illusion"], explanation: "Warm air can hold much more water than cold air. If you heat air without adding moisture, the relative humidity drops, causing dry skin and nasal passages." },
  { id:"nate_178", categoria:"NATE_AIRE_HEATPUMP", pregunta:"La tarjeta de control de una calefacción muestra un código de error: '3 parpadeos - Pressure Switch stuck closed'. ¿Qué significa?", opciones:["Que el switch no cierra", "Que la tarjeta detecta que el switch ya estaba cerrado antes de que el inductor encendiera (posible corto o switch pegado)", "Que no hay gas", "Que el motor está quemado"], respuesta_correcta:1, explicacion:"La tarjeta realiza un test de seguridad: el switch debe estar abierto al inicio. Si está cerrado, asume que alguien lo puenteó ilegalmente o que falló." , question: "The furnace control board displays an error code: '3 flashes - Pressure Switch stuck closed.' What does this mean?", options: ["The switch is not closing", "The board detects the switch was already closed before the inducer started (possible short or stuck switch)", "There is no gas", "The motor is burned"], explanation: "The board runs a safety check: the switch must be open at startup. If it is already closed, it assumes someone jumpered it illegally or it has failed." },
  { id:"nate_179", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si un Heat Pump entrega 30,000 BTU de calor y consume 10,000 BTU de energía eléctrica, ¿cuál es su COP (Coefficient of Performance)?", opciones:["1.0", "3.0", "10.0", "0.33"], respuesta_correcta:1, explicacion:"COP = Energía entregada / Energía consumida. 30,000 / 10,000 = 3.0." , question: "If a heat pump delivers 30,000 BTU of heat and consumes 10,000 BTU of electrical energy, what is its COP (Coefficient of Performance)?", options: ["1.0", "3.0", "10.0", "0.33"], explanation: "COP = Energy delivered / Energy consumed. 30,000 / 10,000 = 3.0." },
  { id:"nate_180", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Por qué solo las unidades de alta eficiencia (Condensing Furnaces) pueden usar tubería de PVC para el escape?", opciones:["Porque el PVC es más barato", "Porque los gases de escape están lo suficientemente fríos (aprox. 100°F-120°F) como para no derretir el plástico", "Porque el PVC resiste el fuego", "Porque el PVC filtra el aire"], respuesta_correcta:1, explicacion:"En unidades estándar, el escape sale a 300-500°F, lo que derretiría el PVC instantáneamente." , question: "Why can only high-efficiency (condensing) furnaces use PVC piping for the exhaust?", options: ["Because PVC is cheaper", "Because the exhaust gases are cool enough (approximately 100-120 degrees F) not to melt the plastic", "Because PVC is fire-resistant", "Because PVC filters the air"], explanation: "In standard-efficiency units, the exhaust exits at 300-500 degrees F, which would instantly melt PVC." },
  { id:"nate_181", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un motor de soplador funciona en modo 'Fan ON' pero no arranca en modo 'Auto' cuando hay un llamado de calor. ¿Dónde está la falla?", opciones:["El motor está quemado", "La tarjeta de control no está activando el circuito de calor del motor", "El termostato no tiene baterías", "El capacitor está débil"], respuesta_correcta:1, explicacion:"Muchos motores tienen velocidades distintas para frío y calor. Si funciona en una pero no en otra, el problema es el control o el devanado específico." , question: "A blower motor works on 'Fan ON' mode but does not start on 'Auto' when there is a call for heat. Where is the fault?", options: ["The motor is burned out", "The control board is not activating the heating speed circuit for the motor", "The thermostat has no batteries", "The capacitor is weak"], explanation: "Many motors have different speed taps for cooling and heating. If the motor works on one but not the other, the problem is the control or the specific winding." },
  { id:"nate_182", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿En qué línea se encuentra ubicado el acumulador de succión de una bomba de calor?", opciones:["Entre la válvula inversora y el compresor", "En la línea de líquido", "Después del condensador exterior", "En la descarga del compresor"], respuesta_correcta:0, explicacion:"Debe estar en la línea de succión permanente, sin importar si el sistema está en modo frío o calor." , question: "On which line is the suction accumulator located in a heat pump?", options: ["Between the reversing valve and the compressor", "On the liquid line", "After the outdoor condenser", "On the compressor discharge"], explanation: "It must be on the permanent suction line, regardless of whether the system is in cooling or heating mode." },
  { id:"nate_183", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede si conectas accidentalmente la terminal 'R' (24V) a la terminal 'C' (Común)?", opciones:["El equipo enciende", "Se quema el fusible de la tarjeta o el transformador por corto circuito directo", "No pasa nada", "El termostato se reinicia"], respuesta_correcta:1, explicacion:"Estás uniendo los dos polos del transformador sin ninguna resistencia (carga) de por medio." , question: "What happens if you accidentally connect the R terminal (24V) to the C terminal (Common)?", options: ["The equipment turns on", "The board fuse or the transformer blows due to a direct short circuit", "Nothing happens", "The thermostat resets"], explanation: "You are connecting both legs of the transformer together with no resistance (load) in between." },
  { id:"nate_184", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Por qué se requiere 'Exceso de Aire' en el proceso de combustión de una calefacción?", opciones:["Para enfriar el equipo", "Para asegurar que cada molécula de combustible encuentre oxígeno y evitar la producción de CO", "Para aumentar la presión", "Para que huela mejor"], respuesta_correcta:1, explicacion:"Teóricamente se necesita una cantidad de aire, pero en la práctica se usa más para garantizar seguridad y limpieza." , question: "Why is 'excess air' required in the combustion process of a furnace?", options: ["To cool the equipment", "To ensure every fuel molecule finds oxygen and to prevent CO production", "To increase the pressure", "To improve the smell"], explanation: "Theoretically a specific amount of air is needed, but in practice more is used to guarantee safety and clean combustion." },
  { id:"nate_185", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Escuchas un sonido de 'estallido' o 'golpe metálico' justo cuando el soplador se apaga en una calefacción. ¿Qué es?", opciones:["El compresor está explotando", "Expansión y contracción térmica de los ductos de metal", "Falta de gas", "El filtro está suelto"], respuesta_correcta:1, explicacion:"El metal se expande al calentarse y se contrae al enfriarse; si los ductos no tienen espacio para moverse, hacen ruidos de estallido (oil-canning)." , question: "You hear a popping or banging metallic sound just as the blower shuts off in a furnace. What is it?", options: ["The compressor is exploding", "Thermal expansion and contraction of sheet-metal ductwork", "Insufficient gas", "The filter is loose"], explanation: "Metal expands when heated and contracts when cooled; if the ductwork does not have room to move, it produces popping sounds (oil-canning)." },
  { id:"nate_186", categoria:"NATE_AIRE_HEATPUMP", pregunta:"En una calefacción vieja con un control de 'Fan Limit' de disco, ¿cuál es la función del ajuste 'Fan Off'?", opciones:["Apagar el gas", "Indicar a qué temperatura del aire el soplador debe apagarse para no soplar aire frío al final del ciclo", "Encender el piloto", "Limitar la presión"], respuesta_correcta:1, explicacion:"Mantiene el ventilador encendido hasta extraer todo el calor útil del intercambiador." , question: "On an older furnace with a disc-type fan limit control, what is the function of the 'Fan Off' setting?", options: ["Shut off the gas", "Set the air temperature at which the blower should turn off to avoid blowing cold air at the end of the cycle", "Light the pilot", "Limit the pressure"], explanation: "It keeps the blower running until all usable heat is extracted from the heat exchanger." },
  { id:"nate_187", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede exactamente cuando un usuario pone su termostato en 'Emergency Heat'?", opciones:["El equipo enfría más rápido", "Se bloquea el compresor exterior y solo funcionan las resistencias eléctricas", "Llama a los bomberos", "Aumenta la velocidad del aire"], respuesta_correcta:1, explicacion:"Se usa solo si la unidad exterior falla. Es muy ineficiente y caro, ya que usa pura electricidad para calentar." , question: "What exactly happens when a user sets their thermostat to 'Emergency Heat'?", options: ["The equipment cools faster", "The outdoor compressor is locked out and only the electric heat strips operate", "It calls the fire department", "Airflow speed increases"], explanation: "It is used only if the outdoor unit fails. It is very inefficient and expensive, as it relies solely on electric resistance heat." },
  { id:"nate_188", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué tipo de manómetro es el más preciso para medir la presión de gas en el manifold?", opciones:["Manómetro de refrigeración estándar", "Manómetro de columna de agua (U-Tube Manometer) o manómetro digital en iwc", "Micrómetro", "Tacómetro"], respuesta_correcta:1, explicacion:"La presión de gas es muy baja; los manómetros de refrigeración no tienen la resolución necesaria para medir pulgadas de agua." , question: "What type of manometer is the most accurate for measuring gas pressure at the furnace manifold?", options: ["Standard refrigeration gauge", "U-tube water column manometer or digital manometer reading in inches WC", "Micrometer", "Tachometer"], explanation: "Gas pressure is very low; refrigeration gauges do not have the resolution needed to measure inches of water column." },
  { id:"nate_189", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede si el drenaje de condensado de una calefacción de alta eficiencia se congela o se tapa?", opciones:["La unidad enfría la casa", "El agua se acumula en el inductor, el switch de presión se abre y la unidad deja de calentar", "El gas fluye más rápido", "No pasa nada"], respuesta_correcta:1, explicacion:"Es un mecanismo de seguridad: si no puede drenar el agua producto de la condensación, no se le permite operar." , question: "What happens if the condensate drain on a high-efficiency furnace freezes or becomes clogged?", options: ["The unit cools the house", "Water backs up into the inducer, the pressure switch opens, and the unit stops heating", "Gas flows faster", "Nothing happens"], explanation: "It is a safety mechanism: if the condensate cannot drain, the unit is not permitted to operate." },
  { id:"nate_190", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es la función de un secuenciador en una calefacción eléctrica?", opciones:["Controlar la música del equipo", "Encender las resistencias una por una para evitar picos de corriente masivos en la línea eléctrica", "Medir el calor", "Invertir las fases"], respuesta_correcta:1, explicacion:"Retrasa el encendido de cada banco de calor unos segundos para proteger el breaker y el transformador del edificio." , question: "What is the function of a sequencer in an electric furnace?", options: ["Control the music of the equipment", "Turn on the heating elements one at a time to avoid massive current spikes on the electrical supply", "Measure the heat", "Reverse the phases"], explanation: "It staggers the energizing of each heater bank by a few seconds to protect the building's breaker and transformer." },
  { id:"nate_191", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué causa que las llamas 'floten' o se despeguen de los quemadores en una calefacción?", opciones:["Exceso de presión de gas o falta de tiro", "Mucho oxígeno", "Falta de gas", "Intercambiador muy frío"], respuesta_correcta:0, explicacion:"Es una condición peligrosa; la llama no es estable y puede generar grandes cantidades de CO." , question: "What causes flames to 'float' or lift off the burners in a furnace?", options: ["Excess gas pressure or insufficient draft", "Too much oxygen", "Insufficient gas", "Very cold heat exchanger"], explanation: "This is a dangerous condition; the flame is unstable and can produce large amounts of CO." },
  { id:"nate_192", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Estás cargando una Heat Pump en invierno (modo calor). ¿Cuál es el método más confiable?", opciones:["Superheat", "Subcooling", "Pesar la carga según la placa del fabricante", "Por amperaje"], respuesta_correcta:2, explicacion:"Las tablas de SH y SC en modo calor son muy variables. Pesar la carga es la única forma de garantizar que el sistema funcione en ambos ciclos." , question: "You are charging a heat pump in winter (heating mode). What is the most reliable method?", options: ["Superheat", "Subcooling", "Weigh in the charge per the manufacturer's nameplate", "By amperage"], explanation: "Superheat and subcooling tables in heating mode are highly variable. Weighing in the charge is the only way to ensure the system works properly in both cycles." },
  { id:"nate_193", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es el 'Temperature Rise' (aumento de temperatura) típico para una calefacción de gas estándar?", opciones:["10°F - 20°F", "40°F - 70°F", "80°F - 100°F", "150°F+"], respuesta_correcta:1, explicacion:"Si el aire entra a 70°F, debe salir entre 110°F y 140°F. Menos indica exceso de aire; más indica falta de aire." , question: "What is the typical temperature rise for a standard gas furnace?", options: ["10 to 20 degrees F", "40 to 70 degrees F", "80 to 100 degrees F", "150 degrees F+"], explanation: "If air enters at 70 degrees F, it should exit between 110 and 140 degrees F. Less indicates excess air; more indicates insufficient airflow." },
  { id:"nate_194", categoria:"NATE_AIRE_HEATPUMP", pregunta:"La unidad enciende, hay llama, pero se apaga exactamente a los 5 segundos. Limpias el sensor de llama y sigue igual. ¿Qué más revisarías?", opciones:["La presión de gas", "La polaridad del voltaje de entrada (L y N invertidos) o la tierra física de la tarjeta", "El capacitor del soplador", "El termostato"], respuesta_correcta:1, explicacion:"El circuito de rectificación de llama requiere una referencia a tierra sólida y polaridad correcta. Si están mal, la tarjeta no 've' la llama." , question: "The furnace ignites and there is flame, but it shuts off at exactly 5 seconds. You clean the flame sensor and it still does the same. What else would you check?", options: ["Gas pressure", "The polarity of the incoming voltage (L and N reversed) or the physical ground of the control board", "The blower capacitor", "The thermostat"], explanation: "The flame rectification circuit requires a solid ground reference and correct polarity. If either is wrong, the board cannot detect the flame." },
  { id:"nate_195", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuáles son los dos parámetros que la mayoría de las tarjetas de Defrost usan para iniciar el ciclo?", opciones:["Tiempo y Temperatura del serpentín exterior", "Humedad y Viento", "Presión de alta y Amperaje", "Luz solar y Voltaje"], respuesta_correcta:0, explicacion:"El sensor debe detectar que el serpentín está bajo punto de congelación y que ha pasado el tiempo acumulado (30, 60 o 90 min)." , question: "What are the two parameters most defrost control boards use to initiate a defrost cycle?", options: ["Time and outdoor coil temperature", "Humidity and wind", "High pressure and amperage", "Sunlight and voltage"], explanation: "The sensor must detect that the coil is below freezing and that the accumulated runtime (30, 60, or 90 min) has elapsed." },
  { id:"nate_196", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué significa que una válvula de gas sea de 'Dos Etapas' (Two-Stage)?", opciones:["Que tiene dos entradas de gas", "Que puede operar a fuego bajo (ahorro) o fuego alto (máxima potencia) según la demanda", "Que se abre dos veces", "Que necesita dos termostatos"], respuesta_correcta:1, explicacion:"Mejora el confort y la eficiencia al no encender siempre a máxima potencia si no es necesario." , question: "What does it mean for a gas valve to be 'two-stage'?", options: ["It has two gas inlets", "It can operate at low fire (economy) or high fire (maximum output) depending on demand", "It opens twice", "It requires two thermostats"], explanation: "It improves comfort and efficiency by not always firing at maximum output when it is not needed." },
  { id:"nate_197", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Cuál es el límite máximo de Monóxido de Carbono (CO) permitido en el escape de una calefacción según los estándares de servicio?", opciones:["0 ppm", "100 ppm (aire libre de aire)", "10,000 ppm", "50%"], respuesta_correcta:1, explicacion:"Aunque ANSI permite hasta 400 ppm, la mayoría de los técnicos pro consideran que arriba de 100 ppm indica un problema de combustión que debe repararse." , question: "What is the maximum carbon monoxide (CO) level allowed in furnace exhaust per service standards?", options: ["0 ppm", "100 ppm (air-free)", "10,000 ppm", "50%"], explanation: "Although ANSI permits up to 400 ppm, most professional technicians consider readings above 100 ppm as indicating a combustion problem that must be repaired." },
  { id:"nate_198", categoria:"NATE_AIRE_HEATPUMP", pregunta:"¿Qué sucede si usas una lija gruesa para limpiar un sensor de llama (flame sensor)?", opciones:["Se limpia mejor", "Se raya la superficie y se acumula carbón más rápido en el futuro (debe usarse lana de acero o un trapo)", "Aumenta la sensibilidad", "Cambia el voltaje"], respuesta_correcta:1, explicacion:"Las rayas atrapan sílice y depósitos de carbono, haciendo que el sensor falle más pronto. Lo ideal es lana de acero fina (steel wool)." , question: "What happens if you use coarse sandpaper to clean a flame sensor?", options: ["It cleans better", "The scratched surface accumulates carbon faster in the future (steel wool or a cloth should be used instead)", "It increases sensitivity", "It changes the voltage"], explanation: "The scratches trap silica and carbon deposits, causing the sensor to fail sooner. Fine steel wool is the ideal cleaning method." },
  { id:"nate_199", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Si un sistema Heat Pump tiene una línea de succión escarchada (con hielo) hasta el compresor en modo calefacción, ¿qué indica?", opciones:["Funcionamiento normal", "Falla del ciclo de defrost o falta de flujo de aire exterior", "Falta de gas", "Válvula inversora rota"], respuesta_correcta:1, explicacion:"En calor, el exterior es el evaporador. Si se llena de hielo, no absorbe calor y el refrigerante regresa líquido/frío al compresor." , question: "If a heat pump system has a frost-covered suction line all the way to the compressor in heating mode, what does this indicate?", options: ["Normal operation", "Defrost cycle failure or lack of outdoor airflow", "Low refrigerant charge", "Broken reversing valve"], explanation: "In heating mode, the outdoor unit is the evaporator. If it is covered in ice, it cannot absorb heat and liquid/cold refrigerant returns to the compressor." },
  { id:"nate_200", categoria:"NATE_AIRE_HEATPUMP", pregunta:"Un horno de gas de 80% AFUE está instalado en un ático. El drenaje del aire acondicionado gotea sobre el intercambiador de calor durante el verano. ¿Qué riesgo principal corres en el invierno?", opciones:["Que el aire huela a humedad", "Corrosión prematura y grietas en el intercambiador (riesgo de CO)", "Que el gas no encienda", "Que el soplador se oxide"], respuesta_correcta:1, explicacion:"El óxido debilita el metal. Al encenderse en invierno, el metal se expande y las zonas oxidadas se fracturan fácilmente." , question: "An 80% AFUE gas furnace is installed in an attic. The air conditioning condensate drain drips onto the heat exchanger during summer. What is the primary risk in winter?", options: ["The air will smell musty", "Premature corrosion and cracks in the heat exchanger (CO risk)", "The gas won't ignite", "The blower will rust"], explanation: "Rust weakens the metal. When the furnace fires in winter, the metal expands and the rusted areas fracture easily." },

  // -- Sistemas Comerciales y Chillers (201-300) --
  { id:"nate_201", categoria:"NATE_COMERCIAL", pregunta:"¿Qué componente en un sistema Inverter es responsable de convertir la corriente AC de la línea a DC y luego modular la frecuencia para el compresor?", opciones:["El Capacitor de Marcha", "El Módulo de Potencia Inteligente (IPM)", "El Puente Rectificador solamente", "El Transformador de Control"], respuesta_correcta:1, explicacion:"El IPM recibe DC rectificada y, mediante transistores IGBT, recrea una onda AC de frecuencia y voltaje variables para controlar la velocidad del compresor." , question: "What component in an inverter system is responsible for converting AC line current to DC and then modulating the frequency for the compressor?", options: ["The run capacitor", "The Intelligent Power Module (IPM)", "The bridge rectifier only", "The control transformer"], explanation: "The IPM receives rectified DC and, using IGBT transistors, recreates a variable-frequency and variable-voltage AC wave to control compressor speed." },
  { id:"nate_202", categoria:"NATE_COMERCIAL", pregunta:"En un congelador (Walk-in Freezer), ¿por qué se instala un calentador en el marco de la puerta?", opciones:["Para que el cliente no tenga frío", "Para evitar que la humedad se congele y la puerta se quede pegada por el hielo", "Para calentar el producto", "Para ayudar al ciclo de deshielo"], respuesta_correcta:1, explicacion:"Sin este calentador (door heater), la condensación externa se congelaría en el sello de la puerta, rompiendo el empaque al intentar abrirla." , question: "In a walk-in freezer, why is a heater installed in the door frame?", options: ["So the customer does not feel cold", "To prevent moisture from freezing and sealing the door shut with ice", "To warm the product", "To assist the defrost cycle"], explanation: "Without this door heater, external condensation would freeze on the door gasket, tearing the seal when the door is opened." },
  { id:"nate_203", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la función principal de la 'Válvula de Expansión Electrónica' (EEV) en un sistema VRF?", opciones:["Solo abrir y cerrar el paso", "Modular el flujo de refrigerante con precisión milimétrica basado en el Superheat calculado por la tarjeta", "Aumentar la presión de succión", "Filtrar el aceite"], respuesta_correcta:1, explicacion:"A diferencia de una TXV mecánica, la EEV usa un motor a pasos (stepper motor) controlado por microprocesador para una eficiencia máxima." , question: "What is the primary function of an Electronic Expansion Valve (EEV) in a VRF system?", options: ["Only open and close the flow", "Modulate refrigerant flow with precision based on superheat calculated by the control board", "Increase suction pressure", "Filter the oil"], explanation: "Unlike a mechanical TXV, the EEV uses a stepper motor controlled by a microprocessor for maximum efficiency." },
  { id:"nate_204", categoria:"NATE_COMERCIAL", pregunta:"Un Mini-Split Inverter muestra un código de error de 'Comunicación (E1/E6)'. Mides 0V DC constantes entre el cable de señal (S/3) y el neutro (2/N). ¿Qué indica esto?", opciones:["Que la comunicación es perfecta", "Que hay un problema en la tarjeta de control (no hay pulsos de datos)", "Que el compresor está quemado", "Que falta refrigerante"], respuesta_correcta:1, explicacion:"La señal de comunicación debe ser un voltaje DC que fluctúa (brinca) rápidamente. Un voltaje fijo de 0V o un voltaje alto constante indican falla de datos." , question: "A mini-split inverter displays a communication error code (E1/E6). You measure a constant 0V DC between the signal wire (S/3) and the neutral (2/N). What does this indicate?", options: ["Communication is functioning correctly", "There is a problem with the control board (no data pulses)", "The compressor is burned out", "The system is low on refrigerant"], explanation: "The communication signal should be a DC voltage that fluctuates rapidly. A fixed 0V or a constant high voltage indicates a data failure." },
  { id:"nate_205", categoria:"NATE_COMERCIAL", pregunta:"¿Dónde se debe instalar el 'Liquid Receiver' (Recibidor de Líquido) en un sistema comercial?", opciones:["En la línea de succión", "En la línea de líquido, inmediatamente después del condensador", "Antes del compresor", "En el techo"], respuesta_correcta:1, explicacion:"Almacena el exceso de refrigerante líquido para asegurar que la válvula de expansión siempre reciba 100% líquido, especialmente en sistemas con carga variable." , question: "Where should the liquid receiver be installed in a commercial system?", options: ["On the suction line", "On the liquid line, immediately after the condenser", "Before the compressor", "On the roof"], explanation: "It stores excess liquid refrigerant to ensure the metering device always receives 100% liquid, especially in systems with variable loads." },
  { id:"nate_206", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es el propósito de un 'Reactor' o 'Choke' en el circuito DC de un equipo Inverter?", opciones:["Enfriar la tarjeta", "Suavizar los picos de corriente y corregir el factor de potencia del sistema", "Arrancar el compresor", "Medir la temperatura"], respuesta_correcta:1, explicacion:"Actúa como un filtro inductivo que protege los componentes electrónicos sensibles de las variaciones bruscas de energía." , question: "What is the purpose of a reactor (choke) in the DC circuit of an inverter system?", options: ["Cool the board", "Smooth out current spikes and correct the system's power factor", "Start the compressor", "Measure temperature"], explanation: "It acts as an inductive filter that protects sensitive electronic components from abrupt energy variations." },
  { id:"nate_207", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede en un Rack de refrigeración si el 'Oil Differential Pressure Switch' se activa?", opciones:["El compresor acelera", "El compresor se apaga para evitar daños por falta de lubricación", "Se abre la válvula de expansión", "Se limpia el aceite solo"], respuesta_correcta:1, explicacion:"Este switch mide la diferencia entre la presión de la bomba de aceite y la presión del cárter; si la diferencia es baja, no hay flujo de aceite." , question: "What happens in a refrigeration rack system if the oil differential pressure switch activates?", options: ["The compressor speeds up", "The compressor shuts down to prevent damage from lack of lubrication", "The expansion valve opens", "The oil cleans itself"], explanation: "This switch measures the difference between oil pump pressure and crankcase pressure; if the differential is low, there is no oil flow." },
  { id:"nate_208", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué es crítico usar 'Y-joints' o 'Refnets' originales en la tubería de un VRF en lugar de tees de cobre estándar?", opciones:["Porque son más caras", "Para asegurar una distribución equitativa del flujo de refrigerante y aceite a cada unidad interior", "Porque el cobre estándar explota", "Por estética"], respuesta_correcta:1, explicacion:"Las tees estándar causan turbulencia y mala distribución, lo que provoca que unas unidades enfríen más que otras o que el aceite no regrese." , question: "Why is it critical to use original Y-joints or Refnets in VRF piping instead of standard copper tees?", options: ["Because they are more expensive", "To ensure equitable distribution of refrigerant flow and oil to each indoor unit", "Because standard copper explodes", "For aesthetic reasons"], explanation: "Standard tees cause turbulence and poor distribution, resulting in some units cooling more than others or oil not returning properly." },
  { id:"nate_209", categoria:"NATE_COMERCIAL", pregunta:"Si un sistema con R-404A tiene una fuga lenta en la línea de vapor durante meses, ¿por qué se recomienda recuperar todo el gas y cargar nuevo en lugar de solo completar la carga?", opciones:["Para vender más gas", "Por el fraccionamiento de la mezcla (los gases con menor punto de ebullición se escapan primero)", "Porque el R-404A se vuelve ácido", "Porque cambia de color"], respuesta_correcta:1, explicacion:"Al ser una mezcla, la proporción química cambia tras una fuga prolongada, alterando las presiones y la eficiencia del sistema." , question: "If an R-404A system has a slow vapor-line leak over several months, why is it recommended to recover all the gas and charge fresh refrigerant instead of just topping off?", options: ["To sell more gas", "Because the blend has fractionated (lower boiling point gases escape first)", "Because R-404A becomes acidic", "Because it changes color"], explanation: "As a blend, its chemical proportions change after a prolonged leak, altering pressures and system efficiency." },
  { id:"nate_210", categoria:"NATE_COMERCIAL", pregunta:"Un sensor de temperatura de descarga del compresor (Discharge Thermistor) marca 0 Ohms. ¿Cómo reaccionará la unidad Inverter?", opciones:["Funcionará normalmente", "Se bloqueará por código de error de sensor en corto", "Enfriará más rápido", "Ignorará la lectura"], respuesta_correcta:1, explicacion:"Las tarjetas electrónicas verifican que los sensores estén dentro de un rango (ej. 5k a 200k Ohms). 0 Ohms es un corto circuito total." , question: "A compressor discharge temperature sensor (thermistor) reads 0 Ohms. How will the inverter unit react?", options: ["It will operate normally", "It will lock out with a shorted sensor error code", "It will cool faster", "It will ignore the reading"], explanation: "Control boards verify that sensors are within a valid range (e.g., 5k to 200k Ohms). 0 Ohms is a complete short circuit." },
  { id:"nate_211", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la función de una válvula de 'Head Pressure Control' (Ori-Al) en un condensador remoto en invierno?", opciones:["Apagar el equipo", "Inundar el condensador con líquido para reducir su superficie efectiva y mantener la presión de alta", "Aumentar el flujo de aire", "Calentar el aceite"], respuesta_correcta:1, explicacion:"Mantiene la presión de descarga estable para que la válvula de expansión pueda alimentar el evaporador correctamente en climas fríos." , question: "What is the function of a head pressure control valve (such as an ORI valve) on a remote condenser in winter?", options: ["Shut off the equipment", "Flood the condenser with liquid to reduce its effective surface area and maintain adequate head pressure", "Increase airflow", "Heat the oil"], explanation: "It keeps discharge pressure stable so the metering device can properly feed the evaporator in cold climates." },
  { id:"nate_212", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué un Mini-Split Inverter puede dar toques eléctricos leves o fallar en su comunicación si no tiene conectada la tierra física?", opciones:["Porque el compresor es de metal", "Debido a la inducción y ruido electrónico generado por la conmutación de alta frecuencia del IPM", "Porque el refrigerante es conductor", "Porque el control usa 220V"], respuesta_correcta:1, explicacion:"La electrónica de potencia genera 'ruido' que debe drenarse a tierra. Sin ella, ese ruido interfiere con los datos de comunicación." , question: "Why can a mini-split inverter give mild electrical shocks or experience communication failures if the physical ground is not connected?", options: ["Because the compressor is made of metal", "Due to induction and electronic noise generated by the high-frequency switching of the IPM", "Because the refrigerant is conductive", "Because the controls use 220V"], explanation: "Power electronics generate noise that must be drained to ground. Without it, this noise interferes with the communication data." },
  { id:"nate_213", categoria:"NATE_COMERCIAL", pregunta:"¿Qué componente permite que un sistema VRF de 3 tubos enfríe una habitación mientras calienta otra simultáneamente?", opciones:["El compresor", "La caja de selección de modo (BS Box / MCU)", "El termostato Wi-Fi", "Una válvula check"], respuesta_correcta:1, explicacion:"Esta caja dirige el vapor caliente de descarga hacia las unidades que piden calor y el líquido frío hacia las que piden frío." , question: "What component allows a 3-pipe VRF system to cool one room while simultaneously heating another?", options: ["The compressor", "The mode selection box (BS Box / MCU)", "The Wi-Fi thermostat", "A check valve"], explanation: "This box directs hot discharge vapor to units calling for heat and cold liquid to units calling for cooling." },
  { id:"nate_214", categoria:"NATE_COMERCIAL", pregunta:"En la tarjeta exterior de un Inverter, ves capacitores electrolíticos grandes (tipo bote). Si están inflados de la parte superior, ¿qué indica?", opciones:["Que están bien cargados", "Falla inminente o daño por sobrevoltaje/calor (deben cambiarse)", "Que el sistema tiene mucho gas", "Es un diseño de fábrica"], respuesta_correcta:1, explicacion:"El electrolito se calienta y genera gas, inflando la válvula de seguridad. Indican que el filtrado de corriente DC ya no es efectivo." , question: "On the outdoor board of an inverter, you see large electrolytic capacitors (can type). If the tops are swollen, what does this indicate?", options: ["They are fully charged", "Imminent failure or damage from overvoltage/heat (they must be replaced)", "The system has too much refrigerant", "It is a factory design feature"], explanation: "The electrolyte overheats and generates gas, bulging the safety vent. This indicates DC filtering is no longer effective." },
  { id:"nate_215", categoria:"NATE_COMERCIAL", pregunta:"En un sistema de baja temperatura (congelado), ¿por qué los ventiladores del evaporador no encienden inmediatamente después del deshielo?", opciones:["Para ahorrar luz", "Retraso de ventilador (Fan Delay) para evitar soplar vapor caliente y humedad al cuarto", "Porque el motor está frío", "Porque la tarjeta está pensando"], respuesta_correcta:1, explicacion:"Permite que el serpentín se enfríe primero para que el agua remanente del deshielo se congele en las aletas y no salga volando hacia el producto." , question: "In a low-temperature (freezer) system, why don't the evaporator fans turn on immediately after defrost?", options: ["To save electricity", "Fan delay prevents blowing warm vapor and moisture into the space", "Because the motor is cold", "Because the board is processing"], explanation: "It allows the coil to cool down first so remaining water from defrost freezes on the fins rather than being blown onto the stored product." },
  { id:"nate_216", categoria:"NATE_COMERCIAL", pregunta:"¿Cómo se prueba un compresor Inverter para saber si está aterrizado?", opciones:["Con una lámpara de prueba", "Con un Megóhmetro (Megger) aplicando al menos 500V DC hacia la carcasa", "Midiendo continuidad con un multímetro de 9V", "Tocándolo con la mano"], respuesta_correcta:1, explicacion:"Un multímetro estándar no detecta fallas de aislamiento microscópicas que la electrónica del IPM sí detecta como falla de tierra." , question: "How do you test an inverter compressor to determine if it is grounded?", options: ["With a test lamp", "With a megohmmeter (megger) applying at least 500V DC to the housing", "By measuring continuity with a 9V multimeter", "By touching it with your hand"], explanation: "A standard multimeter cannot detect microscopic insulation failures that the IPM electronics will detect as a ground fault." },
  { id:"nate_217", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es el estándar de vacío 'Triple Evacuación' para sistemas VRF?", opciones:["Bajar a 500 micrones tres veces", "Bajar a 1500 micrones y romper con nitrógeno, luego 1000 y nitrógeno, y finalmente 500 micrones", "Hacer vacío por 3 horas", "Usar 3 bombas de vacío"], respuesta_correcta:1, explicacion:"El nitrógeno absorbe la humedad restante en cada etapa, asegurando un sistema ultra seco para aceites POE." , question: "What is the standard 'triple evacuation' procedure for VRF systems?", options: ["Pull down to 500 microns three times", "Pull to 1500 microns and break with nitrogen, then to 1000 microns and nitrogen, and finally to 500 microns", "Run the vacuum pump for 3 hours", "Use 3 vacuum pumps"], explanation: "The nitrogen absorbs remaining moisture at each stage, ensuring an ultra-dry system for POE oils." },
  { id:"nate_218", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la ventaja de un sistema con 'Pump Down' sobre uno que solo apaga el compresor por termostato?", opciones:["Usa menos refrigerante", "Elimina la migración de líquido al compresor durante el apagado, evitando arranques inundados", "Enfría más rápido", "Es más silencioso"], respuesta_correcta:1, explicacion:"Al guardar el gas en el recibidor, el compresor arranca en vacío y sin líquido mezclado con el aceite." , question: "What is the advantage of a pump-down system over one that simply shuts the compressor off via the thermostat?", options: ["It uses less refrigerant", "It eliminates refrigerant migration to the compressor during the off cycle, preventing flooded starts", "It cools faster", "It is quieter"], explanation: "By storing the gas in the receiver, the compressor starts in a vacuum with no liquid mixed into the oil." },
  { id:"nate_219", categoria:"NATE_COMERCIAL", pregunta:"Al hacer una conexión flare para R-410A Inverter, ¿por qué es vital usar un abocardador (flaring tool) tipo excéntrico?", opciones:["Para que el flare quede más brillante", "Para bruñir y endurecer la cara del cobre, evitando fugas por las altas presiones del R-410A", "Porque es el más barato", "Para no usar torque"], respuesta_correcta:1, explicacion:"El movimiento excéntrico amasa el cobre uniformemente, creando un sello mucho más resistente que las herramientas de cono fijo." , question: "When making a flare connection for an R-410A inverter, why is it critical to use an eccentric-type flaring tool?", options: ["To make the flare look shinier", "To burnish and work-harden the copper face, preventing leaks at the high pressures of R-410A", "Because it is the cheapest tool", "So torque is unnecessary"], explanation: "The eccentric motion kneads the copper uniformly, creating a much more resilient seal than fixed-cone tools." },
  { id:"nate_220", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede con el compresor Inverter si la temperatura ambiente exterior es de 125°F?", opciones:["Se apaga inmediatamente", "Reduce su frecuencia (velocidad) para proteger el IPM y el compresor de un sobrecalentamiento", "Explota el capacitor", "Sigue funcionando a máxima velocidad"], respuesta_correcta:1, explicacion:"Es una función de protección lógica; prefiere enfriar menos que quemarse por completo." , question: "What happens to the inverter compressor if the outdoor ambient temperature is 125 degrees F?", options: ["It shuts off immediately", "It reduces its frequency (speed) to protect the IPM and compressor from overheating", "The capacitor explodes", "It continues running at maximum speed"], explanation: "This is a logic-based protection function; it prefers to deliver less cooling rather than burn out completely." },
  { id:"nate_221", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué las TXV de refrigeración comercial suelen tener un orificio intercambiable?", opciones:["Para que sean más fáciles de limpiar", "Para ajustar la capacidad de la válvula a la carga térmica exacta del evaporador (tonelaje)", "Para cambiar el refrigerante", "Para que duren más"], respuesta_correcta:1, explicacion:"Un mismo cuerpo de válvula puede servir para 1/2 tonelada o para 3 toneladas simplemente cambiando el cartucho interno (orifice)." , question: "Why do commercial refrigeration TXVs typically have an interchangeable orifice?", options: ["To make them easier to clean", "To match the valve's capacity to the exact thermal load of the evaporator (tonnage)", "To change the refrigerant type", "To make them last longer"], explanation: "A single valve body can serve from 1/2 ton to 3 tons simply by changing the internal orifice cartridge." },
  { id:"nate_222", categoria:"NATE_COMERCIAL", pregunta:"Al probar un compresor Inverter desconectado de la tarjeta, mides: U a V = 1.2 Ohms, V a W = 1.2 Ohms, U a W = 1.2 Ohms. ¿Qué indica?", opciones:["Bobinados balanceados (motor probablemente sano)", "Motor quemado", "Motor en corto", "Error de multímetro"], respuesta_correcta:0, explicacion:"En Inverters (trifásicos DC), todas las bobinas deben tener exactamente la misma resistencia, usualmente muy baja (0.5 a 4 Ohms)." , question: "When testing a disconnected inverter compressor, you measure: U to V = 1.2 Ohms, V to W = 1.2 Ohms, U to W = 1.2 Ohms. What does this indicate?", options: ["Balanced windings (motor is likely sound)", "Motor is burned", "Motor is shorted", "Multimeter error"], explanation: "In inverter (three-phase DC) compressors, all windings must have exactly the same resistance, typically very low (0.5 to 4 Ohms)." },
  { id:"nate_223", categoria:"NATE_COMERCIAL", pregunta:"El R-32 es un refrigerante clasificado como A2L. ¿Qué significa esto?", opciones:["Alta toxicidad", "No inflamable", "Baja toxicidad y ligeramente inflamable", "Gas de alta presión solamente"], respuesta_correcta:2, explicacion:"Los A2L son la nueva generación. Tienen bajo GWP pero requieren herramientas que no generen chispas y protocolos de seguridad adicionales." , question: "R-32 is a refrigerant classified as A2L. What does this mean?", options: ["High toxicity", "Non-flammable", "Low toxicity and mildly flammable", "High-pressure gas only"], explanation: "A2L refrigerants are the new generation. They have low GWP but require non-sparking tools and additional safety protocols." },
  { id:"nate_224", categoria:"NATE_COMERCIAL", pregunta:"Si un acumulador de succión está cubierto de escarcha (hielo) hasta la mitad, ¿qué significa?", opciones:["Que está trabajando perfectamente atrapando refrigerante líquido", "Que le falta gas", "Que el compresor está roto", "Que el cuarto está muy frío"], respuesta_correcta:0, explicacion:"Su función es ser un tanque de evaporación de seguridad. La escarcha muestra el nivel de líquido que está hirviendo dentro de él antes de llegar al compresor." , question: "If a suction accumulator is frosted (iced) halfway up, what does this mean?", options: ["It is working properly, trapping liquid refrigerant", "The system is low on charge", "The compressor is broken", "The room is very cold"], explanation: "Its function is to serve as a safety evaporation tank. The frost line shows the level of liquid boiling off inside before reaching the compressor." },
  { id:"nate_225", categoria:"NATE_COMERCIAL", pregunta:"¿Dónde se ubica típicamente el sensor de 'Pipe Temperature' en la unidad interior de un Mini-Split?", opciones:["En el retorno de aire", "En el medio del serpentín evaporador (punto de saturación)", "En el control remoto", "En el motor del soplador"], respuesta_correcta:1, explicacion:"Se usa para detectar si el serpentín se está congelando o para calcular el sobrecalentamiento electrónico." , question: "Where is the pipe temperature sensor typically located on the indoor unit of a mini-split?", options: ["At the return air inlet", "At the midpoint of the evaporator coil (saturation point)", "On the remote control", "On the blower motor"], explanation: "It is used to detect if the coil is freezing or to electronically calculate superheat." },
  { id:"nate_226", categoria:"NATE_COMERCIAL", pregunta:"¿Cómo se determina la carga final de refrigerante en un sistema VRF de gran escala?", opciones:["Por Superheat", "Cálculo matemático basado en el diámetro y longitud total de todas las líneas de líquido, sumado a la carga de fábrica", "Hasta que la mirilla se aclare", "Por amperaje del compresor"], respuesta_correcta:1, explicacion:"En VRF no hay otra forma. Cada pie de tubo de 1/4\", 3/8\", etc., añade una cantidad específica de onzas al sistema." , question: "How is the final refrigerant charge determined in a large-scale VRF system?", options: ["By superheat", "Mathematical calculation based on the diameter and total length of all liquid lines, added to the factory charge", "Until the sight glass clears", "By compressor amperage"], explanation: "In VRF systems, there is no other way. Each foot of 1/4-inch, 3/8-inch, etc., tubing adds a specific amount of ounces to the system." },
  { id:"nate_227", categoria:"NATE_COMERCIAL", pregunta:"Si el indicador central del visor de líquido está de color AMARILLO, ¿qué acción debes tomar?", opciones:["Agregar más gas", "Cambiar el filtro deshidratador (hay humedad presente)", "Limpiar el condensador", "Nada, está bien"], respuesta_correcta:1, explicacion:"Verde = Seco, Amarillo = Húmedo. La humedad reacciona con el aceite y crea ácidos; el filtro ya se saturó." , question: "If the moisture indicator in the center of the sight glass is YELLOW, what action should you take?", options: ["Add more refrigerant", "Replace the filter drier (moisture is present)", "Clean the condenser", "Nothing; it is fine"], explanation: "Green = Dry. Yellow = Wet. Moisture reacts with oil and creates acids; the filter drier is saturated." },
  { id:"nate_228", categoria:"NATE_COMERCIAL", pregunta:"Al encender un Inverter, el compresor intenta arrancar (hace un pequeño movimiento), se detiene y la tarjeta marca 'Overcurrent Protection'. Mides el compresor y está bien. ¿Qué es lo siguiente a revisar?", opciones:["El capacitor de marcha", "Si el compresor está mecánicamente trabado o si el módulo IPM está dañado", "El sensor de ambiente", "La carga de gas"], respuesta_correcta:1, explicacion:"La tarjeta detecta un pico de amperaje porque el motor no puede girar. Si el motor está bien eléctricamente, el problema es el 'músculo' electrónico (IPM) o una traba mecánica." , question: "When powering on an inverter, the compressor attempts to start (makes a small movement), stops, and the board displays 'Overcurrent Protection.' You test the compressor and it is electrically sound. What should you check next?", options: ["The run capacitor", "Whether the compressor is mechanically seized or the IPM module is damaged", "The ambient sensor", "The refrigerant charge"], explanation: "The board detects a current spike because the motor cannot turn. If the motor is electrically good, the problem is the electronic driver (IPM) or a mechanical lockup." },
  { id:"nate_229", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es un 'Oil Separator' de tipo flotador?", opciones:["Un filtro de aire", "Un dispositivo que separa el aceite del gas de descarga y usa un flotador para regresarlo automáticamente al cárter", "Un medidor de presión", "Un tipo de compresor"], respuesta_correcta:1, explicacion:"Mantiene el nivel de aceite en el compresor y evita que este circule innecesariamente por todo el sistema." , question: "What is a float-type oil separator?", options: ["An air filter", "A device that separates oil from discharge gas and uses a float to automatically return it to the crankcase", "A pressure gauge", "A type of compressor"], explanation: "It maintains the oil level in the compressor and prevents oil from circulating unnecessarily throughout the entire system." },
  { id:"nate_230", categoria:"NATE_COMERCIAL", pregunta:"En un reloj de deshielo Paragon (8145-20), ¿qué significan las terminales 1, 2, 3 y 4?", opciones:["Son solo números", "Línea, Ventiladores, Compresor y Resistencias de deshielo", "Baja, Media, Alta y Tierra", "Norte, Sur, Este y Oeste"], respuesta_correcta:1, explicacion:"Es el estándar para cablear refrigeración comercial: el reloj conmuta la energía del compresor hacia las resistencias." , question: "On a Paragon defrost timer (8145-20), what do terminals 1, 2, 3, and 4 represent?", options: ["They are just numbers", "Line, fans, compressor, and defrost heaters", "Low, medium, high, and ground", "North, south, east, and west"], explanation: "This is the standard wiring for commercial refrigeration: the timer switches power from the compressor to the defrost heaters." },
  { id:"nate_231", categoria:"NATE_COMERCIAL", pregunta:"¿Cómo realiza un sistema VRF el ciclo de 'Oil Recovery'?", opciones:["Hay que drenarlo manualmente", "El sistema aumenta la velocidad del gas y abre todas las EEVs periódicamente para arrastrar el aceite atrapado", "El aceite se evapora", "Usa una bomba eléctrica separada"], respuesta_correcta:1, explicacion:"Como los VRF operan a cargas parciales, el gas a veces es muy lento para mover el aceite. El sistema se 'auto-limpia' cada cierto tiempo." , question: "How does a VRF system perform its oil recovery cycle?", options: ["It must be drained manually", "The system increases gas velocity and opens all EEVs periodically to sweep trapped oil back", "The oil evaporates", "It uses a separate electric pump"], explanation: "Because VRF systems often operate at partial loads, gas velocity can be too low to move oil. The system self-cleans at regular intervals." },
  { id:"nate_232", categoria:"NATE_COMERCIAL", pregunta:"Un equipo Inverter marca 'DC Bus Undervoltage'. Mides el voltaje de entrada y es de 230V correctos. ¿Dónde está el problema?", opciones:["En el motor del ventilador", "En el circuito interno de la tarjeta (puente rectificador o capacitores de filtrado dañados)", "El termostato está mal", "Falta gas"], respuesta_correcta:1, explicacion:"La tarjeta recibe AC pero no puede convertirla o mantenerla en los 320V DC necesarios para operar el compresor." , question: "An inverter unit displays 'DC Bus Undervoltage.' You measure the input voltage at 230V, which is correct. Where is the problem?", options: ["In the outdoor fan motor", "In the internal board circuitry (bridge rectifier or filter capacitors are damaged)", "The thermostat is wrong", "Low refrigerant charge"], explanation: "The board receives AC but cannot convert or maintain it at the approximately 320V DC needed to operate the compressor." },
  { id:"nate_233", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es una válvula 'VPR' (Crankcase Pressure Regulator)?", opciones:["Un regulador de aceite", "Una válvula que limita la presión máxima que entra al compresor para evitar sobrecargas de motor en arranques calientes", "Un sensor de temperatura", "Una válvula de seguridad"], respuesta_correcta:1, explicacion:"Evita que el compresor se 'ahogue' con vapor muy denso después de un deshielo o un paro prolongado." , question: "What is a CPR (Crankcase Pressure Regulator) valve?", options: ["An oil regulator", "A valve that limits the maximum pressure entering the compressor to prevent motor overloads during hot pull-downs", "A temperature sensor", "A safety relief valve"], explanation: "It prevents the compressor from being overwhelmed by very dense vapor after a defrost or extended shutdown." },
  { id:"nate_234", categoria:"NATE_COMERCIAL", pregunta:"¿Cómo puedes probar mecánicamente si una EEV está funcionando sin abrir el sistema?", opciones:["Escuchando el sonido de clic/vibración al encender el equipo o usando un imán de prueba manual (EEV tool)", "Moliéndola con un martillo", "Midiendo la presión con manómetros analógicos solamente", "Viendo si brilla"], respuesta_correcta:0, explicacion:"Al energizar, el control calibra la válvula cerrándola al 100%. Se siente la vibración de los pasos del motor." , question: "How can you mechanically verify that an EEV is functioning without opening the system?", options: ["Listen for clicking/vibration sounds when the unit powers on, or use a manual EEV test magnet", "Hit it with a hammer", "Only by measuring pressure with analog gauges", "See if it glows"], explanation: "Upon energizing, the control calibrates the valve by closing it 100%. The vibration of the stepper motor steps can be felt." },
  { id:"nate_235", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede si el tubo de drenaje de un evaporador de refrigeración no tiene trampa de aire (trap) y sale a una zona caliente?", opciones:["El agua no sale", "El aire caliente y húmedo será succionado hacia el evaporador, causando exceso de hielo y pérdida de eficiencia", "El agua se congela en el tubo", "Huele mal"], respuesta_correcta:1, explicacion:"El ventilador del evaporador crea una presión negativa; sin trampa, el drenaje se vuelve una entrada de aire húmedo." , question: "What happens if the evaporator drain tube in a refrigeration system has no air trap and exits to a warm area?", options: ["The water won't drain", "Warm humid air will be drawn into the evaporator, causing excess frost and loss of efficiency", "The water freezes in the tube", "It smells bad"], explanation: "The evaporator fan creates negative pressure; without a trap, the drain becomes an entry point for warm humid air." },
  { id:"nate_236", categoria:"NATE_COMERCIAL", pregunta:"Un sistema Inverter consume 1200 Watts operando a 230V. ¿Cuál es su consumo de corriente?", opciones:["10.2 A", "5.2 A", "2.1 A", "15 A"], respuesta_correcta:1, explicacion:"I = P / V. 1200 / 230 = 5.21 Amperios." , question: "An inverter system draws 1200 Watts at 230V. What is its current consumption?", options: ["10.2 A", "5.2 A", "2.1 A", "15 A"], explanation: "I = P / V. 1200 / 230 = 5.21 Amps." },
  { id:"nate_237", categoria:"NATE_COMERCIAL", pregunta:"Los motores de ventilador exterior Inverter suelen tener 5 cables. Si mides 310V DC constantes entre Rojo y Negro, ¿qué significa?", opciones:["Que el motor está quemado", "Que el voltaje de alimentación principal al motor está presente (Normal)", "Que hay un corto", "Que el ventilador está girando rápido"], respuesta_correcta:1, explicacion:"En ventiladores DC de 5 hilos, el cable rojo lleva el voltaje del bus de datos DC (aprox 310V) directamente." , question: "Inverter outdoor fan motors typically have 5 wires. If you measure a constant 310V DC between the red and black wires, what does this mean?", options: ["The motor is burned out", "The main DC bus voltage to the motor is present (normal)", "There is a short circuit", "The fan is spinning fast"], explanation: "In 5-wire DC fan motors, the red wire carries the DC bus voltage (approximately 310V) directly." },
  { id:"nate_238", categoria:"NATE_COMERCIAL", pregunta:"Un técnico encuentra que la presión de succión es de 0 psig (vacío) en un sistema de refrigeración comercial que estaba funcionando. ¿Cuál es el primer componente a revisar?", opciones:["El compresor", "La válvula solenoide de la línea de líquido (posiblemente cerrada)", "El termostato", "El ventilador del condensador"], respuesta_correcta:1, explicacion:"Si la solenoide no abre o se quemó, el compresor succiona todo el gas hasta llegar a vacío (Pump Down involuntario)." , question: "A technician finds that the suction pressure is 0 psig (vacuum) on a commercial refrigeration system that was running. What is the first component to check?", options: ["The compressor", "The liquid line solenoid valve (possibly stuck closed)", "The thermostat", "The condenser fan"], explanation: "If the solenoid does not open or is burned out, the compressor pulls all the gas down to vacuum (unintentional pump-down)." },
  { id:"nate_239", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué es obligatorio aislar AMBAS líneas (succión y líquido/gas) en un Mini-Split?", opciones:["Para que se vea mejor", "Porque ambas líneas transportan refrigerante a baja temperatura después del dispositivo de expansión (que está en la unidad exterior)", "Para que no se golpeen", "Porque el manual lo dice"], respuesta_correcta:1, explicacion:"A diferencia de un Split central donde el líquido es tibio, en un Mini-Split el 'líquido' ya se expandió afuera y viene frío." , question: "Why is it mandatory to insulate BOTH lines (suction and liquid/gas) on a mini-split?", options: ["For appearance", "Because both lines carry refrigerant at low temperature after the metering device (which is located in the outdoor unit)", "So they don't get bumped", "Because the manual says so"], explanation: "Unlike a central split system where the liquid is warm, in a mini-split the liquid has already expanded outside and arrives cold." },
  { id:"nate_240", categoria:"NATE_COMERCIAL", pregunta:"Después de apagar la energía de un equipo Inverter, ¿cuánto tiempo debes esperar antes de tocar las terminales de la tarjeta?", opciones:["Nada, al apagar se descarga", "Al menos 5 a 10 minutos (hasta que los capacitores electrolíticos se descarguen)", "1 hora", "Un día"], respuesta_correcta:1, explicacion:"Los capacitores almacenan energía de alto voltaje (300V+) que puede ser letal incluso con el equipo desconectado." , question: "After shutting off power to an inverter unit, how long should you wait before touching the board terminals?", options: ["No wait needed; it discharges when turned off", "At least 5 to 10 minutes (until the electrolytic capacitors discharge)", "1 hour", "One day"], explanation: "The capacitors store high-voltage energy (300V+) that can be lethal even with the equipment disconnected." },
  { id:"nate_241", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede si dos unidades interiores en un sistema VRF tienen la misma dirección (address) configurada?", opciones:["Enfrían el doble", "Error de comunicación y conflicto en el bus de datos (el sistema no arranca)", "Se queman los termostatos", "Funcionan como una sola"], respuesta_correcta:1, explicacion:"Cada unidad debe tener una 'identidad' única para que la unidad maestra sepa cuánta carga enviar a cada habitación." , question: "What happens if two indoor units on a VRF system have the same address configured?", options: ["They cool twice as much", "Communication error and data bus conflict (the system will not start)", "The thermostats burn out", "They operate as one unit"], explanation: "Each unit must have a unique identity so the master unit knows how much load to send to each room." },
  { id:"nate_242", categoria:"NATE_COMERCIAL", pregunta:"Si un sistema de refrigeración comercial cambió de R-22 a R-448A, ¿cuánto aceite mineral puede quedar como máximo en el sistema?", opciones:["50%", "10%", "Menos del 5%", "0%"], respuesta_correcta:2, explicacion:"El aceite mineral no regresa con los nuevos refrigerantes HFO/HFC. Se requieren varios cambios de aceite para llegar al nivel de pureza de POE aceptable." , question: "If a commercial refrigeration system was converted from R-22 to R-448A, what is the maximum amount of mineral oil that can remain in the system?", options: ["50%", "10%", "Less than 5%", "0%"], explanation: "Mineral oil does not return with the newer HFO/HFC refrigerants. Multiple oil changes are needed to reach the acceptable POE purity level." },
  { id:"nate_243", categoria:"NATE_COMERCIAL", pregunta:"Mides un compresor Inverter y encuentras: U-V = 1.2 Ohms, V-W = 1.2 Ohms, U-W = 5.5 Ohms. ¿Cuál es el diagnóstico?", opciones:["Compresor balanceado", "Bobinado dañado / resistencia alta en una fase", "Terminales sucias solamente", "Está bien"], respuesta_correcta:1, explicacion:"En un motor Inverter (trifásico), cualquier desviación de resistencia entre fases indica un fallo en el devanado." , question: "You measure an inverter compressor and find: U-V = 1.2 Ohms, V-W = 1.2 Ohms, U-W = 5.5 Ohms. What is the diagnosis?", options: ["Balanced compressor", "Damaged winding / high resistance in one phase", "Dirty terminals only", "It is fine"], explanation: "In an inverter (three-phase) motor, any deviation in resistance between phases indicates a winding failure." },
  { id:"nate_244", categoria:"NATE_COMERCIAL", pregunta:"En un Mini-Split, ¿cuál es la forma más rápida de saber si la válvula inversora está energizada?", opciones:["Ver si saca chispas", "Acercar un desarmador al solenoide para sentir el magnetismo", "Midiendo la presión solamente", "Gritándole"], respuesta_correcta:1, explicacion:"Si el solenoide está recibiendo voltaje, creará un campo magnético que atraerá el metal del desarmador." , question: "On a mini-split, what is the quickest way to determine if the reversing valve is energized?", options: ["Look for sparks", "Hold a screwdriver near the solenoid to feel the magnetic pull", "Only by measuring pressure", "Yell at it"], explanation: "If the solenoid is receiving voltage, it will create a magnetic field that attracts the metal screwdriver." },
  { id:"nate_245", categoria:"NATE_COMERCIAL", pregunta:"Un cuarto frío tiene mucha escarcha en el techo y las paredes cerca de la puerta. ¿Cuál es la causa?", opciones:["Falta de gas", "Infiltración de aire exterior (empaques de puerta dañados o puerta abierta mucho tiempo)", "El termostato está muy bajo", "Ventiladores muy rápidos"], respuesta_correcta:1, explicacion:"La humedad del aire exterior entra y se congela instantáneamente al tocar las superficies frías del cuarto." , question: "A walk-in cooler has heavy frost on the ceiling and walls near the door. What is the cause?", options: ["Low refrigerant charge", "Outside air infiltration (damaged door gaskets or door left open too long)", "The thermostat is set too low", "Fans are running too fast"], explanation: "Humidity from the outside air enters and freezes instantly upon contacting the cold surfaces of the walk-in." },
  { id:"nate_246", categoria:"NATE_COMERCIAL", pregunta:"¿Qué mide el sensor 'Heatsink Temperature' en un Inverter?", opciones:["La temperatura del aire", "La temperatura del disipador de calor donde está montado el IPM", "La temperatura del cobre", "La temperatura del agua"], respuesta_correcta:1, explicacion:"Protege a los transistores de potencia de quemarse si el flujo de aire del condensador falla o el disipador está sucio." , question: "What does the 'heatsink temperature' sensor measure on an inverter?", options: ["Air temperature", "The temperature of the heat sink where the IPM is mounted", "Copper temperature", "Water temperature"], explanation: "It protects the power transistors from burning out if the condenser airflow fails or the heat sink is dirty." },
  { id:"nate_247", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué es imperativo usar un torquímetro (torque wrench) en las tuercas flare de un Inverter?", opciones:["Para trabajar más lento", "Para evitar grietas por exceso de apriete o fugas por falta del mismo, considerando la expansión térmica", "Porque se ve profesional", "Para no usar llaves inglesas"], respuesta_correcta:1, explicacion:"El R-410A tiene presiones muy altas y las fluctuaciones de temperatura del Inverter fatigan el cobre si no tiene el torque exacto." , question: "Why is it imperative to use a torque wrench on the flare nuts of an inverter system?", options: ["To work more slowly", "To prevent cracks from over-tightening or leaks from under-tightening, considering thermal expansion", "Because it looks professional", "To avoid using adjustable wrenches"], explanation: "R-410A operates at very high pressures and the temperature fluctuations of inverter operation fatigue the copper if the torque is not exact." },
  { id:"nate_248", categoria:"NATE_COMERCIAL", pregunta:"Un condensador comercial tiene 3 ventiladores. El del centro no gira y se siente muy caliente. Los otros dos funcionan. ¿Diagnóstico?", opciones:["Falla de fase principal", "Motor quemado o capacitor de ese motor dañado", "Es normal (ahorro de energía)", "Falta gas"], respuesta_correcta:1, explicacion:"En condensadores múltiples, cada motor suele tener su propio capacitor. Si uno falla, la presión de alta subirá, pero el sistema seguirá operando deficientemente." , question: "A commercial condenser has 3 fans. The center one is not spinning and feels very hot. The other two are running. What is the diagnosis?", options: ["Main phase failure", "Burned motor or that motor's individual capacitor is damaged", "Normal (energy saving mode)", "Low refrigerant charge"], explanation: "In multi-fan condensers, each motor typically has its own capacitor. If one fails, the discharge pressure will rise but the system will continue to operate poorly." },
  { id:"nate_249", categoria:"NATE_COMERCIAL", pregunta:"Muchos sistemas VRF modernos usan aceite PVE (Polyvinylether) en lugar de POE. ¿Cuál es la ventaja?", opciones:["Es más barato", "No reacciona con la humedad para formar ácidos (no se hidroliza)", "Es de color azul", "Huele a fresa"], respuesta_correcta:1, explicacion:"Aunque sigue siendo higroscópico (absorbe agua), el PVE no se descompone químicamente como el POE, lo que lo hace más seguro para sistemas complejos.", question: "Many modern VRF systems use PVE (Polyvinylether) oil instead of POE. What is the advantage?", options: ["It is cheaper", "It does not react with moisture to form acids (it does not hydrolyze)", "It is blue in color", "It smells like strawberry"], explanation: "Although it is still hygroscopic (absorbs water), PVE does not chemically decompose like POE, making it safer for complex systems." },
  { id:"nate_250", categoria:"NATE_COMERCIAL", pregunta:"En un sistema Inverter, ¿qué sucede con el voltaje DC del bus de datos si el voltaje AC de entrada sube un 20%?", opciones:["Se mantiene igual", "El voltaje DC también sube proporcionalmente, pudiendo causar un error de 'Overvoltage' y proteger la tarjeta", "Se quema el termostato", "El compresor gira más lento"], respuesta_correcta:1, explicacion:"VDC = VAC * 1.41. Si sube la entrada, sube el bus de datos, poniendo en riesgo los capacitores y transistores." , question: "In an Inverter system, what happens to the DC bus voltage if the input AC voltage increases by 20%?", options: ["It stays the same", "The DC voltage also rises proportionally, potentially triggering an 'Overvoltage' error and engaging board protection", "The thermostat burns out", "The compressor runs slower"], explanation: "VDC = VAC x 1.41. If the input voltage rises, the DC bus voltage rises as well, putting the capacitors and transistors at risk." },
  { id:"nate_251", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede en un Chiller si el 'Approach Temperature' del evaporador aumenta significativamente por encima de los valores de diseño (ej. > 5°F)?", opciones:["El Chiller enfría más rápido", "Indica una baja transferencia de calor, probablemente por tubos del evaporador sucios o incrustados", "El compresor consume menos energía", "Falta refrigerante únicamente"], respuesta_correcta:1, explicacion:"El 'Approach' es la diferencia entre la temperatura del agua que sale y la temperatura de saturación del refrigerante. Si sube, el calor no está pasando eficientemente al refrigerante." , question: "What happens in a Chiller if the evaporator Approach Temperature rises significantly above design values (e.g., > 5°F)?", options: ["The Chiller cools faster", "It indicates poor heat transfer, likely due to dirty or fouled evaporator tubes", "The compressor uses less energy", "It only means low refrigerant charge"], explanation: "The Approach is the difference between the leaving water temperature and the refrigerant saturation temperature. If it rises, heat is not transferring efficiently to the refrigerant." },
  { id:"nate_252", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es el propósito del 'Blowdown' (Purga) en una torre de enfriamiento?", opciones:["Vaciar la torre para limpiarla", "Remover una porción de agua con alta concentración de sólidos disueltos para evitar incrustaciones", "Enfriar el agua más rápido", "Aumentar el flujo de aire"], respuesta_correcta:1, explicacion:"Al evaporarse el agua, los minerales se quedan y se concentran. Si no se purga, los minerales destruirán los tubos del condensador del Chiller." , question: "What is the purpose of Blowdown in a cooling tower?", options: ["To empty the tower for cleaning", "To remove a portion of water with high dissolved solids concentration to prevent scaling", "To cool the water faster", "To increase airflow"], explanation: "As water evaporates, minerals remain and concentrate. Without blowdown, minerals will destroy the Chiller condenser tubes." },
  { id:"nate_253", categoria:"NATE_COMERCIAL", pregunta:"En un sistema de control DDC, ¿qué es una 'Entrada Analógica' (AI)?", opciones:["Un interruptor de encendido/apagado", "Una señal variable (como 0-10V o 4-20mA) que representa una lectura como temperatura o presión", "Un comando para arrancar un motor", "La pantalla del termostato"], respuesta_correcta:1, explicacion:"A diferencia de las señales digitales (sí/no), las analógicas permiten al sistema saber exactamente 'cuánto' mide un sensor." , question: "In a DDC control system, what is an Analog Input (AI)?", options: ["An on/off switch", "A variable signal (such as 0-10V or 4-20mA) representing a reading like temperature or pressure", "A command to start a motor", "The thermostat display"], explanation: "Unlike digital signals (yes/no), analog signals allow the system to know exactly 'how much' a sensor is measuring." },
  { id:"nate_254", categoria:"NATE_COMERCIAL", pregunta:"En un Chiller que opera con R-123 (baja presión), ¿cuál es la función de la 'Unidad de Purga' (Purge Unit)?", opciones:["Limpiar el aceite", "Remover aire y gases no condensables que se filtran hacia adentro del sistema debido al vacío", "Cargar refrigerante", "Enfriar el panel eléctrico"], respuesta_correcta:1, explicacion:"Como el Chiller opera bajo la presión atmosférica, cualquier fuga permite que entre aire. La purga saca ese aire y devuelve el refrigerante al sistema." , question: "In a Chiller operating with R-123 (low pressure), what is the function of the Purge Unit?", options: ["To clean the oil", "To remove air and non-condensable gases that leak into the system due to the vacuum", "To charge refrigerant", "To cool the electrical panel"], explanation: "Since the Chiller operates below atmospheric pressure, any leak allows air to enter. The purge unit removes that air and returns the refrigerant to the system." },
  { id:"nate_255", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la temperatura teórica más baja a la que una torre de enfriamiento puede enfriar el agua?", opciones:["La temperatura de Bulbo Seco ambiente", "La temperatura de Bulbo Húmedo ambiente", "32°F", "La temperatura del punto de rocío"], respuesta_correcta:1, explicacion:"La torre enfría por evaporación. No puede enfriar el agua por debajo de la capacidad del aire para absorber humedad (Bulbo Húmedo)." , question: "What is the theoretical lowest temperature to which a cooling tower can cool water?", options: ["The ambient Dry Bulb temperature", "The ambient Wet Bulb temperature", "32°F", "The dew point temperature"], explanation: "The tower cools by evaporation. It cannot cool the water below the air's capacity to absorb moisture (Wet Bulb)." },
  { id:"nate_256", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es el fenómeno de 'Surge' (Bombeo) en un compresor centrífugo?", opciones:["Un aumento de potencia", "Una inversión momentánea del flujo de refrigerante cuando la presión de descarga supera la energía del impulsor", "Cuando el compresor se llena de aceite", "Un arranque suave"], respuesta_correcta:1, explicacion:"Es una condición vibratoria violenta y peligrosa que puede destruir los cojinetes y engranajes del compresor." , question: "What is the phenomenon of Surge in a centrifugal compressor?", options: ["A power increase", "A momentary reversal of refrigerant flow when the discharge pressure exceeds the impeller's energy", "When the compressor fills with oil", "A soft start"], explanation: "It is a violent and dangerous vibratory condition that can destroy the compressor's bearings and gears." },
  { id:"nate_257", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la diferencia entre una válvula de 2 vías y una de 3 vías en un sistema de agua helada?", opciones:["La de 3 vías es más grande", "La de 2 vías varía el flujo, la de 3 vías desvía (bypass) el flujo manteniendo el volumen constante", "Solo el precio", "La de 2 vías es para gas y la de 3 para agua"], respuesta_correcta:1, explicacion:"Las de 2 vías se usan con bombas de velocidad variable; las de 3 vías se usaban antes para mantener la presión en bombas de velocidad fija." , question: "What is the difference between a 2-way valve and a 3-way valve in a chilled water system?", options: ["The 3-way valve is larger", "The 2-way valve varies the flow, while the 3-way valve diverts (bypasses) flow to maintain constant volume", "Only the price differs", "The 2-way is for gas and the 3-way is for water"], explanation: "Two-way valves are used with variable speed pumps; three-way valves were previously used to maintain pressure with constant speed pumps." },
  { id:"nate_258", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es el riesgo principal de que el sensor de flujo (Flow Switch) del evaporador sea puenteado o falle?", opciones:["Que el agua se caliente mucho", "Congelamiento y ruptura de los tubos del evaporador al no haber flujo de agua", "Que el compresor consuma más gas", "Ninguno, el sistema tiene otros sensores"], respuesta_correcta:1, explicacion:"Si el compresor enfría agua que no se mueve, el agua se convierte en hielo rápidamente, expandiéndose y reventando los tubos de cobre internos." , question: "What is the main risk if the evaporator Flow Switch is jumpered or fails?", options: ["The water overheats", "Freezing and rupture of the evaporator tubes due to lack of water flow", "The compressor uses more refrigerant", "None, the system has other sensors"], explanation: "If the compressor cools water that is not moving, the water quickly turns to ice, expanding and bursting the internal copper tubes." },
  { id:"nate_259", categoria:"NATE_COMERCIAL", pregunta:"En un lazo de control PID, ¿qué representa la parte 'Integral' (I)?", opciones:["La velocidad de la respuesta", "La corrección del error acumulado en el tiempo para alcanzar exactamente el setpoint", "La protección del motor", "El encendido y apagado"], respuesta_correcta:1, explicacion:"El control integral elimina el 'offset' o la diferencia constante entre la temperatura real y la deseada." , question: "In a PID control loop, what does the Integral (I) component represent?", options: ["The speed of the response", "The correction of accumulated error over time to reach the setpoint exactly", "Motor protection", "On/off switching"], explanation: "Integral control eliminates the 'offset' or constant difference between the actual temperature and the desired temperature." },
  { id:"nate_260", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué se añade Glicol al agua en sistemas de Chiller que operan en procesos industriales de muy baja temperatura?", opciones:["Para que el agua se vea azul", "Para reducir el punto de congelación del agua y evitar que el sistema se rompa", "Para lubricar la bomba", "Para limpiar las tuberías"], respuesta_correcta:1, explicacion:"El glicol actúa como anticongelante, permitiendo que el fluido circule a temperaturas bajo cero sin volverse sólido." , question: "Why is Glycol added to water in Chiller systems that operate in very low temperature industrial processes?", options: ["To make the water look blue", "To lower the freezing point of the water and prevent the system from cracking", "To lubricate the pump", "To clean the piping"], explanation: "Glycol acts as antifreeze, allowing the fluid to circulate at sub-zero temperatures without solidifying." },
  { id:"nate_261", categoria:"NATE_COMERCIAL", pregunta:"Un Chiller tiene una 'Eductor Line'. ¿Para qué sirve?", opciones:["Para cargar gas", "Para retornar el aceite desde el evaporador de inundación hacia el compresor", "Para medir la presión", "Para drenar el agua"], respuesta_correcta:1, explicacion:"En evaporadores inundados (Shell and Tube), el aceite tiende a flotar o mezclarse; la línea eductora usa presión para recuperarlo." , question: "A Chiller has an Eductor Line. What is its purpose?", options: ["To charge refrigerant", "To return oil from the flooded evaporator back to the compressor", "To measure pressure", "To drain the water"], explanation: "In flooded evaporators (Shell and Tube), oil tends to float or mix; the eductor line uses pressure to recover it." },
  { id:"nate_262", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la ventaja de usar un VFD (Variador de Frecuencia) en la bomba de agua helada?", opciones:["Que la bomba hace más ruido", "Ahorro energético masivo al ajustar el flujo a la demanda real del edificio", "Evitar el uso de breakers", "Aumentar el voltaje"], respuesta_correcta:1, explicacion:"Reducir la velocidad de la bomba a la mitad reduce el consumo de potencia a casi un octavo (leyes de afinidad)." , question: "What is the advantage of using a VFD (Variable Frequency Drive) on a chilled water pump?", options: ["The pump makes more noise", "Massive energy savings by adjusting flow to the building's actual demand", "It eliminates the need for breakers", "It increases the voltage"], explanation: "Reducing the pump speed by half reduces power consumption to nearly one-eighth (affinity laws)." },
  { id:"nate_263", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es el 'Fill' (Relleno) dentro de una torre de enfriamiento?", opciones:["Basura acumulada", "Material diseñado para aumentar el área de superficie y el tiempo de contacto entre el agua y el aire", "El flotador del agua", "El motor del ventilador"], respuesta_correcta:1, explicacion:"Maximiza la evaporación. Si el relleno está sucio o roto, la torre pierde toda su capacidad de enfriamiento." , question: "What is the Fill inside a cooling tower?", options: ["Accumulated debris", "Material designed to increase surface area and contact time between water and air", "The water float", "The fan motor"], explanation: "It maximizes evaporation. If the fill is dirty or broken, the tower loses all of its cooling capacity." },
  { id:"nate_264", categoria:"NATE_COMERCIAL", pregunta:"Si las presiones de un Chiller son normales pero el 'Delta T' del agua en el evaporador es de solo 2°F (debería ser 10°F), ¿cuál es el problema?", opciones:["Falta de refrigerante", "Excesivo flujo de agua (la bomba está moviendo el agua demasiado rápido)", "El compresor está fallando", "El agua está muy sucia"], respuesta_correcta:1, explicacion:"Si el agua pasa volando por el evaporador, no tiene tiempo de ceder su calor al refrigerante. El Delta T cae aunque el Chiller esté bien." , question: "If a Chiller's pressures are normal but the evaporator water Delta T is only 2°F (should be 10°F), what is the problem?", options: ["Low refrigerant charge", "Excessive water flow (the pump is moving the water too fast)", "Compressor failure", "Dirty water"], explanation: "If the water passes through the evaporator too quickly, it does not have time to transfer its heat to the refrigerant. The Delta T drops even though the Chiller is working fine." },
  { id:"nate_265", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es BACnet en el mundo de HVAC comercial?", opciones:["Una marca de termostatos", "Un protocolo de comunicación estándar que permite que equipos de diferentes marcas hablen entre sí", "Una red social para técnicos", "Un tipo de cable eléctrico"], respuesta_correcta:1, explicacion:"Permite que un Chiller York hable con un sistema de control Honeywell y ventiladores Trane bajo una misma red." , question: "What is BACnet in commercial HVAC?", options: ["A thermostat brand", "A standard communication protocol that allows equipment from different manufacturers to communicate with each other", "A social network for technicians", "A type of electrical cable"], explanation: "It allows a York Chiller to communicate with a Honeywell control system and Trane fans under a single network." },
  { id:"nate_266", categoria:"NATE_COMERCIAL", pregunta:"¿Cómo modula la capacidad un compresor de tornillo (Screw Compressor) en un Chiller?", opciones:["Prendiendo y apagando", "Mediante una válvula de corredera (Slide Valve) que varía la longitud de la cámara de compresión", "Cambiando el aceite", "Cerrando la succión"], respuesta_correcta:1, explicacion:"La válvula desliza para dejar escapar gas antes de ser comprimido, permitiendo un control de 25% a 100% de carga." , question: "How does a Screw Compressor in a Chiller modulate capacity?", options: ["By turning on and off", "By means of a Slide Valve that varies the length of the compression chamber", "By changing the oil", "By closing the suction"], explanation: "The valve slides to let gas escape before being compressed, allowing control from 25% to 100% load." },
  { id:"nate_267", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es la 'Cavitación' en una bomba de agua y qué ruido produce?", opciones:["Es aire en el sistema y no hace ruido", "Formación de burbujas de vapor que colapsan violentamente; suena como si la bomba tuviera piedras o canicas adentro", "Es cuando la bomba gira al revés", "Un zumbido eléctrico"], respuesta_correcta:1, explicacion:"Ocurre cuando la presión de succión es muy baja. El colapso de las burbujas pica y destruye el impulsor de metal." , question: "What is Cavitation in a water pump and what sound does it produce?", options: ["It is air in the system and it makes no noise", "Formation of vapor bubbles that collapse violently; it sounds like the pump has rocks or marbles inside", "It is when the pump spins in reverse", "An electrical hum"], explanation: "It occurs when suction pressure is too low. The collapsing bubbles pit and destroy the metal impeller." },
  { id:"nate_268", categoria:"NATE_COMERCIAL", pregunta:"Si un Chiller enfriado por agua tiene una presión de descarga extremadamente alta, ¿qué es lo primero que revisarías?", opciones:["La carga de gas", "La bomba de la torre de enfriamiento y el estado de limpieza de los tubos del condensador", "El termostato del edificio", "El aceite del compresor"], respuesta_correcta:1, explicacion:"En Chillers, el condensador depende totalmente del agua de la torre. Si no hay flujo o los tubos están tapados de sarro, la presión se dispara." , question: "If a water-cooled Chiller has an extremely high discharge pressure, what would you check first?", options: ["The refrigerant charge", "The cooling tower pump and the cleanliness of the condenser tubes", "The building thermostat", "The compressor oil"], explanation: "In Chillers, the condenser relies entirely on tower water. If there is no flow or the tubes are clogged with scale, the pressure spikes." },
  { id:"nate_269", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la diferencia entre un sensor de temperatura de 2 hilos y uno de 3 hilos (RTD)?", opciones:["El de 3 hilos es más barato", "El tercer hilo compensa la resistencia del cableado para lecturas de alta precisión en largas distancias", "No hay diferencia", "El tercer hilo es para la luz"], respuesta_correcta:1, explicacion:"En edificios grandes, los cables largos añaden Ohms a la lectura. El tercer hilo anula ese error." , question: "What is the difference between a 2-wire and a 3-wire temperature sensor (RTD)?", options: ["The 3-wire is cheaper", "The third wire compensates for cable resistance to provide high-accuracy readings over long distances", "There is no difference", "The third wire is for lighting"], explanation: "In large buildings, long cables add ohms to the reading. The third wire cancels that error." },
  { id:"nate_270", categoria:"NATE_COMERCIAL", pregunta:"¿Qué bacteria peligrosa puede crecer en torres de enfriamiento mal mantenidas?", opciones:["Salmonella", "Legionella Pneumophila", "E. Coli", "Gripe A"], respuesta_correcta:1, explicacion:"Es una bacteria que se transmite por el aerosol (vapor) de la torre y puede causar neumonía mortal. El tratamiento químico es obligatorio." , question: "What dangerous bacterium can grow in poorly maintained cooling towers?", options: ["Salmonella", "Legionella Pneumophila", "E. Coli", "Influenza A"], explanation: "It is a bacterium transmitted by the tower's aerosol (mist) that can cause fatal pneumonia. Chemical treatment is mandatory." },
  { id:"nate_271", categoria:"NATE_COMERCIAL", pregunta:"En un Chiller de baja presión, ¿qué indica que la unidad de purga esté operando con demasiada frecuencia?", opciones:["Que el Chiller es muy eficiente", "Que hay una fuga significativa en el sistema (el aire está entrando)", "Que le falta aceite", "Es normal en verano"], respuesta_correcta:1, explicacion:"La purga solo debe trabajar ocasionalmente. Si trabaja mucho, indica que el sello del eje o alguna junta está dejando entrar aire." , question: "In a low-pressure Chiller, what does it indicate if the purge unit is operating too frequently?", options: ["That the Chiller is very efficient", "That there is a significant leak in the system (air is entering)", "That the oil level is low", "It is normal during summer"], explanation: "The purge should only operate occasionally. If it runs frequently, it indicates that a shaft seal or gasket is allowing air in." },
  { id:"nate_272", categoria:"NATE_COMERCIAL", pregunta:"¿Qué significa 'Fail-Safe' en un actuador de válvula de agua helada?", opciones:["Que nunca falla", "Que la válvula regresa a una posición segura (abierta o cerrada) mediante un resorte si se pierde la energía eléctrica", "Que la válvula explota", "Que se bloquea manualmente"], respuesta_correcta:1, explicacion:"Por ejemplo, en calefacción quieres que la válvula falle en 'abierto' para evitar que se congelen las tuberías del edificio." , question: "What does 'Fail-Safe' mean in a chilled water valve actuator?", options: ["That it never fails", "That the valve returns to a safe position (open or closed) via a spring if electrical power is lost", "That the valve explodes", "That it locks manually"], explanation: "For example, in heating you want the valve to fail 'open' to prevent the building's pipes from freezing." },
  { id:"nate_273", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es un 'Drift Eliminator' (Eliminador de Arrastre)?", opciones:["Un filtro de aire", "Láminas que atrapan las gotas de agua líquida para que no salgan volando de la torre con el aire", "Un repelente de insectos", "El ventilador de la torre"], respuesta_correcta:1, explicacion:"Evita que la torre 'llueva' sobre el estacionamiento y conserva agua y químicos dentro del sistema." , question: "What is a Drift Eliminator?", options: ["An air filter", "Blades that capture liquid water droplets to prevent them from being carried out of the tower with the airstream", "A bug repellent", "The tower fan"], explanation: "It prevents the tower from 'raining' onto the parking lot and conserves water and chemicals within the system." },
  { id:"nate_274", categoria:"NATE_COMERCIAL", pregunta:"¿Cuántos GPM (Galones por Minuto) de agua helada se requieren por tonelada para un Delta T estándar de 10°F?", opciones:["1.0 GPM/ton", "2.4 GPM/ton", "4.0 GPM/ton", "10 GPM/ton"], respuesta_correcta:1, explicacion:"Fórmula: GPM = BTU / (500 * Delta T). Para 12,000 BTU y 10°F: 12,000 / 5,000 = 2.4 GPM por tonelada." , question: "How many GPM (Gallons Per Minute) of chilled water are required per ton for a standard 10°F Delta T?", options: ["1.0 GPM/ton", "2.4 GPM/ton", "4.0 GPM/ton", "10 GPM/ton"], explanation: "Formula: GPM = BTU / (500 x Delta T). For 12,000 BTU and 10°F: 12,000 / 5,000 = 2.4 GPM per ton." },
  { id:"nate_275", categoria:"NATE_COMERCIAL", pregunta:"Un VFD muestra un error de 'DC Bus Overvoltage' al intentar frenar un ventilador de torre muy grande. ¿Causa probable?", opciones:["El motor es muy chico", "Efecto de regeneración (el motor actúa como generador al desacelerar) y falta de resistencias de frenado", "El cableado está flojo", "Falta gas"], respuesta_correcta:1, explicacion:"La inercia del ventilador empuja el motor, enviando energía de vuelta al VFD y saturando los capacitores DC." , question: "A VFD displays a 'DC Bus Overvoltage' error when trying to decelerate a very large tower fan. What is the probable cause?", options: ["The motor is too small", "Regenerative effect (the motor acts as a generator when decelerating) and the absence of braking resistors", "Loose wiring", "Low refrigerant charge"], explanation: "The fan's inertia drives the motor, sending energy back to the VFD and saturating the DC capacitors." },
  { id:"nate_276", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es un 'Orifice Plate' (Placa de Orificio) en un Chiller industrial?", opciones:["Una placa decorativa", "Un dispositivo de expansión de orificio fijo usado en sistemas de carga constante", "Un filtro de aceite", "Una rejilla de ventilación"], respuesta_correcta:1, explicacion:"Se usa a menudo en Chillers centrífugos grandes por su simplicidad y confiabilidad en lugar de válvulas mecánicas complicadas." , question: "What is an Orifice Plate in an industrial Chiller?", options: ["A decorative plate", "A fixed-orifice expansion device used in constant-load systems", "An oil filter", "A ventilation grille"], explanation: "It is often used in large centrifugal Chillers for its simplicity and reliability instead of complicated mechanical valves." },
  { id:"nate_277", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede en un edificio si la presión diferencial en la punta de la línea (End of Line) cae por debajo del setpoint?", opciones:["El Chiller se apaga", "El VFD de las bombas primarias o secundarias aumenta la velocidad para mantener el flujo en los pisos más altos", "Se cierran todas las válvulas", "Explotan las tuberías"], respuesta_correcta:1, explicacion:"El sensor de presión diferencial es el 'cerebro' que le dice a las bombas qué tan rápido deben girar según la demanda de las AHUs." , question: "What happens in a building if the differential pressure at the End of Line drops below the setpoint?", options: ["The Chiller shuts down", "The VFD on the primary or secondary pumps increases speed to maintain flow to the upper floors", "All valves close", "The pipes burst"], explanation: "The differential pressure sensor is the 'brain' that tells the pumps how fast to run based on AHU demand." },
  { id:"nate_278", categoria:"NATE_COMERCIAL", pregunta:"Al limpiar los tubos de un condensador de Chiller con un cepillo rotativo, ¿por qué es vital que el agua fluya constantemente?", opciones:["Para mojar al técnico", "Para lubricar el cepillo y remover el lodo y sarro desprendido inmediatamente", "Para enfriar el cobre", "Para que el cepillo no haga ruido"], respuesta_correcta:1, explicacion:"Sin agua, el sarro se convierte en una pasta que puede trabar el cepillo o rayar los tubos de cobre." , question: "When cleaning a Chiller condenser's tubes with a rotary brush, why is it vital that water flows constantly?", options: ["To get the technician wet", "To lubricate the brush and immediately flush away loosened sludge and scale", "To cool the copper", "So the brush doesn't make noise"], explanation: "Without water, the scale turns into a paste that can jam the brush or scratch the copper tubes." },
  { id:"nate_279", categoria:"NATE_COMERCIAL", pregunta:"Un transductor de presión de 0-100 psi entrega una señal de 4-20mA. Si el multímetro marca 12mA, ¿cuál es la presión real?", opciones:["12 psi", "50 psi", "25 psi", "100 psi"], respuesta_correcta:1, explicacion:"El rango es de 16mA (20-4). 12mA está justo a la mitad del rango (8mA por encima de los 4mA base). 50% de 100 psi = 50 psi." , question: "A 0-100 psi pressure transducer outputs a 4-20mA signal. If the multimeter reads 12mA, what is the actual pressure?", options: ["12 psi", "50 psi", "25 psi", "100 psi"], explanation: "The range spans 16mA (20-4). 12mA is exactly at the midpoint (8mA above the 4mA base). 50% of 100 psi = 50 psi." },
  { id:"nate_280", categoria:"NATE_COMERCIAL", pregunta:"En un sistema de Chiller, ¿qué es el 'Log de Operación' (Daily Log)?", opciones:["Un pedazo de madera", "Un registro diario de presiones, temperaturas y amperajes para detectar tendencias de falla antes de que ocurran", "La factura del cliente", "El manual de usuario"], respuesta_correcta:1, explicacion:"Es la herramienta más poderosa del técnico comercial. Comparar los datos de hoy con los de hace un mes permite ver si el sistema está perdiendo eficiencia." , question: "In a Chiller system, what is the Daily Operating Log?", options: ["A piece of wood", "A daily record of pressures, temperatures, and amperages used to detect failure trends before they occur", "The customer's invoice", "The user manual"], explanation: "It is the commercial technician's most powerful tool. Comparing today's data with last month's reveals whether the system is losing efficiency." },
  { id:"nate_281", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es una 'Salida Binaria' (BO) en un controlador DDC?", opciones:["Un número del 0 al 10", "Un contacto seco o relé que solo tiene dos estados: Encendido o Apagado", "Una señal para variar la velocidad", "Una entrada de sensor"], respuesta_correcta:1, explicacion:"Se usa para arrancar motores, encender luces o activar solenoides de encendido/apagado." , question: "What is a Binary Output (BO) in a DDC controller?", options: ["A number from 0 to 10", "A dry contact or relay that has only two states: On or Off", "A signal to vary speed", "A sensor input"], explanation: "It is used to start motors, turn on lights, or activate on/off solenoids." },
  { id:"nate_282", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la desventaja principal de un Chiller enfriado por aire frente a uno enfriado por agua?", opciones:["Es más ruidoso", "Menor eficiencia energética (EER) y vida útil más corta debido a la exposición al clima", "No usa compresor", "Usa más agua"], respuesta_correcta:1, explicacion:"El aire es menos eficiente que el agua para rechazar calor, por lo que el compresor debe trabajar a presiones de descarga mucho más altas." , question: "What is the main disadvantage of an air-cooled Chiller compared to a water-cooled Chiller?", options: ["It is noisier", "Lower energy efficiency (EER) and shorter lifespan due to weather exposure", "It does not use a compressor", "It uses more water"], explanation: "Air is less efficient than water at rejecting heat, so the compressor must operate at much higher discharge pressures." },
  { id:"nate_283", categoria:"NATE_COMERCIAL", pregunta:"Ves agua goteando constantemente de la base del eje de una bomba de agua helada de 20 HP. ¿Qué debe reemplazarse?", opciones:["Toda la bomba", "El sello mecánico", "El rodamiento del motor", "El impulsor"], respuesta_correcta:1, explicacion:"El sello mecánico evita que el agua a presión se escape por donde el eje entra a la voluta de la bomba. Es una pieza de desgaste normal." , question: "You see water constantly dripping from the shaft base of a 20 HP chilled water pump. What needs to be replaced?", options: ["The entire pump", "The mechanical seal", "The motor bearing", "The impeller"], explanation: "The mechanical seal prevents pressurized water from escaping where the shaft enters the pump volute. It is a normal wear item." },
  { id:"nate_284", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la función de una caja VAV (Variable Air Volume) en un sistema comercial?", opciones:["Enfriar el aire", "Controlar la cantidad de aire frío que entra a una zona específica basándose en el termostato local", "Limpiar los ductos", "Cambiar el filtro"], respuesta_correcta:1, explicacion:"Permite que un solo Chiller y una sola AHU den diferentes niveles de confort a 50 oficinas distintas." , question: "What is the function of a VAV (Variable Air Volume) box in a commercial system?", options: ["To cool the air", "To control the amount of cold air entering a specific zone based on the local thermostat", "To clean the ductwork", "To change the filter"], explanation: "It allows a single Chiller and a single AHU to provide different comfort levels to 50 different offices." },
  { id:"nate_285", categoria:"NATE_COMERCIAL", pregunta:"En un evaporador 'Inundado', ¿por dónde circula el agua y por dónde el refrigerante?", opciones:["El agua va por la coraza y el refrigerante por los tubos", "El refrigerante va por la coraza y el agua por dentro de los tubos", "Ambos van mezclados", "No usan agua"], respuesta_correcta:1, explicacion:"Es el diseño inverso al residencial. Esto permite una transferencia de calor masiva en Chillers de cientos de toneladas." , question: "In a Flooded Evaporator, where does the water flow and where does the refrigerant flow?", options: ["Water goes through the shell and refrigerant through the tubes", "Refrigerant goes through the shell and water flows inside the tubes", "Both are mixed together", "They do not use water"], explanation: "It is the inverse of residential design. This allows massive heat transfer in Chillers of hundreds of tons." },
  { id:"nate_286", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué se alternan dos tipos diferentes de biocidas en el tratamiento de agua de una torre?", opciones:["Para que el agua huela mejor", "Para evitar que las bacterias y algas desarrollen resistencia inmunológica a un solo veneno", "Porque uno es para el día y otro para la noche", "Para ahorrar dinero"], respuesta_correcta:1, explicacion:"Es como los antibióticos; si siempre usas el mismo, las bacterias aprenden a sobrevivir. Se usan biocidas oxidantes y no-oxidantes." , question: "Why are two different types of biocides alternated in cooling tower water treatment?", options: ["To make the water smell better", "To prevent bacteria and algae from developing resistance to a single chemical", "Because one is for daytime and the other for nighttime", "To save money"], explanation: "Like antibiotics, if you always use the same one, bacteria learn to survive. Oxidizing and non-oxidizing biocides are alternated." },
  { id:"nate_287", categoria:"NATE_COMERCIAL", pregunta:"¿Cuál es la función de un 'Soft Starter' en un compresor de tornillo grande?", opciones:["Enfriar el motor", "Reducir el pico de corriente de arranque (LRA) aumentando el voltaje gradualmente", "Cambiar la velocidad", "Proteger contra rayos"], respuesta_correcta:1, explicacion:"Evita caídas de voltaje en el edificio y estrés mecánico en los acoplamientos del compresor al arrancar." , question: "What is the function of a Soft Starter on a large screw compressor?", options: ["To cool the motor", "To reduce the inrush current peak (LRA) by gradually increasing the voltage", "To change the speed", "To protect against lightning"], explanation: "It prevents voltage drops in the building and mechanical stress on the compressor couplings during startup." },
  { id:"nate_288", categoria:"NATE_COMERCIAL", pregunta:"La torre de enfriamiento se está desbordando por el drenaje de exceso (overflow) continuamente. ¿Qué revisarías?", opciones:["Si el ventilador gira muy rápido", "La válvula de llenado (make-up valve) o el flotador descalibrado/perforado", "Si el agua está muy caliente", "El tamaño de la bomba"], respuesta_correcta:1, explicacion:"Si el flotador se llena de agua o la válvula no sella, el agua entrará sin parar hasta tirarse por el drenaje." , question: "The cooling tower is continuously overflowing through its overflow drain. What would you check?", options: ["If the fan is spinning too fast", "The make-up water valve or the miscalibrated/punctured float", "If the water is too hot", "The pump size"], explanation: "If the float fills with water or the valve does not seal, water will enter non-stop until it overflows through the drain." },
  { id:"nate_289", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué un sistema DDC ajusta la temperatura del agua helada (Chilled Water Reset) hacia arriba cuando la carga del edificio es baja?", opciones:["Para que el cliente tenga calor", "Para ahorrar energía en el compresor, ya que no necesita enfriar tanto el agua si no hay demanda", "Para evitar que las tuberías suden", "Porque el Chiller se cansa"], respuesta_correcta:1, explicacion:"Cada grado que subes el setpoint del agua helada ahorra aproximadamente un 2-3% de energía en el compresor." , question: "Why does a DDC system adjust the chilled water temperature (Chilled Water Reset) upward when the building load is low?", options: ["To make the occupants warm", "To save compressor energy, since it does not need to cool the water as much when demand is low", "To prevent pipes from sweating", "Because the Chiller gets tired"], explanation: "Every degree you raise the chilled water setpoint saves approximately 2-3% of compressor energy." },
  { id:"nate_290", categoria:"NATE_COMERCIAL", pregunta:"¿Qué caracteriza a los compresores Turbocor (Maglev)?", opciones:["Usan aceite sintético especial", "No usan aceite; el eje levita mediante imanes permanentes y rodamientos electromagnéticos", "Son muy ruidosos", "Funcionan con gas natural"], respuesta_correcta:1, explicacion:"Al no haber fricción ni aceite, son increíblemente eficientes y requieren mucho menos mantenimiento." , question: "What characterizes Turbocor (Maglev) compressors?", options: ["They use special synthetic oil", "They are oil-free; the shaft levitates using permanent magnets and electromagnetic bearings", "They are very noisy", "They run on natural gas"], explanation: "With no friction and no oil, they are incredibly efficient and require far less maintenance." },
  { id:"nate_291", categoria:"NATE_COMERCIAL", pregunta:"¿Qué es el 'Reheat' (Recalentamiento) en una manejadora de aire comercial?", opciones:["Un error del sistema", "Calentar el aire después de haberlo enfriado para deshumidificarlo sin sobre-enfriar la habitación", "Cocinar dentro de la AHU", "Ahorrar gas"], respuesta_correcta:1, explicacion:"Enfriamos el aire a 55°F para quitarle el agua, pero si el cuarto ya está frío, lo recalentamos a 65°F antes de inyectarlo." , question: "What is Reheat in a commercial air handling unit?", options: ["A system error", "Heating the air after it has been cooled in order to dehumidify it without over-cooling the room", "Cooking inside the AHU", "Saving gas"], explanation: "We cool the air to 55°F to remove moisture, but if the room is already cold, we reheat it to 65°F before supplying it." },
  { id:"nate_292", categoria:"NATE_COMERCIAL", pregunta:"Después de cambiar un motor de una bomba de acoplamiento directo, ¿qué paso es obligatorio antes de arrancar?", opciones:["Pintar el motor", "Realizar una alineación láser o con indicador de carátula del eje del motor con el eje de la bomba", "Llenar la bomba de aceite", "Cambiar los breakers"], respuesta_correcta:1, explicacion:"Una desalineación de milímetros destruirá los rodamientos y el sello mecánico en pocos días." , question: "After replacing a motor on a direct-coupled pump, what step is mandatory before startup?", options: ["Paint the motor", "Perform a laser alignment or dial indicator alignment of the motor shaft to the pump shaft", "Fill the pump with oil", "Replace the breakers"], explanation: "A misalignment of just millimeters will destroy the bearings and mechanical seal within days." },
  { id:"nate_293", categoria:"NATE_COMERCIAL", pregunta:"Al realizar mantenimiento, encuentras aire atrapado en la parte superior de la coraza del condensador del Chiller. ¿Cómo lo sacas?", opciones:["Abriendo una manguera de gas", "Usando las válvulas de purga manual (Air Vents) situadas en los puntos más altos de las cajas de agua", "Haciendo vacío con el equipo encendido", "Drenando todo el agua"], respuesta_correcta:1, explicacion:"El aire acumulado impide que el agua toque los tubos superiores, reduciendo la capacidad de condensación." , question: "During maintenance, you find air trapped at the top of the Chiller condenser shell. How do you remove it?", options: ["Open a refrigerant hose", "Use the manual air vent valves located at the highest points of the water boxes", "Pull a vacuum with the unit running", "Drain all the water"], explanation: "Trapped air prevents water from contacting the upper tubes, reducing condensing capacity." },
  { id:"nate_294", categoria:"NATE_COMERCIAL", pregunta:"¿Qué significa que un actuador sea 'Modulante'?", opciones:["Que habla", "Que puede posicionar la válvula en cualquier punto entre 0% y 100% basándose en una señal de control", "Que solo abre y cierra", "Que cambia de color"], respuesta_correcta:1, explicacion:"Permite un control preciso de la temperatura abriendo la válvula exactamente lo necesario (ej. 34%)." , question: "What does it mean for an actuator to be 'Modulating'?", options: ["That it talks", "That it can position the valve at any point between 0% and 100% based on a control signal", "That it only opens and closes", "That it changes color"], explanation: "It allows precise temperature control by opening the valve exactly as much as needed (e.g., 34%)." },
  { id:"nate_295", categoria:"NATE_COMERCIAL", pregunta:"En un sistema 'Primary-Secondary', ¿dónde se ubican los Chillers?", opciones:["En el lazo secundario", "En el lazo primario (producción)", "En el techo", "Después de las manejadoras"], respuesta_correcta:1, explicacion:"El lazo primario produce el agua fría a flujo constante, mientras el secundario la distribuye por el edificio a flujo variable." , question: "In a Primary-Secondary system, where are the Chillers located?", options: ["In the secondary loop", "In the primary loop (production)", "On the roof", "After the air handling units"], explanation: "The primary loop produces chilled water at constant flow, while the secondary loop distributes it throughout the building at variable flow." },
  { id:"nate_296", categoria:"NATE_COMERCIAL", pregunta:"Si trabajas en una sala de máquinas con Chiller de Amoníaco, ¿cuál es el color de las máscaras de gas específicas para este refrigerante?", opciones:["Verde", "Gris", "Verde con banda negra (K)", "Amarillo"], respuesta_correcta:2, explicacion:"Es el estándar internacional para filtros que protegen contra vapores de amoníaco. El color es una señal de vida o muerte." , question: "If you work in a mechanical room with an Ammonia Chiller, what is the color of the gas masks specific to this refrigerant?", options: ["Green", "Gray", "Green with a black band (K)", "Yellow"], explanation: "This is the international standard for filters that protect against ammonia vapors. The color coding is a life-or-death indicator." },
  { id:"nate_297", categoria:"NATE_COMERCIAL", pregunta:"¿Por qué un economizador de aire exterior prefiere usar un sensor de Entalpía en lugar de solo uno de temperatura?", opciones:["Porque es más barato", "Porque el sensor de entalpía mide calor total (humedad + temperatura), evitando meter aire 'fresco' pero muy húmedo al edificio", "Porque dura más", "Porque mide la presión"], respuesta_correcta:1, explicacion:"Si afuera hay 70°F pero 90% de humedad, meter ese aire obligaría al Chiller a trabajar de más para deshumidificarlo." , question: "Why does an outdoor air economizer prefer to use an Enthalpy sensor instead of just a temperature sensor?", options: ["Because it is cheaper", "Because the enthalpy sensor measures total heat (humidity + temperature), preventing the introduction of 'cool' but very humid air into the building", "Because it lasts longer", "Because it measures pressure"], explanation: "If it is 70°F outside but at 90% humidity, bringing that air in would force the Chiller to work extra hard to dehumidify it." },
  { id:"nate_298", categoria:"NATE_COMERCIAL", pregunta:"¿Qué sucede con el agua de la torre si el ventilador gira en reversa?", opciones:["Se enfría más", "El aire es empujado hacia abajo, reduciendo drásticamente la evaporación y subiendo la temperatura del agua", "Se congela", "La bomba se rompe"], respuesta_correcta:1, explicacion:"Las torres están diseñadas para que el aire suba (tiro inducido) en contra del agua que cae." , question: "What happens with the tower water if the fan spins in reverse?", options: ["It cools better", "The air is pushed downward, drastically reducing evaporation and raising the water temperature", "It freezes", "The pump breaks"], explanation: "Towers are designed for air to move upward (induced draft) against the falling water." },
  { id:"nate_299", categoria:"NATE_COMERCIAL", pregunta:"¿Qué problema causan los VFDs en la red eléctrica de un hospital o centro de datos?", opciones:["Ahorran mucha luz", "Generan distorsión armónica que puede sobrecalentar transformadores e interferir con equipos médicos sensibles", "Mejoran el factor de potencia", "Hacen que las luces brillen más"], respuesta_correcta:1, explicacion:"La electrónica de potencia de los VFDs 'ensucia' la onda senoidal de la electricidad." , question: "What problem do VFDs cause in the electrical grid of a hospital or data center?", options: ["They save a lot of energy", "They generate harmonic distortion that can overheat transformers and interfere with sensitive medical equipment", "They improve power factor", "They make lights brighter"], explanation: "The power electronics in VFDs 'dirty' the sinusoidal waveform of the electrical supply." },
  { id:"nate_300", categoria:"NATE_COMERCIAL", pregunta:"Un Chiller centrífugo está operando al 100% de carga. La presión de condensación sube rápidamente y el compresor empieza a hacer un ruido como 'estornudos' fuertes. ¿Qué acción inmediata toma el sistema?", opciones:["Aumentar la velocidad", "Cerrar las paletas de entrada (Pre-rotation vanes) y posiblemente apagar por protección contra Surge", "Abrir la válvula de gas", "Cargar más refrigerante"], respuesta_correcta:1, explicacion:"El sistema intenta reducir el flujo para estabilizar la presión y evitar que el Surge destruya el impulsor del compresor." , question: "A centrifugal Chiller is operating at 100% load. The condensing pressure rises rapidly and the compressor begins making loud 'sneezing' noises. What immediate action does the system take?", options: ["Increase speed", "Close the pre-rotation vanes (inlet guide vanes) and possibly shut down on Surge protection", "Open the gas valve", "Add more refrigerant"], explanation: "The system tries to reduce flow to stabilize pressure and prevent Surge from destroying the compressor impeller." },

  // -- Diagnóstico y Diseño (301-399) --
  { id:"nate_301", categoria:"NATE_DIAGNOSTICO", pregunta:"Un técnico encuentra: Presión de succión alta, Presión de descarga baja, Amperaje mucho menor al RLA, y el compresor se siente apenas tibio. ¿Cuál es el diagnóstico?", opciones:["Falta de refrigerante", "Válvulas internas del compresor dañadas o biela rota", "Condensador sucio", "TXV trabada abierta"], respuesta_correcta:1, explicacion:"Si el compresor no puede bombear, no succiona (sube presión) ni comprime (baja presión). Al no mover masa de gas, el motor no hace esfuerzo y el amperaje cae." , question: "A technician finds: high suction pressure, low discharge pressure, amperage much lower than RLA, and the compressor feels barely warm. What is the diagnosis?", options: ["Low refrigerant charge", "Damaged internal compressor valves or a broken connecting rod", "Dirty condenser", "TXV stuck open"], explanation: "If the compressor cannot pump, it does not draw suction (pressure rises) nor compress (pressure drops). Without moving refrigerant mass, the motor exerts no effort and amperage falls." },
  { id:"nate_302", categoria:"NATE_DIAGNOSTICO", pregunta:"Sistema con TXV: Succión muy baja, Superheat muy alto (40°F), Subcooling normal (10°F). Al calentar el bulbo de la TXV con la mano, nada cambia. ¿Qué sucede?", opciones:["Falta gas", "Bulbo de la TXV perdió su carga de potencia o la válvula está trabada cerrada", "El filtro de aire está sucio", "El compresor está fallando"], respuesta_correcta:1, explicacion:"Si el SC es normal, hay gas en el condensador. Si el SH es alto y la válvula no reacciona al calor, el mecanismo de apertura está muerto." , question: "System with TXV: very low suction, very high superheat (40°F), normal subcooling (10°F). Warming the TXV bulb by hand produces no change. What is happening?", options: ["Low refrigerant charge", "The TXV bulb has lost its power element charge or the valve is stuck closed", "The air filter is dirty", "The compressor is failing"], explanation: "If the subcooling is normal, there is refrigerant in the condenser. If superheat is high and the valve does not respond to heat, the opening mechanism is dead." },
  { id:"nate_303", categoria:"NATE_DIAGNOSTICO", pregunta:"El cliente se queja de 'aire tibio'. Encuentras el evaporador congelado totalmente, pero el filtro está nuevo y el soplador gira. Notas que el amperaje del motor del soplador es mucho menor al de la placa. ¿Causa?", opciones:["Motor quemado", "Ductos de retorno colapsados o restringidos (el motor no mueve aire y no hace trabajo)", "Exceso de gas", "Capacitor débil"], respuesta_correcta:1, explicacion:"Un ventilador centrífugo baja su amperaje cuando no tiene aire que mover. Sin flujo de aire, el serpentín se congela." , question: "The customer complains of 'warm air.' You find the evaporator completely frozen, but the filter is new and the blower is spinning. You notice that the blower motor amperage is much lower than the nameplate rating. What is the cause?", options: ["Burned motor", "Collapsed or restricted return ductwork (the motor is not moving air and not doing work)", "Refrigerant overcharge", "Weak capacitor"], explanation: "A centrifugal blower draws lower amperage when it has no air to move. Without airflow, the coil freezes." },
  { id:"nate_304", categoria:"NATE_DIAGNOSTICO", pregunta:"Un Mini-Split Inverter arranca, pero la frecuencia se queda clavada en 30Hz (baja velocidad) y no sube aunque el cuarto esté a 90°F. No hay códigos de error. ¿Qué revisarías?", opciones:["El sensor de temperatura de ambiente (está descalibrado y 'cree' que ya llegó al setpoint)", "Falta de refrigerante", "Capacitor de arranque", "Válvula inversora"], respuesta_correcta:0, explicacion:"Si el sensor marca que el cuarto está a 70°F cuando está a 90°F, la tarjeta nunca pedirá máxima potencia al compresor." , question: "A Mini-Split Inverter starts, but the frequency stays locked at 30Hz (low speed) and does not increase even though the room is at 90°F. There are no error codes. What would you check?", options: ["The room temperature sensor (it is miscalibrated and 'thinks' it has already reached the setpoint)", "Low refrigerant charge", "Start capacitor", "Reversing valve"], explanation: "If the sensor reads 70°F when the room is actually 90°F, the control board will never request maximum power from the compressor." },
  { id:"nate_305", categoria:"NATE_DIAGNOSTICO", pregunta:"Sistema con orificio fijo: Succión alta, Superheat de 0°F (inundando), Descarga alta, Subcooling alto (25°F). ¿Diagnóstico?", opciones:["Evaporador sucio", "Sobrecarga de refrigerante", "Compresor ineficiente", "Motor de condensador lento"], respuesta_correcta:1, explicacion:"El exceso de refrigerante llena el condensador (alto SC) y termina saliendo líquido por el evaporador hacia el compresor (0 SH)." , question: "System with a fixed orifice: high suction, 0°F superheat (flooding), high discharge, high subcooling (25°F). What is the diagnosis?", options: ["Dirty evaporator", "Refrigerant overcharge", "Inefficient compressor", "Slow condenser fan motor"], explanation: "The excess refrigerant fills the condenser (high subcooling) and ends up sending liquid through the evaporator toward the compressor (0°F superheat)." },
  { id:"nate_306", categoria:"NATE_DIAGNOSTICO", pregunta:"Mides 120V de L1 a Tierra y 120V de L2 a Tierra en un condensador, pero entre L1 y L2 mides 0V. ¿Qué está pasando?", opciones:["El equipo está bien", "Se 'voló' solo un fusible en el desconectador y estás midiendo el retorno de la misma fase a través de los bobinados", "El transformador se quemó", "Hay un corto a tierra"], respuesta_correcta:1, explicacion:"Es la trampa clásica. Si una fase se corta, el voltaje de la fase viva viaja por el motor y aparece en la otra terminal. Sin diferencia de potencial (0V), el motor no arranca." , question: "You measure 120V from L1 to Ground and 120V from L2 to Ground at the condensing unit, but between L1 and L2 you measure 0V. What is happening?", options: ["The unit is fine", "Only one fuse in the disconnect has blown and you are reading the same phase feeding back through the windings", "The transformer burned out", "There is a ground fault"], explanation: "This is a classic trap. If one phase is cut, the voltage from the live phase travels through the motor and appears at the other terminal. With no potential difference (0V), the motor will not start." },
  { id:"nate_307", categoria:"NATE_DIAGNOSTICO", pregunta:"Después de hacer vacío a 500 micrones, la presión sube a 1200 y se queda ahí por 20 minutos sin moverse. ¿Qué haces?", opciones:["Buscar otra fuga", "Abrir las válvulas de servicio y arrancar (está seco y hermético)", "Hacer vacío de nuevo porque todavía hay mucha humedad", "Cambiar el aceite de la bomba"], respuesta_correcta:1, explicacion:"Si el vacío se estabiliza por debajo de 2000 micrones, el sistema es hermético. El ligero aumento inicial es normal por la estabilización del sensor." , question: "After pulling a vacuum to 500 microns, the pressure rises to 1,200 and holds there for 20 minutes without moving. What do you do?", options: ["Look for another leak", "Open the service valves and start the system (it is dry and sealed)", "Pull vacuum again because there is still too much moisture", "Change the vacuum pump oil"], explanation: "If the vacuum stabilizes below 2,000 microns, the system is leak-free. The slight initial rise is normal due to sensor stabilization." },
  { id:"nate_308", categoria:"NATE_DIAGNOSTICO", pregunta:"En modo calefacción, el compresor hace un ruido metálico fuerte y la línea de succión está congelada. El ventilador exterior funciona. ¿Causa?", opciones:["Falla del ciclo de defrost", "Migración de líquido (slugging) por falta de carga o acumulador lleno", "Válvula inversora pegada en el medio", "Exceso de aceite"], respuesta_correcta:1, explicacion:"El ruido metálico es el compresor intentando comprimir líquido, lo cual es incompresible y destruye los mecanismos internos." , question: "In heating mode, the compressor makes a loud metallic banging noise and the suction line is frozen. The outdoor fan is running. What is the cause?", options: ["Defrost cycle failure", "Liquid migration (slugging) due to low charge or a full accumulator", "Reversing valve stuck in the middle", "Excess oil"], explanation: "The metallic noise is the compressor trying to compress liquid, which is incompressible and destroys the internal mechanisms." },
  { id:"nate_309", categoria:"NATE_DIAGNOSTICO", pregunta:"Un técnico nota que la presión de descarga baja de 350 psig a 280 psig simplemente con limpiar el condensador que 'se veía limpio'. ¿Qué indica esto?", opciones:["Que el serpentín tenía una capa invisible de grasa o polen (film) bloqueando la transferencia", "Que le faltaba gas", "Que el manómetro está mal", "Que el agua enfrió el gas"], respuesta_correcta:0, explicacion:"A veces la suciedad no es 'lodo', sino una película delgada que actúa como aislante térmico." , question: "A technician notices that the discharge pressure drops from 350 psig to 280 psig simply by cleaning a condenser that 'looked clean.' What does this indicate?", options: ["The coil had an invisible layer of grease or pollen (film) blocking heat transfer", "Low refrigerant charge", "The gauge is faulty", "The water cooled the refrigerant"], explanation: "Sometimes the dirt is not sludge but a thin film that acts as a thermal insulator." },
  { id:"nate_310", categoria:"NATE_DIAGNOSTICO", pregunta:"Un motor de soplador ECM gira pero se detiene al azar. Mides 240V constantes y la señal de control PWM está presente. ¿Qué es lo más probable?", opciones:["El motor se está protegiendo por alta presión estática (ductos chicos)", "El capacitor está fallando", "Falta de refrigerante", "El termostato está mal"], respuesta_correcta:0, explicacion:"Los motores ECM inteligentes monitorean su propio torque. Si la restricción es demasiada, el motor se calienta electrónicamente y se apaga por seguridad." , question: "An ECM blower motor runs but stops randomly. You measure a constant 240V and the PWM control signal is present. What is the most likely cause?", options: ["The motor is self-protecting due to high static pressure (undersized ductwork)", "The capacitor is failing", "Low refrigerant charge", "The thermostat is faulty"], explanation: "Smart ECM motors monitor their own torque. If the restriction is excessive, the motor overheats electronically and shuts down for safety." },
  { id:"nate_311", categoria:"NATE_DIAGNOSTICO", pregunta:"En un rack de refrigeración, la línea de succión está sudando excesivamente hasta la entrada del compresor. El Superheat en el rack es de 2°F. ¿Riesgo?", opciones:["Ninguno, está enfriando bien", "Ruptura de platos de válvulas por retorno de líquido", "Que se congele la tubería", "Aumento de la presión de alta"], respuesta_correcta:1, explicacion:"Un Superheat tan bajo indica que el refrigerante no se evaporó por completo; el líquido llegará al compresor y causará una falla catastrófica." , question: "In a refrigeration rack, the suction line is sweating excessively all the way to the compressor inlet. The superheat at the rack is 2°F. What is the risk?", options: ["None, it is cooling well", "Valve plate failure due to liquid return", "The piping will freeze", "High head pressure increase"], explanation: "Such low superheat indicates the refrigerant has not fully evaporated; liquid will reach the compressor and cause catastrophic failure." },
  { id:"nate_312", categoria:"NATE_DIAGNOSTICO", pregunta:"Al puentear R y Y en la base del termostato, el contactor exterior 'chispea' pero no se queda pegado. ¿Qué revisarías?", opciones:["Si el transformador es de muy pocos VA o hay una resistencia alta en el cable de control", "Si el compresor está amarrado", "Si el fusible del edificio está bien", "El capacitor de marcha"], respuesta_correcta:0, explicacion:"El contactor intenta cerrar, consume energía, el voltaje cae por la debilidad del transformador o cable dañado, y el contactor se suelta. El ciclo se repite creando el chispeo (chatter)." , question: "When jumpering R and Y at the thermostat sub-base, the outdoor contactor 'sparks' but does not hold in. What would you check?", options: ["Whether the transformer has too few VA or there is high resistance in the control wire", "If the compressor is locked up", "If the building fuse is good", "The run capacitor"], explanation: "The contactor tries to close, draws energy, the voltage drops due to a weak transformer or damaged wire, and the contactor releases. The cycle repeats, creating chatter." },
  { id:"nate_313", categoria:"NATE_DIAGNOSTICO", pregunta:"Encuentras escarcha (hielo) a la salida del filtro deshidratador. ¿Qué significa esto?", opciones:["Que el sistema tiene mucho gas", "Que el filtro está obstruido y actuando como un dispositivo de expansión", "Que el evaporador está sucio", "Es normal en R-410A"], respuesta_correcta:1, explicacion:"Cualquier restricción causa una caída de presión. Si la presión cae lo suficiente, el refrigerante empieza a hervir (evaporarse) dentro del filtro, enfriándolo." , question: "You find frost (ice) at the outlet of the filter drier. What does this mean?", options: ["The system is overcharged", "The filter drier is clogged and acting as an expansion device", "The evaporator is dirty", "It is normal with R-410A"], explanation: "Any restriction causes a pressure drop. If the pressure drops enough, the refrigerant begins to boil (evaporate) inside the filter drier, cooling it." },
  { id:"nate_314", categoria:"NATE_DIAGNOSTICO", pregunta:"Un compresor Scroll hace un ruido de 'sonajero' (canicas sueltas) al apagarse. ¿Qué indica?", opciones:["Que está roto", "Que la válvula check interna falló y permite que los scrolls giren en reversa por la presión diferencial", "Falta de aceite", "Capacitor dañado"], respuesta_correcta:1, explicacion:"Al apagarse, el gas de alta intenta regresar a la baja. La check debe evitarlo. Si no lo hace, el compresor gira al revés ruidosamente." , question: "A Scroll compressor makes a 'rattling' noise (like loose marbles) when it shuts off. What does this indicate?", options: ["It is broken", "The internal check valve has failed and is allowing the scrolls to spin in reverse due to pressure differential", "Low oil charge", "Damaged capacitor"], explanation: "When the compressor shuts off, high-side gas tries to flow back to the low side. The check valve should prevent this. If it fails, the compressor spins backward noisily." },
  { id:"nate_315", categoria:"NATE_DIAGNOSTICO", pregunta:"Ves agua saliendo por la tina de emergencia (emergency pan) debajo de una manejadora de aire en un ático. ¿Qué es lo primero que haces?", opciones:["Cambiar la manejadora", "Destapar el drenaje principal y revisar la trampa (P-trap)", "Agregar refrigerante", "Apagar el ventilador"], respuesta_correcta:1, explicacion:"Si el agua llega a la tina de emergencia, es porque el drenaje primario falló totalmente." , question: "You see water coming from the emergency drain pan beneath an air handler in an attic. What is the first thing you do?", options: ["Replace the air handler", "Clear the primary drain and inspect the P-trap", "Add refrigerant", "Turn off the blower"], explanation: "If water has reached the emergency pan, the primary drain has completely failed." },
  { id:"nate_316", categoria:"NATE_DIAGNOSTICO", pregunta:"En una calefacción de gas, el inductor enciende, el ignitor brilla, la válvula de gas hace 'clic', pero no hay llama y se bloquea. ¿Qué revisarías?", opciones:["El sensor de llama", "Que la llave manual de gas esté abierta y que haya presión de entrada a la válvula", "El motor del soplador", "El termostato"], respuesta_correcta:1, explicacion:"Si todo el ciclo eléctrico ocurre pero no hay fuego, simplemente no está llegando combustible." , question: "In a gas furnace, the inducer starts, the ignitor glows, the gas valve clicks, but there is no flame and the unit locks out. What would you check?", options: ["The flame sensor", "That the manual gas shutoff is open and that there is inlet gas pressure at the valve", "The blower motor", "The thermostat"], explanation: "If the entire electrical sequence occurs but there is no fire, fuel is simply not reaching the burner." },
  { id:"nate_317", categoria:"NATE_DIAGNOSTICO", pregunta:"Un compresor tiene 240V en sus terminales, el capacitor está bien, pero el motor no arranca y el amperaje es 0. ¿Qué sucede?", opciones:["Está amarrado (Locked Rotor)", "El protector térmico interno está abierto por sobrecalentamiento", "El breaker está botado", "Falta gas"], respuesta_correcta:1, explicacion:"Si hay voltaje pero no hay flujo de corriente (0 Amps), el circuito está abierto internamente. Si estuviera amarrado, el amperaje sería altísimo (LRA)." , question: "A compressor has 240V at its terminals, the capacitor is good, but the motor does not start and the amperage is 0. What is happening?", options: ["Locked Rotor condition", "The internal thermal overload protector is open due to overheating", "The breaker has tripped", "Low refrigerant charge"], explanation: "If there is voltage but no current flow (0 Amps), the circuit is open internally. If the rotor were locked, the amperage would be extremely high (LRA)." },
  { id:"nate_318", categoria:"NATE_DIAGNOSTICO", pregunta:"Mides un Subcooling de 30°F en un sistema que pide 10°F. Las presiones de alta son extremadamente elevadas. ¿Causa probable?", opciones:["Falta de gas", "No-condensables (aire) en el sistema o sobrecarga masiva", "Evaporador sucio", "TXV muy abierta"], respuesta_correcta:1, explicacion:"El aire no se condensa y ocupa espacio en el condensador, subiendo la presión y el subenfriamiento de forma anormal." , question: "You measure a subcooling of 30°F on a system that calls for 10°F. The high-side pressures are extremely elevated. What is the probable cause?", options: ["Low refrigerant charge", "Non-condensables (air) in the system or a massive refrigerant overcharge", "Dirty evaporator", "TXV wide open"], explanation: "Air does not condense and occupies space in the condenser, raising the pressure and subcooling abnormally." },
  { id:"nate_319", categoria:"NATE_DIAGNOSTICO", pregunta:"Un sistema enfría pero no deshumidifica. El Delta T es de solo 12°F y el soplador está en la velocidad más alta. ¿Qué ajustarías?", opciones:["Bajar la velocidad del soplador para aumentar el tiempo de contacto con el serpentín", "Subir la velocidad del soplador", "Agregar más gas", "Cambiar el condensador"], respuesta_correcta:0, explicacion:"Aire más lento = serpentín más frío = más condensación de agua." , question: "A system cools but does not dehumidify. The Delta T is only 12°F and the blower is on the highest speed. What would you adjust?", options: ["Lower the blower speed to increase the air's contact time with the coil", "Increase the blower speed", "Add more refrigerant", "Replace the condenser"], explanation: "Slower air = colder coil = more moisture condensation." },
  { id:"nate_320", categoria:"NATE_DIAGNOSTICO", pregunta:"Ves burbujas constantes en la mirilla, pero el Subcooling es de 12°F (normal). ¿Qué está pasando?", opciones:["Falta refrigerante", "El refrigerante está sufriendo una caída de presión (flash gas) debido a una restricción o línea de líquido muy larga/vertical", "El compresor está fallando", "Es normal en sistemas nuevos"], respuesta_correcta:1, explicacion:"Si el SC es bueno, hay líquido, pero algo después del condensador está haciendo que el líquido vuelva a convertirse en gas antes de la TXV." , question: "You see constant bubbles in the sight glass, but the subcooling is 12°F (normal). What is happening?", options: ["Low refrigerant charge", "The refrigerant is experiencing a pressure drop (flash gas) due to a restriction or a very long/vertical liquid line", "Compressor failure", "It is normal in new systems"], explanation: "If subcooling is good, there is liquid present, but something after the condenser is causing the liquid to flash back into gas before reaching the TXV." },
  { id:"nate_321", categoria:"NATE_DIAGNOSTICO", pregunta:"Un Mini-Split marca error de 'DC Bus Overvoltage' durante una tormenta eléctrica. ¿Qué componente protegió a la tarjeta pero probablemente se dañó?", opciones:["El fusible de vidrio", "El Varistor (MOV)", "El puente rectificador", "El compresor"], respuesta_correcta:1, explicacion:"El varistor absorbe los picos de voltaje sacrificándose (entrando en corto) para que el resto de la tarjeta no se queme." , question: "A Mini-Split displays a 'DC Bus Overvoltage' error during a lightning storm. What component protected the board but was likely damaged?", options: ["The glass fuse", "The Varistor (MOV)", "The bridge rectifier", "The compressor"], explanation: "The varistor absorbs voltage spikes by sacrificing itself (going into short circuit) so the rest of the board does not burn." },
  { id:"nate_322", categoria:"NATE_DIAGNOSTICO", pregunta:"Un enfriador de botellas no baja de 45°F. La succión es normal pero el Superheat es de 25°F (muy alto). El serpentín está limpio. ¿Qué ajustas?", opciones:["Abrir la TXV (girar vástago en sentido antihorario)", "Cerrar la TXV", "Agregar aceite", "Limpiar el condensador"], respuesta_correcta:0, explicacion:"Un SH alto en un sistema comercial indica que el evaporador no está recibiendo suficiente líquido para su carga actual." , question: "A bottle cooler will not drop below 45°F. The suction is normal but the superheat is 25°F (very high). The coil is clean. What do you adjust?", options: ["Open the TXV (turn the stem counterclockwise)", "Close the TXV", "Add oil", "Clean the condenser"], explanation: "A high superheat in a commercial system indicates the evaporator is not receiving enough liquid for its current load." },
  { id:"nate_323", categoria:"NATE_DIAGNOSTICO", pregunta:"Encuentras un contactor con las puntas de los contactos 'negras' y soldadas entre sí. ¿Qué causó esto?", opciones:["Bajo voltaje o un compresor consumiendo amperaje cercano al LRA por mucho tiempo", "Exceso de gas", "Humedad en el aire", "Hormigas"], respuesta_correcta:0, explicacion:"El arco eléctrico generado por un mal contacto o exceso de carga funde la plata de los contactos, pegándolos." , question: "You find a contactor with 'blackened' contact tips that are welded together. What caused this?", options: ["Low voltage or a compressor drawing near-LRA amperage for an extended period", "Refrigerant overcharge", "Moisture in the air", "Ants"], explanation: "The electrical arcing generated by poor contact or excess load melts the silver on the contacts, fusing them together." },
  { id:"nate_324", categoria:"NATE_DIAGNOSTICO", pregunta:"El cliente dice que la unidad exterior hace un ruido de 'zumbido' muy fuerte pero el ventilador no gira. Al empujar el aspa con un desarmador, el ventilador arranca. ¿Diagnóstico?", opciones:["Motor quemado", "Capacitor de ventilador defectuoso", "Falta de una fase", "Rodamientos amarrados"], respuesta_correcta:1, explicacion:"El motor tiene energía pero no tiene el 'empuje' (desfase) inicial que proporciona el capacitor." , question: "The customer says the outdoor unit makes a loud 'humming' noise but the fan does not spin. When you push the blade with a screwdriver, the fan starts. What is the diagnosis?", options: ["Burned motor", "Defective condenser fan capacitor", "Single-phase loss", "Seized bearings"], explanation: "The motor has power but lacks the initial 'push' (phase shift) that the capacitor provides." },
  { id:"nate_325", categoria:"NATE_DIAGNOSTICO", pregunta:"Mides la temperatura de los 3 tubos inferiores de una válvula inversora. El de succión (centro) está a 50°F, pero uno de los laterales está a 85°F. ¿Qué indica?", opciones:["Funcionamiento normal", "Fuga interna en la válvula inversora (no sella bien)", "Falta de gas", "Compresor ineficiente"], respuesta_correcta:1, explicacion:"Los tubos laterales no deberían transferir calor a la succión. Si uno está caliente, el gas de descarga se está filtrando." , question: "You measure the temperature of the 3 lower tubes on a reversing valve. The suction (center) tube reads 50°F, but one of the side tubes reads 85°F. What does this indicate?", options: ["Normal operation", "Internal leak in the reversing valve (not sealing properly)", "Low refrigerant charge", "Inefficient compressor"], explanation: "The side tubes should not transfer heat to the suction port. If one is hot, discharge gas is leaking through internally." },
  { id:"nate_326", categoria:"NATE_DIAGNOSTICO", pregunta:"Un motor de soplador gira muy lento y zumba. Mides el capacitor y marca 5 µF (su placa dice 10 µF). ¿Qué haces?", opciones:["Cambiar el motor", "Cambiar el capacitor por uno de 10 µF", "Poner dos capacitores de 5 µF en serie", "Aceitar el eje"], respuesta_correcta:1, explicacion:"La pérdida de capacitancia reduce el torque del motor, haciéndolo girar lento y sobrecalentarse." , question: "A blower motor runs very slowly and hums. You measure the capacitor and it reads 5 uF (the nameplate says 10 uF). What do you do?", options: ["Replace the motor", "Replace the capacitor with a 10 uF unit", "Install two 5 uF capacitors in series", "Oil the shaft"], explanation: "Loss of capacitance reduces motor torque, causing it to run slowly and overheat." },
  { id:"nate_327", categoria:"NATE_DIAGNOSTICO", pregunta:"La unidad exterior arranca y se apaga cada 30 segundos. Notas que el ventilador del condensador no enciende. ¿Qué switch está actuando?", opciones:["Presostato de baja", "Presostato de alta (High Pressure Switch)", "Termostato de ambiente", "Sensor de congelamiento"], respuesta_correcta:1, explicacion:"Sin ventilador, la presión de descarga sube al límite en segundos, abriendo el switch de seguridad." , question: "The outdoor unit starts and shuts off every 30 seconds. You notice the condenser fan is not running. Which safety switch is tripping?", options: ["Low Pressure Switch", "High Pressure Switch", "Room thermostat", "Freeze sensor"], explanation: "Without the fan, the discharge pressure rises to the limit within seconds, tripping the safety switch." },
  { id:"nate_328", categoria:"NATE_DIAGNOSTICO", pregunta:"Encuentras una sustancia viscosa blanca (como cera) obstruyendo la TXV de un sistema nuevo. ¿Qué causó esto?", opciones:["Mala soldadura", "Humedad que reaccionó con el aceite POE creando un lodo ácido/ceroso", "Exceso de refrigerante", "Aceite mineral mezclado"], respuesta_correcta:1, explicacion:"Es el resultado de la hidrólisis del aceite POE. Indica que no se hizo un buen vacío o el sistema estuvo abierto mucho tiempo." , question: "You find a white waxy substance blocking the TXV in a new system. What caused this?", options: ["Bad soldering", "Moisture that reacted with the POE oil creating an acidic/waxy sludge", "Refrigerant overcharge", "Mineral oil mixed in"], explanation: "This is the result of POE oil hydrolysis. It indicates a poor vacuum was pulled or the system was left open too long." },
  { id:"nate_329", categoria:"NATE_DIAGNOSTICO", pregunta:"El Delta T en el evaporador es de 30°F (muy alto). ¿Cuál es la causa más probable?", opciones:["Exceso de gas", "Falta de flujo de aire (filtro tapado o motor lento)", "Falta de gas", "Día muy caluroso"], respuesta_correcta:1, explicacion:"Si el aire pasa muy poco o muy lento, se enfría demasiado porque pasa más tiempo en contacto con el serpentín frío." , question: "The evaporator Delta T is 30°F (very high). What is the most probable cause?", options: ["Refrigerant overcharge", "Lack of airflow (clogged filter or slow motor)", "Low refrigerant charge", "Very hot day"], explanation: "If air passes too little or too slowly, it cools excessively because it spends more time in contact with the cold coil." },
  { id:"nate_330", categoria:"NATE_DIAGNOSTICO", pregunta:"Un compresor arranca pero el capacitor de arranque explota después de 10 segundos. ¿Qué falló?", opciones:["El capacitor era de mala calidad", "El Relay de Potencial no abrió sus contactos (quedó pegado)", "El compresor está en corto", "Mucho voltaje en la línea"], respuesta_correcta:1, explicacion:"El capacitor de arranque no está diseñado para estar en el circuito más de 1-3 segundos. Si el relay no lo saca, el calor interno lo hace explotar." , question: "A compressor starts but the start capacitor explodes after 10 seconds. What failed?", options: ["The capacitor was poor quality", "The Potential Relay did not open its contacts (stayed stuck closed)", "The compressor is shorted", "Excessive line voltage"], explanation: "The start capacitor is not designed to stay in the circuit for more than 1-3 seconds. If the relay does not remove it, internal heat causes it to explode." },
  { id:"nate_331", categoria:"NATE_DIAGNOSTICO", pregunta:"Presurizas con nitrógeno a 300 psig. Después de una hora, la presión bajó a 295 psig, pero la temperatura ambiente bajó de 90°F a 75°F. ¿Hay una fuga?", opciones:["Sí, bajó 5 psi", "No, es el efecto de la caída de temperatura en la presión del gas (Ley de Charles)", "Tal vez, hay que esperar un día", "El nitrógeno se absorbió en el aceite"], respuesta_correcta:1, explicacion:"Si la temperatura baja, la presión de un gas en un volumen fijo baja proporcionalmente. Una caída de 15°F justifica esos 5 psi." , question: "You pressurize with nitrogen to 300 psig. After one hour, the pressure drops to 295 psig, but the ambient temperature dropped from 90°F to 75°F. Is there a leak?", options: ["Yes, it dropped 5 psi", "No, it is the effect of temperature drop on gas pressure (Charles's Law)", "Maybe, you need to wait a day", "The nitrogen was absorbed into the oil"], explanation: "If the temperature drops, the pressure of a gas in a fixed volume drops proportionally. A 15°F temperature drop accounts for that 5 psi." },
  { id:"nate_332", categoria:"NATE_DIAGNOSTICO", pregunta:"Un cliente se queja de un ruido de 'sonajero' en la unidad exterior. Encuentras que el ruido desaparece si pones la mano sobre el gabinete. ¿Solución?", opciones:["Cambiar el compresor", "Apretar los tornillos del gabinete y revisar que las tuberías no se toquen entre sí", "Aceitar el ventilador", "Cambiar el termostato"], respuesta_correcta:1, explicacion:"La mayoría de los ruidos molestos son vibraciones mecánicas de paneles sueltos o tubos rozando." , question: "A customer complains of a 'rattling' noise from the outdoor unit. You find that the noise disappears when you place your hand on the cabinet. What is the solution?", options: ["Replace the compressor", "Tighten the cabinet screws and check that pipes are not touching each other", "Oil the fan", "Replace the thermostat"], explanation: "Most annoying noises are mechanical vibrations from loose panels or rubbing tubing." },
  { id:"nate_333", categoria:"NATE_DIAGNOSTICO", pregunta:"Una Heat Pump se llena de hielo sólido en invierno y nunca entra en defrost. El sensor de temperatura exterior marca 100k Ohms a 30°F (Normal). ¿Qué más revisas?", opciones:["Si el ventilador exterior gira", "Que el sensor esté bien pegado físicamente al tubo de cobre (falta de contacto térmico)", "Si el termostato está en modo calor", "La presión de alta"], respuesta_correcta:1, explicacion:"Si el sensor está colgando, mide el aire y no la temperatura real del tubo que tiene el hielo; la tarjeta nunca recibe la señal de inicio." , question: "A Heat Pump is covered in solid ice in winter and never enters defrost. The outdoor temperature sensor reads 100k Ohms at 30°F (normal). What else do you check?", options: ["If the outdoor fan is spinning", "That the sensor is physically secured to the copper tube (lack of thermal contact)", "If the thermostat is in heating mode", "The high-side pressure"], explanation: "If the sensor is hanging loose, it reads the air temperature instead of the actual tube temperature where ice is forming; the board never receives the defrost initiation signal." },
  { id:"nate_334", categoria:"NATE_DIAGNOSTICO", pregunta:"El RLA de un compresor es de 15A. Mides y el compresor está consumiendo 18A constantes. El condensador está limpio y el voltaje es correcto. ¿Diagnóstico?", opciones:["Está bien, tiene margen", "Sobrecarga de refrigerante o fricción mecánica interna", "Falta de gas", "Capacitor muy grande"], respuesta_correcta:1, explicacion:"Operar por encima del RLA (Rated Load Amps) indica que el motor está haciendo más esfuerzo del diseñado." , question: "A compressor's RLA is 15A. You measure the compressor drawing a steady 18A. The condenser is clean and the voltage is correct. What is the diagnosis?", options: ["It is fine, there is margin", "Refrigerant overcharge or internal mechanical friction", "Low refrigerant charge", "Oversized capacitor"], explanation: "Operating above the RLA (Rated Load Amps) indicates the motor is working harder than it was designed for." },
  { id:"nate_335", categoria:"NATE_DIAGNOSTICO", pregunta:"Un Mini-Split gotea agua por la parte delantera de la unidad interior solo cuando el ventilador está en velocidad ALTA. ¿Causa?", opciones:["Drenaje tapado", "El agua es 'succionada' de la tina de drenaje por la alta velocidad del aire (Blow-off)", "El equipo está chueco", "Falta gas"], respuesta_correcta:1, explicacion:"Si la tina está sucia o mal diseñada, la fuerza del aire arrastra las gotas antes de que caigan al drenaje." , question: "A Mini-Split leaks water from the front of the indoor unit only when the fan is on HIGH speed. What is the cause?", options: ["Clogged drain", "Water is being 'blown off' the drain pan by the high air velocity (blow-off)", "The unit is tilted", "Low refrigerant charge"], explanation: "If the drain pan is dirty or poorly designed, the force of the air carries droplets away before they can reach the drain." },
  { id:"nate_336", categoria:"NATE_DIAGNOSTICO", pregunta:"Mides un Superheat de 60°F en la succión del compresor. El refrigerante es R-410A. ¿Qué riesgo corres?", opciones:["Que el evaporador se congele", "Que el bobinado del compresor se queme por falta de enfriamiento (el gas regresa muy caliente)", "Que la presión de alta suba", "Ninguno, es mejor que esté caliente"], respuesta_correcta:1, explicacion:"Los compresores herméticos dependen del gas frío de succión para enfriar sus bobinados internos." , question: "You measure a superheat of 60°F at the compressor suction. The refrigerant is R-410A. What risk do you face?", options: ["The evaporator will freeze", "The compressor windings will burn due to insufficient cooling (the returning gas is too hot)", "High-side pressure will increase", "None, it is better for it to be warm"], explanation: "Hermetic compressors depend on the cool suction gas to cool their internal windings." },
  { id:"nate_337", categoria:"NATE_DIAGNOSTICO", pregunta:"En un sistema Split, el técnico apaga el equipo y escucha un 'borboteo' fuerte en el evaporador. ¿Qué sucede?", opciones:["Humedad en el sistema", "El refrigerante líquido está regresando al evaporador desde la línea de líquido (flash back)", "El compresor está hirviendo", "Es normal"], respuesta_correcta:1, explicacion:"Indica que las presiones están intentando igualarse rápidamente a través del dispositivo de expansión sin control." , question: "In a split system, the technician shuts off the unit and hears a loud 'gurgling' in the evaporator. What is happening?", options: ["Moisture in the system", "Liquid refrigerant is rushing back into the evaporator from the liquid line (flash back)", "The compressor is boiling", "It is normal"], explanation: "It indicates the pressures are attempting to equalize rapidly through the expansion device without control." },
  { id:"nate_338", categoria:"NATE_DIAGNOSTICO", pregunta:"Ves que la llama de la calefacción de gas se 'mueve' o se distorsiona cuando el motor del soplador enciende. ¿Qué indica?", opciones:["Que el soplador es muy fuerte", "Grieta en el intercambiador de calor (el aire del soplador entra a la cámara de combustión)", "Falta de oxígeno", "Presión de gas alta"], respuesta_correcta:1, explicacion:"Es una prueba visual crítica. El aire del soplador no debería tener contacto con las llamas." , question: "You see the gas furnace flame 'wavering' or distorting when the blower motor turns on. What does this indicate?", options: ["The blower is too powerful", "A crack in the heat exchanger (blower air is entering the combustion chamber)", "Lack of oxygen", "High gas pressure"], explanation: "This is a critical visual test. Blower air should not have any contact with the flames." },
  { id:"nate_339", categoria:"NATE_DIAGNOSTICO", pregunta:"Cada vez que conectas el cable 'Y' al termostato, el transformador de 24V se quema. ¿Dónde buscas el problema?", opciones:["En el compresor", "En el cableado que va hacia la unidad exterior (posible cable pelado tocando el cobre)", "En el motor del soplador", "En el capacitor"], respuesta_correcta:1, explicacion:"Al pedir enfriamiento, energizas un cable que está aterrizado, causando un corto directo." , question: "Every time you connect the 'Y' wire at the thermostat, the 24V transformer burns out. Where do you look for the problem?", options: ["At the compressor", "In the wiring running to the outdoor unit (possible bare wire touching copper tubing)", "At the blower motor", "At the capacitor"], explanation: "When calling for cooling, you energize a wire that is grounded, causing a direct short circuit." },
  { id:"nate_340", categoria:"NATE_DIAGNOSTICO", pregunta:"Un sistema tiene 0°F de Subcooling pero la presión de alta es normal. ¿Qué falta?", opciones:["Aceite", "Refrigerante (el condensador no tiene líquido acumulado)", "Limpiar el filtro", "Voltaje"], respuesta_correcta:1, explicacion:"0 SC significa que el refrigerante sale del condensador apenas como vapor saturado o mezcla, no como líquido puro." , question: "A system has 0°F subcooling but the high-side pressure is normal. What is missing?", options: ["Oil", "Refrigerant (the condenser has no accumulated liquid)", "A clean filter", "Voltage"], explanation: "Zero subcooling means the refrigerant is leaving the condenser as barely saturated vapor or a mixture, not as pure liquid." },
  { id:"nate_341", categoria:"NATE_DIAGNOSTICO", pregunta:"Después de un retro-fit de R-22 a R-407C, el sistema enfría bien pero el visor de aceite se ve 'lechoso'. ¿Qué pasó?", opciones:["El gas es de mala calidad", "No se cambió el aceite mineral por POE (son incompatibles y se separan)", "Entró mucha agua", "Es normal los primeros días"], respuesta_correcta:1, explicacion:"El aceite mineral no se disuelve en el R-407C y crea una emulsión que no lubrica." , question: "After a retrofit from R-22 to R-407C, the system cools well but the oil sight glass looks 'milky.' What happened?", options: ["Bad quality refrigerant", "The mineral oil was not replaced with POE (they are incompatible and separate)", "Too much moisture entered", "It is normal for the first few days"], explanation: "Mineral oil does not dissolve in R-407C and creates an emulsion that does not lubricate." },
  { id:"nate_342", categoria:"NATE_DIAGNOSTICO", pregunta:"La unidad exterior no enciende. Mides continuidad en el presostato de alta y marca 'O.L'. Al presionar el botón rojo del switch, marca 0 Ohms. ¿Qué falló?", opciones:["El switch está roto", "Hubo un evento de alta presión y el switch es de reinicio manual", "Falta gas", "El contactor está pegado"], respuesta_correcta:1, explicacion:"Los switches con botón rojo obligan al técnico a revisar por qué subió la presión antes de volver a arrancar." , question: "The outdoor unit will not turn on. You measure continuity on the high-pressure switch and it reads 'O.L.' When you press the red reset button on the switch, it reads 0 Ohms. What happened?", options: ["The switch is broken", "A high-pressure event occurred and the switch is manual-reset type", "Low refrigerant charge", "The contactor is welded shut"], explanation: "Manual-reset switches with a red button force the technician to investigate why the pressure rose before restarting." },
  { id:"nate_343", categoria:"NATE_DIAGNOSTICO", pregunta:"La línea de succión está caliente al tacto (80°F) y la presión es muy baja. ¿Diagnóstico?", opciones:["Falta de refrigerante", "Compresor quemado", "Filtro de aire sucio", "Voltaje bajo"], respuesta_correcta:0, explicacion:"Poco gas se evapora muy rápido al inicio del evaporador y se calienta mucho antes de salir del equipo." , question: "The suction line is hot to the touch (80°F) and the pressure is very low. What is the diagnosis?", options: ["Low refrigerant charge", "Burned compressor", "Dirty air filter", "Low voltage"], explanation: "A small amount of refrigerant evaporates very quickly at the beginning of the evaporator and becomes highly superheated before leaving the unit." },
  { id:"nate_344", categoria:"NATE_DIAGNOSTICO", pregunta:"Un Mini-Split tiene el evaporador congelado. El ventilador gira pero muy débilmente. Limpias el aspa y sigue igual. ¿Qué componente electrónico falló?", opciones:["El sensor de ambiente", "El capacitor del motor del ventilador (si es AC) o el driver de la tarjeta (si es DC)", "El relé de potencia", "El transformador"], respuesta_correcta:1, explicacion:"Si el motor no tiene fuerza para vencer la resistencia del aire, no habrá transferencia de calor." , question: "A Mini-Split has a frozen evaporator. The fan spins but very weakly. Cleaning the blade does not help. What electronic component has failed?", options: ["The room temperature sensor", "The fan motor capacitor (if AC) or the board driver (if DC)", "The power relay", "The transformer"], explanation: "If the motor lacks the force to overcome air resistance, there will be no heat transfer." },
  { id:"nate_345", categoria:"NATE_DIAGNOSTICO", pregunta:"Ves burbujas subiendo por el tubo de drenaje hacia la tina mientras el equipo funciona. ¿Qué le falta al drenaje?", opciones:["Limpieza", "Una trampa de aire (P-trap) correctamente instalada", "Más inclinación", "Un respiradero"], respuesta_correcta:1, explicacion:"La presión negativa del soplador succiona aire por el drenaje. La trampa de agua bloquea ese aire." , question: "You see bubbles rising through the drain tube into the pan while the unit is running. What does the drain need?", options: ["Cleaning", "A properly installed P-trap", "More slope", "A vent"], explanation: "The negative pressure from the blower pulls air through the drain. A water trap blocks that air." },
  { id:"nate_346", categoria:"NATE_DIAGNOSTICO", pregunta:"En un compresor trifásico, mides: L1=20A, L2=21A, L3=35A. ¿Qué haces?", opciones:["Apagar inmediatamente; hay un desbalance de corriente severo que quemará el motor", "Dejarlo funcionar", "Cambiar el gas", "Limpiar el condensador"], respuesta_correcta:0, explicacion:"Un desbalance mayor al 10% indica problemas de voltaje de entrada o daño en los bobinados." , question: "On a three-phase compressor, you measure: L1=20A, L2=21A, L3=35A. What do you do?", options: ["Shut it down immediately; there is a severe current imbalance that will burn the motor", "Let it keep running", "Change the refrigerant", "Clean the condenser"], explanation: "An imbalance greater than 10% indicates incoming voltage problems or winding damage." },
  { id:"nate_347", categoria:"NATE_DIAGNOSTICO", pregunta:"La presión de succión oscila (sube y baja) rítmicamente. El Superheat también varía de 5°F a 20°F constantemente. ¿Cómo se llama este fenómeno?", opciones:["Superheat normal", "TXV Hunting (Válvula 'cazando')", "Compresión variable", "Efecto de aceite"], respuesta_correcta:1, explicacion:"Ocurre cuando la TXV está mal dimensionada o el bulbo está en una mala posición, causando que la válvula abra y cierre de más." , question: "The suction pressure oscillates (rises and falls) rhythmically. The superheat also varies from 5°F to 20°F constantly. What is this phenomenon called?", options: ["Normal superheat variation", "TXV Hunting", "Variable compression", "Oil effect"], explanation: "It occurs when the TXV is improperly sized or the sensing bulb is poorly positioned, causing the valve to over-open and over-close." },
  { id:"nate_348", categoria:"NATE_DIAGNOSTICO", pregunta:"Mides 0 microamperios en el sensor de llama, pero la llama está presente. El cable está bien. ¿Qué haces?", opciones:["Cambiar la tarjeta", "Limpiar el sensor de llama con lana de acero fina", "Subir la presión de gas", "Cambiar el ignitor"], respuesta_correcta:1, explicacion:"La acumulación de sílice (polvo quemado) aisla el sensor e impide que la corriente fluya." , question: "You measure 0 microamps at the flame sensor, but the flame is present. The wire is intact. What do you do?", options: ["Replace the control board", "Clean the flame sensor with fine steel wool", "Increase the gas pressure", "Replace the ignitor"], explanation: "The buildup of silica (burned dust) insulates the sensor and prevents current from flowing." },
  { id:"nate_349", categoria:"NATE_DIAGNOSTICO", pregunta:"Un sistema tiene: Succión Baja, Descarga Alta, Superheat Alto, Subcooling Alto. ¿Cuál es el diagnóstico único que explica todo?", opciones:["Falta de refrigerante", "Restricción en el lado de alta (ej. filtro tapado o TXV cerrada) con carga completa", "Sobrecarga de refrigerante", "Compresor ineficiente"], respuesta_correcta:1, explicacion:"La restricción baja la succión (SH alto). Como el gas no pasa, se amontona en el condensador, subiendo la presión de alta y el subenfriamiento." , question: "A system shows: low suction, high discharge, high superheat, high subcooling. What is the single diagnosis that explains everything?", options: ["Low refrigerant charge", "Restriction on the high side (e.g., clogged filter drier or closed TXV) with a full charge", "Refrigerant overcharge", "Inefficient compressor"], explanation: "The restriction starves the low side (high superheat). Since the refrigerant cannot pass through, it stacks up in the condenser, raising both the high-side pressure and subcooling." },
  { id:"nate_350", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué factor del Manual J tiene el mayor impacto en la carga de enfriamiento de una casa con muchas ventanas orientadas al oeste?", opciones:["Infiltración de aire", "Ganancia de calor solar (SHGC)", "Calor latente de las personas", "Conducción a través de las paredes"], respuesta_correcta:1, explicacion:"La radiación solar directa a través del vidrio (especialmente por la tarde en el oeste) es la fuente de calor más intensa en el diseño residencial." , question: "What Manual J factor has the greatest impact on the cooling load of a house with many west-facing windows?", options: ["Air infiltration", "Solar Heat Gain Coefficient (SHGC)", "Latent heat from occupants", "Conduction through the walls"], explanation: "Direct solar radiation through glass (especially in the afternoon on the west side) is the most intense heat source in residential design." },
  { id:"nate_351", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué sucede con el flujo de aire (CFM) si la longitud equivalente de los ductos aumenta debido al uso excesivo de codos y vueltas?", opciones:["El flujo de aire aumenta", "La presión estática aumenta y los CFM disminuyen", "El motor gira más rápido para compensar", "No afecta a los motores ECM"], respuesta_correcta:1, explicacion:"Cada codo añade 'fricción'. A mayor fricción, más presión estática tiene que vencer el ventilador, lo que reduce el volumen de aire entregado." , question: "What happens to airflow (CFM) if the equivalent length of the ductwork increases due to excessive use of elbows and turns?", options: ["Airflow increases", "Static pressure increases and CFM decreases", "The motor speeds up to compensate", "It does not affect ECM motors"], explanation: "Each elbow adds friction. The more friction, the more static pressure the blower must overcome, which reduces the delivered air volume." },
  { id:"nate_352", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la diferencia principal entre el rating SEER y el nuevo SEER2?", opciones:["SEER2 usa un refrigerante distinto", "SEER2 se calcula con una presión estática externa más alta (0.50 iwc) para reflejar instalaciones reales", "SEER2 solo aplica a unidades Inverter", "Es solo un cambio de nombre comercial"], respuesta_correcta:1, explicacion:"El SEER viejo se probaba a 0.1 iwc, lo cual era poco realista. SEER2 exige más esfuerzo del equipo para obtener la misma calificación." , question: "What is the main difference between the SEER and the new SEER2 rating?", options: ["SEER2 uses a different refrigerant", "SEER2 is calculated with a higher external static pressure (0.50 iwc) to reflect real-world installations", "SEER2 only applies to Inverter units", "It is just a commercial name change"], explanation: "The old SEER was tested at 0.1 iwc, which was unrealistic. SEER2 demands more effort from the equipment to achieve the same rating." },
  { id:"nate_353", categoria:"NATE_DIAGNOSTICO", pregunta:"En el diseño de ventilación, ¿qué es el 'Aire de Reemplazo' (Make-up Air)?", opciones:["Aire acondicionado de reserva", "Aire exterior introducido para reemplazar el aire que ha sido expulsado por campanas de cocina o extractores", "Aire que sale por las ventanas", "El aire del retorno"], respuesta_correcta:1, explicacion:"Evita que la casa entre en presión negativa, lo cual causaría infiltraciones no deseadas o problemas de tiro en calentadores de gas." , question: "In ventilation design, what is Make-up Air?", options: ["Backup air conditioning", "Outdoor air introduced to replace air that has been exhausted by kitchen hoods or exhaust fans", "Air that escapes through windows", "Return air"], explanation: "It prevents the building from going into negative pressure, which would cause unwanted infiltration or draft problems with gas-fired appliances." },
  { id:"nate_354", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es el componente de un sistema de ductos que tiene la mayor 'Longitud Equivalente' (resistencia al flujo)?", opciones:["10 pies de ducto recto", "Un codo de 90 grados de radio corto", "Una bota de registro", "El filtro de aire plisado de alta eficiencia"], respuesta_correcta:1, explicacion:"En términos de Manual D, un codo mal diseñado puede equivaler a 30 o 50 pies de ducto recto en términos de fricción." , question: "Which duct system component has the greatest Equivalent Length (resistance to flow)?", options: ["10 feet of straight duct", "A short-radius 90-degree elbow", "A register boot", "A high-efficiency pleated air filter"], explanation: "In Manual D terms, a poorly designed elbow can be equivalent to 30 or 50 feet of straight duct in terms of friction." },
  { id:"nate_355", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué sucede con el 'Sensible Heat Ratio' (SHR) de un equipo si el serpentín del evaporador opera muy frío?", opciones:["El SHR aumenta", "El SHR disminuye (el equipo remueve más calor latente/humedad)", "El SHR se mantiene en 1.0", "El equipo gasta menos luz"], respuesta_correcta:1, explicacion:"SHR es la relación de calor sensible sobre calor total. Si remueves más humedad (latente), el porcentaje de calor sensible en la mezcla baja." , question: "What happens to the Sensible Heat Ratio (SHR) of equipment when the evaporator coil operates very cold?", options: ["The SHR increases", "The SHR decreases (the equipment removes more latent heat/moisture)", "The SHR stays at 1.0", "The equipment uses less energy"], explanation: "SHR is the ratio of sensible heat to total heat. If you remove more moisture (latent heat), the sensible percentage of the total drops." },
  { id:"nate_356", categoria:"NATE_DIAGNOSTICO", pregunta:"Según las buenas prácticas, ¿cuál es la caída de presión máxima aceptable en una línea de succión de cobre?", opciones:["0 psi", "Equivalente a una caída de temperatura de saturación de 2°F", "10 psi", "50 psi"], respuesta_correcta:1, explicacion:"Si la tubería es muy delgada o larga, la presión cae tanto que la capacidad del compresor disminuye drásticamente." , question: "According to best practices, what is the maximum acceptable pressure drop in a copper suction line?", options: ["0 psi", "Equivalent to a 2°F drop in saturation temperature", "10 psi", "50 psi"], explanation: "If the tubing is too small or too long, the pressure drops so much that the compressor's capacity decreases drastically." },
  { id:"nate_357", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Por qué no se debe usar cinta 'Duct Tape' de tela tradicional para sellar las uniones de los ductos de metal?", opciones:["Porque es muy cara", "Porque el pegamento se seca y falla con el calor/frío; debe usarse cinta de aluminio (Mastic Tape) o sellador líquido", "Porque es conductora de electricidad", "Porque el color gris no combina"], respuesta_correcta:1, explicacion:"La cinta de tela se desprende en pocos años. El sellado hermético es clave para la eficiencia del sistema." , question: "Why should traditional cloth Duct Tape not be used to seal metal duct joints?", options: ["Because it is too expensive", "Because the adhesive dries out and fails with heat and cold; aluminum tape (mastic tape) or liquid sealant should be used instead", "Because it conducts electricity", "Because the gray color does not match"], explanation: "Cloth tape comes loose within a few years. Airtight sealing is key to system efficiency." },
  { id:"nate_358", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué es el 'Throw' (Alcance) de una rejilla de suministro?", opciones:["La fuerza con la que avientas la rejilla", "La distancia que recorre el aire desde la rejilla hasta que su velocidad baja a un nivel estándar (ej. 50 fpm)", "El ancho de la rejilla", "El ruido que hace el aire"], respuesta_correcta:1, explicacion:"Un buen diseño asegura que el aire llegue al centro del cuarto sin causar corrientes molestas (drafts) sobre las personas." , question: "What is the Throw of a supply register?", options: ["How hard you toss the register", "The distance the air travels from the register until its velocity drops to a standard level (e.g., 50 fpm)", "The width of the register", "The noise the air makes"], explanation: "Good design ensures that air reaches the center of the room without causing uncomfortable drafts over the occupants." },
  { id:"nate_359", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué herramienta se utiliza para medir la hermeticidad de una casa y encontrar fugas de aire en la envolvente?", opciones:["Anemómetro", "Blower Door Test", "Manómetro de gas", "Cámara termográfica solamente"], respuesta_correcta:1, explicacion:"Es un ventilador potente que se coloca en la puerta para presurizar/despresurizar la casa y medir cuántas veces cambia el aire por hora (ACH)." , question: "What tool is used to measure a home's airtightness and find air leaks in the building envelope?", options: ["Anemometer", "Blower Door Test", "Gas manometer", "Thermal imaging camera only"], explanation: "It is a powerful fan placed in the doorway to pressurize/depressurize the house and measure how many Air Changes per Hour (ACH) occur." },
  { id:"nate_360", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es el propósito del Manual S de ACCA?", opciones:["Diseñar ductos", "Seleccionar el equipo específico basándose en los datos del Manual J y las tablas de rendimiento expandido del fabricante", "Calcular el costo del trabajo", "Entrenar técnicos"], respuesta_correcta:1, explicacion:"Manual J dice cuántos BTU necesitas; Manual S asegura que el equipo que compres realmente entregue esos BTU a tus condiciones locales." , question: "What is the purpose of ACCA Manual S?", options: ["To design ductwork", "To select the specific equipment based on Manual J data and the manufacturer's expanded performance tables", "To calculate job cost", "To train technicians"], explanation: "Manual J tells you how many BTUs you need; Manual S ensures the equipment you purchase actually delivers those BTUs at your local conditions." },
  { id:"nate_361", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué es el 'Bypass Factor' de un serpentín evaporador?", opciones:["Una válvula de alivio", "El porcentaje de aire que pasa a través del serpentín sin tocar las aletas frías", "La velocidad del ventilador", "Un tipo de filtro"], respuesta_correcta:1, explicacion:"Ningún serpentín es 100% eficiente; siempre hay una parte del aire que no se enfría ni se deshumidifica." , question: "What is the Bypass Factor of an evaporator coil?", options: ["A relief valve", "The percentage of air that passes through the coil without contacting the cold fins", "The fan speed", "A type of filter"], explanation: "No coil is 100% efficient; there is always a portion of air that is neither cooled nor dehumidified." },
  { id:"nate_362", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Por qué es mala idea tener un solo retorno central en una casa grande con muchas habitaciones cerradas?", opciones:["Porque el filtro se ensucia más", "Porque crea desbalances de presión (las habitaciones se presurizan y el aire no circula bien hacia el retorno)", "Porque hace mucho ruido", "Porque gasta más gas"], respuesta_correcta:1, explicacion:"Si cierras la puerta de un cuarto con suministro pero sin retorno, el aire no puede entrar y el confort se pierde." , question: "Why is it a bad idea to have a single central return in a large house with many closed bedrooms?", options: ["Because the filter gets dirty faster", "Because it creates pressure imbalances (rooms pressurize and air cannot circulate back to the return properly)", "Because it is noisy", "Because it uses more refrigerant"], explanation: "If you close the door of a room with supply but no return, the air cannot circulate and comfort is lost." },
  { id:"nate_363", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué calibre de cable de cobre es el mínimo requerido para un circuito de 30 Amperios según el NEC?", opciones:["Calibre 14", "Calibre 12", "Calibre 10", "Calibre 8"], respuesta_correcta:2, explicacion:"Calibre 14 = 15A, Calibre 12 = 20A, Calibre 10 = 30A. Usar un cable más delgado causaría sobrecalentamiento e incendio." , question: "What is the minimum copper wire gauge required for a 30-Amp circuit per the NEC?", options: ["14 AWG", "12 AWG", "10 AWG", "8 AWG"], explanation: "14 AWG = 15A, 12 AWG = 20A, 10 AWG = 30A. Using a thinner wire would cause overheating and fire." },
  { id:"nate_364", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué mide el rating HSPF2?", opciones:["La eficiencia en modo enfriamiento", "La eficiencia estacional de calefacción en una bomba de calor (Heat Pump)", "La presión del gas", "La velocidad del aire"], respuesta_correcta:1, explicacion:"HSPF (Heating Seasonal Performance Factor) es para calor, SEER es para frío." , question: "What does the HSPF2 rating measure?", options: ["Cooling mode efficiency", "The seasonal heating efficiency of a Heat Pump", "Gas pressure", "Airflow velocity"], explanation: "HSPF (Heating Seasonal Performance Factor) is for heating; SEER is for cooling." },
  { id:"nate_365", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la profundidad mínima recomendada para una trampa de condensado (P-trap) en un sistema de presión negativa?", opciones:["1 pulgada", "2 pulgadas (o según la presión estática del equipo)", "12 pulgadas", "No necesita profundidad"], respuesta_correcta:1, explicacion:"Si la succión del ventilador es más fuerte que el peso del agua en la trampa, el agua no saldrá y se desbordará la tina." , question: "What is the minimum recommended depth for a condensate P-trap on a negative-pressure system?", options: ["1 inch", "2 inches (or as dictated by the unit's static pressure)", "12 inches", "No depth is needed"], explanation: "If the blower's suction is stronger than the weight of the water in the trap, the water will not drain and the pan will overflow." },
  { id:"nate_366", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cómo se mide la velocidad del aire dentro de un ducto de metal?", opciones:["Con un manómetro de agua", "Con un anemómetro de hilo caliente (Hot Wire Anemometer) o un tubo Pitot", "Viendo qué tan rápido se mueve el polvo", "Con un termómetro"], respuesta_correcta:1, explicacion:"Permiten medir los pies por minuto (FPM) en puntos específicos del flujo." , question: "How is air velocity measured inside a metal duct?", options: ["With a water manometer", "With a hot wire anemometer or a Pitot tube", "By watching how fast dust moves", "With a thermometer"], explanation: "These instruments allow measurement of feet per minute (FPM) at specific points within the airstream." },
  { id:"nate_367", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué es el método 'ACH' (Air Changes per Hour)?", opciones:["Cambiar el filtro cada hora", "El número de veces que el volumen total de aire de una casa se reemplaza por aire exterior en una hora", "La velocidad del motor", "Un tipo de refrigerante"], respuesta_correcta:1, explicacion:"Es vital para calcular cuánto calor 'nuevo' entra a la casa por grietas en ventanas y puertas." , question: "What is the ACH (Air Changes per Hour) method?", options: ["Changing the filter every hour", "The number of times the total air volume of a house is replaced by outdoor air in one hour", "The motor speed", "A type of refrigerant"], explanation: "It is vital for calculating how much 'new' heat enters the home through cracks around windows and doors." },
  { id:"nate_368", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es el componente más crítico en un sistema de zonas (Zoning) para evitar que la presión estática suba demasiado cuando solo una zona está abierta?", opciones:["Un termostato extra", "Un damper de bypass (Barometric Bypass Damper) o un motor de soplador variable", "Ductos más grandes", "Un compresor más fuerte"], respuesta_correcta:1, explicacion:"Alivian el exceso de presión enviando el aire sobrante al retorno o reduciendo la velocidad del motor." , question: "What is the most critical component in a zoning system to prevent static pressure from rising too high when only one zone is calling?", options: ["An extra thermostat", "A barometric bypass damper or a variable-speed blower motor", "Larger ductwork", "A more powerful compressor"], explanation: "They relieve excess pressure by sending surplus air back to the return or by reducing the motor speed." },
  { id:"nate_369", categoria:"NATE_DIAGNOSTICO", pregunta:"Si un cuarto tiene una carga sensible de 10,000 BTU/h y quieres mantener un Delta T de 20°F, ¿cuántos CFM necesitas?", opciones:["200 CFM", "463 CFM", "800 CFM", "1000 CFM"], respuesta_correcta:1, explicacion:"Fórmula: CFM = BTU / (1.08 * Delta T). 10,000 / (1.08 * 20) = 462.9 CFM." , question: "If a room has a sensible load of 10,000 BTU/h and you want to maintain a Delta T of 20°F, how many CFM do you need?", options: ["200 CFM", "463 CFM", "800 CFM", "1000 CFM"], explanation: "Formula: CFM = BTU / (1.08 x Delta T). 10,000 / (1.08 x 20) = 462.9 CFM." },
  { id:"nate_370", categoria:"NATE_DIAGNOSTICO", pregunta:"¿A qué temperatura exterior fija se calcula el EER2 (Energy Efficiency Ratio)?", opciones:["75°F", "82°F", "95°F", "115°F"], respuesta_correcta:2, explicacion:"A diferencia del SEER2 (que es un promedio estacional), el EER2 mide la eficiencia en el punto más caluroso del verano (95°F)." , question: "At what fixed outdoor temperature is EER2 (Energy Efficiency Ratio) calculated?", options: ["75°F", "82°F", "95°F", "115°F"], explanation: "Unlike SEER2 (which is a seasonal average), EER2 measures efficiency at the hottest point of summer (95°F)." },
  { id:"nate_371", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la función del 'Plenum' de suministro?", opciones:["Filtrar el aire", "Servir como cámara de distribución donde se conectan todos los ductos ramales", "Enfriar el refrigerante", "Soportar el peso del equipo"], respuesta_correcta:1, explicacion:"Es la caja metálica o de duct board inmediatamente después del evaporador." , question: "What is the function of the supply Plenum?", options: ["To filter the air", "To serve as a distribution chamber where all branch ducts connect", "To cool the refrigerant", "To support the weight of the equipment"], explanation: "It is the metal or duct board box located immediately after the evaporator." },
  { id:"nate_372", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué significa el R-Value en el aislamiento de ductos?", opciones:["Resistencia al flujo de aire", "Resistencia térmica (capacidad de impedir el paso del calor)", "Radio del ducto", "Rigidez del material"], respuesta_correcta:1, explicacion:"A mayor número R (ej. R-8 es mejor que R-4.2), menos calor pierde o gana el aire dentro del ducto." , question: "What does the R-Value mean in duct insulation?", options: ["Resistance to airflow", "Thermal resistance (the ability to impede heat transfer)", "Duct radius", "Material rigidity"], explanation: "The higher the R number (e.g., R-8 is better than R-4.2), the less heat the air inside the duct loses or gains." },
  { id:"nate_373", categoria:"NATE_DIAGNOSTICO", pregunta:"Si rotas una casa 90 grados en el software de carga térmica, ¿cambia la carga de enfriamiento?", opciones:["No, el área de las paredes es la misma", "Sí, porque la ubicación de las ventanas respecto al sol cambia drásticamente la ganancia solar", "Solo si la casa es de dos pisos", "No, el sol sale igual para todos"], respuesta_correcta:1, explicacion:"La orientación es un dato crítico en Manual J; ventanas al oeste son mucho más 'calientes' que al norte." , question: "If you rotate a house 90 degrees in the load calculation software, does the cooling load change?", options: ["No, the wall area is the same", "Yes, because the window orientation relative to the sun drastically changes the solar heat gain", "Only if the house is two stories", "No, the sun is the same for everyone"], explanation: "Orientation is a critical input in Manual J; west-facing windows are much 'hotter' than north-facing ones." },
  { id:"nate_374", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es el error más común al instalar ducto flexible?", opciones:["Usar mucho pegamento", "No estirarlo completamente (dejarlo arrugado aumenta la fricción hasta un 400%)", "Usarlo en el ático", "Ponerle aislamiento"], respuesta_correcta:1, explicacion:"El ducto flexible debe estar 'tight' (tenso). Las arrugas internas matan el flujo de aire." , question: "What is the most common mistake when installing flex duct?", options: ["Using too much adhesive", "Not stretching it fully (leaving it bunched up increases friction by up to 400%)", "Using it in the attic", "Adding insulation"], explanation: "Flex duct must be pulled tight. Internal wrinkles kill airflow." },
  { id:"nate_375", categoria:"NATE_DIAGNOSTICO", pregunta:"Si el aire de retorno tiene una entalpía de 30 BTU/lb y el de suministro de 20 BTU/lb, ¿cuánto calor total se está removiendo por cada libra de aire?", opciones:["10 BTU/lb", "50 BTU/lb", "2 BTU/lb", "0 BTU/lb"], respuesta_correcta:0, explicacion:"La diferencia de entalpía (ΔH) indica el cambio en el contenido total de calor (sensible + latente)." , question: "If the return air has an enthalpy of 30 BTU/lb and the supply air has 20 BTU/lb, how much total heat is being removed per pound of air?", options: ["10 BTU/lb", "50 BTU/lb", "2 BTU/lb", "0 BTU/lb"], explanation: "The enthalpy difference (Delta H) indicates the change in total heat content (sensible + latent)." },
  { id:"nate_376", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Por qué es importante mantener la velocidad de cara (Face Velocity) en el evaporador por debajo de 500 fpm?", opciones:["Para que no haga ruido", "Para evitar que las gotas de condensado salgan volando del serpentín hacia los ductos (Moisture Carryover)", "Para que el filtro dure más", "Para ahorrar energía"], respuesta_correcta:1, explicacion:"Si el aire pasa muy rápido, 'sopla' el agua fuera de las aletas, causando moho en los ductos." , question: "Why is it important to keep the Face Velocity at the evaporator below 500 fpm?", options: ["To reduce noise", "To prevent condensate droplets from being blown off the coil into the ductwork (Moisture Carryover)", "To make the filter last longer", "To save energy"], explanation: "If the air passes too fast, it 'blows' water off the fins, causing mold growth in the ductwork." },
  { id:"nate_377", categoria:"NATE_DIAGNOSTICO", pregunta:"¿De qué trata la norma ASHRAE 62.2?", opciones:["De la eficiencia de los motores", "De la ventilación aceptable para la Calidad del Aire Interior (IAQ) en edificios residenciales", "Del tipo de refrigerante", "Del tamaño de los tornillos"], respuesta_correcta:1, explicacion:"Establece cuánto aire fresco debe introducirse a una casa para que sea saludable para los humanos." , question: "What does ASHRAE Standard 62.2 address?", options: ["Motor efficiency", "Acceptable ventilation for Indoor Air Quality (IAQ) in residential buildings", "Refrigerant type", "Screw sizes"], explanation: "It establishes how much fresh air must be introduced into a home for it to be healthy for occupants." },
  { id:"nate_378", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la función de un ERV (Energy Recovery Ventilator)?", opciones:["Solo meter aire fresco", "Intercambiar calor Y humedad entre el aire que sale y el aire que entra para reducir la carga en el AC", "Limpiar el aire con luz UV", "Aumentar la presión de gas"], respuesta_correcta:1, explicacion:"A diferencia del HRV (solo calor), el ERV también ayuda a controlar la humedad del aire fresco entrante." , question: "What is the function of an ERV (Energy Recovery Ventilator)?", options: ["Only to bring in fresh air", "To exchange both heat AND moisture between the exhaust and incoming air to reduce the load on the AC", "To clean the air with UV light", "To increase gas pressure"], explanation: "Unlike an HRV (heat only), an ERV also helps control the humidity of the incoming fresh air." },
  { id:"nate_379", categoria:"NATE_DIAGNOSTICO", pregunta:"Si mides la presión estática en el suministro (+0.3) y en el retorno (-0.2), ¿cuál es la Presión Estática Total Externa (TESP)?", opciones:["0.1 iwc", "0.5 iwc", "-0.1 iwc", "0.6 iwc"], respuesta_correcta:1, explicacion:"La TESP es la suma de los valores absolutos: 0.3 + 0.2 = 0.5 iwc." , question: "If you measure the static pressure on the supply side (+0.3) and the return side (-0.2), what is the Total External Static Pressure (TESP)?", options: ["0.1 iwc", "0.5 iwc", "-0.1 iwc", "0.6 iwc"], explanation: "TESP is the sum of the absolute values: 0.3 + 0.2 = 0.5 iwc." },
  { id:"nate_380", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué equipo electrónico dentro de una casa genera la mayor carga de calor sensible para el Manual J?", opciones:["Una televisión LED", "Un refrigerador", "Una estufa de gas encendida", "Una computadora de gaming de alto rendimiento"], respuesta_correcta:2, explicacion:"Los electrodomésticos de cocina que usan fuego o resistencias grandes añaden miles de BTU de calor sensible." , question: "What household electronic equipment generates the greatest sensible heat load for Manual J purposes?", options: ["An LED television", "A refrigerator", "A gas stove in use", "A high-performance gaming computer"], explanation: "Cooking appliances that use open flame or large resistance elements add thousands of BTUs of sensible heat." },
  { id:"nate_381", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la ventaja de los ductos de 'Duct Board' (fibra de vidrio rígida) frente a los de metal?", opciones:["Son más resistentes a los golpes", "Tienen aislamiento térmico y acústico integrado", "Duran 100 años", "No necesitan sellado"], respuesta_correcta:1, explicacion:"El material mismo es aislante, lo que ahorra tiempo de instalación y reduce el ruido del aire." , question: "What is the advantage of Duct Board (rigid fiberglass) ductwork compared to sheet metal?", options: ["It is more impact-resistant", "It has built-in thermal and acoustic insulation", "It lasts 100 years", "It does not need sealing"], explanation: "The material itself is insulating, which saves installation time and reduces airflow noise." },
  { id:"nate_382", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué factor aumenta drásticamente la carga latente en un gimnasio comercial?", opciones:["Las luces", "La respiración y transpiración intensa de las personas (metabolismo alto)", "Las máquinas de pesas", "Las ventanas"], respuesta_correcta:1, explicacion:"Una persona haciendo ejercicio exhala y suda mucha más agua que una persona sentada, añadiendo carga de humedad al sistema." , question: "What factor drastically increases the latent load in a commercial gym?", options: ["The lights", "Intense breathing and perspiration from occupants (high metabolic rate)", "Weight machines", "The windows"], explanation: "A person exercising exhales and sweats far more moisture than a person sitting, adding significant humidity load to the system." },
  { id:"nate_383", categoria:"NATE_DIAGNOSTICO", pregunta:"¿A qué porcentaje de Humedad Relativa (RH) se debe configurar un humidificador en invierno para evitar condensación en las ventanas?", opciones:["10%", "35% - 45%", "60%", "80%"], respuesta_correcta:1, explicacion:"Es el rango de confort. Arriba de 50% en invierno, el agua chorreará por los vidrios fríos, causando moho." , question: "At what Relative Humidity (RH) percentage should a humidifier be set in winter to avoid window condensation?", options: ["10%", "35% - 45%", "60%", "80%"], explanation: "This is the comfort range. Above 50% in winter, water will run down the cold glass, causing mold growth." },
  { id:"nate_384", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Por qué un equipo Inverter tiene un SEER2 mucho más alto que un equipo de una sola velocidad?", opciones:["Porque usa mejor refrigerante", "Porque puede operar a capacidades bajas (ej. 30%) durante la mayor parte del tiempo, consumiendo mucha menos energía", "Porque el compresor es más grande", "Porque no usa aceite"], respuesta_correcta:1, explicacion:"La mayor parte del año no hace 95°F. El Inverter ajusta su potencia a la carga real, evitando arranques y paros costosos." , question: "Why does an Inverter unit have a much higher SEER2 than a single-speed unit?", options: ["Because it uses a better refrigerant", "Because it can operate at low capacities (e.g., 30%) during most of the time, consuming far less energy", "Because the compressor is larger", "Because it does not use oil"], explanation: "For most of the year it is not 95°F outside. The Inverter adjusts its output to the actual load, avoiding costly start-and-stop cycles." },
  { id:"nate_385", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la función de las 'Turning Vanes' dentro de un codo de ducto de metal cuadrado?", opciones:["Enfriar el aire", "Guiar el aire suavemente a través de la curva para reducir la turbulencia y la caída de presión", "Hacer el ducto más fuerte", "Filtrar el aire"], respuesta_correcta:1, explicacion:"Transforman un codo ineficiente en uno de baja fricción." , question: "What is the function of Turning Vanes inside a square metal duct elbow?", options: ["To cool the air", "To guide the air smoothly through the turn to reduce turbulence and pressure drop", "To make the duct stronger", "To filter the air"], explanation: "They transform an inefficient elbow into a low-friction one." },
  { id:"nate_386", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué certifica el sello UL 181 en una cinta o sellador de ductos?", opciones:["Que es de color gris", "Que cumple con estándares de resistencia al fuego, adhesión y durabilidad para sistemas de aire", "Que es biodegradable", "Que se puede usar en plomería"], respuesta_correcta:1, explicacion:"Es el código de seguridad obligatorio para cualquier material que toque el flujo de aire." , question: "What does the UL 181 label certify on a duct tape or sealant?", options: ["That it is gray in color", "That it meets fire resistance, adhesion, and durability standards for air distribution systems", "That it is biodegradable", "That it can be used in plumbing"], explanation: "It is the mandatory safety standard for any material that contacts the airstream." },
  { id:"nate_387", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué es la 'Estratificación' del aire en un cuarto con techos muy altos?", opciones:["Que el aire huele mal", "La formación de capas de aire con diferentes temperaturas (aire caliente arriba, frío abajo)", "El movimiento circular del aire", "Cuando el aire se sale por la puerta"], respuesta_correcta:1, explicacion:"El aire caliente es menos denso y sube. En invierno, esto es un problema porque el calor se queda atrapado en el techo." , question: "What is air Stratification in a room with very high ceilings?", options: ["That the air smells bad", "The formation of air layers at different temperatures (warm air at the top, cold air at the bottom)", "Circular air movement", "When air escapes through the door"], explanation: "Warm air is less dense and rises. In winter, this is a problem because the heat stays trapped at ceiling level." },
  { id:"nate_388", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cada cuántos pies se debe soportar horizontalmente un ducto flexible de 12 pulgadas?", opciones:["Cada 2 pies", "Cada 4 pies (según estándares SMACNA)", "Cada 10 pies", "No necesita soportes"], respuesta_correcta:1, explicacion:"Soportes muy alejados causan que el ducto se 'pande' (sag), creando restricciones al flujo." , question: "At what interval should a 12-inch flexible duct be supported when installed horizontally?", options: ["Every 2 feet", "Every 4 feet (per SMACNA standards)", "Every 10 feet", "It does not need supports"], explanation: "Supports spaced too far apart cause the duct to sag, creating airflow restrictions." },
  { id:"nate_389", categoria:"NATE_DIAGNOSTICO", pregunta:"Si mezclas 1000 CFM de aire de retorno a 75°F con 200 CFM de aire exterior a 95°F, ¿cuál será la temperatura aproximada del aire resultante?", opciones:["75°F", "78.3°F", "85°F", "95°F"], respuesta_correcta:1, explicacion:"Es un promedio ponderado: [(1000 * 75) + (200 * 95)] / 1200 = 78.33°F." , question: "If you mix 1,000 CFM of return air at 75°F with 200 CFM of outdoor air at 95°F, what will be the approximate resulting mixed-air temperature?", options: ["75°F", "78.3°F", "85°F", "95°F"], explanation: "It is a weighted average: [(1,000 x 75) + (200 x 95)] / 1,200 = 78.33°F." },
  { id:"nate_390", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué color de techo (shingles) genera la menor carga térmica en el verano?", opciones:["Negro", "Gris oscuro", "Blanco o colores claros (Cool Roof)", "Rojo"], respuesta_correcta:2, explicacion:"Los colores claros reflejan la radiación solar en lugar de absorberla hacia el ático." , question: "What roof color (shingles) generates the least thermal load in summer?", options: ["Black", "Dark gray", "White or light colors (Cool Roof)", "Red"], explanation: "Light colors reflect solar radiation instead of absorbing it into the attic." },
  { id:"nate_391", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Para qué sirve un 'Balancing Damper'?", opciones:["Para cerrar el aire totalmente", "Para ajustar manualmente el flujo de aire a cada cuarto y asegurar que todos reciban lo que dice el diseño", "Para sostener el ducto", "Para filtrar el aire"], respuesta_correcta:1, explicacion:"Se instalan en los ramales cerca del plenum principal para balancear el sistema." , question: "What is the purpose of a Balancing Damper?", options: ["To shut off airflow completely", "To manually adjust the airflow to each room to ensure every space receives what the design specifies", "To support the duct", "To filter the air"], explanation: "They are installed in the branch runs near the main plenum to balance the system." },
  { id:"nate_392", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuál es la eficiencia eléctrica típica de un motor ECM frente a uno PSC?", opciones:["Iguales", "El ECM es aproximadamente un 20-30% más eficiente", "El PSC es mejor", "No se puede medir"], respuesta_correcta:1, explicacion:"Los motores de conmutación electrónica pierden mucho menos calor y consumen menos Watts para mover el mismo aire." , question: "What is the typical electrical efficiency advantage of an ECM motor over a PSC motor?", options: ["They are equal", "The ECM is approximately 20-30% more efficient", "The PSC is better", "It cannot be measured"], explanation: "Electronically commutated motors waste far less heat and consume fewer watts to move the same amount of air." },
  { id:"nate_393", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué sucede si instalas un difusor de techo justo encima de un termostato?", opciones:["El termostato se ve mejor", "El termostato 'leerá' el aire frío que sale y apagará el equipo antes de que el cuarto esté realmente frío (Short Cycling)", "El aire circula mejor", "No pasa nada"], respuesta_correcta:1, explicacion:"Es un error de diseño básico; el termostato debe sentir el aire promedio del cuarto, no el chorro de suministro." , question: "What happens if you install a ceiling diffuser directly above a thermostat?", options: ["The thermostat looks better", "The thermostat 'reads' the cold supply air and shuts off the unit before the room is actually cool (Short Cycling)", "The air circulates better", "Nothing happens"], explanation: "It is a basic design error; the thermostat must sense the room's average air temperature, not the direct supply airstream." },
  { id:"nate_394", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Cuántos BTU de calor sensible añade una persona adulta en reposo a la carga de una habitación?", opciones:["50 BTU", "230 - 250 BTU", "1000 BTU", "0 BTU"], respuesta_correcta:1, explicacion:"Es el estándar usado en Manual J para el calor corporal de una persona sentada." , question: "How many BTUs of sensible heat does one adult at rest add to a room's load?", options: ["50 BTU", "230 - 250 BTU", "1,000 BTU", "0 BTU"], explanation: "This is the standard used in Manual J for the body heat of a seated person." },
  { id:"nate_395", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Qué es un 'Canvas Connector' (conector de lona)?", opciones:["Un parche para fugas", "Una unión flexible entre la manejadora y el plenum de metal para evitar que la vibración del motor se transmita a los ductos", "Un tipo de filtro", "Una bota de registro"], respuesta_correcta:1, explicacion:"Aísla mecánicamente el equipo de la red de ductos, reduciendo el ruido en la casa." , question: "What is a Canvas Connector?", options: ["A patch for leaks", "A flexible joint between the air handler and the metal plenum to prevent motor vibration from transferring to the ductwork", "A type of filter", "A register boot"], explanation: "It mechanically isolates the equipment from the duct network, reducing noise in the house." },
  { id:"nate_396", categoria:"NATE_DIAGNOSTICO", pregunta:"Si un filtro MERV 13 tiene una caída de presión de 0.3 iwc y tu ventilador solo aguanta 0.5 iwc de TESP total, ¿cuánto queda para el resto del sistema de ductos?", opciones:["0.5 iwc", "0.2 iwc", "0.8 iwc", "0 iwc"], respuesta_correcta:1, explicacion:"El presupuesto de presión es limitado. Un filtro muy restrictivo deja poco margen para ductos largos o rejillas." , question: "If a MERV 13 filter has a pressure drop of 0.3 iwc and your blower can only handle 0.5 iwc of total TESP, how much is left for the rest of the duct system?", options: ["0.5 iwc", "0.2 iwc", "0.8 iwc", "0 iwc"], explanation: "The pressure budget is limited. A highly restrictive filter leaves little margin for long ducts or registers." },
  { id:"nate_397", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Por qué un equipo de SEER 20 podría no ahorrar tanto dinero en un clima desértico muy seco frente a uno de SEER 14?", opciones:["Porque el sol lo daña", "Porque el SEER se calcula sobre un promedio que incluye deshumidificación; en climas secos, la eficiencia sensible es lo que importa", "Porque gasta más agua", "Porque los filtros se tapan más"], respuesta_correcta:1, explicacion:"Es una sutileza de ingeniería: el beneficio del SEER alto a veces se pierde si el equipo no está optimizado para calor extremo y seco." , question: "Why might a SEER 20 unit not save as much money in a very dry desert climate compared to a SEER 14 unit?", options: ["Because the sun damages it", "Because SEER is calculated using an average that includes dehumidification; in dry climates, sensible efficiency is what matters", "Because it uses more water", "Because the filters clog faster"], explanation: "This is an engineering nuance: the high SEER benefit can be diminished if the equipment is not optimized for extreme dry heat." },
  { id:"nate_398", categoria:"NATE_DIAGNOSTICO", pregunta:"¿Por qué las rejillas de retorno son siempre mucho más grandes que las de suministro?", opciones:["Para que entre más aire", "Para mantener la velocidad del aire baja (silenciosa) y no forzar la succión del ventilador", "Porque son más baratas", "Por estética"], respuesta_correcta:1, explicacion:"La succión ruidosa es molesta; un retorno grande garantiza un funcionamiento silencioso." , question: "Why are return grilles always much larger than supply grilles?", options: ["To let in more air", "To keep the air velocity low (quiet) and not strain the blower's suction", "Because they are cheaper", "For aesthetics"], explanation: "Noisy suction is annoying; a large return ensures quiet operation." },
  { id:"nate_399", categoria:"NATE_DIAGNOSTICO", pregunta:"En un cálculo de Manual J, ¿qué significa el término 'U-Value'?", opciones:["La velocidad del viento", "El inverso del R-Value (U = 1/R), indicando la tasa de transferencia de calor a través de un material", "La humedad del aire", "El voltaje del equipo"], respuesta_correcta:1, explicacion:"Mientras que R es resistencia, U es transmitancia. En Manual J se usa U para calcular cuántos BTU pasan por hora por cada pie cuadrado." , question: "In a Manual J calculation, what does the term U-Value mean?", options: ["Wind speed", "The inverse of R-Value (U = 1/R), indicating the rate of heat transfer through a material", "Air humidity", "Equipment voltage"], explanation: "While R represents resistance, U represents transmittance. In Manual J, U is used to calculate how many BTUs pass per hour per square foot." },

  // -- Industrial Avanzado (400-749) --
  { id:"nate_400", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la principal ventaja de un sistema de refrigeración en rack (paralelo) frente a unidades individuales?", opciones:["Es más fácil de instalar", "Eficiencia energética superior al ciclar compresores de diferentes tamaños según la carga real", "Usa menos tubería", "No requiere mantenimiento"], respuesta_correcta:1, explicacion:"El rack puede encender un compresor pequeño para la carga de noche y todos los compresores para el día, manteniendo una presión de succión constante y eficiente." , question: "What is the main advantage of a rack (parallel) refrigeration system over individual units?", options: ["It is easier to install", "Superior energy efficiency by cycling different-sized compressors based on the actual load", "It uses less piping", "It requires no maintenance"], explanation: "The rack can run a small compressor for the nighttime load and all compressors for the daytime, maintaining a constant and efficient suction pressure." },
  { id:"nate_401", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de CO2 transcrítico, ¿qué sucede cuando la temperatura ambiente supera el punto crítico (87.8°F)?", opciones:["El gas se congela", "El refrigerante no puede condensarse en líquido; el sistema opera en modo 'Gas Cooler'", "El sistema explota", "El compresor se detiene"], respuesta_correcta:1, explicacion:"Por encima del punto crítico, no hay diferencia entre líquido y vapor. El intercambiador exterior solo enfría el gas denso sin condensarlo." , question: "In a transcritical CO2 system, what happens when the ambient temperature exceeds the critical point (87.8°F)?", options: ["The gas freezes", "The refrigerant cannot condense into liquid; the system operates in Gas Cooler mode", "The system explodes", "The compressor stops"], explanation: "Above the critical point, there is no distinction between liquid and vapor. The outdoor heat exchanger only cools the dense gas without condensing it." },
  { id:"nate_402", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'EPR' (Electronic Pressure Regulator) en un sistema de supermercado?", opciones:["Un sensor de movimiento", "Una válvula modulante que controla con precisión la temperatura de un gabinete específico ajustando la presión del evaporador", "Un interruptor de emergencia", "Un medidor de voltaje"], respuesta_correcta:1, explicacion:"Permite que un mismo rack de baja temperatura maneje diferentes vitrinas con temperaturas ligeramente distintas." , question: "What is an EPR (Electronic Pressure Regulator) in a supermarket system?", options: ["A motion sensor", "A modulating valve that precisely controls a specific display case's temperature by adjusting evaporator pressure", "An emergency shut-off", "A voltage meter"], explanation: "It allows a single low-temperature rack to serve multiple display cases with slightly different temperature requirements." },
  { id:"nate_403", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del 'Oil Reservoir' (Reservorio de Aceite) en un sistema paralelo?", opciones:["Guardar aceite sucio", "Mantener un inventario de aceite a presión intermedia para alimentar los reguladores de nivel de cada compresor", "Enfriar el aceite", "Bombear aceite al techo"], respuesta_correcta:1, explicacion:"Asegura que cada compresor tenga el nivel exacto de lubricación sin importar cuál esté encendido o apagado." , question: "What is the function of the Oil Reservoir in a parallel compressor system?", options: ["To store dirty oil", "To maintain an oil inventory at intermediate pressure to feed the level regulators of each compressor", "To cool the oil", "To pump oil to the roof"], explanation: "It ensures each compressor has the exact level of lubrication regardless of which compressors are running." },
  { id:"nate_404", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de CO2 en cascada, ¿cuál es la función del Chiller de CO2?", opciones:["Enfriar el agua", "Condensar el CO2 usando un refrigerante secundario (como R-134a o R-404A) en el lado de alta", "Hacer hielo", "Calentar el aceite"], respuesta_correcta:1, explicacion:"En cascada, el CO2 nunca llega al punto crítico porque otro sistema de refrigeración lo ayuda a condensarse." , question: "In a cascade CO2 system, what is the function of the CO2 Chiller?", options: ["To cool water", "To condense the CO2 using a secondary refrigerant (such as R-134a or R-404A) on the high side", "To make ice", "To heat the oil"], explanation: "In a cascade arrangement, the CO2 never reaches the critical point because another refrigeration system helps it condense." },
  { id:"nate_405", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la presión de diseño típica para el lado de alta de un sistema de CO2 transcrítico?", opciones:["300 psig", "800 psig", "1,500 a 1,740 psig (120 bar)", "5,000 psig"], respuesta_correcta:2, explicacion:"El CO2 opera a presiones extremadamente altas, requiriendo tuberías de cobre-hierro (K65) o acero inoxidable." , question: "What is the typical design pressure for the high side of a transcritical CO2 system?", options: ["300 psig", "800 psig", "1,500 to 1,740 psig (120 bar)", "5,000 psig"], explanation: "CO2 operates at extremely high pressures, requiring iron-reinforced copper (K65) or stainless steel tubing." },
  { id:"nate_406", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa un rack con 'Succión Dividida' (Split Suction)?", opciones:["Que el tubo está roto", "Que el rack tiene dos grupos de compresores operando a diferentes presiones de succión (ej. Media y Baja temp)", "Que usa dos tipos de gas", "Que el aceite se separa en dos"], respuesta_correcta:1, explicacion:"Ahorra espacio y equipo al consolidar diferentes necesidades de refrigeración en un solo mueble físico." , question: "What does a rack with Split Suction mean?", options: ["That the pipe is broken", "That the rack has two groups of compressors operating at different suction pressures (e.g., medium and low temperature)", "That it uses two types of refrigerant", "That the oil separates into two"], explanation: "It saves space and equipment by consolidating different refrigeration needs into a single physical rack." },
  { id:"nate_407", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se aprovecha el 'Calor de Desperdicio' en un supermercado grande?", opciones:["Se tira al aire", "Mediante un intercambiador de calor de desrecalentamiento (Desuperheater) para calentar agua sanitaria o el aire de la tienda", "Se usa para enfriar", "No se puede aprovechar"], respuesta_correcta:1, explicacion:"El calor que los compresores extraen de la comida se usa para que el supermercado no gaste en calefacción o agua caliente." , question: "How is Waste Heat utilized in a large supermarket?", options: ["It is vented to the atmosphere", "Through a desuperheater heat exchanger to heat domestic hot water or the store's air", "It is used for cooling", "It cannot be utilized"], explanation: "The heat that the compressors extract from the food is used so the supermarket does not have to spend on heating or hot water." },
  { id:"nate_408", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué es vital una válvula check a la descarga de cada compresor en un rack en paralelo?", opciones:["Para que no hagan ruido", "Para evitar que el refrigerante de los compresores encendidos migre hacia el compresor que está apagado", "Para medir la presión", "Para filtrar basura"], respuesta_correcta:1, explicacion:"Sin la check, el compresor apagado se llenaría de líquido, causando un golpe de ariete al intentar arrancar." , question: "Why is a check valve at the discharge of each compressor in a parallel rack critical?", options: ["To reduce noise", "To prevent refrigerant from running compressors from migrating into a compressor that is off", "To measure pressure", "To filter debris"], explanation: "Without the check valve, the idle compressor would fill with liquid, causing liquid slugging upon the next startup attempt." },
  { id:"nate_409", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede si se libera presión de CO2 líquido demasiado rápido hacia la atmósfera (por debajo de 60 psig)?", opciones:["Se vuelve vapor invisible", "Se convierte instantáneamente en 'Hielo Seco' (sólido), lo que puede bloquear válvulas de seguridad", "Se calienta", "Explota por fuego"], respuesta_correcta:1, explicacion:"El CO2 no existe como líquido a presión atmosférica; pasa directamente de sólido a gas o viceversa si se cruza el punto triple." , question: "What happens if CO2 liquid pressure is released too rapidly to the atmosphere (below 60 psig)?", options: ["It becomes invisible vapor", "It instantly converts to Dry Ice (solid), which can block safety relief valves", "It heats up", "It explodes due to fire"], explanation: "CO2 does not exist as a liquid at atmospheric pressure; it passes directly from solid to gas or vice versa when crossing the triple point." },
  { id:"nate_410", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la diferencia entre un condensador y un 'Gas Cooler' en CO2?", opciones:["Solo el nombre", "El condensador cambia el estado de gas a líquido; el Gas Cooler solo baja la temperatura del gas supercrítico", "El Gas Cooler usa agua", "El condensador es más grande"], respuesta_correcta:1, explicacion:"En modo transcrítico no hay condensación, solo enfriamiento sensible de un fluido de alta densidad." , question: "What is the difference between a Condenser and a Gas Cooler in CO2?", options: ["Only the name", "A condenser changes the state from gas to liquid; a Gas Cooler only lowers the temperature of the supercritical gas", "The Gas Cooler uses water", "The condenser is bigger"], explanation: "In transcritical mode there is no condensation, only sensible cooling of a high-density fluid." },
  { id:"nate_411", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué sirve el 'Flash Tank' en un sistema de CO2 transcrítico?", opciones:["Para guardar aceite", "Para separar el líquido del vapor después de la válvula de alta presión y mantener una presión intermedia estable", "Para limpiar el gas", "Para enfriar el panel"], respuesta_correcta:1, explicacion:"El líquido del Flash Tank va a los evaporadores y el vapor se regresa a los compresores (o compresor de bypass) para eficiencia." , question: "What is the purpose of the Flash Tank in a transcritical CO2 system?", options: ["To store oil", "To separate liquid from vapor after the high-pressure valve and maintain a stable intermediate pressure", "To clean the gas", "To cool the panel"], explanation: "Liquid from the Flash Tank goes to the evaporators and the vapor is returned to the compressors (or bypass compressor) for efficiency." },
  { id:"nate_412", categoria:"NATE_INDUSTRIAL", pregunta:"Mides una presión de cárter de 30 psig y una presión de salida de la bomba de aceite de 75 psig. ¿Cuál es la presión neta de aceite?", opciones:["105 psig", "45 psig", "30 psig", "75 psig"], respuesta_correcta:1, explicacion:"Presión neta = Salida de bomba - Presión de succión (cárter). 75 - 30 = 45 psig. Un valor sano para la mayoría de los compresores." , question: "You measure a crankcase pressure of 30 psig and an oil pump outlet pressure of 75 psig. What is the net oil pressure?", options: ["105 psig", "45 psig", "30 psig", "75 psig"], explanation: "Net oil pressure = Pump outlet - Suction (crankcase) pressure. 75 - 30 = 45 psig. This is a healthy value for most compressors." },
  { id:"nate_413", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la 'Succión Flotante' (Floating Suction) en un controlador de rack?", opciones:["Que los tubos no están sujetos", "Aumentar el setpoint de presión de succión lo más posible basándose en la vitrina que más demanda, para ahorrar energía", "Una fuga de gas", "Cambiar el gas constantemente"], respuesta_correcta:1, explicacion:"Si el rack puede mantener el frío con una succión más alta (menos vacío), el compresor trabaja menos y gasta menos luz." , question: "What is Floating Suction in a rack controller?", options: ["That the pipes are not secured", "Raising the suction pressure setpoint as high as possible based on the case with the highest demand, to save energy", "A gas leak", "Constantly changing the refrigerant"], explanation: "If the rack can maintain temperatures with a higher suction pressure (less vacuum), the compressors work less and consume less power." },
  { id:"nate_414", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué es más eficiente el deshielo por gas caliente que por resistencias eléctricas?", opciones:["Porque el gas es gratis", "Porque el calor se aplica desde adentro de los tubos, derritiendo el hielo más rápido y uniforme", "Porque no usa cables", "Porque enfría al mismo tiempo"], respuesta_correcta:1, explicacion:"Reduce el tiempo de deshielo de 45 min a 15 min, evitando que el producto suba de temperatura." , question: "Why is hot gas defrost more efficient than electric resistance defrost?", options: ["Because the gas is free", "Because the heat is applied from inside the tubes, melting the ice faster and more uniformly", "Because it does not use wires", "Because it cools at the same time"], explanation: "It reduces defrost time from 45 minutes to 15 minutes, preventing the product from rising in temperature." },
  { id:"nate_415", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se debe usar tubería de cobre Tipo M o L estándar en el lado de alta de un sistema de CO2?", opciones:["Porque el CO2 corroe el cobre", "Porque el grosor de pared no resiste las presiones de más de 1,400 psig", "Porque el gas se sale por los poros", "Por el precio"], respuesta_correcta:1, explicacion:"Se requiere cobre reforzado con hierro (K65) o acero para soportar de forma segura las presiones supercríticas." , question: "Why should standard Type M or Type L copper tubing not be used on the high side of a CO2 system?", options: ["Because CO2 corrodes copper", "Because the wall thickness cannot withstand pressures exceeding 1,400 psig", "Because the gas escapes through the pores", "Because of the cost"], explanation: "Iron-reinforced copper (K65) or steel is required to safely handle supercritical pressures." },
  { id:"nate_416", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Suction Scrubber' en un rack industrial?", opciones:["Un cepillo para tubos", "Un separador de líquido de gran tamaño que protege a los compresores de inundaciones masivas", "Un filtro de aire", "Un tipo de aceite"], respuesta_correcta:1, explicacion:"Es la última línea de defensa antes de que el vapor entre a los compresores del rack." , question: "What is a Suction Scrubber in an industrial rack?", options: ["A tube-cleaning brush", "An oversized liquid separator that protects the compressors from massive flooding", "An air filter", "A type of oil"], explanation: "It is the last line of defense before vapor enters the rack compressors." },
  { id:"nate_417", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo funciona un descargador (unloader) de culata en un compresor reciprocante?", opciones:["Apaga el compresor", "Bloquea la succión de un par de cilindros para que el pistón se mueva sin bombear gas, reduciendo la capacidad", "Saca el aceite", "Aumenta la velocidad"], respuesta_correcta:1, explicacion:"Permite que un compresor de 4 cilindros funcione como uno de 2 cilindros cuando la carga es baja." , question: "How does a cylinder head unloader work on a reciprocating compressor?", options: ["It turns the compressor off", "It blocks the suction on a pair of cylinders so the piston moves without pumping gas, reducing capacity", "It removes oil", "It increases speed"], explanation: "It allows a 4-cylinder compressor to operate as a 2-cylinder compressor when the load is low." },
  { id:"nate_418", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de 'Lazo Secundario', ¿cuál es la ventaja de bombear glicol a las vitrinas en lugar de refrigerante?", opciones:["El glicol es más frío", "Reduce drásticamente la carga de refrigerante del sistema y el riesgo de fugas masivas en el área de ventas", "Es más barato que el agua", "Las bombas son más pequeñas"], respuesta_correcta:1, explicacion:"El refrigerante se queda confinado en la sala de máquinas; a la tienda solo va una mezcla de agua y glicol segura." , question: "In a Secondary Loop system, what is the advantage of pumping glycol to the display cases instead of refrigerant?", options: ["Glycol is colder", "It drastically reduces the system's refrigerant charge and the risk of massive leaks in the sales area", "It is cheaper than water", "The pumps are smaller"], explanation: "The refrigerant stays confined in the machine room; only a safe water-glycol mixture is sent to the sales floor." },
  { id:"nate_419", categoria:"NATE_INDUSTRIAL", pregunta:"El separador de aceite está muy caliente en la parte superior pero frío en la parte inferior. El compresor marca baja presión de aceite. ¿Causa?", opciones:["Falta de gas", "El flotador interno del separador está trabado o el filtro de aceite está tapado", "Mucho aceite en el sistema", "El condensador está sucio"], respuesta_correcta:1, explicacion:"Si el aceite no puede salir del separador para volver al reservorio, los compresores se quedan sin lubricación." , question: "The oil separator is very hot at the top but cold at the bottom. The compressor shows low oil pressure. What is the cause?", options: ["Low refrigerant charge", "The internal float in the separator is stuck or the oil filter is clogged", "Too much oil in the system", "The condenser is dirty"], explanation: "If the oil cannot leave the separator to return to the reservoir, the compressors are starved of lubrication." },
  { id:"nate_420", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué el CO2 transcrítico pierde mucha eficiencia en climas muy calurosos (ej. 100°F+)?", opciones:["Porque el gas se evapora", "Debido a la alta potencia requerida para comprimir el gas en estado supercrítico y la falta de calor latente en el rechazo", "Porque los ventiladores fallan", "Porque el aceite se quema"], respuesta_correcta:1, explicacion:"Sin el cambio de fase (condensación), el sistema debe mover mucho más volumen de gas para obtener el mismo enfriamiento." , question: "Why does transcritical CO2 lose significant efficiency in very hot climates (e.g., 100°F+)?", options: ["Because the gas evaporates", "Due to the high power required to compress gas in a supercritical state and the lack of latent heat in the rejection process", "Because the fans fail", "Because the oil burns"], explanation: "Without the phase change (condensation), the system must move a much larger volume of gas to achieve the same cooling effect." },
  { id:"nate_421", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Case Controller' en una vitrina moderna de supermercado?", opciones:["Un termostato", "Un microprocesador local que gestiona la EEV, ventiladores, luces y deshielo de esa vitrina específica", "Un sensor de luz", "El dueño del súper"], respuesta_correcta:1, explicacion:"Se comunica con el rack para pedir refrigerante solo cuando es necesario, optimizando el consumo." , question: "What is the Case Controller in a modern supermarket display case?", options: ["A thermostat", "A local microprocessor that manages the EEV, fans, lights, and defrost for that specific display case", "A light sensor", "The store owner"], explanation: "It communicates with the rack to request refrigerant only when needed, optimizing energy consumption." },
  { id:"nate_422", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa que un compresor sea 'Semi-hermético'?", opciones:["Que se puede abrir para reparar internamente (tornillos en la carcasa)", "Que solo enfría la mitad", "Que no usa aceite", "Que es de plástico"], respuesta_correcta:0, explicacion:"A diferencia de los herméticos (soldados), estos permiten cambiar platos de válvulas, bobinados o pistones." , question: "What does it mean for a compressor to be Semi-Hermetic?", options: ["It can be opened for internal repairs (bolts on the casing)", "It only cools halfway", "It does not use oil", "It is made of plastic"], explanation: "Unlike hermetic compressors (welded shut), semi-hermetic units allow replacement of valve plates, windings, or pistons." },
  { id:"nate_423", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se instalan válvulas de retención (check) en las líneas de succión de evaporadores de baja temperatura que comparten rack con media temperatura?", opciones:["Para que no vibren", "Para evitar que el refrigerante de media temperatura (más alta presión) migre al evaporador de baja durante el deshielo", "Para medir el flujo", "Para filtrar el aceite"], respuesta_correcta:1, explicacion:"El gas siempre viaja hacia la zona de menor presión. Sin la check, el evaporador de baja se inundaría de gas de los otros." , question: "Why are check valves installed on the suction lines of low-temperature evaporators that share a rack with medium-temperature circuits?", options: ["To prevent vibration", "To prevent medium-temperature refrigerant (higher pressure) from migrating into the low-temperature evaporator during defrost", "To measure flow", "To filter oil"], explanation: "Gas always travels toward the lower pressure zone. Without the check valve, the low-temperature evaporator would flood with gas from the other circuits." },
  { id:"nate_424", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función de un 'Eyectador' (Ejector) en un sistema de CO2 transcrítico avanzado?", opciones:["Sacar el aire", "Usar la energía de expansión del gas de alta para succionar vapor del evaporador, reduciendo el trabajo del compresor", "Bombear aceite", "Limpiar los tubos"], respuesta_correcta:1, explicacion:"Es una forma de recuperar energía que normalmente se pierde en la válvula de expansión, mejorando el COP en climas cálidos." , question: "What is the function of an Ejector in an advanced transcritical CO2 system?", options: ["To remove air", "To use the expansion energy from the high-pressure gas to draw vapor from the evaporator, reducing compressor work", "To pump oil", "To clean the tubes"], explanation: "It is a way to recover energy that is normally lost through the expansion valve, improving COP in warm climates." },
  { id:"nate_425", categoria:"NATE_INDUSTRIAL", pregunta:"Un rack de 4 compresores muestra que el Compresor #1 consume el doble de amperaje que los otros 3, pero todos son iguales. ¿Qué revisas?", opciones:["Si el condensador está sucio", "Si el compresor #1 tiene las válvulas de descarga obstruidas o está trabajando a una presión de succión distinta", "Si el gas es el correcto", "El termostato de la tienda"], respuesta_correcta:1, explicacion:"Un compresor que lucha contra una restricción interna o descarga bloqueada consumirá mucho más amperaje." , question: "A 4-compressor rack shows Compressor #1 drawing double the amperage of the other 3, but all compressors are identical. What do you check?", options: ["If the condenser is dirty", "If Compressor #1 has obstructed discharge valves or is operating at a different suction pressure", "If the refrigerant is correct", "The store thermostat"], explanation: "A compressor struggling against an internal restriction or a blocked discharge will draw much higher amperage." },
  { id:"nate_426", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se reconoce visualmente la tubería de cobre K65 usada para CO2?", opciones:["Es de color verde", "Tiene una marca grabada 'K65' y es notablemente más pesada y rígida que el cobre tipo L", "Es de plástico por fuera", "Es cuadrada"], respuesta_correcta:1, explicacion:"Contiene un pequeño porcentaje de hierro que le da una resistencia mecánica superior a la alta presión." , question: "How can you visually identify K65 copper tubing used for CO2?", options: ["It is green in color", "It has an engraved 'K65' marking and is noticeably heavier and more rigid than Type L copper", "It has a plastic coating on the outside", "It is square-shaped"], explanation: "It contains a small percentage of iron that gives it superior mechanical strength for high-pressure applications." },
  { id:"nate_427", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa una alarma de 'High Discharge Temperature' en un compresor de rack?", opciones:["Que el cuarto está caliente", "Que el gas de descarga superó el límite (ej. 225°F), indicando falta de gas, falla de enfriamiento de motor o válvulas rotas", "Que el aceite está frío", "Que el condensador se apagó"], respuesta_correcta:1, explicacion:"Es una alarma crítica que previene que el aceite se carbonice y destruya el compresor." , question: "What does a 'High Discharge Temperature' alarm on a rack compressor mean?", options: ["The room is hot", "The discharge gas has exceeded the limit (e.g., 225°F), indicating low charge, motor cooling failure, or broken valves", "The oil is cold", "The condenser shut off"], explanation: "It is a critical alarm that prevents the oil from carbonizing and destroying the compressor." },
  { id:"nate_428", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la 'Cortina de Aire' en una vitrina de supermercado abierta?", opciones:["Una cortina de plástico", "Un flujo laminar de aire frío que actúa como barrera para evitar que el aire caliente de la tienda entre a la vitrina", "Un ventilador de techo", "Un sensor de presencia"], respuesta_correcta:1, explicacion:"Si la cortina se rompe (por ventiladores externos o bloqueos), la vitrina perderá todo el frío." , question: "What is the Air Curtain in an open supermarket display case?", options: ["A plastic curtain", "A laminar flow of cold air that acts as a barrier to prevent warm store air from entering the display case", "A ceiling fan", "A motion sensor"], explanation: "If the air curtain is disrupted (by external fans or blockages), the display case will lose all of its cooling." },
  { id:"nate_429", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un sistema 'Booster' de CO2?", opciones:["Un sistema con turbo", "Un sistema donde los compresores de baja temperatura descargan en la succión de los compresores de media temperatura", "Un sistema que usa nitrógeno", "Un sistema de una sola etapa"], respuesta_correcta:0, explicacion:"Optimiza la compresión al no obligar a los compresores de baja a subir la presión hasta el nivel del Gas Cooler de un solo golpe." , question: "What is a CO2 Booster system?", options: ["A turbocharged system", "A system where the low-temperature compressors discharge into the suction of the medium-temperature compressors", "A system that uses nitrogen", "A single-stage system"], explanation: "It optimizes compression by not forcing the low-temperature compressors to raise the pressure all the way to the Gas Cooler level in a single step." },
  { id:"nate_430", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se deben limpiar los filtros de malla de las vitrinas (suction screens) periódicamente?", opciones:["Para que el gas huela bien", "Para evitar caídas de presión que hagan que la vitrina no alcance la temperatura aunque el rack esté bien", "Para ahorrar aceite", "Para que no hagan ruido"], respuesta_correcta:1, explicacion:"La suciedad en la succión actúa como una TXV cerrada, dejando el evaporador sin capacidad." , question: "Why must display case suction screens be cleaned periodically?", options: ["So the gas smells good", "To prevent pressure drops that would keep the case from reaching temperature even though the rack is operating properly", "To save oil", "To prevent noise"], explanation: "Dirt on the suction screen acts like a closed TXV, starving the evaporator of capacity." },
  { id:"nate_431", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del 'Compresor Líder' en un rack moderno?", opciones:["Es el que manda a los otros", "Es el compresor equipado con un VFD para modular la capacidad de forma fina y evitar arranques frecuentes de otros compresores", "Es el más grande", "Es el que tiene más aceite"], respuesta_correcta:1, explicacion:"El VFD ajusta la succión con precisión milimétrica mientras los otros compresores entran solo como apoyo grueso." , question: "What is the function of the Lead Compressor in a modern rack?", options: ["It commands the other compressors", "It is the compressor equipped with a VFD to finely modulate capacity and prevent frequent starts of the other compressors", "It is the largest one", "It has the most oil"], explanation: "The VFD adjusts suction with pinpoint precision while the other compressors only come on as coarse-capacity steps." },
  { id:"nate_432", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el límite de inflamabilidad (LFL) del Amoníaco en el aire?", opciones:["0.1%", "15.5% a 27%", "50%", "No es inflamable"], respuesta_correcta:1, explicacion:"Aunque es difícil de encender, el amoníaco puede explotar si alcanza estas concentraciones en un espacio cerrado con una chispa." , question: "What is the Lower Flammability Limit (LFL) of Ammonia in air?", options: ["0.1%", "15.5% to 27%", "50%", "It is not flammable"], explanation: "Although it is difficult to ignite, ammonia can explode if it reaches these concentrations in an enclosed space with a spark." },
  { id:"nate_433", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué hace la 'Flash Gas Bypass Valve' en un rack de CO2?", opciones:["Tira el gas a la calle", "Envía el exceso de vapor del Flash Tank directamente a la succión de los compresores de media temperatura", "Limpia el aceite", "Enfría el condensador"], respuesta_correcta:1, explicacion:"Evita que el vapor innecesario pase por los evaporadores, mejorando la eficiencia del ciclo." , question: "What does the Flash Gas Bypass Valve do on a CO2 rack?", options: ["It vents gas outside", "It sends excess vapor from the Flash Tank directly to the suction of the medium-temperature compressors", "It cleans the oil", "It cools the condenser"], explanation: "It prevents unnecessary vapor from passing through the evaporators, improving cycle efficiency." },
  { id:"nate_434", categoria:"NATE_INDUSTRIAL", pregunta:"Ves que el aceite en la mirilla del compresor tiene mucha espuma (bubbles) durante el arranque. ¿Qué indica?", opciones:["Que el aceite es de buena calidad", "Presencia de refrigerante líquido en el cárter (migración)", "Que le falta aceite", "Que el compresor gira muy rápido"], respuesta_correcta:1, explicacion:"Al arrancar, la presión baja y el refrigerante mezclado con el aceite 'hierve' violentamente, creando la espuma que no lubrica bien." , question: "You see heavy foaming (bubbles) in the compressor oil sight glass during startup. What does this indicate?", options: ["The oil is good quality", "Liquid refrigerant is present in the crankcase (migration)", "Low oil level", "The compressor is spinning too fast"], explanation: "Upon startup, the pressure drops and the refrigerant mixed with the oil 'boils' violently, creating foam that does not lubricate properly." },
  { id:"nate_435", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué sirve una válvula reguladora de presión de evaporación (KVP)?", opciones:["Para subir la presión de alta", "Para evitar que la presión de evaporación caiga por debajo de un punto seteado (protección contra congelamiento de producto)", "Para medir el gas", "Para cerrar el sistema"], respuesta_correcta:0, explicacion:"Mantiene el evaporador a una temperatura mínima constante, ideal para frutas o vegetales delicados." , question: "What is the purpose of an Evaporator Pressure Regulating valve (KVP)?", options: ["To raise the high-side pressure", "To prevent the evaporating pressure from falling below a set point (freeze protection for the product)", "To measure the refrigerant", "To shut down the system"], explanation: "It maintains the evaporator at a constant minimum temperature, ideal for delicate produce like fruits or vegetables." },
  { id:"nate_436", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la temperatura crítica exacta del R-744?", opciones:["162°F", "31.1°C (87.9°F)", "100°C", "0°C"], respuesta_correcta:1, explicacion:"Es una temperatura muy baja, lo que explica por qué el CO2 entra en modo transcrítico tan fácilmente en verano." , question: "What is the exact critical temperature of R-744?", options: ["162°F", "31.1°C (87.9°F)", "100°C", "0°C"], explanation: "It is a very low critical temperature, which explains why CO2 enters transcritical mode so easily in summer." },
  { id:"nate_437", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es Modbus en la refrigeración comercial?", opciones:["Un tipo de compresor", "Un protocolo de comunicación usado para conectar los controladores de las vitrinas con el computador central del rack", "Una marca de gas", "Un software de diseño"], respuesta_correcta:1, explicacion:"Es el estándar industrial para que todos los componentes electrónicos del supermercado se entiendan." , question: "What is Modbus in commercial refrigeration?", options: ["A type of compressor", "A communication protocol used to connect display case controllers with the rack's central computer", "A refrigerant brand", "Design software"], explanation: "It is the industrial standard that allows all electronic components in a supermarket to communicate with each other." },
  { id:"nate_438", categoria:"NATE_INDUSTRIAL", pregunta:"Un rack tiene una vibración excesiva que hace vibrar las vitrinas a 100 metros de distancia. ¿Qué revisarías?", opciones:["Si el gas está sucio", "La alineación de los compresores y el estado de los soportes antivibratorios (spring isolators) del rack", "Si las luces de la tienda están prendidas", "El termostato"], respuesta_correcta:1, explicacion:"Si los resortes del rack están 'vencidos' o tocando el piso, la vibración se transmite por toda la estructura del edificio." , question: "A rack has excessive vibration that is transferring to display cases 100 meters away. What would you inspect?", options: ["If the refrigerant is contaminated", "The compressor alignment and the condition of the anti-vibration mounts (spring isolators) on the rack", "If the store lights are on", "The thermostat"], explanation: "If the rack's spring isolators are worn out or bottomed out, vibration transmits through the building's entire structure." },
  { id:"nate_439", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué las válvulas de alivio en sistemas de CO2 suelen tener una tubería de descarga hacia el exterior con un diseño especial?", opciones:["Para que se vea bonito", "Para evitar que la nieve de CO2 bloquee la tubería durante una descarga masiva", "Para que no haga ruido", "Para recolectar el gas"], respuesta_correcta:1, explicacion:"Si el CO2 se solidifica en el escape, la presión seguirá subiendo hasta que algo explote." , question: "Why do CO2 system relief valves typically have a specially designed discharge pipe routed to the outdoors?", options: ["For aesthetics", "To prevent CO2 snow from blocking the pipe during a massive discharge event", "To reduce noise", "To collect the gas"], explanation: "If the CO2 solidifies in the vent pipe, the pressure will continue to build until something fails catastrophically." },
  { id:"nate_440", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Oil Level Regulator'?", opciones:["Una varilla de medición", "Una válvula flotadora montada en el cárter del compresor que mantiene el nivel de aceite automáticamente", "Un sensor de luz", "Una bomba de mano"], respuesta_correcta:1, explicacion:"Es el componente que recibe el aceite del reservorio y decide cuándo dejarlo entrar al compresor." , question: "What is an Oil Level Regulator?", options: ["A dipstick", "A float valve mounted on the compressor crankcase that automatically maintains the proper oil level", "A light sensor", "A hand pump"], explanation: "It is the component that receives oil from the reservoir and determines when to allow it into the compressor." },
  { id:"nate_441", categoria:"NATE_INDUSTRIAL", pregunta:"Tocando las culatas (heads) de un compresor de 6 cilindros, notas que una está mucho más caliente que las otras dos. ¿Diagnóstico?", opciones:["Funcionamiento normal", "Válvulas de descarga en esa culata están dañadas o el descargador está fallando", "Esa culata no tiene aceite", "Falta gas"], respuesta_correcta:1, explicacion:"El gas se queda 're-comprimiendo' en el mismo cilindro, generando calor excesivo por fricción y falta de flujo." , question: "When touching the cylinder heads of a 6-cylinder compressor, you notice one head is much hotter than the other two. What is the diagnosis?", options: ["Normal operation", "The discharge valves on that head are damaged or the unloader is malfunctioning", "That head has no oil", "Low refrigerant charge"], explanation: "The gas is being 're-compressed' in the same cylinder, generating excessive heat from friction and lack of flow." },
  { id:"nate_442", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un sistema de CO2 tarda mucho más en presurizarse inicialmente que uno de R-404A?", opciones:["Porque el gas es lento", "Porque hay que cargar vapor muy lentamente hasta superar los 60 psig para evitar formar hielo seco dentro del sistema", "Porque el tanque es chico", "Porque las mangueras son delgadas"], respuesta_correcta:1, explicacion:"Si metes líquido en un sistema al vacío, el CO2 se vuelve sólido instantáneamente y tapa todo." , question: "Why does a CO2 system take much longer to initially pressurize than an R-404A system?", options: ["Because the gas is slow", "Because vapor must be charged very slowly until exceeding 60 psig to avoid forming dry ice inside the system", "Because the tank is small", "Because the hoses are thin"], explanation: "If you introduce liquid into a system under vacuum, the CO2 instantly solidifies and blocks everything." },
  { id:"nate_443", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué las vitrinas de carne fresca suelen tener un deshielo por aire (off-cycle) en lugar de resistencias?", opciones:["Para ahorrar luz", "Para evitar que el calor de las resistencias 'cocine' o reseque la capa superficial de la carne", "Porque la carne no se congela", "Porque el gas es mejor"], respuesta_correcta:1, explicacion:"El deshielo natural mantiene la humedad necesaria para que la carne se vea fresca y roja." , question: "Why do fresh meat display cases typically use off-cycle (air) defrost instead of electric resistance defrost?", options: ["To save electricity", "To prevent the heat from resistance elements from 'cooking' or drying out the surface layer of the meat", "Because the meat does not freeze", "Because hot gas is better"], explanation: "Natural defrost maintains the moisture necessary for the meat to look fresh and red." },
  { id:"nate_444", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Uneven Rack'?", opciones:["Un rack chueco", "Un sistema en paralelo con compresores de diferentes capacidades (ej. un 10HP, un 20HP y un 30HP) para un control de carga más flexible", "Un rack con un solo compresor", "Un rack de plástico"], respuesta_correcta:1, explicacion:"Permite 'escalones' de capacidad más precisos sin necesidad de VFD en todos los compresores." , question: "What is an Uneven Rack?", options: ["A crooked rack", "A parallel system with compressors of different capacities (e.g., 10HP, 20HP, and 30HP) for more flexible load control", "A rack with a single compressor", "A plastic rack"], explanation: "It allows more precise capacity 'steps' without needing a VFD on every compressor." },
  { id:"nate_445", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué controla la válvula de alta presión (HPV) en un sistema transcrítico?", opciones:["La temperatura del cuarto", "Mantiene la presión óptima en el Gas Cooler para maximizar el COP basado en la temperatura exterior", "El nivel de aceite", "La velocidad del ventilador"], respuesta_correcta:1, explicacion:"Es el corazón del sistema; ajusta la presión supercrítica para que el sistema rinda lo más posible." , question: "What does the High Pressure Valve (HPV) control in a transcritical system?", options: ["The room temperature", "It maintains the optimal pressure in the Gas Cooler to maximize COP based on the outdoor temperature", "The oil level", "The fan speed"], explanation: "It is the heart of the system; it adjusts the supercritical pressure so the system performs as efficiently as possible." },
  { id:"nate_446", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se está popularizando la soldadura por inducción en la fabricación de racks?", opciones:["Porque es más barata", "Proporciona calor uniforme, reduce el error humano y no requiere llama abierta (más seguro)", "Usa pegamento", "No necesita nitrógeno"], respuesta_correcta:1, explicacion:"Garantiza uniones perfectas en sistemas que operan a presiones críticas." , question: "Why is induction brazing becoming popular in rack manufacturing?", options: ["Because it is cheaper", "It provides uniform heat, reduces human error, and requires no open flame (safer)", "It uses adhesive", "It does not require nitrogen"], explanation: "It guarantees perfect joints in systems that operate at critical pressures." },
  { id:"nate_447", categoria:"NATE_INDUSTRIAL", pregunta:"Un compresor de rack intenta arrancar, zumba y dispara el breaker. Los otros compresores funcionan bien. Mides las bobinas y están balanceadas. ¿Qué revisas?", opciones:["Si el condensador está sucio", "Si hay líquido en el cárter o si el compresor está mecánicamente trabado", "El gas del sistema", "La luz del tablero"], respuesta_correcta:1, explicacion:"Si el motor está bien pero no puede girar, el problema es una traba mecánica o un 'slug' de líquido." , question: "A rack compressor tries to start, buzzes, and trips the breaker. The other compressors work fine. You measure the windings and they are balanced. What do you check?", options: ["If the condenser is dirty", "If there is liquid in the crankcase or if the compressor is mechanically seized", "The system refrigerant", "The panel indicator light"], explanation: "If the motor is electrically sound but cannot rotate, the issue is a mechanical lockup or a liquid slug." },
  { id:"nate_448", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo afecta el uso de 'Subenfriamiento de Líquido' (Liquid Subcooling) al tamaño del rack?", opciones:["Lo hace más grande", "Aumenta la capacidad neta de enfriamiento, permitiendo usar compresores ligeramente más pequeños para la misma carga", "No afecta", "Lo hace más ruidoso"], respuesta_correcta:1, explicacion:"Cada grado de subenfriamiento extra añade aproximadamente un 0.5% de capacidad al sistema sin gastar más energía." , question: "How does Liquid Subcooling affect the size of the rack?", options: ["It makes it larger", "It increases the net cooling capacity, allowing slightly smaller compressors to be used for the same load", "It has no effect", "It makes it noisier"], explanation: "Each additional degree of subcooling adds approximately 0.5% capacity to the system without consuming more energy." },
  { id:"nate_449", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de refrigeración por CO2, ¿qué es el 'Adiabatic Cooling' aplicado al Gas Cooler?", opciones:["Enfriar con hielo", "Usar paneles húmedos para enfriar el aire que entra al Gas Cooler, permitiendo que el CO2 se mantenga en modo subcrítico por más tiempo", "Enfriar el aceite con agua", "Apagar el sistema al mediodía"], respuesta_correcta:1, explicacion:"Es la técnica más usada en climas calientes para que el CO2 sea competitivo frente a refrigerantes sintéticos." , question: "In a CO2 refrigeration system, what is Adiabatic Cooling applied to the Gas Cooler?", options: ["Cooling with ice", "Using wetted media pads to cool the air entering the Gas Cooler, allowing the CO2 to stay in subcritical mode longer", "Cooling the oil with water", "Shutting down the system at noon"], explanation: "It is the most widely used technique in hot climates to make CO2 competitive against synthetic refrigerants." },
  { id:"nate_450", categoria:"NATE_INDUSTRIAL", pregunta:"Si un puente rectificador de onda completa en una tarjeta Inverter tiene un diodo abierto, ¿cuál será el síntoma principal en el Bus DC?", opciones:["El voltaje DC será 0V", "Voltaje DC inestable con mucho 'ripple' (rizado), causando errores de sobrecorriente o subvoltaje", "El compresor girará más rápido", "No afecta en nada"], respuesta_correcta:1, explicacion:"Al faltar un diodo, la rectificación es incompleta. Los capacitores no pueden mantener el voltaje estable bajo carga, y la electrónica detecta la inestabilidad como una falla de energía." , question: "If a full-wave bridge rectifier on an Inverter board has one open diode, what will be the main symptom on the DC Bus?", options: ["DC voltage will be 0V", "Unstable DC voltage with heavy ripple, causing overcurrent or undervoltage faults", "The compressor will run faster", "No effect whatsoever"], explanation: "With one diode missing, the rectification is incomplete. The capacitors cannot hold stable voltage under load, and the electronics detect the instability as a power fault." },
  { id:"nate_451", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja de usar un sensor de presión de 4-20 mA frente a uno de 0-5V en una planta industrial con cables largos?", opciones:["Es más barato", "La señal de corriente (mA) no sufre caídas de voltaje por la resistencia del cable y es inmune al ruido electromagnético", "Mide más presión", "Se conecta directo a 120V"], respuesta_correcta:1, explicacion:"En 4-20 mA, mientras el lazo esté cerrado, la corriente es la misma en todo el cable. En voltaje, la resistencia del cable largo 'roba' señal, falseando la lectura." , question: "What is the advantage of using a 4-20mA pressure sensor over a 0-5V sensor in an industrial plant with long cable runs?", options: ["It is cheaper", "The current signal (mA) does not suffer voltage drops from cable resistance and is immune to electromagnetic noise", "It measures higher pressure", "It connects directly to 120V"], explanation: "With 4-20mA, as long as the loop is closed, the current is the same throughout the entire cable. With voltage, cable resistance 'steals' signal, falsifying the reading." },
  { id:"nate_452", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué componente dentro del módulo IPM (Intelligent Power Module) actúa como el interruptor de alta velocidad para generar la onda del compresor?", opciones:["Un transformador", "Un relé de estado sólido", "Transistores IGBT (Insulated Gate Bipolar Transistor)", "Un condensador electrolítico"], respuesta_correcta:2, explicacion:"Los IGBTs combinan la velocidad de conmutación de un MOSFET con la capacidad de manejo de alta corriente de un transistor bipolar." , question: "What component inside the IPM (Intelligent Power Module) acts as the high-speed switch to generate the compressor drive waveform?", options: ["A transformer", "A solid-state relay", "IGBT (Insulated Gate Bipolar Transistor) transistors", "An electrolytic capacitor"], explanation: "IGBTs combine the switching speed of a MOSFET with the high-current handling capability of a bipolar transistor." },
  { id:"nate_453", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué sirve un optoacoplador en una tarjeta de control de un equipo Split?", opciones:["Para enfriar los chips", "Para aislar eléctricamente el circuito de alta potencia del microprocesador de baja potencia mediante luz", "Para medir la luminosidad del cuarto", "Para conectar el Wi-Fi"], respuesta_correcta:1, explicacion:"Protege al 'cerebro' (CPU) de picos de voltaje. Si hay un corto en el contactor, el optoacoplador se quema pero salva al microprocesador caro." , question: "What is the purpose of an optocoupler on a split system control board?", options: ["To cool the chips", "To electrically isolate the high-power circuit from the low-power microprocessor by means of light", "To measure room brightness", "To connect Wi-Fi"], explanation: "It protects the 'brain' (CPU) from voltage spikes. If there is a short at the contactor, the optocoupler burns out but saves the expensive microprocessor." },
  { id:"nate_454", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la 'Lógica Difusa' (Fuzzy Logic) en un termostato de alta gama?", opciones:["Que el termostato no sabe qué hacer", "Un algoritmo que aprende los hábitos del usuario y las características térmicas de la casa para anticipar el encendido", "Un tipo de pantalla borrosa", "Un error de programación"], respuesta_correcta:1, explicacion:"Va más allá del ON/OFF; imita el razonamiento humano para suavizar las rampas de aceleración y mejorar el confort." , question: "What is Fuzzy Logic in a high-end thermostat?", options: ["The thermostat does not know what to do", "An algorithm that learns the user's habits and the home's thermal characteristics to anticipate when to turn on", "A type of blurry display", "A programming error"], explanation: "It goes beyond ON/OFF; it mimics human reasoning to smooth acceleration ramps and improve comfort." },
  { id:"nate_455", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras un componente circular negro o azul cerca del fusible de entrada que estalló. ¿Qué es y por qué sucedió?", opciones:["Es un capacitor; falló por calor", "Es un Varistor (MOV); actuó ante un pico de voltaje (rayo o transitorio) para proteger la tarjeta", "Es un puente rectificador", "Es una resistencia quemada"], respuesta_correcta:1, explicacion:"El varistor entra en corto circuito a propósito cuando el voltaje sube demasiado, forzando al fusible a romperse y cortando la energía dañina." , question: "You find a circular black or blue component near the input fuse that has burst. What is it and why did it happen?", options: ["It is a capacitor; it failed due to heat", "It is a Varistor (MOV); it activated in response to a voltage spike (lightning or transient) to protect the board", "It is a bridge rectifier", "It is a burned resistor"], explanation: "The varistor intentionally goes into short circuit when the voltage rises too high, forcing the fuse to blow and cutting off the damaging energy." },
  { id:"nate_456", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se usa el protocolo RS-485 (dos cables trenzados) para la comunicación en sistemas VRF?", opciones:["Porque los cables son más baratos", "Por su alta inmunidad al ruido eléctrico en distancias de hasta 1000 metros", "Porque no necesita corriente", "Para que el internet sea más rápido"], respuesta_correcta:1, explicacion:"Al ser una señal diferencial, el ruido que afecta a un cable también afecta al otro y se cancela en el receptor." , question: "Why is the RS-485 protocol (two twisted wires) used for communication in VRF systems?", options: ["Because the cables are cheaper", "For its high immunity to electrical noise over distances of up to 1,000 meters", "Because it does not need current", "To make the internet faster"], explanation: "As a differential signal, noise that affects one wire also affects the other and is canceled out at the receiver." },
  { id:"nate_457", categoria:"NATE_INDUSTRIAL", pregunta:"Al revisar la señal de comunicación entre la unidad interior y exterior, ¿qué herramienta te permite ver los paquetes de datos reales?", opciones:["Un multímetro en escala de Hz", "Un Osciloscopio", "Un manómetro digital", "Un termómetro láser"], respuesta_correcta:1, explicacion:"Solo el osciloscopio tiene la velocidad para graficar los pulsos digitales y ver si la señal está 'limpia' o deformada por interferencia." , question: "When checking the communication signal between the indoor and outdoor units, what tool allows you to see the actual data packets?", options: ["A multimeter in Hz mode", "An Oscilloscope", "A digital manifold gauge", "A laser thermometer"], explanation: "Only an oscilloscope has the speed to graph digital pulses and see whether the signal is clean or distorted by interference." },
  { id:"nate_458", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del transformador 'Chopper' en una fuente conmutada de una tarjeta electrónica de HVAC?", opciones:["Reducir el voltaje de 120V a 24V de forma tradicional", "Transferir energía a alta frecuencia (kHz) para convertir el alto voltaje DC en voltajes bajos regulados (12V, 5V)", "Arrancar el motor del soplador", "Filtrar el aceite"], respuesta_correcta:1, explicacion:"Las fuentes SMPS son mucho más pequeñas y eficientes que las fuentes con transformadores pesados de hierro." , question: "What is the function of the Chopper transformer in a switched-mode power supply on an HVAC control board?", options: ["To reduce 120V to 24V in a traditional way", "To transfer energy at high frequency (kHz) to convert high DC voltage into regulated low voltages (12V, 5V)", "To start the blower motor", "To filter oil"], explanation: "SMPS power supplies are much smaller and more efficient than heavy iron-core transformer-based supplies." },
  { id:"nate_459", categoria:"NATE_INDUSTRIAL", pregunta:"Un motor de soplador DC tiene 3 cables de potencia y 3 cables delgados de señal. ¿Para qué sirven los cables de señal?", opciones:["Para la luz", "Son sensores de efecto Hall que informan a la tarjeta la posición exacta y velocidad del rotor", "Para el termostato", "No sirven para nada"], respuesta_correcta:1, explicacion:"La tarjeta necesita saber dónde está el imán del rotor para saber qué bobina energizar a continuación." , question: "A DC blower motor has 3 power wires and 3 thin signal wires. What are the signal wires for?", options: ["For lighting", "They are Hall effect sensors that report the exact rotor position and speed to the control board", "For the thermostat", "They serve no purpose"], explanation: "The board needs to know where the rotor magnet is in order to determine which coil to energize next." },
  { id:"nate_460", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué es peligroso tocar los chips de una tarjeta electrónica sin una pulsera antiestática o sin 'aterrizarse' primero?", opciones:["Porque te puedes electrocutar", "Porque la Descarga Electrostática (ESD) de tu cuerpo puede destruir los circuitos microscópicos de los chips", "Porque se ensucian", "Porque la tarjeta se calienta"], respuesta_correcta:1, explicacion:"Una chispa estática que tú ni sientes puede tener 3000V, lo cual fulmina un procesador de 5V instantáneamente." , question: "Why is it dangerous to touch the chips on a control board without an anti-static wrist strap or grounding yourself first?", options: ["Because you could get electrocuted", "Because Electrostatic Discharge (ESD) from your body can destroy the microscopic circuits in the chips", "Because they get dirty", "Because the board heats up"], explanation: "A static spark you cannot even feel can carry 3,000V, which instantly kills a 5V processor." },
  { id:"nate_461", categoria:"NATE_INDUSTRIAL", pregunta:"Si un microprocesador tiene un pin de 'Reset' pegado a nivel bajo (0V), ¿qué hará la unidad de HVAC?", opciones:["Funcionará a media capacidad", "La tarjeta estará 'muerta' o reiniciándose constantemente (no hará nada)", "Enfriará al máximo", "Dará un error de comunicación"], respuesta_correcta:1, explicacion:"El Reset mantiene al procesador en 'pausa'. Mientras no suba a 5V, el programa no arranca." , question: "If a microprocessor has its Reset pin stuck at logic low (0V), what will the HVAC unit do?", options: ["It will run at half capacity", "The board will be 'dead' or constantly rebooting (it will do nothing)", "It will cool at maximum output", "It will throw a communication error"], explanation: "The Reset holds the processor in 'pause.' Until it goes high to 5V, the program will not execute." },
  { id:"nate_462", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los equipos Inverter a veces disparan los interruptores diferenciales (RCD/GFCI) estándar?", opciones:["Porque están en corto", "Debido a las corrientes de fuga naturales de alta frecuencia generadas por los filtros EMI y la conmutación", "Porque el compresor es muy potente", "Porque el cable es delgado"], respuesta_correcta:1, explicacion:"Los Inverters requieren GFCIs de 'Clase B' o específicos para electrónica, que no se confundan con el ruido de alta frecuencia." , question: "Why do Inverter units sometimes trip standard RCD/GFCI breakers?", options: ["Because they are shorted", "Due to the natural high-frequency leakage currents generated by EMI filters and the switching process", "Because the compressor is too powerful", "Because the wire is too thin"], explanation: "Inverters require Class B GFCIs or electronics-rated types that do not false-trip on high-frequency noise." },
  { id:"nate_463", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué componente suele usar la tarjeta para controlar la velocidad de un motor de ventilador AC pequeño de forma gradual?", opciones:["Un relé mecánico", "Un Triac (operando por control de fase)", "Un contactor", "Un fusible"], respuesta_correcta:1, explicacion:"El Triac corta la onda de AC para entregar solo una parte de la energía al motor, regulando su velocidad electrónicamente." , question: "What component does the board typically use to gradually control the speed of a small AC fan motor?", options: ["A mechanical relay", "A Triac (operating via phase control)", "A contactor", "A fuse"], explanation: "The Triac chops the AC waveform to deliver only a portion of the energy to the motor, electronically regulating its speed." },
  { id:"nate_464", categoria:"NATE_INDUSTRIAL", pregunta:"Un equipo funciona bien, pero si golpeas suavemente la unidad interior, se apaga o falla. ¿Qué buscas en la tarjeta?", opciones:["Un sensor roto", "Soldaduras frías (agrietadas) en los terminales de relés o conectores principales", "Un chip quemado", "Falta de gas"], respuesta_correcta:1, explicacion:"Con el tiempo y la vibración, la soldadura de estaño se quiebra, creando un contacto intermitente que falla con el movimiento." , question: "A unit works fine, but if you gently tap the indoor unit, it shuts off or faults. What do you look for on the board?", options: ["A broken sensor", "Cold (cracked) solder joints on relay terminals or main connectors", "A burned chip", "Low refrigerant charge"], explanation: "Over time and vibration, the tin solder cracks, creating an intermittent contact that fails with movement." },
  { id:"nate_465", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el voltaje típico de operación del módulo Wi-Fi dentro de una tarjeta de Mini-Split?", opciones:["120V AC", "24V AC", "3.3V o 5V DC", "12V DC"], respuesta_correcta:2, explicacion:"Casi toda la lógica digital de comunicación opera a voltajes muy bajos y regulados." , question: "What is the typical operating voltage of the Wi-Fi module inside a Mini-Split control board?", options: ["120V AC", "24V AC", "3.3V or 5V DC", "12V DC"], explanation: "Nearly all digital communication logic operates on very low, regulated voltages." },
  { id:"nate_466", categoria:"NATE_INDUSTRIAL", pregunta:"El compresor sigue encendido aunque apagues el termostato y desconectes el cable 'Y'. ¿Qué componente de la tarjeta falló?", opciones:["El microprocesador", "El relé de potencia de la tarjeta (contactos soldados/pegados)", "El sensor de temperatura", "El fusible"], respuesta_correcta:1, explicacion:"Si los contactos internos del relé se fundieron y se pegaron, la energía pasará siempre, sin importar la orden del control." , question: "The compressor stays on even after you turn off the thermostat and disconnect the 'Y' wire. What board component has failed?", options: ["The microprocessor", "The board's power relay (contacts welded/fused shut)", "The temperature sensor", "The fuse"], explanation: "If the relay's internal contacts have fused together, power will pass through regardless of the control signal." },
  { id:"nate_467", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un termistor PTC en el circuito de arranque de una tarjeta?", opciones:["Un sensor de frío", "Una resistencia que aumenta su valor con el calor, usada para limitar la corriente de irrupción (Inrush current)", "Un tipo de relé", "Un fusible que no se rompe"], respuesta_correcta:1, explicacion:"Protege los componentes de la tarjeta al arrancar; cuando se calienta, limita el paso de corriente excesiva." , question: "What is a PTC thermistor in a control board's startup circuit?", options: ["A cold sensor", "A resistor that increases its resistance with heat, used to limit inrush current", "A type of relay", "A fuse that does not break"], explanation: "It protects the board components during power-up; as it heats up, it limits excessive current flow." },
  { id:"nate_468", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se pueden usar diodos rectificadores comunes (como el 1N4007) en la parte de alta frecuencia de un Inverter?", opciones:["Porque son muy chicos", "Porque son demasiado lentos para conmutar a las frecuencias de kHz requeridas, causando sobrecalentamiento", "Porque el color es distinto", "Porque no aguantan el voltaje"], respuesta_correcta:1, explicacion:"Se requieren diodos de 'Recuperación Rápida' (Ultra Fast) que puedan encenderse y apagarse miles de veces por segundo." , question: "Why can common rectifier diodes (such as the 1N4007) not be used in the high-frequency section of an Inverter?", options: ["Because they are too small", "Because they are too slow to switch at the required kHz frequencies, causing overheating", "Because they are the wrong color", "Because they cannot handle the voltage"], explanation: "Ultra-fast recovery diodes that can turn on and off thousands of times per second are required." },
  { id:"nate_469", categoria:"NATE_INDUSTRIAL", pregunta:"La tarjeta muestra un error de 'EEPROM Failure'. ¿Qué significa?", opciones:["Que el compresor está mal", "Que la memoria donde se guardan los parámetros de fábrica y configuración está corrupta o dañada", "Que le falta gas", "Que el Wi-Fi no conecta"], respuesta_correcta:1, explicacion:"La EEPROM es donde la tarjeta 'recuerda' quién es y cómo operar. Si falla, el procesador no sabe qué hacer." , question: "The board shows an 'EEPROM Failure' error. What does this mean?", options: ["The compressor is bad", "The memory chip where factory parameters and configuration are stored is corrupted or damaged", "Low refrigerant charge", "The Wi-Fi will not connect"], explanation: "The EEPROM is where the board 'remembers' its identity and how to operate. If it fails, the processor does not know what to do." },
  { id:"nate_470", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significan las siglas PWM en el control de motores y solenoides?", opciones:["Power Watt Management", "Pulse Width Modulation (Modulación por Ancho de Pulso)", "Pressure Water Meter", "Pure Wave Modulation"], respuesta_correcta:1, explicacion:"Es la técnica de apagar y encender la energía muy rápido para variar la potencia entregada a un componente." , question: "What does the acronym PWM stand for in motor and solenoid control?", options: ["Power Watt Management", "Pulse Width Modulation", "Pressure Water Meter", "Pure Wave Modulation"], explanation: "It is the technique of rapidly switching power on and off to vary the amount of energy delivered to a component." },
  { id:"nate_471", categoria:"NATE_INDUSTRIAL", pregunta:"Ves un pequeño rastro de líquido o 'aceite' debajo de un capacitor electrolítico en la tarjeta. ¿Qué haces?", opciones:["Limpiarlo y dejarlo", "Reemplazar el capacitor inmediatamente; el electrolito se salió y el componente fallará", "Ponerle pegamento", "Nada, es normal"], respuesta_correcta:1, explicacion:"La fuga de electrolito es el fin de la vida útil del capacitor y puede corroer las pistas de cobre de la tarjeta." , question: "You see a small trail of liquid or 'oil' underneath an electrolytic capacitor on the board. What do you do?", options: ["Clean it and leave it", "Replace the capacitor immediately; the electrolyte has leaked and the component will fail", "Apply adhesive", "Nothing, it is normal"], explanation: "Electrolyte leakage signals the end of the capacitor's service life and can corrode the copper traces on the board." },
  { id:"nate_472", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema con comunicación digital, ¿qué sucede si el cable de comunicación se pasa junto a cables de alta potencia sin blindaje?", opciones:["Los cables se calientan", "La inducción electromagnética genera 'ruido' que corrompe los datos, causando errores intermitentes", "El voltaje sube", "Nada, son cables distintos"], respuesta_correcta:1, explicacion:"Los cables de datos deben estar separados o usar cable blindado (shielded) para evitar interferencias." , question: "In a system with digital communication, what happens if the communication cable is run alongside high-power cables without shielding?", options: ["The cables overheat", "Electromagnetic induction creates noise that corrupts data, causing intermittent errors", "The voltage increases", "Nothing, they are separate cables"], explanation: "Data cables must be separated or use shielded cable to avoid interference." },
  { id:"nate_473", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la 'Histéresis' en la lógica de un termostato?", opciones:["Un error de lectura", "El diferencial de temperatura (margen) entre el encendido y el apagado para evitar ciclos cortos", "La velocidad del aire", "El tiempo de garantía"], respuesta_correcta:1, explicacion:"Si el setpoint es 72°F, la histéresis hace que encienda a 73°F y apague a 71°F para que el equipo no prenda y apague cada segundo." , question: "What is Hysteresis in thermostat logic?", options: ["A reading error", "The temperature differential (deadband) between the turn-on and turn-off points to prevent short cycling", "Airflow velocity", "The warranty period"], explanation: "If the setpoint is 72°F, hysteresis causes the system to turn on at 73°F and off at 71°F so the equipment does not cycle every second." },
  { id:"nate_474", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo pruebas un puente rectificador con un multímetro en función de diodo?", opciones:["Midiendo resistencia", "Verificando la caída de voltaje (aprox 0.5V) entre las terminales AC y DC en el sentido correcto", "Midiendo continuidad", "Viendo si sale humo"], respuesta_correcta:1, explicacion:"Debes probar los 4 diodos internos: deben conducir en un sentido y bloquear en el otro." , question: "How do you test a bridge rectifier with a multimeter in diode mode?", options: ["By measuring resistance", "By verifying the voltage drop (approximately 0.5V) between the AC and DC terminals in the correct direction", "By measuring continuity", "By checking for smoke"], explanation: "You must test all 4 internal diodes: each should conduct in one direction and block in the other." },
  { id:"nate_475", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué sirven los anillos de ferrita negro que a veces abrazan los cables de comunicación?", opciones:["Para sostener los cables", "Para suprimir ruidos de alta frecuencia e interferencia electromagnética (EMI)", "Para pesar el cable", "Para decorar"], respuesta_correcta:1, explicacion:"Actúan como un filtro que 'limpia' la señal de comunicación de ruidos externos." , question: "What are the black ferrite rings that sometimes wrap around communication cables used for?", options: ["To hold the cables", "To suppress high-frequency noise and electromagnetic interference (EMI)", "To add weight to the cable", "For decoration"], explanation: "They act as a filter that 'cleans' the communication signal of external noise." },
  { id:"nate_476", categoria:"NATE_INDUSTRIAL", pregunta:"Ves un pequeño transformador toroidal (donde pasa un cable por el centro) en la tarjeta exterior. ¿Qué mide?", opciones:["El voltaje de entrada", "La corriente (Amps) que consume el compresor para protección y control de carga", "La temperatura", "La velocidad del viento"], respuesta_correcta:1, explicacion:"Permite que la tarjeta sepa en tiempo real cuánto esfuerzo está haciendo el compresor." , question: "You see a small toroidal transformer (where a wire passes through the center) on the outdoor unit board. What does it measure?", options: ["The input voltage", "The current (Amps) consumed by the compressor for protection and load management", "The temperature", "Wind speed"], explanation: "It allows the board to know in real time how much effort the compressor is exerting." },
  { id:"nate_477", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del 'Oscilador de Cristal' junto al microprocesador?", opciones:["Generar luz", "Proporcionar la señal de 'reloj' (frecuencia estable) para que el procesador ejecute las instrucciones", "Filtrar el voltaje", "Medir la humedad"], respuesta_correcta:1, explicacion:"Es el metrónomo de la tarjeta. Sin él, el microprocesador no puede procesar información." , question: "What is the function of the Crystal Oscillator next to the microprocessor?", options: ["To generate light", "To provide a stable clock signal (frequency) so the processor can execute instructions", "To filter voltage", "To measure humidity"], explanation: "It is the board's metronome. Without it, the microprocessor cannot process information." },
  { id:"nate_478", categoria:"NATE_INDUSTRIAL", pregunta:"Un Inverter marca 'DC Link Voltage High' en un día de mucho viento con el equipo apagado. ¿Qué pasó?", opciones:["Cayó un rayo", "El viento hizo girar el ventilador exterior, el motor actuó como generador y cargó los capacitores de la tarjeta", "El gas se expandió", "El termostato falló"], respuesta_correcta:1, explicacion:"Es un fenómeno real en motores DC/ECM: al girar por el viento, mandan voltaje de regreso a la tarjeta." , question: "An Inverter shows 'DC Link Voltage High' on a very windy day with the unit off. What happened?", options: ["Lightning struck", "The wind spun the outdoor fan, the motor acted as a generator, and charged the board capacitors", "The refrigerant expanded", "The thermostat failed"], explanation: "This is a real phenomenon with DC/ECM motors: when spun by the wind, they send voltage back to the board." },
  { id:"nate_479", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se usa un diodo Zener en un circuito de control?", opciones:["Para rectificar potencia", "Como regulador de voltaje fijo (referencia de voltaje)", "Como interruptor", "Para proteger contra calor"], respuesta_correcta:1, explicacion:"Mantiene un voltaje constante (ej. 5.1V) para que los sensores tengan una base de medición estable." , question: "What is a Zener diode used for in a control circuit?", options: ["To rectify power", "As a fixed voltage regulator (voltage reference)", "As a switch", "To protect against heat"], explanation: "It maintains a constant voltage (e.g., 5.1V) so that sensors have a stable measurement baseline." },
  { id:"nate_480", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un equipo no arranca inmediatamente después de que lo apagas y lo vuelves a encender?", opciones:["Porque está cansado", "Por el temporizador de retardo (3-5 min) para permitir que las presiones se igualen y proteger el compresor", "Porque el control es lento", "Porque no tiene gas"], respuesta_correcta:1, explicacion:"Evita arranques contra alta presión que podrían quemar el motor o dañar el capacitor." , question: "Why does a unit not restart immediately after being turned off and back on?", options: ["Because it is tired", "Due to the time-delay timer (3-5 minutes) that allows pressures to equalize and protects the compressor", "Because the control is slow", "Because it has no refrigerant"], explanation: "It prevents starting against high head pressure, which could burn the motor or damage the capacitor." },
  { id:"nate_481", categoria:"NATE_INDUSTRIAL", pregunta:"La unidad interior hace un zumbido intermitente y el display parpadea. Los voltajes de 24V están bien. ¿Qué componente de la fuente DC revisarías?", opciones:["El fusible", "Los capacitores de filtrado de la fuente (pueden tener alta ESR/resistencia interna)", "El motor", "El gas"], respuesta_correcta:1, explicacion:"Si los capacitores se secan, el voltaje DC tiene 'ruido' y la lógica digital se vuelve loca." , question: "The indoor unit makes an intermittent buzzing noise and the display flickers. The 24V voltages are fine. What DC power supply component would you check?", options: ["The fuse", "The power supply filter capacitors (they may have high ESR/internal resistance)", "The motor", "The refrigerant"], explanation: "If the capacitors dry out, the DC voltage has 'noise' and the digital logic behaves erratically." },
  { id:"nate_482", categoria:"NATE_INDUSTRIAL", pregunta:"En una red Modbus, ¿qué es el 'Slave ID'?", opciones:["La marca del equipo", "La dirección numérica única que identifica a cada equipo en la red", "La clave del Wi-Fi", "El modelo del compresor"], respuesta_correcta:1, explicacion:"Sin una dirección única, el controlador central no sabría a quién le está enviando las órdenes." , question: "On a Modbus network, what is the Slave ID?", options: ["The equipment brand", "The unique numerical address that identifies each device on the network", "The Wi-Fi password", "The compressor model number"], explanation: "Without a unique address, the central controller would not know which device it is sending commands to." },
  { id:"nate_483", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja de un SSR (Solid State Relay) sobre un relé mecánico?", opciones:["Es más grande", "No tiene partes móviles, no genera chispas y puede conmutar millones de veces sin desgastarse", "Es más barato", "Se puede reparar con soldadura"], respuesta_correcta:1, explicacion:"Ideal para controles que requieren encendidos y apagados muy frecuentes (como resistencias de precisión)." , question: "What is the advantage of an SSR (Solid State Relay) over a mechanical relay?", options: ["It is larger", "It has no moving parts, generates no sparks, and can switch millions of times without wearing out", "It is cheaper", "It can be repaired with solder"], explanation: "It is ideal for controls requiring very frequent on/off switching (such as precision resistance heaters)." },
  { id:"nate_484", categoria:"NATE_INDUSTRIAL", pregunta:"Al medir con multímetro las terminales U, V, W del compresor hacia el Bus (+) y (-) en la tarjeta, obtienes 0.5V en todas en una dirección. ¿Qué indica?", opciones:["Que el IPM está quemado", "Que los diodos de protección internos del IPM están aparentemente bien (Normal)", "Que hay un corto total", "Que la tarjeta no tiene energía"], respuesta_correcta:1, explicacion:"Es la prueba estándar para descartar que un transistor del IPM se haya quedado 'pegado' o en corto." , question: "When measuring with a multimeter the U, V, W compressor terminals to the Bus (+) and (-) on the board, you get 0.5V on all in one direction. What does this indicate?", options: ["The IPM is burned", "The internal protection diodes of the IPM appear to be intact (Normal)", "There is a total short circuit", "The board has no power"], explanation: "This is the standard test to rule out that an IPM transistor has become stuck or shorted." },
  { id:"nate_485", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué banda de frecuencia suelen usar los termostatos inalámbricos no-WiFi para comunicarse con su base?", opciones:["2.4 GHz", "900 MHz o 433 MHz", "FM Radio", "Rayos X"], respuesta_correcta:1, explicacion:"Estas frecuencias bajas atraviesan mejor las paredes y tienen mayor alcance dentro de una casa que el Wi-Fi estándar." , question: "What frequency band do non-WiFi wireless thermostats typically use to communicate with their base unit?", options: ["2.4 GHz", "900 MHz or 433 MHz", "FM Radio", "X-rays"], explanation: "These lower frequencies penetrate walls better and have greater range inside a home than standard Wi-Fi." },
  { id:"nate_486", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo sabe el microprocesador la temperatura si el termistor solo cambia su resistencia?", opciones:["Midiendo Ohms directamente", "A través de un circuito divisor de voltaje que convierte el cambio de resistencia en un cambio de voltaje (0-5V) legible por el ADC", "Por magnetismo", "Adivinando"], respuesta_correcta:1, explicacion:"El cerebro de la tarjeta solo entiende de voltajes; necesita que los Ohms se traduzcan a Volts." , question: "How does the microprocessor know the temperature if the thermistor only changes its resistance?", options: ["By measuring Ohms directly", "Through a voltage divider circuit that converts the resistance change into a voltage change (0-5V) readable by the ADC", "By magnetism", "By guessing"], explanation: "The board's brain only understands voltages; it needs the Ohms to be translated into Volts." },
  { id:"nate_487", categoria:"NATE_INDUSTRIAL", pregunta:"Un Mini-Split no responde al control remoto ni al botón auxiliar, pero tiene luces encendidas. Desconectas el sensor de temperatura y el equipo empieza a responder. ¿Por qué?", opciones:["El sensor estaba sucio", "El sensor estaba en corto y 'tumbaba' el voltaje de 5V de toda la sección lógica de la tarjeta", "Era coincidencia", "El gas fluyó"], respuesta_correcta:1, explicacion:"Un componente en corto puede saturar la fuente de alimentación digital, dejando al procesador sin energía para pensar." , question: "A Mini-Split does not respond to the remote control or the auxiliary button, but lights are on. You disconnect the temperature sensor and the unit starts responding. Why?", options: ["The sensor was dirty", "The sensor was shorted and was pulling down the 5V supply of the entire logic section of the board", "It was a coincidence", "The refrigerant flowed"], explanation: "A shorted component can saturate the digital power supply, leaving the processor without enough energy to function." },
  { id:"nate_488", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el circuito PFC (Power Factor Correction) en un equipo Inverter de gama alta?", opciones:["Un ventilador extra", "Un circuito que asegura que la corriente y el voltaje estén en fase, maximizando la eficiencia y reduciendo armónicos", "Un protector contra rayos", "Un medidor de gas"], respuesta_correcta:1, explicacion:"Ayuda a que el equipo aproveche casi el 100% de la energía que toma de la red eléctrica." , question: "What is the PFC (Power Factor Correction) circuit in a high-end Inverter unit?", options: ["An extra fan", "A circuit that ensures the current and voltage are in phase, maximizing efficiency and reducing harmonics", "A surge protector", "A gas meter"], explanation: "It helps the equipment utilize nearly 100% of the energy it draws from the electrical grid." },
  { id:"nate_489", categoria:"NATE_INDUSTRIAL", pregunta:"Mides continuidad en una bobina (inductor) grande de la tarjeta y marca 0.2 Ohms. ¿Cuál es su estado?", opciones:["Está en corto", "Está bien (los inductores tienen una resistencia óhmica muy baja)", "Está abierta", "Debe medir 100 Ohms"], respuesta_correcta:1, explicacion:"Un inductor es básicamente un cable enrollado; su función es magnética, no resistiva." , question: "You measure continuity on a large inductor (coil) on the board and it reads 0.2 Ohms. What is its condition?", options: ["It is shorted", "It is good (inductors have a very low DC resistance)", "It is open", "It should read 100 Ohms"], explanation: "An inductor is essentially a wound wire; its function is magnetic, not resistive." },
  { id:"nate_490", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué parte del control PID evita que la temperatura 'oscile' demasiado alrededor del setpoint?", opciones:["La P (Proporcional)", "La D (Derivativa), que reacciona a la velocidad del cambio", "La I (Integral)", "El ventilador"], respuesta_correcta:1, explicacion:"La parte derivativa actúa como un freno para que el sistema no se pase de largo (overshoot) al llegar a la meta." , question: "Which part of PID control prevents the temperature from oscillating too much around the setpoint?", options: ["The P (Proportional) component", "The D (Derivative) component, which reacts to the rate of change", "The I (Integral) component", "The fan"], explanation: "The derivative component acts as a brake to prevent the system from overshooting its target." },
  { id:"nate_491", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo puedes saber si un control remoto está enviando señal infrarroja si no tienes herramientas?", opciones:["Escuchando el sonido", "Viendo el emisor a través de la cámara de tu celular (se verá una luz parpadeante púrpura)", "Tocando el foco", "Oliendo el control"], respuesta_correcta:1, explicacion:"Los sensores de las cámaras digitales pueden captar el espectro infrarrojo que el ojo humano no ve." , question: "How can you tell if a remote control is sending an infrared signal without any tools?", options: ["By listening for a sound", "By viewing the emitter through your phone's camera (you will see a flickering purple light)", "By touching the LED", "By smelling the remote"], explanation: "Digital camera sensors can pick up the infrared spectrum that the human eye cannot see." },
  { id:"nate_492", categoria:"NATE_INDUSTRIAL", pregunta:"Ves un pequeño cilindro de vidrio con dos láminas metálicas adentro en una tarjeta de flujo. ¿Qué es?", opciones:["Un fusible", "Un Relé Reed que se activa con la presencia de un imán (usado en sensores de flujo de agua)", "Una luz piloto", "Una resistencia"], respuesta_correcta:1, explicacion:"Es un interruptor magnético muy confiable para detectar movimiento sin contacto físico." , question: "You see a small glass cylinder with two metal strips inside on a flow sensor board. What is it?", options: ["A fuse", "A Reed Relay that is activated by the presence of a magnet (used in water flow sensors)", "A pilot light", "A resistor"], explanation: "It is a very reliable magnetic switch for detecting motion without physical contact." },
  { id:"nate_493", categoria:"NATE_INDUSTRIAL", pregunta:"En un bus Modbus, ¿qué es la resistencia de terminación de 120 Ohms?", opciones:["Una resistencia para calentar", "Una resistencia necesaria en el último equipo de la red para evitar el 'eco' (reflexión) de la señal", "Para limitar el amperaje", "Para proteger contra cortos"], respuesta_correcta:1, explicacion:"Sin ella, los datos rebotan al final del cable y chocan con los nuevos datos, causando errores de comunicación." , question: "On a Modbus bus, what is the 120-Ohm termination resistor?", options: ["A heating resistor", "A resistor needed at the last device on the network to prevent signal echo (reflection)", "A current-limiting resistor", "A short-circuit protector"], explanation: "Without it, data bounces back at the end of the cable and collides with new data, causing communication errors." },
  { id:"nate_494", categoria:"NATE_INDUSTRIAL", pregunta:"La tarjeta no enciende. Mides el Bus DC y tiene 320V, pero en la salida del regulador de 5V mides 0V. ¿Qué chip falló?", opciones:["El microprocesador", "El IC Oscilador de la fuente conmutada (ej. TNY266 o Viper22A)", "El puente rectificador", "El sensor de ambiente"], respuesta_correcta:1, explicacion:"Es el componente que 'pica' el voltaje para que el transformador chopper funcione. Es la falla número 1 en tarjetas que no prenden." , question: "The board will not power on. You measure 320V on the DC Bus, but the 5V regulator output reads 0V. What chip has failed?", options: ["The microprocessor", "The switching power supply oscillator IC (e.g., TNY266 or Viper22A)", "The bridge rectifier", "The room temperature sensor"], explanation: "It is the component that 'chops' the voltage for the chopper transformer to work. It is the number one failure in boards that will not turn on." },
  { id:"nate_495", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede si aumentas demasiado la frecuencia de portadora (Carrier Frequency) en un Inverter?", opciones:["El motor hace menos ruido (silencioso) pero el IPM se calienta mucho más", "El motor se quema", "El aire sale más frío", "Ahorra más luz"], respuesta_correcta:0, explicacion:"A mayor frecuencia, hay más conmutaciones por segundo, lo que genera más calor por pérdidas en los transistores." , question: "What happens if you increase the Carrier Frequency on an Inverter too much?", options: ["The motor runs quieter but the IPM heats up significantly more", "The motor burns out", "The air comes out colder", "It saves more energy"], explanation: "A higher frequency means more switching events per second, which generates more heat from losses in the transistors." },
  { id:"nate_496", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo mide la humedad un sensor electrónico capacitivo?", opciones:["Pesando el agua", "Midiendo el cambio en la capacitancia de una película polimérica al absorber moléculas de vapor de agua", "Por la temperatura", "Viendo el color del aire"], respuesta_correcta:1, explicacion:"El agua cambia las propiedades eléctricas del material del sensor, y la tarjeta traduce eso a porcentaje de RH." , question: "How does an electronic capacitive humidity sensor measure humidity?", options: ["By weighing the water", "By measuring the change in capacitance of a polymer film as it absorbs water vapor molecules", "By temperature", "By observing the color of the air"], explanation: "Water changes the electrical properties of the sensor material, and the board translates that into a percentage of RH." },
  { id:"nate_497", categoria:"NATE_INDUSTRIAL", pregunta:"El display de un equipo muestra números incompletos o parpadea de forma errática. Mides 5V pero tienen mucho ruido AC. ¿Causa?", opciones:["Display dañado", "Capacitor de filtrado de la línea de 5V seco o dañado", "Mucho gas", "Control remoto sin pilas"], respuesta_correcta:1, explicacion:"El voltaje 'sucio' hace que la lógica del display falle. Un capacitor nuevo de 10 centavos suele arreglar tarjetas de 200 dólares." , question: "A unit's display shows incomplete numbers or flickers erratically. You measure 5V but there is significant AC noise. What is the cause?", options: ["Damaged display", "Dried out or damaged filter capacitor on the 5V rail", "Too much refrigerant", "Dead remote batteries"], explanation: "Noisy voltage causes the display logic to malfunction. A new capacitor worth a few cents often fixes boards costing hundreds of dollars." },
  { id:"nate_498", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del disco negro marcado 'NTC' en serie con la entrada de AC de la tarjeta?", opciones:["Medir la temperatura del cuarto", "Limitar el chispazo inicial (inrush) al cargar los capacitores grandes al encender", "Proteger contra rayos", "Filtrar el ruido"], respuesta_correcta:1, explicacion:"Empieza con mucha resistencia cuando está frío y baja al calentarse, permitiendo un arranque suave de la electrónica." , question: "What is the function of the black disc marked 'NTC' wired in series with the board's AC input?", options: ["To measure the room temperature", "To limit the initial inrush spike when the large capacitors charge at power-on", "To protect against lightning", "To filter noise"], explanation: "It starts with high resistance when cold and decreases as it warms up, allowing a soft start for the electronics." },
  { id:"nate_499", categoria:"NATE_INDUSTRIAL", pregunta:"Un microprocesador de una tarjeta de alta tecnología tiene un pin marcado como 'Watchdog'. ¿Para qué sirve?", opciones:["Para vigilar que no roben el equipo", "Es un temporizador interno que reinicia el procesador si el programa se queda 'congelado' o trabado", "Para medir el tiempo de uso", "Para conectar una alarma"], respuesta_correcta:1, explicacion:"Es el 'perro guardián'. Si el software falla, el Watchdog muerde el reset para que el equipo vuelva a operar solo." , question: "A microprocessor on a high-tech control board has a pin labeled 'Watchdog.' What is its purpose?", options: ["To monitor for theft", "It is an internal timer that resets the processor if the program freezes or hangs", "To track usage time", "To connect an alarm"], explanation: "It is the 'guard dog.' If the software crashes, the Watchdog triggers a reset so the unit can resume operation on its own." },
  { id:"nate_500", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un congelador de ultra-baja temperatura (-80°C) utiliza dos sistemas de refrigeración independientes (Cascada)?", opciones:["Para tener un respaldo si uno falla", "Porque un solo compresor no puede manejar la relación de compresión necesaria para alcanzar esas temperaturas", "Para gastar menos luz", "Porque usa dos tipos de aceite"], respuesta_correcta:1, explicacion:"El sistema 'alto' enfría el condensador del sistema 'bajo'. Esto permite alcanzar temperaturas extremas dividiendo el trabajo de compresión en dos etapas con diferentes refrigerantes." , question: "Why does an ultra-low temperature freezer (-80°C) use two independent refrigeration systems (Cascade)?", options: ["To have a backup if one fails", "Because a single compressor cannot handle the compression ratio needed to reach those temperatures", "To use less electricity", "Because it uses two types of oil"], explanation: "The 'high' stage cools the condenser of the 'low' stage. This allows reaching extreme temperatures by dividing the compression work into two stages with different refrigerants." },
  { id:"nate_501", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la fuente de energía principal en un sistema de refrigeración por absorción (como los usados en hoteles o casas rodantes)?", opciones:["Un compresor inverter", "Calor (gas propano, vapor o una resistencia eléctrica)", "Magnetismo", "Energía eólica"], respuesta_correcta:1, explicacion:"Estos sistemas no tienen compresor mecánico; utilizan calor para separar el refrigerante (amoníaco) del absorbente (agua)." , question: "What is the primary energy source in an absorption refrigeration system (such as those used in hotels or RVs)?", options: ["An Inverter compressor", "Heat (propane gas, steam, or an electric resistance heater)", "Magnetism", "Wind energy"], explanation: "These systems have no mechanical compressor; they use heat to separate the refrigerant (ammonia) from the absorbent (water)." },
  { id:"nate_502", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede con el movimiento molecular de una sustancia cuando alcanza el 'Cero Absoluto' (0 Kelvin)?", opciones:["Se acelera", "Se detiene teóricamente por completo (mínima energía interna)", "Se vuelve gas", "Explota"], respuesta_correcta:1, explicacion:"A 0 K (-273.15°C), no hay calor residual y el desorden molecular (entropía) es mínimo." , question: "What happens to the molecular movement of a substance when it reaches Absolute Zero (0 Kelvin)?", options: ["It speeds up", "It theoretically stops completely (minimum internal energy)", "It becomes a gas", "It explodes"], explanation: "At 0 K (-273.15°C), there is no residual heat and molecular disorder (entropy) is at a minimum." },
  { id:"nate_503", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se llama el componente donde el evaporador del sistema de etapa alta enfría al condensador del sistema de etapa baja?", opciones:["Acumulador", "Intercambiador Inter-etapa (Cascade Condenser)", "Torre de enfriamiento", "Filtro deshidratador"], respuesta_correcta:1, explicacion:"Es el corazón de la cascada; ahí es donde ocurre la transferencia de calor entre ambos circuitos cerrados." , question: "What is the name of the component where the high-stage evaporator cools the low-stage condenser?", options: ["Accumulator", "Inter-stage Heat Exchanger (Cascade Condenser)", "Cooling tower", "Filter drier"], explanation: "It is the heart of the cascade; that is where the heat transfer between the two closed circuits occurs." },
  { id:"nate_504", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué refrigerante es comúnmente usado en la etapa de baja temperatura de una cascada para alcanzar -80°C?", opciones:["R-22", "R-508B o R-23", "R-410A", "Agua"], respuesta_correcta:1, explicacion:"Son refrigerantes con puntos de ebullición extremadamente bajos, diseñados específicamente para aplicaciones de ultra-congelación." , question: "What refrigerant is commonly used in the low-temperature stage of a cascade system to reach -80°C?", options: ["R-22", "R-508B or R-23", "R-410A", "Water"], explanation: "These are refrigerants with extremely low boiling points, designed specifically for ultra-low-temperature applications." },
  { id:"nate_505", categoria:"NATE_INDUSTRIAL", pregunta:"En grandes Chillers de absorción industriales, ¿qué combinación de sustancias se usa comúnmente?", opciones:["Agua (como refrigerante) y Bromuro de Litio (como absorbente)", "R-134a y Aceite", "Amoníaco y Aire", "Glicol y Alcohol"], respuesta_correcta:0, explicacion:"El agua se evapora a muy baja presión para enfriar, y el Bromuro de Litio (una sal) la absorbe para reiniciar el ciclo." , question: "In large industrial absorption Chillers, what combination of substances is commonly used?", options: ["Water (as refrigerant) and Lithium Bromide (as absorbent)", "R-134a and Oil", "Ammonia and Air", "Glycol and Alcohol"], explanation: "Water evaporates at very low pressure to provide cooling, and Lithium Bromide (a salt) absorbs it to restart the cycle." },
  { id:"nate_506", categoria:"NATE_INDUSTRIAL", pregunta:"Si el compresor de la etapa ALTA de una cascada falla, ¿qué sucede con la etapa BAJA?", opciones:["Sigue funcionando igual", "La presión de descarga de la etapa baja subirá peligrosamente hasta que el presostato la apague (no puede condensar)", "Enfría más", "Se congela el aceite"], respuesta_correcta:1, explicacion:"Sin la etapa alta, el condensador de la etapa baja no tiene forma de rechazar calor." , question: "If the HIGH stage compressor of a cascade system fails, what happens to the LOW stage?", options: ["It keeps running normally", "The low stage discharge pressure will rise dangerously until the pressure switch shuts it down (it cannot reject heat)", "It cools more", "The oil freezes"], explanation: "Without the high stage, the low stage condenser has no way to reject heat." },
  { id:"nate_507", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la refrigeración termoeléctrica (Efecto Peltier)?", opciones:["Enfriar con hielo", "Crear una diferencia de temperatura al pasar corriente eléctrica por la unión de dos semiconductores distintos", "Usar un ventilador", "Refrigeración por agua"], respuesta_correcta:1, explicacion:"Se usa en cavas de vino pequeñas o enfriadores de CPU. No usa refrigerante ni partes móviles, solo electricidad." , question: "What is thermoelectric refrigeration (Peltier Effect)?", options: ["Cooling with ice", "Creating a temperature difference by passing electric current through the junction of two different semiconductors", "Using a fan", "Water-based refrigeration"], explanation: "It is used in small wine coolers or CPU coolers. It uses no refrigerant or moving parts, only electricity." },
  { id:"nate_508", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la temperatura de ebullición del Nitrógeno Líquido a presión atmosférica?", opciones:["0°C", "-196°C (-321°F)", "-50°C", "-273°C"], respuesta_correcta:1, explicacion:"A esa temperatura, el nitrógeno se convierte en líquido. Se usa para congelación instantánea y medicina." , question: "What is the boiling point of Liquid Nitrogen at atmospheric pressure?", options: ["0°C", "-196°C (-321°F)", "-50°C", "-273°C"], explanation: "At that temperature, nitrogen becomes a liquid. It is used for flash freezing and medical applications." },
  { id:"nate_509", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el riesgo principal de una fuga de nitrógeno en una habitación cerrada sin ventilación?", opciones:["Incendio", "Asfixia por desplazamiento de oxígeno (el nitrógeno es invisible e inodoro)", "Explosión", "Envenenamiento"], respuesta_correcta:1, explicacion:"El nitrógeno desplaza el aire respirable. Una persona puede desmayarse y morir sin darse cuenta de que no hay oxígeno." , question: "What is the main risk of a nitrogen leak in a sealed room without ventilation?", options: ["Fire", "Asphyxiation by oxygen displacement (nitrogen is invisible and odorless)", "Explosion", "Poisoning"], explanation: "Nitrogen displaces breathable air. A person can pass out and die without realizing there is no oxygen." },
  { id:"nate_510", categoria:"NATE_INDUSTRIAL", pregunta:"En refrigeración de amoníaco de dos etapas, ¿para qué sirve el 'Intercooler'?", opciones:["Para enfriar el aceite", "Para enfriar el gas de descarga de la primera etapa antes de que entre a la segunda etapa", "Para calentar el agua", "Para filtrar gas"], respuesta_correcta:1, explicacion:"Reduce la temperatura de entrada al segundo compresor, mejorando la eficiencia y protegiendo el equipo del calor excesivo." , question: "In a two-stage ammonia refrigeration system, what is the purpose of the Intercooler?", options: ["To cool the oil", "To cool the discharge gas from the first stage before it enters the second stage", "To heat the water", "To filter gas"], explanation: "It reduces the inlet temperature to the second compressor, improving efficiency and protecting the equipment from excessive heat." },
  { id:"nate_511", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se añade gas hidrógeno en un refrigerador de absorción doméstico (tipo Servel)?", opciones:["Para que sea inflamable", "Para igualar la presión total en el sistema y permitir que el amoníaco se evapore a baja temperatura parcial", "Como combustible", "Para detectar fugas"], respuesta_correcta:1, explicacion:"El hidrógeno permite que la presión total sea alta (seguridad) pero la presión parcial del amoníaco sea baja (evaporación fría)." , question: "Why is hydrogen gas added to a domestic absorption refrigerator (Servel type)?", options: ["To make it flammable", "To equalize the total system pressure and allow ammonia to evaporate at a low partial pressure", "As fuel", "To detect leaks"], explanation: "Hydrogen allows the total pressure to remain high (safety) while the partial pressure of ammonia stays low (cold evaporation)." },
  { id:"nate_512", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del 'Expansion Tank' (tanque de expansión) en el lado de baja de un sistema de ultra-baja temperatura?", opciones:["Guardar líquido extra", "Almacenar el refrigerante en estado de vapor cuando el equipo está apagado para evitar presiones excesivas al calentarse", "Medir el aceite", "Enfriar el compresor"], respuesta_correcta:1, explicacion:"Cuando el equipo se apaga y sube a temperatura ambiente, el refrigerante de baja presión se expandiría tanto que rompería las tuberías si no tuviera ese tanque." , question: "What is the function of the Expansion Tank on the low side of an ultra-low temperature system?", options: ["To store extra liquid", "To store refrigerant in vapor state when the equipment is off to prevent excessive pressures upon warming", "To measure oil", "To cool the compressor"], explanation: "When the equipment shuts down and warms to ambient temperature, the low-pressure refrigerant would expand so much it would burst the piping without that tank." },
  { id:"nate_513", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede con el sello de una puerta de un congelador de -80°C si no se limpia la escarcha?", opciones:["Se vuelve más hermético", "El hielo deforma el empaque y permite la entrada de humedad, creando un bloque de hielo que impedirá abrir la puerta", "No pasa nada", "Se calienta el empaque"], respuesta_correcta:1, explicacion:"A esas temperaturas, la mínima entrada de aire se convierte en hielo duro como roca instantáneamente." , question: "What happens to the door gasket of a -80°C freezer if frost is not cleaned regularly?", options: ["It becomes more airtight", "Ice deforms the gasket and allows moisture entry, creating an ice block that will prevent the door from opening", "Nothing happens", "The gasket heats up"], explanation: "At those temperatures, the slightest air infiltration turns into rock-hard ice instantaneously." },
  { id:"nate_514", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué describe el efecto Joule-Thomson usado en la licuefacción de gases?", opciones:["El cambio de color de un gas", "El cambio de temperatura de un gas real cuando se expande a través de una válvula sin intercambio de calor", "La velocidad del sonido", "La presión del aceite"], respuesta_correcta:1, explicacion:"Es el principio básico de por qué un gas se enfría al pasar por una restricción (como la TXV)." , question: "What does the Joule-Thomson effect used in gas liquefaction describe?", options: ["The color change of a gas", "The temperature change of a real gas when it expands through a valve without heat exchange", "The speed of sound", "Oil pressure"], explanation: "It is the basic principle behind why a gas cools when passing through a restriction (such as a TXV)." },
  { id:"nate_515", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué tipo de aceite se requiere en la etapa de ultra-baja temperatura donde el refrigerante no es miscible?", opciones:["Aceite de cocina", "Aceite sintético especial de ultra-baja viscosidad o sistemas de separación de aceite de alta eficiencia", "Aceite mineral común", "No usa aceite"], respuesta_correcta:1, explicacion:"A -80°C, el aceite normal se vuelve sólido como una vela, bloqueando el sistema." , question: "What type of oil is required in the ultra-low temperature stage where the refrigerant is not miscible?", options: ["Cooking oil", "Special ultra-low viscosity synthetic oil or high-efficiency oil separation systems", "Common mineral oil", "No oil is used"], explanation: "At -80°C, regular oil becomes solid like a candle, blocking the system." },
  { id:"nate_516", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la liofilización (Freeze-drying)?", opciones:["Congelar con agua", "Deshidratar un producto congelado mediante sublimación (el hielo pasa a vapor sin pasar por líquido) bajo alto vacío", "Cocinar con frío", "Limpiar con nitrógeno"], respuesta_correcta:1, explicacion:"Se usa para conservar vacunas o café instantáneo, manteniendo las propiedades del producto intactas." , question: "What is freeze-drying (lyophilization)?", options: ["Freezing with water", "Dehydrating a frozen product through sublimation (ice turns directly to vapor without passing through liquid) under high vacuum", "Cooking with cold", "Cleaning with nitrogen"], explanation: "It is used to preserve vaccines or instant coffee, keeping the product properties intact." },
  { id:"nate_517", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un compresor 'Compound'?", opciones:["Un compresor de plástico", "Un solo compresor con dos etapas de compresión internas (una culata de baja y otra de alta)", "Un compresor muy grande", "Un motor eléctrico"], respuesta_correcta:1, explicacion:"Permite hacer el trabajo de una cascada simple en un solo cuerpo de máquina para ahorrar espacio." , question: "What is a Compound compressor?", options: ["A plastic compressor", "A single compressor with two internal compression stages (one low-side cylinder head and one high-side cylinder head)", "A very large compressor", "An electric motor"], explanation: "It allows performing the work of a simple cascade system in a single machine body to save space." },
  { id:"nate_518", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se usa Teflon o materiales cerámicos en las válvulas de sistemas criogénicos?", opciones:["Porque son baratos", "Porque el caucho y los elastómeros comunes se vuelven quebradizos como el vidrio a temperaturas criogénicas", "Porque no se ensucian", "Porque brillan"], respuesta_correcta:1, explicacion:"Los materiales estándar fallan por fatiga térmica extrema en estos sistemas." , question: "Why are Teflon or ceramic materials used in cryogenic system valves?", options: ["Because they are cheap", "Because rubber and common elastomers become brittle like glass at cryogenic temperatures", "Because they do not get dirty", "Because they are shiny"], explanation: "Standard materials fail due to extreme thermal fatigue in these systems." },
  { id:"nate_519", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede si el lazo de control de la etapa alta oscila mucho en una cascada?", opciones:["Nada relevante", "Inestabilidad total en la etapa baja, provocando alarmas de temperatura y posibles daños al compresor de ultra-baja", "El equipo enfría más", "Se apaga el display"], respuesta_correcta:1, explicacion:"Como la etapa baja depende de la alta para condensar, cualquier variación arriba se amplifica abajo." , question: "What happens if the control loop of the high stage oscillates excessively in a cascade system?", options: ["Nothing significant", "Total instability in the low stage, triggering temperature alarms and potential damage to the ultra-low compressor", "The equipment cools more", "The display turns off"], explanation: "Since the low stage depends on the high stage for condensing, any variation above is amplified below." },
  { id:"nate_520", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué ocurre en el 'Generador' de un sistema de absorción?", opciones:["Se crea electricidad", "Se aplica calor a la solución rica para evaporar el refrigerante y separarlo del absorbente", "Se filtra el agua", "Se apaga el sistema"], respuesta_correcta:1, explicacion:"Es el equivalente al compresor, pero usa energía térmica en lugar de mecánica." , question: "What happens in the Generator of an absorption system?", options: ["Electricity is generated", "Heat is applied to the rich solution to evaporate the refrigerant and separate it from the absorbent", "Water is filtered", "The system shuts down"], explanation: "It is the equivalent of the compressor, but uses thermal energy instead of mechanical energy." },
  { id:"nate_521", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja del aceite PVE en sistemas de baja temperatura frente al POE?", opciones:["Es más barato", "Es menos higroscópico y no forma ceras ácidas al contacto con trazas de humedad", "Es más denso", "No tiene olor"], respuesta_correcta:1, explicacion:"La estabilidad química del PVE es superior en sistemas complejos de ultra-congelación." , question: "What is the advantage of PVE oil over POE oil in low-temperature systems?", options: ["It is cheaper", "It is less hygroscopic and does not form acid waxes on contact with traces of moisture", "It is denser", "It has no odor"], explanation: "The chemical stability of PVE is superior in complex ultra-freezing systems." },
  { id:"nate_522", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prefieren sensores Pt100 (RTD) sobre termistores NTC en laboratorios de ultra-congelación?", opciones:["Porque son más grandes", "Por su altísima precisión, estabilidad a largo plazo y rango lineal en temperaturas extremas", "Porque son inalámbricos", "Porque no usan cables"], respuesta_correcta:1, explicacion:"En vacunas, un error de 1 grado es inaceptable. El Pt100 es el estándar de oro." , question: "Why are Pt100 (RTD) sensors preferred over NTC thermistors in ultra-freezing laboratories?", options: ["Because they are larger", "Due to their extremely high accuracy, long-term stability, and linear range at extreme temperatures", "Because they are wireless", "Because they do not use wires"], explanation: "For vaccines, a 1-degree error is unacceptable. The Pt100 is the gold standard." },
  { id:"nate_523", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Dewar'?", opciones:["Un tipo de compresor", "Un recipiente de almacenamiento aislado al vacío (como un termo gigante) para líquidos criogénicos", "Un sensor de flujo", "Un gas noble"], respuesta_correcta:1, explicacion:"El vacío entre las paredes del Dewar impide la transferencia de calor, manteniendo el líquido frío por días." , question: "What is a Dewar?", options: ["A type of compressor", "A vacuum-insulated storage vessel (like a giant thermos) for cryogenic liquids", "A flow sensor", "A noble gas"], explanation: "The vacuum between the Dewar walls prevents heat transfer, keeping the liquid cold for days." },
  { id:"nate_524", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué combinación de gases naturales se usa a menudo en cascadas ecológicas modernas?", opciones:["R-290 (Propano) en la etapa alta y R-1150 (Etileno) en la etapa baja", "Agua y aire", "CO2 y Oxígeno", "Helio y Neón"], respuesta_correcta:0, explicacion:"Permite alcanzar -100°C con un impacto ambiental (GWP) casi de cero." , question: "What combination of natural gases is often used in modern eco-friendly cascade systems?", options: ["R-290 (Propane) in the high stage and R-1150 (Ethylene) in the low stage", "Water and air", "CO2 and Oxygen", "Helium and Neon"], explanation: "It allows reaching -100°C with a global warming potential (GWP) of nearly zero." },
  { id:"nate_525", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el COP típico de un sistema de absorción de etapa simple?", opciones:["3.0 a 4.0", "0.6 a 0.7", "10.0", "1.5"], respuesta_correcta:1, explicacion:"La eficiencia energética es baja comparada con la compresión eléctrica, pero es ideal si tienes calor residual o vapor 'gratis'." , question: "What is the typical COP of a single-stage absorption system?", options: ["3.0 to 4.0", "0.6 to 0.7", "10.0", "1.5"], explanation: "Energy efficiency is low compared to electric compression, but it is ideal when waste heat or free steam is available." },
  { id:"nate_526", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se usa una mezcla de Helio y Oxígeno en aplicaciones de buceo profundo o medicina?", opciones:["Para flotar", "Para reducir la densidad del gas respirado y evitar la narcosis de nitrógeno a gran profundidad", "Para enfriar los pulmones", "Para hablar chistoso"], respuesta_correcta:1, explicacion:"Aunque no es refrigeración directa, es una aplicación crítica de gases criogénicos en soporte de vida." , question: "What is a Helium-Oxygen mixture used for in deep diving or medical applications?", options: ["To float", "To reduce the density of the breathing gas and prevent nitrogen narcosis at great depth", "To cool the lungs", "To make your voice sound funny"], explanation: "Although not direct refrigeration, it is a critical application of cryogenic gases in life support." },
  { id:"nate_527", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras que el compresor de baja temperatura vibra violentamente al arrancar. ¿Qué revisarías?", opciones:["El gas", "Si el calentador de cárter funcionó correctamente para evitar la migración de refrigerante líquido al aceite", "La carga de las baterías", "El color del compresor"], respuesta_correcta:1, explicacion:"A ultra-baja temperatura, la migración es masiva. Sin calor en el cárter, el compresor intentará comprimir líquido." , question: "You find that the low-temperature compressor vibrates violently on startup. What would you check?", options: ["The gas", "Whether the crankcase heater operated correctly to prevent liquid refrigerant migration into the oil", "The battery charge", "The color of the compressor"], explanation: "At ultra-low temperatures, migration is massive. Without crankcase heat, the compressor will attempt to compress liquid." },
  { id:"nate_528", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prefiere el Acero Inoxidable 316L en tuberías criogénicas industriales?", opciones:["Porque es barato", "Porque mantiene su ductilidad y no se vuelve frágil a temperaturas bajo -150°C", "Porque es más ligero", "Porque no necesita soldadura"], respuesta_correcta:1, explicacion:"El acero al carbón se rompería como cristal a esas temperaturas. El inoxidable resiste el choque térmico." , question: "Why is 316L Stainless Steel preferred for industrial cryogenic piping?", options: ["Because it is cheap", "Because it maintains its ductility and does not become brittle at temperatures below -150°C", "Because it is lighter", "Because it does not need welding"], explanation: "Carbon steel would shatter like glass at those temperatures. Stainless steel withstands thermal shock." },
  { id:"nate_529", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué componente consume la mayor parte de la energía ELÉCTRICA en un sistema de absorción?", opciones:["El quemador", "La bomba de solución (que mueve el líquido del absorbedor al generador)", "El ventilador", "Las luces"], respuesta_correcta:1, explicacion:"Es el único motor eléctrico significativo en el sistema, pero su consumo es mínimo comparado con un compresor." , question: "What component consumes the most ELECTRICAL energy in an absorption system?", options: ["The burner", "The solution pump (which moves liquid from the absorber to the generator)", "The fan", "The lights"], explanation: "It is the only significant electric motor in the system, but its consumption is minimal compared to a compressor." },
  { id:"nate_530", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los separadores de aceite en cascadas de -80°C son tan grandes y complejos?", opciones:["Para que el técnico trabaje más", "Para garantizar un retorno del 99.9% del aceite antes de que entre al evaporador de ultra-baja, donde se congelaría", "Para enfriar el gas", "Para ahorrar gas"], respuesta_correcta:1, explicacion:"Cualquier rastro de aceite que llegue al evaporador se convertirá en 'cera' y bloqueará el flujo de refrigerante." , question: "Why are oil separators in -80°C cascade systems so large and complex?", options: ["To give the technician more work", "To ensure 99.9% oil return before it enters the ultra-low evaporator, where it would freeze", "To cool the gas", "To save gas"], explanation: "Any trace of oil reaching the evaporator will turn into wax and block refrigerant flow." },
  { id:"nate_531", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un Tubo de Vórtice (Vortex Tube)?", opciones:["Un ventilador circular", "Un dispositivo mecánico que separa el aire comprimido en corrientes de aire caliente y aire frío sin partes móviles", "Un tipo de compresor", "Un sensor de flujo"], respuesta_correcta:1, explicacion:"Se usa para enfriamiento puntual en máquinas herramientas. Es pura física de fluidos." , question: "What is a Vortex Tube?", options: ["A circular fan", "A mechanical device that separates compressed air into hot and cold air streams without moving parts", "A type of compressor", "A flow sensor"], explanation: "It is used for spot cooling on machine tools. It is pure fluid dynamics." },
  { id:"nate_532", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué precaución se debe tener con los manómetros usados en sistemas de Oxígeno Líquido?", opciones:["Que sean de plástico", "Deben estar certificados como 'Libres de Aceite' (Oil-Free) para evitar explosiones espontáneas", "Que sean digitales", "No se pueden usar manómetros"], respuesta_correcta:1, explicacion:"El oxígeno puro reacciona violentamente (combustión) con cualquier traza de hidrocarburo o aceite." , question: "What precaution must be taken with pressure gauges used on Liquid Oxygen systems?", options: ["They must be plastic", "They must be certified as Oil-Free to prevent spontaneous explosions", "They must be digital", "Pressure gauges cannot be used"], explanation: "Pure oxygen reacts violently (combustion) with any trace of hydrocarbon or oil." },
  { id:"nate_533", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un ultracongelador tarda hasta 24 horas en llegar de 25°C a -80°C?", opciones:["Porque el compresor es lento", "Por la inmensa masa térmica que debe enfriar y para permitir una estabilización gradual de las presiones de ambas etapas", "Porque no tiene gas", "Para ahorrar luz"], respuesta_correcta:1, explicacion:"Apurar el proceso podría causar choques térmicos en los metales o fallas por presión en el intercambiador de cascada." , question: "Why does an ultra-low freezer take up to 24 hours to go from 25°C to -80°C?", options: ["Because the compressor is slow", "Due to the immense thermal mass that must be cooled and to allow gradual pressure stabilization of both stages", "Because it has no gas", "To save electricity"], explanation: "Rushing the process could cause thermal shock in the metals or pressure failures in the cascade heat exchanger." },
  { id:"nate_534", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede en un Chiller de absorción si entran gases no-condensables (aire)?", opciones:["Enfría mejor", "La presión interna sube, la capacidad cae drásticamente y la solución de bromuro de litio puede cristalizarse (volverse sólida)", "El agua hierve", "Se apaga la luz"], respuesta_correcta:1, explicacion:"La cristalización es la peor pesadilla en absorción; requiere calentar toda la máquina para volver la sal a estado líquido." , question: "What happens in an absorption chiller if non-condensable gases (air) enter the system?", options: ["It cools better", "Internal pressure rises, capacity drops drastically, and the lithium bromide solution may crystallize (turn solid)", "The water boils", "The light turns off"], explanation: "Crystallization is the worst nightmare in absorption; it requires heating the entire machine to return the salt to a liquid state." },
  { id:"nate_535", categoria:"NATE_INDUSTRIAL", pregunta:"¿A qué temperatura ocurre la sublimación del Hielo Seco (CO2 sólido)?", opciones:["0°C", "-78.5°C (-109.3°F)", "-20°C", "100°C"], respuesta_correcta:1, explicacion:"Es la temperatura constante a la que se mantiene el hielo seco mientras se evapora directamente a gas." , question: "At what temperature does Dry Ice (solid CO2) sublimate?", options: ["0°C", "-78.5°C (-109.3°F)", "-20°C", "100°C"], explanation: "It is the constant temperature at which dry ice sublimates directly into gas." },
  { id:"nate_536", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un sistema de 'Refrigerante Mixto' (MR) usado en plantas de GNL?", opciones:["Mezclar R-22 con R-410A", "Un solo ciclo de refrigeración que usa una mezcla de nitrógeno, metano, etano y propano para enfriar en un amplio rango de temperaturas", "Usar agua y aceite", "Es un error de carga"], respuesta_correcta:1, explicacion:"Permite licuar Gas Natural de forma eficiente aprovechando los diferentes puntos de ebullición de la mezcla." , question: "What is a Mixed Refrigerant (MR) system used in LNG plants?", options: ["Mixing R-22 with R-410A", "A single refrigeration cycle that uses a blend of nitrogen, methane, ethane, and propane to cool across a wide temperature range", "Using water and oil", "It is a charging error"], explanation: "It allows efficient liquefaction of Natural Gas by taking advantage of the different boiling points of the mixture." },
  { id:"nate_537", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la causa más común de cristalización en un sistema de Bromuro de Litio?", opciones:["Falta de energía", "Falla en la torre de enfriamiento o entrada de aire al sistema (pérdida de vacío)", "Mucho calor", "Agua muy limpia"], respuesta_correcta:1, explicacion:"Si la solución se enfría demasiado o se concentra de más por falta de purga, se vuelve sólida como sal de mesa." , question: "What is the most common cause of crystallization in a Lithium Bromide system?", options: ["Power failure", "Cooling tower failure or air infiltration into the system (loss of vacuum)", "Too much heat", "Very clean water"], explanation: "If the solution cools too much or becomes over-concentrated due to lack of purging, it solidifies like table salt." },
  { id:"nate_538", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué gas es el R-170?", opciones:["Metano", "Etano", "Propano", "Butano"], respuesta_correcta:1, explicacion:"Es un refrigerante natural muy usado en la etapa de baja de cascadas por su bajísimo punto de ebullición." , question: "What gas is R-170?", options: ["Methane", "Ethane", "Propane", "Butane"], explanation: "It is a natural refrigerant widely used in the low stage of cascade systems due to its extremely low boiling point." },
  { id:"nate_539", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué unidad de medida se usa para vacíos profundos en liofilización industrial?", opciones:["psig", "mTorr (miliTorr) o Micrones", "Bar", "Pulgadas de Mercurio"], respuesta_correcta:1, explicacion:"En estos procesos, 1 pulgada de mercurio es una medida demasiado grosera. Se requieren milésimas de Torr." , question: "What unit of measurement is used for deep vacuums in industrial freeze-drying?", options: ["psig", "mTorr (milliTorr) or Microns", "Bar", "Inches of Mercury"], explanation: "In these processes, 1 inch of mercury is far too coarse a measurement. Thousandths of a Torr are required." },
  { id:"nate_540", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja de un refrigerador de ciclo Stirling?", opciones:["Es muy ruidoso", "Puede alcanzar temperaturas criogénicas en un solo paso con altísima eficiencia y sin válvulas", "Es barato", "Usa mucha agua"], respuesta_correcta:1, explicacion:"Se usa en satélites y cámaras infrarrojas de alta tecnología." , question: "What is the advantage of a Stirling cycle refrigerator?", options: ["It is very noisy", "It can reach cryogenic temperatures in a single step with very high efficiency and no valves", "It is cheap", "It uses a lot of water"], explanation: "It is used in satellites and high-tech infrared cameras." },
  { id:"nate_541", categoria:"NATE_INDUSTRIAL", pregunta:"Un ultracongelador marca -72°C en lugar de -80°C y el compresor de etapa alta no para nunca. ¿Qué revisas?", opciones:["La luz del cuarto", "Si el condensador de la etapa alta está sucio o el ventilador falló", "Si la puerta está abierta", "El gas de la etapa baja"], respuesta_correcta:1, explicacion:"Si la etapa alta pierde eficiencia, no puede enfriar bien el condensador de la etapa baja, limitando el enfriamiento final." , question: "An ultra-low freezer reads -72°C instead of -80°C and the high-stage compressor never shuts off. What do you check?", options: ["The room lights", "Whether the high-stage condenser is dirty or the fan has failed", "Whether the door is open", "The low-stage refrigerant charge"], explanation: "If the high stage loses efficiency, it cannot properly cool the low-stage condenser, limiting the final cooling capacity." },
  { id:"nate_542", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se añade Cromato de Litio a los sistemas de absorción?", opciones:["Para que el agua se vea amarilla", "Para formar una capa protectora interna en el acero y evitar la corrosión por el bromuro de litio", "Para limpiar el sistema", "Para que huela mejor"], respuesta_correcta:1, explicacion:"El bromuro de litio es una sal muy corrosiva; sin inhibidores, destruiría el Chiller en pocos meses." , question: "Why is Lithium Chromate added to absorption systems?", options: ["To make the water look yellow", "To form a protective internal layer on the steel and prevent corrosion from lithium bromide", "To clean the system", "To make it smell better"], explanation: "Lithium bromide is a highly corrosive salt; without inhibitors, it would destroy the chiller within months." },
  { id:"nate_543", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué le sucede a ciertos metales cuando se enfrían con Helio Líquido (-269°C)?", opciones:["Se vuelven aislantes", "Se vuelven superconductores (resistencia eléctrica cero)", "Se deshacen", "Cambian de color"], respuesta_correcta:1, explicacion:"Es la base de las máquinas de Resonancia Magnética (MRI) en los hospitales." , question: "What happens to certain metals when cooled with Liquid Helium (-269°C)?", options: ["They become insulators", "They become superconductors (zero electrical resistance)", "They disintegrate", "They change color"], explanation: "This is the basis of MRI (Magnetic Resonance Imaging) machines in hospitals." },
  { id:"nate_544", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se deben usar guantes de látex o cuero ajustados al manejar nitrógeno líquido?", opciones:["Porque se rompen", "Porque si el líquido cae dentro, el guante lo atrapa contra tu piel causando una quemadura instantánea; deben usarse guantes criogénicos holgados", "Porque son feos", "Porque el nitrógeno los quema"], respuesta_correcta:1, explicacion:"Los guantes criogénicos permiten sacárselos rápidamente si algo de líquido entra." , question: "Why should tight-fitting latex or leather gloves not be worn when handling liquid nitrogen?", options: ["Because they tear", "Because if liquid spills inside, the glove traps it against your skin causing an instant burn; loose-fitting cryogenic gloves must be used", "Because they are ugly", "Because nitrogen burns them"], explanation: "Cryogenic gloves can be removed quickly if any liquid gets inside." },
  { id:"nate_545", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es una 'Válvula de Alivio de Dos Etapas'?", opciones:["Una válvula con dos resortes", "Un sistema de seguridad que protege al sistema si la presión sube por falla de enfriamiento de la cascada", "Una válvula para gas", "Una válvula para aceite"], respuesta_correcta:1, explicacion:"Garantiza que el refrigerante caro de la etapa baja no se pierda ante un pico menor de presión." , question: "What is a Two-Stage Relief Valve?", options: ["A valve with two springs", "A safety system that protects the system if pressure rises due to cascade cooling failure", "A gas valve", "An oil valve"], explanation: "It ensures that the expensive low-stage refrigerant is not lost during a minor pressure spike." },
  { id:"nate_546", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué caracteriza a un Chiller de absorción de 'Triple Efecto'?", opciones:["Que es tres veces más grande", "Usa tres generadores en serie para maximizar el uso del calor, alcanzando COPs de 1.7 o más", "Que usa tres tipos de sal", "Que no usa agua"], respuesta_correcta:1, explicacion:"Es la tecnología de absorción más avanzada y eficiente del mundo." , question: "What characterizes a Triple-Effect absorption chiller?", options: ["It is three times larger", "It uses three generators in series to maximize heat utilization, achieving COPs of 1.7 or higher", "It uses three types of salt", "It does not use water"], explanation: "It is the most advanced and efficient absorption technology in the world." },
  { id:"nate_547", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se obtiene el Oxígeno y Nitrógeno puro de forma industrial?", opciones:["Mediante reacciones químicas", "Mediante destilación fraccionada del aire líquido a temperaturas criogénicas", "Usando filtros de papel", "Succionándolo con bombas"], respuesta_correcta:1, explicacion:"Se enfría el aire hasta volverlo líquido y luego se 'hierve' poco a poco para separar cada gas por su punto de ebullición." , question: "How are pure Oxygen and Nitrogen obtained industrially?", options: ["Through chemical reactions", "Through fractional distillation of liquid air at cryogenic temperatures", "Using paper filters", "Sucking it out with pumps"], explanation: "Air is cooled until it becomes liquid, then slowly boiled to separate each gas by its boiling point." },
  { id:"nate_548", categoria:"NATE_INDUSTRIAL", pregunta:"Escuchas un sonido de 'cascada' o agua corriendo dentro de un Chiller de absorción. ¿Es normal?", opciones:["No, hay una fuga", "Sí, es el flujo de la solución de bromuro de litio cayendo sobre los tubos del absorbedor", "Es el gas que se sale", "La bomba está rota"], respuesta_correcta:1, explicacion:"A diferencia de los sistemas de compresión, en absorción el movimiento de líquidos es constante y audible." , question: "You hear a cascading or running water sound inside an absorption chiller. Is this normal?", options: ["No, there is a leak", "Yes, it is the flow of lithium bromide solution falling over the absorber tubes", "It is gas escaping", "The pump is broken"], explanation: "Unlike compression systems, in absorption systems the movement of liquids is constant and audible." },
  { id:"nate_549", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de ultra-baja temperatura, ¿qué es el 'Oil Log' en el evaporador?", opciones:["Un registro de aceite", "La acumulación de aceite congelado en las paredes del evaporador que actúa como aislante y bloquea el intercambio de calor", "Un filtro de aceite", "Una bomba de aceite"], respuesta_correcta:1, explicacion:"Es la falla más difícil de diagnosticar; el sistema parece tener gas pero no enfría porque el aceite 'tapizó' el cobre por dentro." , question: "In an ultra-low temperature system, what is Oil Logging in the evaporator?", options: ["An oil record", "The accumulation of frozen oil on the evaporator walls that acts as insulation and blocks heat exchange", "An oil filter", "An oil pump"], explanation: "It is the most difficult fault to diagnose; the system appears to have refrigerant but does not cool because oil has coated the copper internally." },
  { id:"nate_550", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un congelador de ultra-baja temperatura (-80°C) utiliza dos sistemas de refrigeración independientes (Cascada)?", opciones:["Para tener un respaldo si uno falla", "Porque un solo compresor no puede manejar la relación de compresión necesaria para alcanzar esas temperaturas", "Para gastar menos luz", "Porque usa dos tipos de aceite"], respuesta_correcta:1, explicacion:"El sistema 'alto' enfría el condensador del sistema 'bajo'. Esto permite alcanzar temperaturas extremas dividiendo el trabajo de compresión en dos etapas con diferentes refrigerantes." , question: "Why does an ultra-low temperature freezer (-80°C) use two independent refrigeration systems (Cascade)?", options: ["To have a backup if one fails", "Because a single compressor cannot handle the compression ratio needed to reach those temperatures", "To use less electricity", "Because it uses two types of oil"], explanation: "The high system cools the condenser of the low system. This allows reaching extreme temperatures by dividing the compression work into two stages with different refrigerants." },
  { id:"nate_551", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la fuente de energía principal en un sistema de refrigeración por absorción (como los usados en hoteles o casas rodantes)?", opciones:["Un compresor inverter", "Calor (gas propano, vapor o una resistencia eléctrica)", "Magnetismo", "Energía eólica"], respuesta_correcta:1, explicacion:"Estos sistemas no tienen compresor mecánico; utilizan calor para separar el refrigerante (amoníaco) del absorbente (agua)." , question: "What is the primary energy source in an absorption refrigeration system (such as those used in hotels or RVs)?", options: ["An inverter compressor", "Heat (propane gas, steam, or an electric heating element)", "Magnetism", "Wind energy"], explanation: "These systems have no mechanical compressor; they use heat to separate the refrigerant (ammonia) from the absorbent (water)." },
  { id:"nate_552", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede con el movimiento molecular de una sustancia cuando alcanza el 'Cero Absoluto' (0 Kelvin)?", opciones:["Se acelera", "Se detiene teóricamente por completo (mínima energía interna)", "Se vuelve gas", "Explota"], respuesta_correcta:1, explicacion:"A 0 K (-273.15°C), no hay calor residual y el desorden molecular (entropía) es mínimo." , question: "What happens to the molecular motion of a substance when it reaches Absolute Zero (0 Kelvin)?", options: ["It accelerates", "It theoretically stops completely (minimum internal energy)", "It becomes a gas", "It explodes"], explanation: "At 0 K (-273.15°C), there is no residual heat and molecular disorder (entropy) is at a minimum." },
  { id:"nate_553", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se llama el componente donde el evaporador del sistema de etapa alta enfría al condensador del sistema de etapa baja?", opciones:["Acumulador", "Intercambiador Inter-etapa (Cascade Condenser)", "Torre de enfriamiento", "Filtro deshidratador"], respuesta_correcta:1, explicacion:"Es el corazón de la cascada; ahí es donde ocurre la transferencia de calor entre ambos circuitos cerrados." , question: "What is the component called where the high-stage evaporator cools the low-stage condenser?", options: ["Accumulator", "Inter-stage Heat Exchanger (Cascade Condenser)", "Cooling tower", "Filter drier"], explanation: "It is the heart of the cascade; that is where the heat transfer between both closed circuits occurs." },
  { id:"nate_554", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué refrigerante es comúnmente usado en la etapa de baja temperatura de una cascada para alcanzar -80°C?", opciones:["R-22", "R-508B o R-23", "R-410A", "Agua"], respuesta_correcta:1, explicacion:"Son refrigerantes con puntos de ebullición extremadamente bajos, diseñados específicamente para aplicaciones de ultra-congelación." , question: "What refrigerant is commonly used in the low-temperature stage of a cascade to reach -80°C?", options: ["R-22", "R-508B or R-23", "R-410A", "Water"], explanation: "These are refrigerants with extremely low boiling points, specifically designed for ultra-low freezing applications." },
  { id:"nate_555", categoria:"NATE_INDUSTRIAL", pregunta:"En grandes Chillers de absorción industriales, ¿qué combinación de sustancias se usa comúnmente?", opciones:["Agua (como refrigerante) y Bromuro de Litio (como absorbente)", "R-134a y Aceite", "Amoníaco y Aire", "Glicol y Alcohol"], respuesta_correcta:0, explicacion:"El agua se evapora a muy baja presión para enfriar, y el Bromuro de Litio (una sal) la absorbe para reiniciar el ciclo." , question: "In large industrial absorption chillers, what combination of substances is commonly used?", options: ["Water (as refrigerant) and Lithium Bromide (as absorbent)", "R-134a and Oil", "Ammonia and Air", "Glycol and Alcohol"], explanation: "Water evaporates at very low pressure to provide cooling, and Lithium Bromide (a salt) absorbs it to restart the cycle." },
  { id:"nate_556", categoria:"NATE_INDUSTRIAL", pregunta:"Si el compresor de la etapa ALTA de una cascada falla, ¿qué sucede con la etapa BAJA?", opciones:["Sigue funcionando igual", "La presión de descarga de la etapa baja subirá peligrosamente hasta que el presostato la apague (no puede condensar)", "Enfría más", "Se congela el aceite"], respuesta_correcta:1, explicacion:"Sin la etapa alta, el condensador de la etapa baja no tiene forma de rechazar calor." , question: "If the HIGH stage compressor of a cascade system fails, what happens to the LOW stage?", options: ["It keeps running normally", "The low stage discharge pressure will rise dangerously until the pressure switch shuts it down (it cannot reject heat)", "It cools more", "The oil freezes"], explanation: "Without the high stage, the low stage condenser has no way to reject heat." },
  { id:"nate_557", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la refrigeración termoeléctrica (Efecto Peltier)?", opciones:["Enfriar con hielo", "Crear una diferencia de temperatura al pasar corriente eléctrica por la unión de dos semiconductores distintos", "Usar un ventilador", "Refrigeración por agua"], respuesta_correcta:1, explicacion:"Se usa en cavas de vino pequeñas o enfriadores de CPU. No usa refrigerante ni partes móviles, solo electricidad." , question: "What is thermoelectric refrigeration (Peltier Effect)?", options: ["Cooling with ice", "Creating a temperature difference by passing electric current through the junction of two different semiconductors", "Using a fan", "Water-based refrigeration"], explanation: "It is used in small wine coolers or CPU coolers. It uses no refrigerant or moving parts, only electricity." },
  { id:"nate_558", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la temperatura de ebullición del Nitrógeno Líquido a presión atmosférica?", opciones:["0°C", "-196°C (-321°F)", "-50°C", "-273°C"], respuesta_correcta:1, explicacion:"A esa temperatura, el nitrógeno se convierte en líquido. Se usa para congelación instantánea y medicina." , question: "What is the boiling point of Liquid Nitrogen at atmospheric pressure?", options: ["0°C", "-196°C (-321°F)", "-50°C", "-273°C"], explanation: "At that temperature, nitrogen becomes a liquid. It is used for flash freezing and medical applications." },
  { id:"nate_559", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el riesgo principal de una fuga de nitrógeno en una habitación cerrada sin ventilación?", opciones:["Incendio", "Asfixia por desplazamiento de oxígeno (el nitrógeno es invisible e inodoro)", "Explosión", "Envenenamiento"], respuesta_correcta:1, explicacion:"El nitrógeno desplaza el aire respirable. Una persona puede desmayarse y morir sin darse cuenta de que no hay oxígeno." , question: "What is the main risk of a nitrogen leak in a sealed room without ventilation?", options: ["Fire", "Asphyxiation by oxygen displacement (nitrogen is invisible and odorless)", "Explosion", "Poisoning"], explanation: "Nitrogen displaces breathable air. A person can pass out and die without realizing there is no oxygen." },
  { id:"nate_560", categoria:"NATE_INDUSTRIAL", pregunta:"En refrigeración de amoníaco de dos etapas, ¿para qué sirve el 'Intercooler'?", opciones:["Para enfriar el aceite", "Para enfriar el gas de descarga de la primera etapa antes de que entre a la segunda etapa", "Para calentar el agua", "Para filtrar gas"], respuesta_correcta:1, explicacion:"Reduce la temperatura de entrada al segundo compresor, mejorando la eficiencia y protegiendo el equipo del calor excesivo." , question: "In a two-stage ammonia refrigeration system, what is the purpose of the Intercooler?", options: ["To cool the oil", "To cool the discharge gas from the first stage before it enters the second stage", "To heat the water", "To filter gas"], explanation: "It reduces the inlet temperature to the second compressor, improving efficiency and protecting the equipment from excessive heat." },
  { id:"nate_561", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se añade gas hidrógeno en un refrigerador de absorción doméstico (tipo Servel)?", opciones:["Para que sea inflamable", "Para igualar la presión total en el sistema y permitir que el amoníaco se evapore a baja temperatura parcial", "Como combustible", "Para detectar fugas"], respuesta_correcta:1, explicacion:"El hidrógeno permite que la presión total sea alta (seguridad) pero la presión parcial del amoníaco sea baja (evaporación fría)." , question: "Why is hydrogen gas added to a domestic absorption refrigerator (Servel type)?", options: ["To make it flammable", "To equalize the total system pressure and allow ammonia to evaporate at a low partial pressure", "As fuel", "To detect leaks"], explanation: "Hydrogen allows the total pressure to remain high (safety) while the partial pressure of ammonia stays low (cold evaporation)." },
  { id:"nate_562", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función del 'Expansion Tank' (tanque de expansión) en el lado de baja de un sistema de ultra-baja temperatura?", opciones:["Guardar líquido extra", "Almacenar el refrigerante en estado de vapor cuando el equipo está apagado para evitar presiones excesivas al calentarse", "Medir el aceite", "Enfriar el compresor"], respuesta_correcta:1, explicacion:"Cuando el equipo se apaga y sube a temperatura ambiente, el refrigerante de baja presión se expandiría tanto que rompería las tuberías si no tuviera ese tanque." , question: "What is the function of the Expansion Tank on the low side of an ultra-low temperature system?", options: ["To store extra liquid", "To store refrigerant in vapor state when the equipment is off to prevent excessive pressures upon warming", "To measure oil", "To cool the compressor"], explanation: "When the equipment shuts down and warms to ambient temperature, the low-pressure refrigerant would expand so much it would burst the piping without that tank." },
  { id:"nate_563", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede con el sello de una puerta de un congelador de -80°C si no se limpia la escarcha?", opciones:["Se vuelve más hermético", "El hielo deforma el empaque y permite la entrada de humedad, creando un bloque de hielo que impedirá abrir la puerta", "No pasa nada", "Se calienta el empaque"], respuesta_correcta:1, explicacion:"A esas temperaturas, la mínima entrada de aire se convierte en hielo duro como roca instantáneamente." , question: "What happens to the door gasket of a -80°C freezer if frost is not cleaned regularly?", options: ["It becomes more airtight", "Ice deforms the gasket and allows moisture entry, creating an ice block that will prevent the door from opening", "Nothing happens", "The gasket heats up"], explanation: "At those temperatures, the slightest air infiltration turns into rock-hard ice instantaneously." },
  { id:"nate_564", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué describe el efecto Joule-Thomson usado en la licuefacción de gases?", opciones:["El cambio de color de un gas", "El cambio de temperatura de un gas real cuando se expande a través de una válvula sin intercambio de calor", "La velocidad del sonido", "La presión del aceite"], respuesta_correcta:1, explicacion:"Es el principio básico de por qué un gas se enfría al pasar por una restricción (como la TXV)." , question: "What does the Joule-Thomson effect used in gas liquefaction describe?", options: ["The color change of a gas", "The temperature change of a real gas when it expands through a valve without heat exchange", "The speed of sound", "Oil pressure"], explanation: "It is the basic principle behind why a gas cools when passing through a restriction (such as a TXV)." },
  { id:"nate_565", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué tipo de aceite se requiere en la etapa de ultra-baja temperatura donde el refrigerante no es miscible?", opciones:["Aceite de cocina", "Aceite sintético especial de ultra-baja viscosidad o sistemas de separación de aceite de alta eficiencia", "Aceite mineral común", "No usa aceite"], respuesta_correcta:1, explicacion:"A -80°C, el aceite normal se vuelve sólido como una vela, bloqueando el sistema." , question: "What type of oil is required in the ultra-low temperature stage where the refrigerant is not miscible?", options: ["Cooking oil", "Special ultra-low viscosity synthetic oil or high-efficiency oil separation systems", "Common mineral oil", "No oil is used"], explanation: "At -80°C, regular oil becomes solid like a candle, blocking the system." },
  { id:"nate_566", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la liofilización (Freeze-drying)?", opciones:["Congelar con agua", "Deshidratar un producto congelado mediante sublimación (el hielo pasa a vapor sin pasar por líquido) bajo alto vacío", "Cocinar con frío", "Limpiar con nitrógeno"], respuesta_correcta:1, explicacion:"Se usa para conservar vacunas o café instantáneo, manteniendo las propiedades del producto intactas." , question: "What is freeze-drying (lyophilization)?", options: ["Freezing with water", "Dehydrating a frozen product through sublimation (ice turns directly to vapor without passing through liquid) under high vacuum", "Cooking with cold", "Cleaning with nitrogen"], explanation: "It is used to preserve vaccines or instant coffee, keeping the product properties intact." },
  { id:"nate_567", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un compresor 'Compound'?", opciones:["Un compresor de plástico", "Un solo compresor con dos etapas de compresión internas (una culata de baja y otra de alta)", "Un compresor muy grande", "Un motor eléctrico"], respuesta_correcta:1, explicacion:"Permite hacer el trabajo de una cascada simple en un solo cuerpo de máquina para ahorrar espacio." , question: "What is a Compound compressor?", options: ["A plastic compressor", "A single compressor with two internal compression stages (one low-side cylinder head and one high-side cylinder head)", "A very large compressor", "An electric motor"], explanation: "It allows performing the work of a simple cascade system in a single machine body to save space." },
  { id:"nate_568", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se usa Teflon o materiales cerámicos en las válvulas de sistemas criogénicos?", opciones:["Porque son baratos", "Porque el caucho y los elastómeros comunes se vuelven quebradizos como el vidrio a temperaturas criogénicas", "Porque no se ensucian", "Porque brillan"], respuesta_correcta:1, explicacion:"Los materiales estándar fallan por fatiga térmica extrema en estos sistemas." , question: "Why are Teflon or ceramic materials used in cryogenic system valves?", options: ["Because they are cheap", "Because rubber and common elastomers become brittle like glass at cryogenic temperatures", "Because they do not get dirty", "Because they are shiny"], explanation: "Standard materials fail due to extreme thermal fatigue in these systems." },
  { id:"nate_569", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede si el lazo de control de la etapa alta oscila mucho en una cascada?", opciones:["Nada relevante", "Inestabilidad total en la etapa baja, provocando alarmas de temperatura y posibles daños al compresor de ultra-baja", "El equipo enfría más", "Se apaga el display"], respuesta_correcta:1, explicacion:"Como la etapa baja depende de la alta para condensar, cualquier variación arriba se amplifica abajo." , question: "What happens if the control loop of the high stage oscillates excessively in a cascade system?", options: ["Nothing significant", "Total instability in the low stage, triggering temperature alarms and potential damage to the ultra-low compressor", "The equipment cools more", "The display turns off"], explanation: "Since the low stage depends on the high stage for condensing, any variation above is amplified below." },
  { id:"nate_570", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué ocurre en el 'Generador' de un sistema de absorción?", opciones:["Se crea electricidad", "Se aplica calor a la solución rica para evaporar el refrigerante y separarlo del absorbente", "Se filtra el agua", "Se apaga el sistema"], respuesta_correcta:1, explicacion:"Es el equivalente al compresor, pero usa energía térmica en lugar de mecánica." , question: "What happens in the Generator of an absorption system?", options: ["Electricity is generated", "Heat is applied to the rich solution to evaporate the refrigerant and separate it from the absorbent", "Water is filtered", "The system shuts down"], explanation: "It is the equivalent of the compressor, but uses thermal energy instead of mechanical energy." },
  { id:"nate_571", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja del aceite PVE en sistemas de baja temperatura frente al POE?", opciones:["Es más barato", "Es menos higroscópico y no forma ceras ácidas al contacto con trazas de humedad", "Es más denso", "No tiene olor"], respuesta_correcta:1, explicacion:"La estabilidad química del PVE es superior en sistemas complejos de ultra-congelación." , question: "What is the advantage of PVE oil over POE oil in low-temperature systems?", options: ["It is cheaper", "It is less hygroscopic and does not form acid waxes on contact with traces of moisture", "It is denser", "It has no odor"], explanation: "The chemical stability of PVE is superior in complex ultra-freezing systems." },
  { id:"nate_572", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prefieren sensores Pt100 (RTD) sobre termistores NTC en laboratorios de ultra-congelación?", opciones:["Porque son más grandes", "Por su altísima precisión, estabilidad a largo plazo y rango lineal en temperaturas extremas", "Porque son inalámbricos", "Porque no usan cables"], respuesta_correcta:1, explicacion:"En vacunas, un error de 1 grado es inaceptable. El Pt100 es el estándar de oro." , question: "Why are Pt100 (RTD) sensors preferred over NTC thermistors in ultra-freezing laboratories?", options: ["Because they are larger", "Due to their extremely high accuracy, long-term stability, and linear range at extreme temperatures", "Because they are wireless", "Because they do not use wires"], explanation: "For vaccines, a 1-degree error is unacceptable. The Pt100 is the gold standard." },
  { id:"nate_573", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Dewar'?", opciones:["Un tipo de compresor", "Un recipiente de almacenamiento aislado al vacío (como un termo gigante) para líquidos criogénicos", "Un sensor de flujo", "Un gas noble"], respuesta_correcta:1, explicacion:"El vacío entre las paredes del Dewar impide la transferencia de calor, manteniendo el líquido frío por días." , question: "What is a Dewar?", options: ["A type of compressor", "A vacuum-insulated storage vessel (like a giant thermos) for cryogenic liquids", "A flow sensor", "A noble gas"], explanation: "The vacuum between the Dewar walls prevents heat transfer, keeping the liquid cold for days." },
  { id:"nate_574", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué combinación de gases naturales se usa a menudo en cascadas ecológicas modernas?", opciones:["R-290 (Propano) en la etapa alta y R-1150 (Etileno) en la etapa baja", "Agua y aire", "CO2 y Oxígeno", "Helio y Neón"], respuesta_correcta:0, explicacion:"Permite alcanzar -100°C con un impacto ambiental (GWP) casi de cero." , question: "What combination of natural gases is often used in modern eco-friendly cascade systems?", options: ["R-290 (Propane) in the high stage and R-1150 (Ethylene) in the low stage", "Water and air", "CO2 and Oxygen", "Helium and Neon"], explanation: "It allows reaching -100°C with a global warming potential (GWP) of nearly zero." },
  { id:"nate_575", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el COP típico de un sistema de absorción de etapa simple?", opciones:["3.0 a 4.0", "0.6 a 0.7", "10.0", "1.5"], respuesta_correcta:1, explicacion:"La eficiencia energética es baja comparada con la compresión eléctrica, pero es ideal si tienes calor residual o vapor 'gratis'." , question: "What is the typical COP of a single-stage absorption system?", options: ["3.0 to 4.0", "0.6 to 0.7", "10.0", "1.5"], explanation: "Energy efficiency is low compared to electric compression, but it is ideal when waste heat or free steam is available." },
  { id:"nate_576", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se usa una mezcla de Helio y Oxígeno en aplicaciones de buceo profundo o medicina?", opciones:["Para flotar", "Para reducir la densidad del gas respirado y evitar la narcosis de nitrógeno a gran profundidad", "Para enfriar los pulmones", "Para hablar chistoso"], respuesta_correcta:1, explicacion:"Aunque no es refrigeración directa, es una aplicación crítica de gases criogénicos en soporte de vida." , question: "What is a Helium-Oxygen mixture used for in deep diving or medical applications?", options: ["To float", "To reduce the density of the breathing gas and prevent nitrogen narcosis at great depth", "To cool the lungs", "To make your voice sound funny"], explanation: "Although not direct refrigeration, it is a critical application of cryogenic gases in life support." },
  { id:"nate_577", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras que el compresor de baja temperatura vibra violentamente al arrancar. ¿Qué revisarías?", opciones:["El gas", "Si el calentador de cárter funcionó correctamente para evitar la migración de refrigerante líquido al aceite", "La carga de las baterías", "El color del compresor"], respuesta_correcta:1, explicacion:"A ultra-baja temperatura, la migración es masiva. Sin calor en el cárter, el compresor intentará comprimir líquido." , question: "You find that the low-temperature compressor vibrates violently on startup. What would you check?", options: ["The gas", "Whether the crankcase heater operated correctly to prevent liquid refrigerant migration into the oil", "The battery charge", "The color of the compressor"], explanation: "At ultra-low temperatures, migration is massive. Without crankcase heat, the compressor will attempt to compress liquid." },
  { id:"nate_578", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prefiere el Acero Inoxidable 316L en tuberías criogénicas industriales?", opciones:["Porque es barato", "Porque mantiene su ductilidad y no se vuelve frágil a temperaturas bajo -150°C", "Porque es más ligero", "Porque no necesita soldadura"], respuesta_correcta:1, explicacion:"El acero al carbón se rompería como cristal a esas temperaturas. El inoxidable resiste el choque térmico." , question: "Why is 316L Stainless Steel preferred for industrial cryogenic piping?", options: ["Because it is cheap", "Because it maintains its ductility and does not become brittle at temperatures below -150°C", "Because it is lighter", "Because it does not need welding"], explanation: "Carbon steel would shatter like glass at those temperatures. Stainless steel withstands thermal shock." },
  { id:"nate_579", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué componente consume la mayor parte de la energía ELÉCTRICA en un sistema de absorción?", opciones:["El quemador", "La bomba de solución (que mueve el líquido del absorbedor al generador)", "El ventilador", "Las luces"], respuesta_correcta:1, explicacion:"Es el único motor eléctrico significativo en el sistema, pero su consumo es mínimo comparado con un compresor." , question: "What component consumes the most ELECTRICAL energy in an absorption system?", options: ["The burner", "The solution pump (which moves liquid from the absorber to the generator)", "The fan", "The lights"], explanation: "It is the only significant electric motor in the system, but its consumption is minimal compared to a compressor." },
  { id:"nate_580", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los separadores de aceite en cascadas de -80°C son tan grandes y complejos?", opciones:["Para que el técnico trabaje más", "Para garantizar un retorno del 99.9% del aceite antes de que entre al evaporador de ultra-baja, donde se congelaría", "Para enfriar el gas", "Para ahorrar gas"], respuesta_correcta:1, explicacion:"Cualquier rastro de aceite que llegue al evaporador se convertirá en 'cera' y bloqueará el flujo de refrigerante." , question: "Why are oil separators in -80°C cascade systems so large and complex?", options: ["To give the technician more work", "To ensure 99.9% oil return before it enters the ultra-low evaporator, where it would freeze", "To cool the gas", "To save gas"], explanation: "Any trace of oil reaching the evaporator will turn into wax and block refrigerant flow." },
  { id:"nate_581", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un Tubo de Vórtice (Vortex Tube)?", opciones:["Un ventilador circular", "Un dispositivo mecánico que separa el aire comprimido en corrientes de aire caliente y aire frío sin partes móviles", "Un tipo de compresor", "Un sensor de flujo"], respuesta_correcta:1, explicacion:"Se usa para enfriamiento puntual en máquinas herramientas. Es pura física de fluidos." , question: "What is a Vortex Tube?", options: ["A circular fan", "A mechanical device that separates compressed air into hot and cold air streams without moving parts", "A type of compressor", "A flow sensor"], explanation: "It is used for spot cooling on machine tools. It is pure fluid dynamics." },
  { id:"nate_582", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué precaución se debe tener con los manómetros usados en sistemas de Oxígeno Líquido?", opciones:["Que sean de plástico", "Deben estar certificados como 'Libres de Aceite' (Oil-Free) para evitar explosiones espontáneas", "Que sean digitales", "No se pueden usar manómetros"], respuesta_correcta:1, explicacion:"El oxígeno puro reacciona violentamente (combustión) con cualquier traza de hidrocarburo o aceite." , question: "What precaution must be taken with pressure gauges used on Liquid Oxygen systems?", options: ["They must be plastic", "They must be certified as Oil-Free to prevent spontaneous explosions", "They must be digital", "Pressure gauges cannot be used"], explanation: "Pure oxygen reacts violently (combustion) with any trace of hydrocarbon or oil." },
  { id:"nate_583", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un ultracongelador tarda hasta 24 horas en llegar de 25°C a -80°C?", opciones:["Porque el compresor es lento", "Por la inmensa masa térmica que debe enfriar y para permitir una estabilización gradual de las presiones de ambas etapas", "Porque no tiene gas", "Para ahorrar luz"], respuesta_correcta:1, explicacion:"Apurar el proceso podría causar choques térmicos en los metales o fallas por presión en el intercambiador de cascada." , question: "Why does an ultra-low freezer take up to 24 hours to go from 25°C to -80°C?", options: ["Because the compressor is slow", "Due to the immense thermal mass that must be cooled and to allow gradual pressure stabilization of both stages", "Because it has no gas", "To save electricity"], explanation: "Rushing the process could cause thermal shock in the metals or pressure failures in the cascade heat exchanger." },
  { id:"nate_584", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede en un Chiller de absorción si entran gases no-condensables (aire)?", opciones:["Enfría mejor", "La presión interna sube, la capacidad cae drásticamente y la solución de bromuro de litio puede cristalizarse (volverse sólida)", "El agua hierve", "Se apaga la luz"], respuesta_correcta:1, explicacion:"La cristalización es la peor pesadilla en absorción; requiere calentar toda la máquina para volver la sal a estado líquido." , question: "What happens in an absorption chiller if non-condensable gases (air) enter the system?", options: ["It cools better", "Internal pressure rises, capacity drops drastically, and the lithium bromide solution may crystallize (turn solid)", "The water boils", "The light turns off"], explanation: "Crystallization is the worst nightmare in absorption; it requires heating the entire machine to return the salt to a liquid state." },
  { id:"nate_585", categoria:"NATE_INDUSTRIAL", pregunta:"¿A qué temperatura ocurre la sublimación del Hielo Seco (CO2 sólido)?", opciones:["0°C", "-78.5°C (-109.3°F)", "-20°C", "100°C"], respuesta_correcta:1, explicacion:"Es la temperatura constante a la que se mantiene el hielo seco mientras se evapora directamente a gas." , question: "At what temperature does Dry Ice (solid CO2) sublimate?", options: ["0°C", "-78.5°C (-109.3°F)", "-20°C", "100°C"], explanation: "It is the constant temperature at which dry ice sublimates directly into gas." },
  { id:"nate_586", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un sistema de 'Refrigerante Mixto' (MR) usado en plantas de GNL?", opciones:["Mezclar R-22 con R-410A", "Un solo ciclo de refrigeración que usa una mezcla de nitrógeno, metano, etano y propano para enfriar en un amplio rango de temperaturas", "Usar agua y aceite", "Es un error de carga"], respuesta_correcta:1, explicacion:"Permite licuar Gas Natural de forma eficiente aprovechando los diferentes puntos de ebullición de la mezcla." , question: "What is a Mixed Refrigerant (MR) system used in LNG plants?", options: ["Mixing R-22 with R-410A", "A single refrigeration cycle that uses a blend of nitrogen, methane, ethane, and propane to cool across a wide temperature range", "Using water and oil", "It is a charging error"], explanation: "It allows efficient liquefaction of Natural Gas by taking advantage of the different boiling points of the mixture." },
  { id:"nate_587", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la causa más común de cristalización en un sistema de Bromuro de Litio?", opciones:["Falta de energía", "Falla en la torre de enfriamiento o entrada de aire al sistema (pérdida de vacío)", "Mucho calor", "Agua muy limpia"], respuesta_correcta:1, explicacion:"Si la solución se enfría demasiado o se concentra de más por falta de purga, se vuelve sólida como sal de mesa." , question: "What is the most common cause of crystallization in a Lithium Bromide system?", options: ["Power failure", "Cooling tower failure or air infiltration into the system (loss of vacuum)", "Too much heat", "Very clean water"], explanation: "If the solution cools too much or becomes over-concentrated due to lack of purging, it solidifies like table salt." },
  { id:"nate_588", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué gas es el R-170?", opciones:["Metano", "Etano", "Propano", "Butano"], respuesta_correcta:1, explicacion:"Es un refrigerante natural muy usado en la etapa de baja de cascadas por su bajísimo punto de ebullición." , question: "What gas is R-170?", options: ["Methane", "Ethane", "Propane", "Butane"], explanation: "It is a natural refrigerant widely used in the low stage of cascade systems due to its extremely low boiling point." },
  { id:"nate_589", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué unidad de medida se usa para vacíos profundos en liofilización industrial?", opciones:["psig", "mTorr (miliTorr) o Micrones", "Bar", "Pulgadas de Mercurio"], respuesta_correcta:1, explicacion:"En estos procesos, 1 pulgada de mercurio es una medida demasiado grosera. Se requieren milésimas de Torr." , question: "What unit of measurement is used for deep vacuums in industrial freeze-drying?", options: ["psig", "mTorr (milliTorr) or Microns", "Bar", "Inches of Mercury"], explanation: "In these processes, 1 inch of mercury is far too coarse a measurement. Thousandths of a Torr are required." },
  { id:"nate_590", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja de un refrigerador de ciclo Stirling?", opciones:["Es muy ruidoso", "Puede alcanzar temperaturas criogénicas en un solo paso con altísima eficiencia y sin válvulas", "Es barato", "Usa mucha agua"], respuesta_correcta:1, explicacion:"Se usa en satélites y cámaras infrarrojas de alta tecnología." , question: "What is the advantage of a Stirling cycle refrigerator?", options: ["It is very noisy", "It can reach cryogenic temperatures in a single step with very high efficiency and no valves", "It is cheap", "It uses a lot of water"], explanation: "It is used in satellites and high-tech infrared cameras." },
  { id:"nate_591", categoria:"NATE_INDUSTRIAL", pregunta:"Un ultracongelador marca -72°C en lugar de -80°C y el compresor de etapa alta no para nunca. ¿Qué revisas?", opciones:["La luz del cuarto", "Si el condensador de la etapa alta está sucio o el ventilador falló", "Si la puerta está abierta", "El gas de la etapa baja"], respuesta_correcta:1, explicacion:"Si la etapa alta pierde eficiencia, no puede enfriar bien el condensador de la etapa baja, limitando el enfriamiento final." , question: "An ultra-low freezer reads -72°C instead of -80°C and the high-stage compressor never shuts off. What do you check?", options: ["The room lights", "Whether the high-stage condenser is dirty or the fan has failed", "Whether the door is open", "The low-stage refrigerant charge"], explanation: "If the high stage loses efficiency, it cannot properly cool the low-stage condenser, limiting the final cooling capacity." },
  { id:"nate_592", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se añade Cromato de Litio a los sistemas de absorción?", opciones:["Para que el agua se vea amarilla", "Para formar una capa protectora interna en el acero y evitar la corrosión por el bromuro de litio", "Para limpiar el sistema", "Para que huela mejor"], respuesta_correcta:1, explicacion:"El bromuro de litio es una sal muy corrosiva; sin inhibidores, destruiría el Chiller en pocos meses." , question: "Why is Lithium Chromate added to absorption systems?", options: ["To make the water look yellow", "To form a protective internal layer on the steel and prevent corrosion from lithium bromide", "To clean the system", "To make it smell better"], explanation: "Lithium bromide is a highly corrosive salt; without inhibitors, it would destroy the chiller within months." },
  { id:"nate_593", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué le sucede a ciertos metales cuando se enfrían con Helio Líquido (-269°C)?", opciones:["Se vuelven aislantes", "Se vuelven superconductores (resistencia eléctrica cero)", "Se deshacen", "Cambian de color"], respuesta_correcta:1, explicacion:"Es la base de las máquinas de Resonancia Magnética (MRI) en los hospitales." , question: "What happens to certain metals when cooled with Liquid Helium (-269°C)?", options: ["They become insulators", "They become superconductors (zero electrical resistance)", "They disintegrate", "They change color"], explanation: "This is the basis of MRI (Magnetic Resonance Imaging) machines in hospitals." },
  { id:"nate_594", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se deben usar guantes de látex o cuero ajustados al manejar nitrógeno líquido?", opciones:["Porque se rompen", "Porque si el líquido cae dentro, el guante lo atrapa contra tu piel causando una quemadura instantánea; deben usarse guantes criogénicos holgados", "Porque son feos", "Porque el nitrógeno los quema"], respuesta_correcta:1, explicacion:"Los guantes criogénicos permiten sacárselos rápidamente si algo de líquido entra." , question: "Why should tight-fitting latex or leather gloves not be worn when handling liquid nitrogen?", options: ["Because they tear", "Because if liquid spills inside, the glove traps it against your skin causing an instant burn; loose-fitting cryogenic gloves must be used", "Because they are ugly", "Because nitrogen burns them"], explanation: "Cryogenic gloves can be removed quickly if any liquid gets inside." },
  { id:"nate_595", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es una 'Válvula de Alivio de Dos Etapas'?", opciones:["Una válvula con dos resortes", "Un sistema de seguridad que protege al sistema si la presión sube por falla de enfriamiento de la cascada", "Una válvula para gas", "Una válvula para aceite"], respuesta_correcta:1, explicacion:"Garantiza que el refrigerante caro de la etapa baja no se pierda ante un pico menor de presión." , question: "What is a Two-Stage Relief Valve?", options: ["A valve with two springs", "A safety system that protects the system if pressure rises due to cascade cooling failure", "A gas valve", "An oil valve"], explanation: "It ensures that the expensive low-stage refrigerant is not lost during a minor pressure spike." },
  { id:"nate_596", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué caracteriza a un Chiller de absorción de 'Triple Efecto'?", opciones:["Que es tres veces más grande", "Usa tres generadores en serie para maximizar el uso del calor, alcanzando COPs de 1.7 o más", "Que usa tres tipos de sal", "Que no usa agua"], respuesta_correcta:1, explicacion:"Es la tecnología de absorción más avanzada y eficiente del mundo." , question: "What characterizes a Triple-Effect absorption chiller?", options: ["It is three times larger", "It uses three generators in series to maximize heat utilization, achieving COPs of 1.7 or higher", "It uses three types of salt", "It does not use water"], explanation: "It is the most advanced and efficient absorption technology in the world." },
  { id:"nate_597", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se obtiene el Oxígeno y Nitrógeno puro de forma industrial?", opciones:["Mediante reacciones químicas", "Mediante destilación fraccionada del aire líquido a temperaturas criogénicas", "Usando filtros de papel", "Succionándolo con bombas"], respuesta_correcta:1, explicacion:"Se enfría el aire hasta volverlo líquido y luego se 'hierve' poco a poco para separar cada gas por su punto de ebullición." , question: "How are pure Oxygen and Nitrogen obtained industrially?", options: ["Through chemical reactions", "Through fractional distillation of liquid air at cryogenic temperatures", "Using paper filters", "Sucking it out with pumps"], explanation: "Air is cooled until it becomes liquid, then slowly boiled to separate each gas by its boiling point." },
  { id:"nate_598", categoria:"NATE_INDUSTRIAL", pregunta:"Escuchas un sonido de 'cascada' o agua corriendo dentro de un Chiller de absorción. ¿Es normal?", opciones:["No, hay una fuga", "Sí, es el flujo de la solución de bromuro de litio cayendo sobre los tubos del absorbedor", "Es el gas que se sale", "La bomba está rota"], respuesta_correcta:1, explicacion:"A diferencia de los sistemas de compresión, en absorción el movimiento de líquidos es constante y audible." , question: "You hear a cascading or running water sound inside an absorption chiller. Is this normal?", options: ["No, there is a leak", "Yes, it is the flow of lithium bromide solution falling over the absorber tubes", "It is gas escaping", "The pump is broken"], explanation: "Unlike compression systems, in absorption systems the movement of liquids is constant and audible." },
  { id:"nate_599", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de ultra-baja temperatura, ¿qué es el 'Oil Log' en el evaporador?", opciones:["Un registro de aceite", "La acumulación de aceite congelado en las paredes del evaporador que actúa como aislante y bloquea el intercambio de calor", "Un filtro de aceite", "Una bomba de aceite"], respuesta_correcta:1, explicacion:"Es la falla más difícil de diagnosticar; el sistema parece tener gas pero no enfría porque el aceite 'tapizó' el cobre por dentro." , question: "In an ultra-low temperature system, what is Oil Logging in the evaporator?", options: ["An oil record", "The accumulation of frozen oil on the evaporator walls that acts as insulation and blocks heat exchange", "An oil filter", "An oil pump"], explanation: "It is the most difficult fault to diagnose; the system appears to have refrigerant but does not cool because oil has coated the copper internally." },
  { id:"nate_600", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la principal ventaja de una bomba de calor geotérmica (Ground Source Heat Pump) frente a una de aire?", opciones:["Es más barata de instalar", "Aprovecha la temperatura constante del subsuelo, manteniendo un COP alto incluso en inviernos extremos", "No usa refrigerante", "No necesita electricidad"], respuesta_correcta:1, explicacion:"A unos metros bajo tierra, la temperatura es constante (aprox. 55°F). Esto hace que el equipo siempre trabaje en condiciones ideales, a diferencia del aire exterior que varía mucho." , question: "What is the main advantage of a Ground Source Heat Pump (geothermal) over an air-source unit?", options: ["It is cheaper to install", "It leverages the constant underground temperature, maintaining a high COP even in extreme winters", "It does not use refrigerant", "It does not need electricity"], explanation: "A few feet underground, the temperature is constant (approximately 55°F). This allows the equipment to always operate under ideal conditions, unlike outdoor air which varies widely." },
  { id:"nate_601", categoria:"NATE_INDUSTRIAL", pregunta:"¿En qué consiste un sistema geotérmico de 'Lazo Abierto' (Open Loop)?", opciones:["Usa aire de la calle", "Succiona agua directamente de un pozo o acuífero, extrae/cede calor y la descarga en otro pozo o cuerpo de agua", "No tiene tuberías", "Usa glicol en un circuito cerrado"], respuesta_correcta:1, explicacion:"Es altamente eficiente pero requiere un suministro de agua abundante y permisos ambientales por el manejo del agua del subsuelo." , question: "What does an Open Loop geothermal system consist of?", options: ["It uses outdoor air", "It draws water directly from a well or aquifer, extracts or rejects heat, and discharges it into another well or body of water", "It has no piping", "It uses glycol in a closed circuit"], explanation: "It is highly efficient but requires an abundant water supply and environmental permits for groundwater management." },
  { id:"nate_602", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el propósito de un sistema de 'Ice Storage' (Almacenamiento de Hielo) en un edificio comercial?", opciones:["Vender hielo a los empleados", "Fabricar hielo por la noche (luz barata) para usarlo como enfriamiento durante el día (pico de demanda y luz cara)", "Enfriar el servidor", "Reducir el tamaño de los ductos"], respuesta_correcta:1, explicacion:"Es una estrategia de 'Peak Shaving'. Reduce masivamente los costos operativos al desplazar el consumo eléctrico a horas valle." , question: "What is the purpose of an Ice Storage system in a commercial building?", options: ["To sell ice to employees", "To make ice at night (cheap electricity) to use as cooling during the day (peak demand and expensive electricity)", "To cool the server room", "To reduce duct size"], explanation: "It is a Peak Shaving strategy. It massively reduces operating costs by shifting electrical consumption to off-peak hours." },
  { id:"nate_603", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo funciona un aire acondicionado asistido por energía Solar Térmica?", opciones:["Usa paneles solares para hacer electricidad", "Usa colectores solares para calentar el refrigerante antes del compresor, reduciendo el trabajo mecánico necesario para la compresión", "Funciona con espejos", "Solo funciona de día"], respuesta_correcta:1, explicacion:"El calor del sol ayuda a elevar la presión y temperatura del gas, haciendo que el compresor trabaje menos tiempo o a menor frecuencia." , question: "How does a Solar Thermal-assisted air conditioner work?", options: ["It uses solar panels to generate electricity", "It uses solar collectors to heat the refrigerant before the compressor, reducing the mechanical work required for compression", "It works with mirrors", "It only works during the day"], explanation: "Solar heat helps raise the gas pressure and temperature, making the compressor run less time or at lower frequency." },
  { id:"nate_604", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se usa una mezcla de agua y anticongelante en los lazos cerrados geotérmicos horizontales?", opciones:["Para que el agua no se pudra", "Para evitar que el fluido se congele dentro de las tuberías enterradas durante el invierno cuando se extrae calor", "Para lubricar la bomba de lodo", "Para que las tuberías no se oxiden"], respuesta_correcta:1, explicacion:"Aunque la tierra esté a 55°F, el fluido dentro del tubo puede bajar de 32°F al ceder su calor al evaporador del equipo." , question: "Why is a water-antifreeze mixture used in horizontal closed-loop geothermal systems?", options: ["To prevent the water from rotting", "To prevent the fluid from freezing inside the buried pipes during winter when heat is being extracted", "To lubricate the mud pump", "To prevent pipe corrosion"], explanation: "Although the ground is at 55°F, the fluid inside the pipe can drop below 32°F when giving up its heat to the equipment evaporator." },
  { id:"nate_605", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué componente es necesario para conectar un aire acondicionado estándar de 220V a un sistema de paneles solares DC?", opciones:["Un transformador", "Un Inversor de Corriente (Inverter) que convierta DC en AC", "Una batería de auto", "Un contactor especial"], respuesta_correcta:1, explicacion:"Los paneles generan corriente directa; el inversor es el que 'fabrica' la corriente alterna que el equipo necesita." , question: "What component is needed to connect a standard 220V AC air conditioner to a DC solar panel system?", options: ["A transformer", "A power inverter that converts DC to AC", "A car battery", "A special contactor"], explanation: "The panels generate direct current; the inverter produces the alternating current that the equipment needs." },
  { id:"nate_606", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Desuperheater' en una unidad geotérmica?", opciones:["Un filtro de gas", "Un intercambiador pequeño que usa el calor de descarga del compresor para calentar agua doméstica gratis", "Un ventilador de alta velocidad", "Un sensor de humedad"], respuesta_correcta:1, explicacion:"Es una de las funciones más populares en geotermia, ya que proporciona agua caliente casi sin costo adicional." , question: "What is a Desuperheater in a geothermal unit?", options: ["A gas filter", "A small heat exchanger that uses compressor discharge heat to heat domestic hot water for free", "A high-speed fan", "A humidity sensor"], explanation: "It is one of the most popular features in geothermal systems, providing hot water at almost no additional cost." },
  { id:"nate_607", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la profundidad típica de un pozo geotérmico vertical para una casa residencial?", opciones:["10 a 20 pies", "150 a 400 pies por cada tonelada de refrigeración", "1,000 pies fijos", "Depende de la altura de la casa"], respuesta_correcta:1, explicacion:"La longitud del pozo determina cuánta transferencia de calor puede realizar el sistema. A mayor carga, más profundidad se requiere." , question: "What is the typical depth of a vertical geothermal borehole for a residential home?", options: ["10 to 20 feet", "150 to 400 feet per ton of refrigeration", "1,000 feet fixed", "It depends on the height of the house"], explanation: "The borehole length determines how much heat transfer the system can perform. The greater the load, the more depth is required." },
  { id:"nate_608", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los sistemas de almacenamiento térmico prefieren congelar agua en lugar de solo enfriarla?", opciones:["Porque el hielo ocupa menos espacio", "Para aprovechar el Calor Latente de Fusión (144 BTU/lb), que almacena mucha más energía que el calor sensible", "Porque el hielo es más limpio", "Para que no se evapore"], respuesta_correcta:1, explicacion:"Cambiar el estado del agua absorbe una cantidad masiva de energía, lo que permite tanques de almacenamiento más compactos." , question: "Why do thermal storage systems prefer to freeze water instead of just chilling it?", options: ["Because ice takes up less space", "To take advantage of the Latent Heat of Fusion (144 BTU/lb), which stores much more energy than sensible heat", "Because ice is cleaner", "To prevent evaporation"], explanation: "Changing the state of water absorbs a massive amount of energy, allowing for more compact storage tanks." },
  { id:"nate_609", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo se aplica la energía solar en un Chiller de Absorción?", opciones:["Usando paneles fotovoltaicos", "Usando agua caliente de colectores solares como fuente de calor para el Generador del ciclo de absorción", "Reflejando luz en el condensador", "No se puede"], respuesta_correcta:1, explicacion:"Es la forma más pura de 'enfriar con calor'. El sol calienta el agua que hace funcionar el ciclo químico del Chiller." , question: "How is solar energy applied in an Absorption Chiller?", options: ["Using photovoltaic panels", "Using hot water from solar collectors as the heat source for the Generator in the absorption cycle", "Reflecting light on the condenser", "It cannot be done"], explanation: "It is the purest form of cooling with heat. The sun heats the water that drives the chemical cycle of the chiller." },
  { id:"nate_610", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué material se usa casi exclusivamente para los lazos enterrados en geotermia debido a su durabilidad de más de 50 años?", opciones:["Cobre tipo K", "Polietileno de Alta Densidad (HDPE) con uniones por termofusión", "PVC cédula 40", "Hierro galvanizado"], respuesta_correcta:1, explicacion:"El HDPE es flexible, resistente a la corrosión del suelo y la termofusión hace que las uniones sean más fuertes que el tubo mismo." , question: "What material is used almost exclusively for buried geothermal loops due to its 50+ year durability?", options: ["Type K Copper", "High-Density Polyethylene (HDPE) with heat-fused joints", "Schedule 40 PVC", "Galvanized iron"], explanation: "HDPE is flexible, resistant to soil corrosion, and heat-fused joints are stronger than the pipe itself." },
  { id:"nate_611", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué el EER de un sistema geotérmico puede llegar a 30 o 40, mientras que uno de aire difícilmente pasa de 15?", opciones:["Porque el compresor es mágico", "Porque el 'disipador' (la tierra) está a 55°F en lugar de los 95°F del aire exterior en verano", "Porque no tiene ventilador exterior", "Porque usa menos refrigerante"], respuesta_correcta:1, explicacion:"La eficiencia depende del diferencial de temperatura. Es mucho más fácil rechazar calor a 55°F que a 100°F." , question: "Why can the EER of a geothermal system reach 30 or 40, while an air-source unit barely exceeds 15?", options: ["Because the compressor is magical", "Because the heat sink (the ground) is at 55°F instead of 95°F outdoor air in summer", "Because it has no outdoor fan", "Because it uses less refrigerant"], explanation: "Efficiency depends on the temperature differential. It is much easier to reject heat to 55°F than to 100°F." },
  { id:"nate_612", categoria:"NATE_INDUSTRIAL", pregunta:"En una planta de agua helada, ¿qué es un sistema 'Híbrido' Geotérmico?", opciones:["Que usa gas y luz", "Un sistema que combina un lazo geotérmico con una torre de enfriamiento para balancear el calor del suelo", "Que usa dos tipos de compresores", "Que funciona con agua y aceite"], respuesta_correcta:1, explicacion:"Evita que el suelo se caliente demasiado tras años de solo rechazar calor (enfriamiento), manteniendo la eficiencia a largo plazo." , question: "In a chilled water plant, what is a Hybrid Geothermal system?", options: ["One that uses gas and electricity", "A system that combines a geothermal loop with a cooling tower to balance ground heat", "One that uses two types of compressors", "One that runs on water and oil"], explanation: "It prevents the ground from overheating after years of only rejecting heat (cooling), maintaining long-term efficiency." },
  { id:"nate_613", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede en un aire acondicionado solar 100% DC si pasa una nube muy densa?", opciones:["Se quema el compresor", "El compresor reduce su velocidad instantáneamente o se apaga si no hay baterías de respaldo", "Sigue funcionando a tope", "Explota el inversor"], respuesta_correcta:1, explicacion:"Los motores DC en estos equipos varían su potencia según el voltaje que entregan los paneles en tiempo real." , question: "What happens to a 100% DC solar air conditioner if a very dense cloud passes over?", options: ["The compressor burns out", "The compressor instantly reduces speed or shuts down if there are no backup batteries", "It keeps running at full capacity", "The inverter explodes"], explanation: "DC motors in these units vary their power output based on the voltage delivered by the panels in real time." },
  { id:"nate_614", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras que la bomba de calor geotérmica se apaga por 'Low Pressure' en modo calefacción. El flujo de agua es correcto. ¿Qué revisas en el lazo?", opciones:["El nivel de aceite", "La concentración de anticongelante (el intercambiador de agua-refrigerante podría estar congelándose internamente)", "Si el sol salió hoy", "El filtro de aire"], respuesta_correcta:1, explicacion:"Si no hay suficiente anticongelante, el agua se convierte en escarcha dentro del intercambiador, bloqueando la transferencia de calor." , question: "You find that the geothermal heat pump trips on Low Pressure in heating mode. Water flow is correct. What do you check on the loop?", options: ["The oil level", "The antifreeze concentration (the water-to-refrigerant heat exchanger may be freezing internally)", "Whether the sun came out today", "The air filter"], explanation: "If there is not enough antifreeze, the water turns to frost inside the heat exchanger, blocking heat transfer." },
  { id:"nate_615", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Circulator Pump' en un sistema geotérmico?", opciones:["Una bomba de vacío", "La bomba que mueve el agua o glicol a través del lazo enterrado hacia el equipo", "Un ventilador", "Una bomba de condensado"], respuesta_correcta:1, explicacion:"Es el componente que vence la fricción de los cientos de pies de tubería HDPE enterrada." , question: "What is a Circulator Pump in a geothermal system?", options: ["A vacuum pump", "The pump that moves water or glycol through the buried loop to the equipment", "A fan", "A condensate pump"], explanation: "It is the component that overcomes the friction of the hundreds of feet of buried HDPE piping." },
  { id:"nate_616", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué es importante evitar la turbulencia dentro de un tanque de almacenamiento térmico de agua fría?", opciones:["Para que el agua no haga espuma", "Para mantener la estratificación (agua fría abajo, tibia arriba) y que el Chiller siempre reciba el agua más caliente", "Para que no se rompa el tanque", "Para que las bacterias no crezcan"], respuesta_correcta:1, explicacion:"La termoclina (capa de separación) permite usar el agua fría hasta la última gota sin que se mezcle con el retorno." , question: "Why is it important to avoid turbulence inside a chilled water thermal storage tank?", options: ["To prevent the water from foaming", "To maintain stratification (cold water at the bottom, warm water on top) so the chiller always receives the warmest water", "To prevent the tank from breaking", "To prevent bacterial growth"], explanation: "The thermocline (separation layer) allows using the cold water down to the last drop without it mixing with the return water." },
  { id:"nate_617", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Bentonite Grout' en una instalación geotérmica vertical?", opciones:["Un tipo de pegamento", "Un material de relleno térmicamente conductivo que sella el pozo y asegura el contacto entre el tubo y la tierra", "Un aislante", "Un refrigerante"], respuesta_correcta:1, explicacion:"Sin un buen grout, el aire actuaría como aislante dentro del pozo y el sistema no funcionaría." , question: "What is Bentonite Grout in a vertical geothermal installation?", options: ["A type of adhesive", "A thermally conductive fill material that seals the borehole and ensures contact between the pipe and the earth", "An insulator", "A refrigerant"], explanation: "Without proper grout, air would act as insulation inside the borehole and the system would not work." },
  { id:"nate_618", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un sistema de 'Deshumidificación Desecante Solar'?", opciones:["Un ventilador con sol", "Usa calor solar para 'secar' (regenerar) una rueda desecante que quita la humedad del aire del edificio", "Un tipo de filtro", "Un aire acondicionado de ventana"], respuesta_correcta:1, explicacion:"Es excelente en climas húmedos: el sol hace el trabajo pesado de quitar la humedad y el AC solo baja la temperatura." , question: "What is a Solar Desiccant Dehumidification system?", options: ["A fan with sun", "It uses solar heat to dry (regenerate) a desiccant wheel that removes humidity from the building air", "A type of filter", "A window air conditioner"], explanation: "It is excellent in humid climates: the sun does the heavy lifting of removing humidity and the AC only lowers the temperature." },
  { id:"nate_619", categoria:"NATE_INDUSTRIAL", pregunta:"Si un sistema HVAC solar genera más energía de la que consume el equipo, ¿qué sucede en un esquema de 'Net Metering'?", opciones:["La energía se pierde", "El exceso de energía se inyecta a la red eléctrica y el medidor 'gira hacia atrás' (crédito a favor)", "Se queman los cables", "El equipo enfría más"], respuesta_correcta:1, explicacion:"Es el incentivo financiero principal para instalar sistemas solares conectados a la red." , question: "If a solar HVAC system generates more energy than the equipment consumes, what happens under a Net Metering arrangement?", options: ["The energy is wasted", "The excess energy is fed back into the electrical grid and the meter spins backward (credit to the owner)", "The wires burn out", "The equipment cools more"], explanation: "It is the primary financial incentive for installing grid-connected solar systems." },
  { id:"nate_620", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué ventaja ofrece el uso de CO2 como refrigerante en una bomba de calor geotérmica?", opciones:["Es más barato", "Capacidad superior para producir agua muy caliente (160°F+) para calefacción por radiadores con alta eficiencia", "No necesita tubos", "Es menos ruidoso"], respuesta_correcta:1, explicacion:"El CO2 transcrítico es excelente para aplicaciones de calefacción de alta temperatura partiendo de fuentes frías." , question: "What advantage does using CO2 as a refrigerant offer in a geothermal heat pump?", options: ["It is cheaper", "Superior capacity to produce very hot water (160°F+) for radiator heating with high efficiency", "It does not need pipes", "It is quieter"], explanation: "Transcritical CO2 is excellent for high-temperature heating applications starting from cold sources." },
  { id:"nate_621", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la profundidad mínima para enterrar un lazo geotérmico horizontal para evitar que el clima superficial lo afecte?", opciones:["1 pie", "4 a 6 pies", "50 pies", "No importa la profundidad"], respuesta_correcta:1, explicacion:"A esa profundidad, la temperatura del suelo empieza a ser estable y no se ve afectada por las heladas o el sol directo diario." , question: "What is the minimum depth for burying a horizontal geothermal loop to avoid surface climate effects?", options: ["1 foot", "4 to 6 feet", "50 feet", "Depth does not matter"], explanation: "At that depth, the ground temperature begins to be stable and is not affected by frost or direct daily sunlight." },
  { id:"nate_622", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un panel PVT?", opciones:["Un panel de plástico", "Un panel híbrido que genera electricidad (PV) y agua caliente (Térmico) simultáneamente", "Un sensor de luz", "Un tipo de soporte"], respuesta_correcta:1, explicacion:"Al enfriar las celdas fotovoltaicas con agua, estas producen más electricidad y el agua caliente se usa para el sistema HVAC." , question: "What is a PVT panel?", options: ["A plastic panel", "A hybrid panel that generates electricity (PV) and hot water (Thermal) simultaneously", "A light sensor", "A type of mounting bracket"], explanation: "By cooling the photovoltaic cells with water, they produce more electricity and the heated water is used for the HVAC system." },
  { id:"nate_623", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué mide un 'Heat of Extraction' (HOE) en un diagnóstico geotérmico?", opciones:["La temperatura del aire", "La cantidad real de calor que el equipo está logrando sacar de la tierra por cada tonelada", "El consumo de agua", "La profundidad del pozo"], respuesta_correcta:1, explicacion:"Es la prueba de rendimiento real: si el HOE es bajo, el lazo subterráneo está mal diseñado o fallando." , question: "What does Heat of Extraction (HOE) measure in a geothermal diagnostic?", options: ["Air temperature", "The actual amount of heat the equipment is managing to pull from the ground per ton", "Water consumption", "Borehole depth"], explanation: "It is the real performance test: if the HOE is low, the underground loop is poorly designed or failing." },
  { id:"nate_624", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de almacenamiento de hielo de 'Lazo Cerrado', ¿qué circula por dentro de los serpentines del tanque?", opciones:["Refrigerante R-410A", "Una solución de Glicol al 25-30% enfriada por el Chiller a unos 22°F", "Agua pura", "Aire frío"], respuesta_correcta:1, explicacion:"El glicol no se congela y permite enfriar el agua del tanque hasta convertirla en hielo por fuera del tubo." , question: "In a closed-loop ice storage system, what circulates inside the coils of the tank?", options: ["R-410A refrigerant", "A 25-30% Glycol solution chilled by the chiller to approximately 22°F", "Pure water", "Cold air"], explanation: "The glycol does not freeze and allows cooling the tank water until it turns to ice on the outside of the coil." },
  { id:"nate_625", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prefieren los microinversores en instalaciones HVAC solares con sombras parciales?", opciones:["Son más grandes", "Porque permiten que cada panel funcione de forma independiente; si una sombra tapa un panel, los demás siguen al 100%", "No necesitan cables", "Son para interior"], respuesta_correcta:1, explicacion:"En un inversor de cadena (string), una sola sombra reduce la producción de toda la serie de paneles." , question: "Why are microinverters preferred in solar HVAC installations with partial shading?", options: ["They are larger", "Because they allow each panel to operate independently; if shade covers one panel, the rest continue at 100%", "They do not need wires", "They are for indoor use"], explanation: "With a string inverter, a single shadow reduces the output of the entire series of panels." },
  { id:"nate_626", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Slinky Loop' en geotermia?", opciones:["Un juguete", "Tubería HDPE colocada en forma de círculos superpuestos para maximizar la superficie de contacto en trincheras cortas", "Un tipo de compresor", "Un sensor de presión"], respuesta_correcta:1, explicacion:"Permite instalar más pies de tubo en menos espacio de excavación." , question: "What is a Slinky Loop in geothermal systems?", options: ["A toy", "HDPE pipe laid in overlapping circles to maximize contact surface area in short trenches", "A type of compressor", "A pressure sensor"], explanation: "It allows installing more feet of pipe in less excavation space." },
  { id:"nate_627", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema geotérmico de agua-agua, ¿qué es la 'Compensación Climática'?", opciones:["Pedir perdón al clima", "Ajustar automáticamente la temperatura del agua de suministro según la temperatura exterior (Outdoor Reset)", "Cambiar el gas en invierno", "Apagar el equipo si llueve"], respuesta_correcta:1, explicacion:"Si afuera no hace tanto frío, el equipo produce agua menos caliente para ahorrar energía." , question: "In a water-to-water geothermal system, what is Outdoor Reset (weather compensation)?", options: ["Apologizing to the climate", "Automatically adjusting the supply water temperature based on the outdoor temperature", "Changing the gas in winter", "Shutting off the equipment if it rains"], explanation: "If it is not very cold outside, the equipment produces less hot water to save energy." },
  { id:"nate_628", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función de una batería de Litio (ESS) en un sistema HVAC solar off-grid?", opciones:["Hacer el equipo más pesado", "Almacenar energía durante el día para poder operar el aire acondicionado por la noche", "Filtrar la electricidad", "Medir el amperaje"], respuesta_correcta:1, explicacion:"Es lo que permite la independencia total de la red eléctrica." , question: "What is the function of a Lithium battery (ESS) in an off-grid solar HVAC system?", options: ["To make the equipment heavier", "To store energy during the day to operate the air conditioner at night", "To filter electricity", "To measure amperage"], explanation: "It is what enables total independence from the electrical grid." },
  { id:"nate_629", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Pond Loop' (lazo de estanque)?", opciones:["Ductos en una alberca", "Colocar los lazos de tubería HDPE en el fondo de un lago o estanque profundo en lugar de enterrarlos", "Enfriar con lluvia", "Un tipo de drenaje"], respuesta_correcta:1, explicacion:"Es la forma más barata de instalar geotermia si el cliente tiene un cuerpo de agua lo suficientemente grande y profundo." , question: "What is a Pond Loop?", options: ["Ducts in a swimming pool", "Placing HDPE pipe loops at the bottom of a lake or deep pond instead of burying them", "Cooling with rain", "A type of drain"], explanation: "It is the cheapest way to install a geothermal system if the client has a sufficiently large and deep body of water." },
  { id:"nate_630", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo afecta la humedad relativa alta a la eficiencia de un colector solar de aire?", opciones:["La aumenta", "La reduce ligeramente debido a la absorción de parte de la radiación por el vapor de agua en la atmósfera", "No la afecta", "Apaga los paneles"], respuesta_correcta:1, explicacion:"El aire muy húmedo es menos transparente a ciertas longitudes de onda solares." , question: "How does high relative humidity affect the efficiency of a solar air collector?", options: ["It increases it", "It slightly reduces it due to absorption of some radiation by water vapor in the atmosphere", "It does not affect it", "It shuts down the panels"], explanation: "Very humid air is less transparent to certain solar wavelengths." },
  { id:"nate_631", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el flujo de agua estándar en el lazo geotérmico para un funcionamiento eficiente?", opciones:["0.1 GPM/ton", "3.0 GPM/ton por cada tonelada de capacidad", "10 GPM fijos", "El máximo de la bomba"], respuesta_correcta:1, explicacion:"Es el flujo balanceado para obtener la transferencia de calor óptima sin gastar energía excesiva en el bombeo." , question: "What is the standard water flow rate in a geothermal loop for efficient operation?", options: ["0.1 GPM/ton", "3.0 GPM per ton of capacity", "10 GPM fixed", "Maximum pump output"], explanation: "It is the balanced flow rate for optimal heat transfer without spending excessive energy on pumping." },
  { id:"nate_632", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el ángulo de inclinación ideal para paneles solares en un sistema HVAC que se usará principalmente en VERANO?", opciones:["Latitud del lugar + 15 grados", "Latitud del lugar - 15 grados (más plano para captar el sol alto de verano)", "90 grados vertical", "0 grados plano"], respuesta_correcta:1, explicacion:"Optimizar el ángulo para la estación de mayor consumo maximiza el ahorro económico." , question: "What is the ideal tilt angle for solar panels in an HVAC system used primarily in SUMMER?", options: ["Latitude of location + 15 degrees", "Latitude of location - 15 degrees (flatter to capture the high summer sun)", "90 degrees vertical", "0 degrees flat"], explanation: "Optimizing the angle for the season of highest consumption maximizes economic savings." },
  { id:"nate_633", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los colectores solares de tubos de vacío son mejores que los planos para sistemas de absorción?", opciones:["Son más ligeros", "Pueden alcanzar temperaturas mucho más altas (más de 180°F) con mínimas pérdidas térmicas", "Son más baratos", "No se rompen"], respuesta_correcta:1, explicacion:"El vacío es el mejor aislante; permite captar calor incluso en días nublados o fríos." , question: "Why are evacuated tube solar collectors better than flat-plate collectors for absorption systems?", options: ["They are lighter", "They can reach much higher temperatures (over 180°F) with minimal thermal losses", "They are cheaper", "They do not break"], explanation: "The vacuum is the best insulator; it allows capturing heat even on cloudy or cold days." },
  { id:"nate_634", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un pozo de 'Columna Estacionaria'?", opciones:["Un pozo seco", "Un pozo profundo de agua donde la misma agua se succiona de abajo y se regresa arriba, usando la roca como intercambiador", "Un tubo de PVC", "Una torre de agua"], respuesta_correcta:1, explicacion:"Se usa en zonas con roca sólida y mucha agua, requiriendo menos espacio que los pozos verticales múltiples." , question: "What is a Standing Column Well?", options: ["A dry well", "A deep water well where the same water is drawn from the bottom and returned to the top, using the rock as a heat exchanger", "A PVC pipe", "A water tower"], explanation: "It is used in areas with solid rock and abundant water, requiring less space than multiple vertical boreholes." },
  { id:"nate_635", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo verificas si hay aire atrapado en un lazo geotérmico recién instalado?", opciones:["Viendo burbujas en el agua", "Escuchando ruidos de 'gurgle' en la bomba y observando fluctuaciones en la presión del lazo", "Midiendo el voltaje", "El equipo enfría más"], respuesta_correcta:1, explicacion:"El aire es el enemigo número uno de la transferencia de calor y puede causar cavitación en las bombas." , question: "How do you verify if there is trapped air in a newly installed geothermal loop?", options: ["Looking for bubbles in the water", "Listening for gurgling sounds at the pump and observing pressure fluctuations in the loop", "Measuring voltage", "The equipment cools more"], explanation: "Air is the number one enemy of heat transfer and can cause cavitation in the pumps." },
  { id:"nate_636", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué son los PCM (Phase Change Materials) avanzados?", opciones:["Plásticos para ductos", "Materiales (como sales o ceras) diseñados para congelar/derretir a temperaturas específicas (ej. 50°F) para guardar energía", "Un tipo de filtro", "Un gas refrigerante"], respuesta_correcta:1, explicacion:"Permiten 'guardar frío' sin necesidad de enfriar hasta los 32°F del agua, ahorrando energía en el Chiller." , question: "What are advanced PCMs (Phase Change Materials)?", options: ["Plastics for ducts", "Materials (such as salts or waxes) designed to freeze/melt at specific temperatures (e.g., 50°F) to store energy", "A type of filter", "A refrigerant gas"], explanation: "They allow storing cold without needing to chill down to 32°F like water, saving energy in the chiller." },
  { id:"nate_637", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo ayuda un colector solar de aire a una calefacción de gas en invierno?", opciones:["No ayuda", "Pre-calienta el aire de retorno antes de que entre al horno, reduciendo el consumo de gas", "Produce electricidad", "Enfría el ático"], respuesta_correcta:1, explicacion:"Es una forma de calefacción solar directa muy sencilla y efectiva." , question: "How does a solar air collector assist a gas furnace in winter?", options: ["It does not help", "It pre-heats the return air before it enters the furnace, reducing gas consumption", "It produces electricity", "It cools the attic"], explanation: "It is a very simple and effective form of direct solar heating." },
  { id:"nate_638", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un sistema geotérmico DX?", opciones:["Uno que usa agua", "Un sistema donde el refrigerante circula directamente por tubos de cobre enterrados (sin intercambiador de agua intermedio)", "Un equipo de ventana", "Un sistema sin compresor"], respuesta_correcta:1, explicacion:"Elimina una etapa de transferencia de calor, siendo muy eficiente, pero requiere mucha carga de refrigerante y cobre protegido." , question: "What is a DX (Direct Expansion) geothermal system?", options: ["One that uses water", "A system where the refrigerant circulates directly through copper pipes buried in the ground (no intermediate water heat exchanger)", "A window unit", "A system without a compressor"], explanation: "It eliminates one stage of heat transfer, making it very efficient, but requires a large refrigerant charge and protected copper." },
  { id:"nate_639", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué hace un equipo HVAC 'Smart Grid Ready'?", opciones:["Tiene Wi-Fi", "Puede recibir señales de la compañía eléctrica para reducir su consumo durante picos de demanda nacional", "Es muy inteligente", "Funciona con pilas"], respuesta_correcta:1, explicacion:"Ayuda a estabilizar la red eléctrica y a veces el usuario recibe descuentos por permitir este control." , question: "What does a Smart Grid Ready HVAC unit do?", options: ["It has Wi-Fi", "It can receive signals from the utility company to reduce its consumption during national peak demand periods", "It is very intelligent", "It runs on batteries"], explanation: "It helps stabilize the electrical grid and sometimes the user receives discounts for allowing this control." },
  { id:"nate_640", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el COP máximo teórico que puede alcanzar una bomba de calor geotérmica?", opciones:["1.0", "Alrededor de 4.0 a 5.0", "100.0", "0.5"], respuesta_correcta:1, explicacion:"Significa que por cada 1 kW de electricidad, el equipo entrega 4 o 5 kW de calor. Es 400-500% eficiente." , question: "What is the maximum theoretical COP that a geothermal heat pump can achieve?", options: ["1.0", "Around 4.0 to 5.0", "100.0", "0.5"], explanation: "It means that for every 1 kW of electricity, the equipment delivers 4 or 5 kW of heat. That is 400-500% efficient." },
  { id:"nate_641", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Solar Tracker'?", opciones:["Un GPS", "Un mecanismo motorizado que hace que los paneles sigan la trayectoria del sol durante el día", "Un sensor de luz", "Un medidor de nubes"], respuesta_correcta:1, explicacion:"Aumenta la producción de energía hasta un 30% al mantener los paneles siempre perpendiculares al sol." , question: "What is a Solar Tracker?", options: ["A GPS device", "A motorized mechanism that makes the panels follow the path of the sun throughout the day", "A light sensor", "A cloud meter"], explanation: "It increases energy production by up to 30% by keeping the panels always perpendicular to the sun." },
  { id:"nate_642", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede si un sistema geotérmico se usa SOLO para enfriamiento durante 20 años en un clima muy caliente?", opciones:["La tierra se enfría", "La temperatura del suelo sube gradualmente (Thermal Build-up), reduciendo la eficiencia del equipo cada año", "Se crea un volcán", "Nada, la tierra es infinita"], respuesta_correcta:1, explicacion:"El suelo no puede disipar el calor tan rápido como lo inyectamos. Se requiere un diseño que permita al suelo 'descansar'." , question: "What happens if a geothermal system is used ONLY for cooling for 20 years in a very hot climate?", options: ["The ground cools down", "The ground temperature gradually rises (Thermal Build-up), reducing the equipment efficiency each year", "A volcano forms", "Nothing, the earth is infinite"], explanation: "The soil cannot dissipate heat as fast as it is injected. A design that allows the ground to rest is required." },
  { id:"nate_643", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función de un Inversor Híbrido?", opciones:["Usar dos tipos de gas", "Gestionar simultáneamente los paneles solares, las baterías y la conexión a la red eléctrica", "Enfriar y calentar", "No necesita cables"], respuesta_correcta:1, explicacion:"Es el cerebro que decide de dónde tomar energía y dónde guardarla para que el AC nunca se apague." , question: "What is the function of a Hybrid Inverter?", options: ["To use two types of gas", "To simultaneously manage the solar panels, batteries, and electrical grid connection", "To cool and heat", "It does not need wires"], explanation: "It is the brain that decides where to draw energy from and where to store it so the AC never shuts off." },
  { id:"nate_644", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el componente que absorbe el calor en un colector solar plano?", opciones:["El vidrio", "La placa absorbedora (típicamente cobre pintado de negro selectivo)", "El marco de aluminio", "El aislamiento"], respuesta_correcta:1, explicacion:"Está diseñada para absorber la mayor cantidad de radiación y transferirla a los tubos con agua." , question: "What is the component that absorbs heat in a flat-plate solar collector?", options: ["The glass", "The absorber plate (typically copper with a selective black coating)", "The aluminum frame", "The insulation"], explanation: "It is designed to absorb the maximum amount of radiation and transfer it to the water tubes." },
  { id:"nate_645", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un diseño geotérmico debe minimizar la potencia de bombeo?", opciones:["Para que no haga ruido", "Porque si la bomba gasta mucha luz, el ahorro neto del sistema (COP) disminuye drásticamente", "Para que el agua no corra", "Para usar cables delgados"], respuesta_correcta:1, explicacion:"El objetivo es que la bomba consuma menos del 10% de la energía total del sistema." , question: "Why must a geothermal design minimize pumping power?", options: ["To reduce noise", "Because if the pump uses too much electricity, the net system savings (COP) decreases drastically", "To slow the water flow", "To use thinner wiring"], explanation: "The goal is for the pump to consume less than 10% of the total system energy." },
  { id:"nate_646", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es la 'Energía Solar de Concentración' (CSP)?", opciones:["Muchos paneles juntos", "Uso de espejos para concentrar la luz en un punto pequeño y alcanzar temperaturas de más de 500°F", "Lentes de aumento", "Un tipo de linterna"], respuesta_correcta:1, explicacion:"Se usa para mover turbinas de vapor o Chillers de absorción de triple efecto en grandes industrias." , question: "What is Concentrated Solar Power (CSP)?", options: ["Many panels together", "Using mirrors to concentrate light onto a small point and reach temperatures above 500°F", "Magnifying lenses", "A type of flashlight"], explanation: "It is used to drive steam turbines or triple-effect absorption chillers in large industrial facilities." },
  { id:"nate_647", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Free Cooling' en un sistema geotérmico de agua-agua?", opciones:["Aire acondicionado gratis", "Circular el agua del lazo de tierra directamente por un serpentín de aire sin encender el compresor", "Abrir las ventanas", "Usar hielo"], respuesta_correcta:1, explicacion:"Si la tierra está a 50°F y solo necesitas enfriar un poco, el agua fresca del suelo es suficiente sin gastar energía en comprimir." , question: "What is Free Cooling in a water-to-water geothermal system?", options: ["Free air conditioning", "Circulating water from the ground loop directly through an air coil without turning on the compressor", "Opening the windows", "Using ice"], explanation: "If the ground is at 50°F and only light cooling is needed, the cool water from the ground is sufficient without spending energy on compression." },
  { id:"nate_648", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cada cuánto se debe cambiar el agua de un lazo geotérmico cerrado?", opciones:["Cada año", "Nunca, si el sistema es hermético y el inhibidor de corrosión es el adecuado", "Cada vez que llueve", "Cada mes"], respuesta_correcta:1, explicacion:"Es un sistema sellado para toda la vida. Solo se monitorea la presión y el pH." , question: "How often should the water in a closed geothermal loop be changed?", options: ["Every year", "Never, as long as the system is hermetically sealed and the corrosion inhibitor is appropriate", "Every time it rains", "Every month"], explanation: "It is a sealed system designed to last a lifetime. Only the pressure and pH are monitored." },
  { id:"nate_649", categoria:"NATE_INDUSTRIAL", pregunta:"En un análisis de ciclo de vida (LCCA), ¿cuál es el tiempo de recuperación de inversión (Payback) típico de un sistema geotérmico frente a uno de aire?", opciones:["1 mes", "5 a 10 años (dependiendo de incentivos fiscales y costo de energía)", "50 años", "Nunca se recupera"], respuesta_correcta:1, explicacion:"Aunque es más caro al principio, el ahorro masivo mensual y la larga duración del lazo (50+ años) lo hacen muy rentable." , question: "In a Life Cycle Cost Analysis (LCCA), what is the typical payback period for a geothermal system versus an air-source system?", options: ["1 month", "5 to 10 years (depending on tax incentives and energy costs)", "50 years", "It never pays back"], explanation: "Although more expensive upfront, the massive monthly savings and long loop lifespan (50+ years) make it very profitable." },
  { id:"nate_650", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa la clasificación ISO 5 en un cuarto limpio?", opciones:["Que el cuarto tiene 5 puertas", "No más de 3,520 partículas de 0.5 micras por metro cúbico de aire", "Que el aire cambia cada 5 minutos", "Que la temperatura es de 5°C"], respuesta_correcta:1, explicacion:"ISO 5 (equivalente a Clase 100) es un nivel de pureza altísimo usado en la fabricación de microchips y llenado de viales farmacéuticos." , question: "What does ISO 5 classification mean in a cleanroom?", options: ["The room has 5 doors", "No more than 3,520 particles of 0.5 microns per cubic meter of air", "The air changes every 5 minutes", "The temperature is 5°C"], explanation: "ISO 5 (equivalent to Class 100) is an extremely high purity level used in microchip manufacturing and pharmaceutical vial filling." },
  { id:"nate_651", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la eficiencia mínima de un filtro HEPA (High Efficiency Particulate Air)?", opciones:["80%", "95%", "99.97% para partículas de 0.3 micras", "100% para todo"], respuesta_correcta:2, explicacion:"Se usa 0.3 micras como referencia porque es el tamaño de partícula más difícil de atrapar (MPPS)." , question: "What is the minimum efficiency of a HEPA (High Efficiency Particulate Air) filter?", options: ["80%", "95%", "99.97% for particles of 0.3 microns", "100% for everything"], explanation: "0.3 microns is used as the reference because it is the Most Penetrating Particle Size (MPPS)." },
  { id:"nate_652", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un cuarto de aislamiento para enfermedades infecciosas (como tuberculosis) debe tener 'Presión Negativa'?", opciones:["Para que el aire de afuera entre al cuarto y evite que los patógenos escapen al pasillo", "Para que el paciente respire mejor", "Para ahorrar energía", "Para que no entre polvo"], respuesta_correcta:0, explicacion:"Al mantener el cuarto a menor presión que el pasillo, el aire siempre fluye 'hacia adentro', conteniendo los virus en el sistema de extracción filtrado." , question: "Why must an isolation room for infectious diseases (such as tuberculosis) maintain Negative Pressure?", options: ["So that outside air enters the room and prevents pathogens from escaping into the hallway", "So the patient can breathe better", "To save energy", "To prevent dust from entering"], explanation: "By maintaining the room at lower pressure than the hallway, air always flows inward, containing the viruses in the filtered exhaust system." },
  { id:"nate_653", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué caracteriza al 'Flujo de Aire Laminar' en un quirófano?", opciones:["Que el aire gira en círculos", "Aire que se mueve en líneas paralelas a una velocidad uniforme, barriendo las partículas fuera de la zona quirúrgica", "Aire muy frío", "Aire que sale por el piso"], respuesta_correcta:1, explicacion:"Evita la turbulencia que podría levantar bacterias del suelo hacia la herida abierta del paciente." , question: "What characterizes Laminar Airflow in an operating room?", options: ["The air spins in circles", "Air moving in parallel lines at a uniform velocity, sweeping particles away from the surgical zone", "Very cold air", "Air coming out through the floor"], explanation: "It prevents the turbulence that could carry bacteria from the floor toward the patient's open wound." },
  { id:"nate_654", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la diferencia entre un filtro HEPA y un filtro ULPA?", opciones:["Solo el tamaño", "El ULPA tiene una eficiencia superior (99.999%) para partículas aún más pequeñas (0.12 micras)", "El HEPA es lavable", "El ULPA es para agua"], respuesta_correcta:1, explicacion:"ULPA significa 'Ultra-Low Penetration Air'. Se usa en nanotecnología avanzada." , question: "What is the difference between a HEPA filter and a ULPA filter?", options: ["Only the size", "ULPA has a higher efficiency (99.999%) for even smaller particles (0.12 microns)", "HEPA is washable", "ULPA is for water"], explanation: "ULPA stands for Ultra-Low Penetration Air. It is used in advanced nanotechnology." },
  { id:"nate_655", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el rango típico de cambios de aire por hora (ACH) para un quirófano estándar según ASHRAE 170?", opciones:["2 a 4 ACH", "20 a 30 ACH", "100 ACH", "No hay norma"], respuesta_correcta:1, explicacion:"Se requiere un volumen masivo de aire filtrado para mantener la esterilidad del ambiente médico." , question: "What is the typical range of air changes per hour (ACH) for a standard operating room per ASHRAE 170?", options: ["2 to 4 ACH", "20 to 30 ACH", "100 ACH", "There is no standard"], explanation: "A massive volume of filtered air is required to maintain the sterility of the medical environment." },
  { id:"nate_656", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué instrumento se usa para determinar exactamente cuándo cambiar un filtro HEPA en un cuarto limpio?", opciones:["Un calendario", "Un manómetro diferencial (midiendo la caída de presión en pulgadas de agua)", "Viendo si está gris", "Oliendo el aire"], respuesta_correcta:1, explicacion:"Cuando el filtro se satura, la resistencia al paso del aire sube. Al llegar a la presión estática de diseño final, debe reemplazarse." , question: "What instrument is used to determine exactly when to replace a HEPA filter in a cleanroom?", options: ["A calendar", "A differential pressure manometer (measuring the pressure drop in inches of water column)", "Looking to see if it is gray", "Smelling the air"], explanation: "When the filter becomes loaded, resistance to airflow increases. When it reaches the final design static pressure, it must be replaced." },
  { id:"nate_657", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función de las lámparas UV-C instaladas dentro de las manejadoras de aire (AHU)?", opciones:["Iluminar para el mantenimiento", "Esterilizar el serpentín y el aire destruyendo el ADN de virus, bacterias y moho", "Calentar el aire", "Hacer que el refrigerante brille"], respuesta_correcta:1, explicacion:"La radiación ultravioleta de onda corta es un germicida potente que mantiene el sistema libre de biopelículas." , question: "What is the function of UV-C lamps installed inside Air Handling Units (AHUs)?", options: ["To provide maintenance lighting", "To sterilize the coil and the air by destroying the DNA of viruses, bacteria, and mold", "To heat the air", "To make the refrigerant glow"], explanation: "Short-wave ultraviolet radiation is a potent germicide that keeps the system free of biofilm." },
  { id:"nate_658", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es una 'Antecámara' o 'Gowning Room'?", opciones:["Un cuarto de cámaras", "Una zona de transición con presión controlada donde el personal se pone el traje especial antes de entrar al cuarto limpio", "Donde se guarda el gas", "Una sala de espera"], respuesta_correcta:1, explicacion:"Actúa como una 'esclusa' de aire para evitar la contaminación cruzada." , question: "What is an Anteroom or Gowning Room?", options: ["A camera room", "A transition zone with controlled pressure where personnel put on special garments before entering the cleanroom", "Where gas is stored", "A waiting room"], explanation: "It acts as an air lock to prevent cross-contamination." },
  { id:"nate_659", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los cuartos limpios de electrónica mantienen una humedad relativa estricta del 45-50%?", opciones:["Para que los empleados no suden", "Para evitar descargas electrostáticas (si es muy seco) y corrosión/crecimiento biológico (si es muy húmedo)", "Para que el pegamento pegue", "No es necesario controlarla"], respuesta_correcta:1, explicacion:"El control de humedad es crítico para proteger los componentes sensibles a la estática." , question: "Why do electronics cleanrooms maintain a strict relative humidity of 45-50%?", options: ["So employees do not sweat", "To prevent electrostatic discharge (if too dry) and corrosion/biological growth (if too humid)", "So adhesive sticks properly", "Humidity control is not necessary"], explanation: "Humidity control is critical to protect components sensitive to static electricity." },
  { id:"nate_660", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se usa el sistema 'Bag-in Bag-out' (BIBO) al cambiar filtros?", opciones:["Para ahorrar bolsas de basura", "Para cambiar filtros contaminados con agentes biológicos o radiactivos sin exponer al técnico ni al ambiente", "Para que el filtro no se raye", "Es una marca de filtros"], respuesta_correcta:1, explicacion:"El técnico nunca toca el filtro directamente; todo el proceso ocurre dentro de una bolsa de plástico sellada." , question: "What is the Bag-in Bag-out (BIBO) system used for when changing filters?", options: ["To save trash bags", "To change filters contaminated with biological or radioactive agents without exposing the technician or the environment", "To prevent the filter from getting scratched", "It is a filter brand"], explanation: "The technician never touches the filter directly; the entire process occurs inside a sealed plastic bag." },
  { id:"nate_661", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prohíbe el uso de aislamiento térmico INTERNO (fibra de vidrio) en ductos para hospitales?", opciones:["Porque pica", "Porque las fibras pueden desprenderse o atrapar humedad y bacterias, contaminando el aire estéril", "Porque es muy caro", "Porque el metal se ve mejor"], respuesta_correcta:1, explicacion:"Los ductos deben ser de metal liso (acero inoxidable o galvanizado) y el aislamiento debe ir siempre por fuera." , question: "Why is internal thermal insulation (fiberglass) prohibited in hospital ductwork?", options: ["Because it is itchy", "Because fibers can break loose or trap moisture and bacteria, contaminating the sterile air", "Because it is too expensive", "Because bare metal looks better"], explanation: "Ducts must be smooth metal (stainless steel or galvanized) and insulation must always be on the outside." },
  { id:"nate_662", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'DOP Test' (o PAO Test) en un cuarto limpio?", opciones:["Una prueba de dopaje al técnico", "Una prueba de integridad del filtro HEPA usando aerosol para detectar fugas en el sello o en el papel del filtro", "Medir la presión del aceite", "Revisar el gas"], respuesta_correcta:1, explicacion:"Garantiza que el filtro fue instalado correctamente y que no tiene perforaciones microscópicas." , question: "What is a DOP Test (or PAO Test) in a cleanroom?", options: ["A drug test for the technician", "A HEPA filter integrity test using aerosol to detect leaks in the seal or filter media", "Measuring oil pressure", "Checking the gas"], explanation: "It ensures the filter was installed correctly and has no microscopic perforations." },
  { id:"nate_663", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es una FFU (Fan Filter Unit)?", opciones:["Un ventilador de techo normal", "Un módulo que combina un ventilador motorizado y un filtro HEPA, permitiendo crear techos de flujo limpio modulares", "Un sensor de temperatura", "Una rejilla de retorno"], respuesta_correcta:1, explicacion:"Son la base de los cuartos limpios modernos; se instalan cientos de ellas en el plafón para mover aire limpio." , question: "What is an FFU (Fan Filter Unit)?", options: ["A regular ceiling fan", "A module that combines a motorized fan and a HEPA filter, allowing the creation of modular clean-air ceilings", "A temperature sensor", "A return air grille"], explanation: "They are the foundation of modern cleanrooms; hundreds are installed in the ceiling to deliver clean air." },
  { id:"nate_664", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el riesgo de que la humedad en un quirófano caiga por debajo del 20%?", opciones:["Que el cirujano tenga sed", "Aumento drástico del riesgo de chispas por electricidad estática en presencia de gases anestésicos inflamables", "Que el aire pese menos", "Que las luces fallen"], respuesta_correcta:1, explicacion:"Aunque ya no se usan anestésicos tan explosivos como el éter, la estática sigue siendo un riesgo de seguridad mayor." , question: "What is the risk if operating room humidity drops below 20%?", options: ["The surgeon gets thirsty", "Drastic increase in the risk of sparks from static electricity in the presence of flammable anesthetic gases", "The air weighs less", "The lights fail"], explanation: "Although highly explosive anesthetics like ether are no longer commonly used, static remains a major safety risk." },
  { id:"nate_665", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué sirve el manómetro Magnehelic instalado en la pared de un cuarto limpio?", opciones:["Para ver la hora", "Para monitorear en tiempo real la presión diferencial entre el cuarto limpio y las áreas adyacentes", "Para medir el voltaje", "Para ajustar el termostato"], respuesta_correcta:1, explicacion:"Si la aguja se sale del rango verde, el cuarto ha perdido su integridad y la producción debe detenerse." , question: "What is the purpose of the Magnehelic gauge installed on the wall of a cleanroom?", options: ["To tell the time", "To monitor the differential pressure between the cleanroom and adjacent areas in real time", "To measure voltage", "To adjust the thermostat"], explanation: "If the needle goes outside the green range, the room has lost its integrity and production must stop." },
  { id:"nate_666", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la función de una Campana de Bioseguridad Clase II?", opciones:["Cocinar muestras", "Proteger al usuario, al producto y al ambiente mediante cortinas de aire y filtración HEPA", "Guardar reactivos", "Enfriar químicos"], respuesta_correcta:1, explicacion:"Es el lugar de trabajo seguro para manipular virus o bacterias peligrosas." , question: "What is the function of a Class II Biosafety Cabinet?", options: ["To cook samples", "To protect the user, the product, and the environment through air curtains and HEPA filtration", "To store reagents", "To cool chemicals"], explanation: "It is the safe workspace for handling dangerous viruses or bacteria." },
  { id:"nate_667", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los laboratorios químicos usan sistemas de Volumen de Aire Variable (VAV) vinculados a las campanas de extracción?", opciones:["Para ahorrar energía", "Para mantener la velocidad de cara en la campana constante mientras se abre o cierra la ventana de guillotina", "Para que no haga ruido", "Para filtrar el aire"], respuesta_correcta:1, explicacion:"Si abres la ventana, el sistema debe inyectar más aire para evitar que los vapores químicos se salgan hacia la cara del técnico." , question: "Why do chemical laboratories use Variable Air Volume (VAV) systems linked to fume hoods?", options: ["To save energy", "To maintain a constant face velocity at the hood while the sash is opened or closed", "To reduce noise", "To filter the air"], explanation: "If the sash is opened, the system must supply more air to prevent chemical vapors from escaping toward the technician's face." },
  { id:"nate_668", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se pueden usar ruedas entálpicas (ERVs) estándar en sistemas de extracción de laboratorios peligrosos?", opciones:["Porque son muy grandes", "Por el riesgo de contaminación cruzada (fuga de aire de extracción hacia el aire de inyección)", "Porque el plástico se derrite", "Porque no ahorran energía"], respuesta_correcta:1, explicacion:"Se deben usar 'Run-around loops' (lazos de glicol) que garantizan una separación física total entre ambos flujos de aire." , question: "Why can standard enthalpy wheels (ERVs) not be used in exhaust systems of hazardous laboratories?", options: ["Because they are too large", "Due to the risk of cross-contamination (exhaust air leaking into the supply air)", "Because the plastic melts", "Because they do not save energy"], explanation: "Run-around loops (glycol coils) must be used instead to guarantee complete physical separation between both airstreams." },
  { id:"nate_669", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la fuente número uno de generación de partículas dentro de un cuarto limpio en operación?", opciones:["Las máquinas", "Las personas (piel, cabello, respiración, ropa)", "El aire acondicionado", "Las luces"], respuesta_correcta:1, explicacion:"Un humano sentado genera 100,000 partículas por minuto. Por eso se usan trajes de 'conejito' (bunny suits)." , question: "What is the number one source of particle generation inside an operating cleanroom?", options: ["The machines", "People (skin, hair, breathing, clothing)", "The air conditioning", "The lights"], explanation: "A seated person generates 100,000 particles per minute. That is why bunny suits are worn." },
  { id:"nate_670", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué se instalan filtros MERV 8 o MERV 11 antes de un filtro HEPA?", opciones:["Para limpiar el aire doble", "Para proteger el filtro HEPA (que es muy caro) atrapando las partículas grandes primero", "Para que el sistema no haga ruido", "No son necesarios"], respuesta_correcta:1, explicacion:"El pre-filtro cuesta $20, el HEPA cuesta $500. Es lógica económica de mantenimiento." , question: "Why are MERV 8 or MERV 11 pre-filters installed upstream of a HEPA filter?", options: ["To double-clean the air", "To protect the HEPA filter (which is very expensive) by trapping large particles first", "To prevent the system from making noise", "They are not necessary"], explanation: "The pre-filter costs $20, the HEPA costs $500. It is simple maintenance economics." },
  { id:"nate_671", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es una unidad CRAC?", opciones:["Un aire de ventana", "Computer Room Air Conditioner (Unidad diseñada para alta densidad de calor sensible y control de humedad en centros de datos)", "Un sensor de humo", "Un servidor"], respuesta_correcta:1, explicacion:"A diferencia del confort humano, estas unidades trabajan 24/7 moviendo volúmenes masivos de aire." , question: "What is a CRAC unit?", options: ["A window air conditioner", "Computer Room Air Conditioner (a unit designed for high sensible heat density and humidity control in data centers)", "A smoke sensor", "A server"], explanation: "Unlike human comfort units, these units operate 24/7 moving massive volumes of air." },
  { id:"nate_672", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo funciona un contador de partículas láser (Laser Particle Counter)?", opciones:["Viendo las partículas con una lupa", "Midiendo la dispersión de luz (scattering) cuando una partícula cruza un rayo láser", "Pesando el aire", "Por magnetismo"], respuesta_correcta:1, explicacion:"Es el único instrumento capaz de contar millones de partículas invisibles al ojo humano en tiempo real." , question: "How does a Laser Particle Counter work?", options: ["By looking at particles with a magnifying glass", "By measuring the light scattering when a particle crosses a laser beam", "By weighing the air", "By magnetism"], explanation: "It is the only instrument capable of counting millions of invisible particles in real time." },
  { id:"nate_673", categoria:"NATE_INDUSTRIAL", pregunta:"¿Para qué sirve un piso ESD (Electrostatic Discharge) en un cuarto limpio de electrónica?", opciones:["Para que no se raye", "Para drenar de forma segura la electricidad estática de las personas hacia tierra", "Para que brille", "Para aislar el frío"], respuesta_correcta:1, explicacion:"Trabaja en conjunto con el calzado especial de los técnicos." , question: "What is the purpose of an ESD (Electrostatic Discharge) floor in an electronics cleanroom?", options: ["To prevent scratches", "To safely drain static electricity from people to ground", "To make it shiny", "To insulate against cold"], explanation: "It works in conjunction with the special footwear worn by technicians." },
  { id:"nate_674", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa PQ en la validación de un sistema HVAC para medicinas?", opciones:["Precio de Quincena", "Performance Qualification (Prueba de que el sistema cumple su función bajo carga real de producción)", "Presión Químíca", "Punto de Quiebre"], respuesta_correcta:1, explicacion:"Es el paso final antes de que la FDA o la COFEPRIS permitan fabricar medicamentos en ese cuarto." , question: "What does PQ mean in the validation of an HVAC system for pharmaceutical manufacturing?", options: ["Payday Quotient", "Performance Qualification (proof that the system meets its function under actual production load)", "Chemical Pressure", "Breaking Point"], explanation: "It is the final step before the FDA or regulatory agencies allow drugs to be manufactured in that room." },
  { id:"nate_675", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la velocidad típica del aire a la cara de un filtro HEPA en un techo laminar?", opciones:["10 fpm", "90 fpm (+/- 20%)", "500 fpm", "2000 fpm"], respuesta_correcta:1, explicacion:"Es la velocidad estándar de diseño para mantener un flujo unidireccional sin causar turbulencias molestas o ruidosas." , question: "What is the typical air velocity at the face of a HEPA filter in a laminar ceiling?", options: ["10 fpm", "90 fpm (+/- 20%)", "500 fpm", "2000 fpm"], explanation: "It is the standard design velocity for maintaining unidirectional flow without causing bothersome turbulence or noise." },
  { id:"nate_676", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se monitorea el CO2 en las salas de espera de un hospital?", opciones:["Para ver si hay fuego", "Como indicador de la calidad del aire y la tasa de ventilación (aire fresco)", "Para detectar fugas de gas", "Para medir el oxígeno"], respuesta_correcta:1, explicacion:"Si el CO2 sube de 800-1000 ppm, significa que no hay suficiente aire fresco entrando y aumenta el riesgo de contagio aéreo." , question: "Why is CO2 monitored in hospital waiting rooms?", options: ["To check for fire", "As an indicator of air quality and ventilation rate (fresh air)", "To detect gas leaks", "To measure oxygen"], explanation: "If CO2 rises above 800-1000 ppm, it means insufficient fresh air is entering and the risk of airborne infection increases." },
  { id:"nate_677", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué tipo de humidificador se prefiere en un hospital para evitar el crecimiento bacteriano?", opciones:["Humidificador de panel evaporativo", "Generador de vapor por electrodos o resistencia (Steam Humidifier)", "Atomizador de agua fría", "Un balde con agua"], respuesta_correcta:1, explicacion:"El vapor es estéril porque el agua hirvió; no hay riesgo de dispersar legionella o moho como en los sistemas de agua fría." , question: "What type of humidifier is preferred in a hospital to prevent bacterial growth?", options: ["Evaporative pad humidifier", "Electrode or resistance steam generator (Steam Humidifier)", "Cold water atomizer", "A bucket of water"], explanation: "Steam is sterile because the water has been boiled; there is no risk of dispersing Legionella or mold as with cold water systems." },
  { id:"nate_678", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el objetivo de la configuración de 'Pasillo Frío / Pasillo Caliente'?", opciones:["Separar a los empleados", "Evitar que el aire caliente de escape de los servidores se mezcle con el aire frío de inyección, mejorando la eficiencia", "Que el cuarto se vea ordenado", "Reducir el ruido"], respuesta_correcta:1, explicacion:"Maximiza el Delta T y permite que el aire acondicionado trabaje en su punto más eficiente." , question: "What is the objective of the Hot Aisle / Cold Aisle configuration?", options: ["To separate employees", "To prevent hot exhaust air from the servers from mixing with the cold supply air, improving efficiency", "To make the room look organized", "To reduce noise"], explanation: "It maximizes the Delta T and allows the air conditioning to operate at its most efficient point." },
  { id:"nate_679", categoria:"NATE_INDUSTRIAL", pregunta:"Ves que el conteo de partículas sube repentinamente en un cuarto limpio ISO 7. El filtro HEPA es nuevo. ¿Qué revisas?", opciones:["Si el compresor tiene aceite", "El sello de la junta (gasket) o el marco del filtro HEPA (fuga de bypass)", "Si las luces están prendidas", "El termostato"], respuesta_correcta:1, explicacion:"Un filtro HEPA puede estar perfecto, pero si el aire 'se salta' el filtro por un sello mal apretado, el cuarto se contaminará." , question: "You see the particle count suddenly rise in an ISO 7 cleanroom. The HEPA filter is new. What do you check?", options: ["Whether the compressor has oil", "The gasket seal or the HEPA filter frame (bypass leak)", "Whether the lights are on", "The thermostat"], explanation: "A HEPA filter can be perfect, but if air bypasses the filter through a poorly tightened seal, the room will become contaminated." },
  { id:"nate_680", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un sistema SCADA en un entorno industrial farmacéutico?", opciones:["Una marca de gas", "Supervisory Control and Data Acquisition (Sistema central que monitorea y registra todas las variables críticas de HVAC para cumplimiento legal)", "Un tipo de motor", "Un sensor de movimiento"], respuesta_correcta:1, explicacion:"Es el 'gran hermano' que guarda pruebas de que el aire siempre estuvo a la temperatura y presión correcta." , question: "What is a SCADA system in a pharmaceutical industrial environment?", options: ["A gas brand", "Supervisory Control and Data Acquisition (a central system that monitors and records all critical HVAC variables for legal compliance)", "A type of motor", "A motion sensor"], explanation: "It is the big brother that keeps proof that the air was always at the correct temperature and pressure." },
  { id:"nate_681", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el sistema 'Scavenging' en un quirófano?", opciones:["Limpiar el suelo", "Extracción dedicada para los gases anestésicos exhalados por el paciente para que no los respire el personal médico", "Sacar la basura", "Filtrar la sangre"], respuesta_correcta:1, explicacion:"Es un sistema de ventilación de seguridad independiente del HVAC general." , question: "What is the Scavenging system in an operating room?", options: ["Cleaning the floor", "Dedicated extraction for anesthetic gases exhaled by the patient so medical staff do not breathe them", "Taking out the trash", "Filtering blood"], explanation: "It is a safety ventilation system independent of the general HVAC." },
  { id:"nate_682", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo atrapa un filtro HEPA partículas MUCHO más pequeñas que los huecos de sus fibras?", opciones:["Por magnetismo", "Por Movimiento Browniano (difusión), interceptación e impacto inercial", "Porque las partículas se pegan solas", "Porque el filtro es de esponja"], respuesta_correcta:1, explicacion:"Las partículas ultra-pequeñas rebotan erráticamente y chocan con las fibras, quedando atrapadas por fuerzas moleculares (Van der Waals)." , question: "How does a HEPA filter trap particles MUCH smaller than the gaps between its fibers?", options: ["By magnetism", "Through Brownian Motion (diffusion), interception, and inertial impaction", "Because the particles stick by themselves", "Because the filter is made of sponge"], explanation: "Ultra-small particles bounce erratically and collide with fibers, becoming trapped by molecular forces (Van der Waals)." },
  { id:"nate_683", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Ionizador de Aire'?", opciones:["Un filtro de aire", "Un dispositivo que neutraliza las cargas electrostáticas en el aire inyectando iones positivos y negativos", "Un purificador de agua", "Un ventilador"], respuesta_correcta:1, explicacion:"Se usa para proteger las obleas de silicio que atraen polvo por estática como si fueran imanes." , question: "What is an Air Ionizer?", options: ["An air filter", "A device that neutralizes electrostatic charges in the air by injecting positive and negative ions", "A water purifier", "A fan"], explanation: "It is used to protect silicon wafers that attract dust through static electricity like magnets." },
  { id:"nate_684", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué los ductos de extracción de la cocina de un hospital deben ser independientes y tener su propio sistema contra incendios?", opciones:["Para que el olor no llegue a los pacientes", "Para evitar que un fuego en la cocina se propague por todo el hospital a través del sistema HVAC", "Porque son más sucios", "No es necesario"], respuesta_correcta:1, explicacion:"La grasa acumulada es combustible puro; el ducto debe ser hermético y resistente al fuego." , question: "Why must hospital kitchen exhaust ducts be independent and have their own fire suppression system?", options: ["To keep the smell from reaching patients", "To prevent a kitchen fire from spreading throughout the hospital via the HVAC system", "Because they are dirtier", "It is not necessary"], explanation: "Accumulated grease is pure fuel; the duct must be airtight and fire-rated." },
  { id:"nate_685", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo ayuda el sistema HVAC a mitigar el gas Radón en edificios?", opciones:["Lo filtra con HEPA", "Mediante ventilación de dilución y mantenimiento de una ligera presión positiva en los niveles bajos para evitar la infiltración del gas desde el suelo", "Lo quema", "No se puede mitigar"], respuesta_correcta:1, explicacion:"El Radón es un gas radiactivo natural que emana del suelo; la presión positiva impide su entrada." , question: "How does the HVAC system help mitigate Radon gas in buildings?", options: ["It filters it with HEPA", "Through dilution ventilation and maintaining a slight positive pressure at lower levels to prevent gas infiltration from the soil", "It burns it", "It cannot be mitigated"], explanation: "Radon is a naturally occurring radioactive gas that emanates from the soil; positive pressure prevents its entry." },
  { id:"nate_686", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cada cuánto se deben calibrar los sensores de presión de un laboratorio farmacéutico?", opciones:["Nunca", "Anualmente (o según el SOP de la empresa) por un laboratorio acreditado", "Cada vez que se ensucian", "Cuando fallan"], respuesta_correcta:1, explicacion:"La trazabilidad de la calibración es obligatoria para auditorías legales." , question: "How often should pressure sensors in a pharmaceutical laboratory be calibrated?", options: ["Never", "Annually (or per the company SOP) by an accredited laboratory", "Every time they get dirty", "When they fail"], explanation: "Calibration traceability is mandatory for legal audits." },
  { id:"nate_687", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Filtro HEPA con Sello de Gel'?", opciones:["Un filtro que usa gelatina", "Un filtro donde el marco se sumerge en un canal lleno de silicona fluida (gel) para garantizar un sello 100% libre de fugas", "Un filtro que enfría", "Un filtro para líquidos"], respuesta_correcta:1, explicacion:"Es superior a los sellos de hule (gaskets) porque el gel no se deforma ni se agrieta con el tiempo." , question: "What is a Gel-Seal HEPA Filter?", options: ["A filter that uses gelatin", "A filter where the frame is submerged in a channel filled with fluid silicone (gel) to guarantee a 100% leak-free seal", "A filter that cools", "A filter for liquids"], explanation: "It is superior to rubber gaskets because the gel does not deform or crack over time." },
  { id:"nate_688", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa PUE (Power Usage Effectiveness) en un centro de datos?", opciones:["Precio por Unidad Eléctrica", "Relación entre la energía total consumida y la energía usada solo por los equipos IT (mide la eficiencia del HVAC)", "Potencia Útil de Enfriamiento", "Punto de Uso Eléctrico"], respuesta_correcta:1, explicacion:"Un PUE de 1.0 sería perfecto (toda la luz va a los servidores). Un PUE de 2.0 significa que gastas tanta luz enfriando como procesando datos." , question: "What does PUE (Power Usage Effectiveness) mean in a data center?", options: ["Price Per Electrical Unit", "The ratio between total energy consumed and the energy used solely by IT equipment (measures HVAC efficiency)", "Useful Cooling Power", "Point of Electrical Use"], explanation: "A PUE of 1.0 would be perfect (all power goes to the servers). A PUE of 2.0 means you spend as much power on cooling as on processing data." },
  { id:"nate_689", categoria:"NATE_INDUSTRIAL", pregunta:"Escuchas un silbido constante en el pasillo de un hospital cerca de un cuarto limpio. ¿Qué es?", opciones:["El compresor", "Aire escapando a alta velocidad por un sello de puerta dañado debido a la alta presión diferencial", "Un pájaro en el ducto", "El gas del equipo"], respuesta_correcta:1, explicacion:"Las presiones de 0.05\" o 0.1\" iwc generan silbidos fuertes si hay fugas en los marcos de las puertas." , question: "You hear a constant whistling in a hospital hallway near a cleanroom. What is it?", options: ["The compressor", "Air escaping at high velocity through a damaged door seal due to high differential pressure", "A bird in the duct", "Gas from the equipment"], explanation: "Pressures of 0.05 or 0.1 inches of water column generate loud whistling if there are leaks in the door frames." },
  { id:"nate_690", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Clean-up Time' (Tiempo de Recuperación)?", opciones:["El tiempo que tarda el técnico en limpiar", "El tiempo que tarda el sistema HVAC en volver a la clasificación ISO tras un evento de contaminación masiva", "El tiempo de garantía", "El tiempo de vacío"], respuesta_correcta:1, explicacion:"Mide la capacidad del sistema para 'barrer' contaminantes rápidamente." , question: "What is Clean-up Time (Recovery Time)?", options: ["The time it takes the technician to clean up", "The time it takes the HVAC system to return to its ISO classification after a mass contamination event", "The warranty period", "The vacuum time"], explanation: "It measures the system's ability to quickly sweep out contaminants." },
  { id:"nate_691", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el enfriamiento 'In-Row'?", opciones:["Aire acondicionado de ventana", "Unidades de enfriamiento colocadas directamente entre los racks de servidores para enfriar en la fuente de calor", "Enfriar el techo", "Enfriar con agua bendita"], respuesta_correcta:1, explicacion:"Es mucho más eficiente que tratar de enfriar todo el cuarto desde una esquina." , question: "What is In-Row Cooling?", options: ["A window air conditioner", "Cooling units placed directly between server racks to cool at the heat source", "Ceiling cooling", "Cooling with holy water"], explanation: "It is much more efficient than trying to cool the entire room from a corner." },
  { id:"nate_692", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se usa un anemómetro de 'hilo caliente' en lugar de uno de aspas para medir en la cara de un filtro HEPA?", opciones:["Porque es más bonito", "Porque es mucho más sensible a las bajas velocidades de aire (90 fpm) requeridas en laboratorios", "Porque calienta el aire", "Porque no usa baterías"], respuesta_correcta:1, explicacion:"Las aspas mecánicas tienen demasiada fricción para medir velocidades tan bajas con precisión." , question: "Why is a hot-wire anemometer used instead of a vane anemometer for measuring at the face of a HEPA filter?", options: ["Because it looks nicer", "Because it is much more sensitive to the low air velocities (90 fpm) required in laboratories", "Because it heats the air", "Because it does not use batteries"], explanation: "Mechanical vanes have too much friction to measure such low velocities accurately." },
  { id:"nate_693", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué caracteriza a un sistema de 'Doble Ducto' en un hospital antiguo?", opciones:["Tiene dos ductos de gas", "Un ducto lleva aire frío y otro aire caliente; se mezclan en la habitación para obtener la temperatura deseada", "Es un ducto dentro de otro", "Es un sistema para agua"], respuesta_correcta:1, explicacion:"Eran sistemas muy precisos pero extremadamente ineficientes en consumo de energía." , question: "What characterizes a Dual-Duct system in an older hospital?", options: ["It has two gas ducts", "One duct carries cold air and the other carries hot air; they are mixed at the room to achieve the desired temperature", "It is a duct inside another duct", "It is a water system"], explanation: "These were very precise systems but extremely wasteful in energy consumption." },
  { id:"nate_694", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué las lámparas de un cuarto limpio se instalan con carcasas aerodinámicas (teardrop)?", opciones:["Por estética", "Para minimizar la turbulencia en el flujo de aire laminar que baja del techo", "Para que no pesen", "Para que alumbren más"], respuesta_correcta:1, explicacion:"Cualquier obstáculo cuadrado crearía 'remolinos' de aire sucio debajo de la lámpara." , question: "Why are cleanroom light fixtures installed with aerodynamic (teardrop) housings?", options: ["For aesthetics", "To minimize turbulence in the laminar airflow descending from the ceiling", "To reduce weight", "To increase brightness"], explanation: "Any square obstruction would create dirty air eddies beneath the light fixture." },
  { id:"nate_695", categoria:"NATE_INDUSTRIAL", pregunta:"¿En qué área de un hospital es crítico el control de vapores de formaldehído?", opciones:["En la cafetería", "En Patología y Morgue (usado para preservar tejidos)", "En el estacionamiento", "En pediatría"], respuesta_correcta:1, explicacion:"Es un químico cancerígeno que requiere extracción directa al exterior con filtración de carbón activado." , question: "In what area of a hospital is formaldehyde vapor control critical?", options: ["In the cafeteria", "In Pathology and the Morgue (used to preserve tissue)", "In the parking garage", "In pediatrics"], explanation: "It is a carcinogenic chemical that requires direct exhaust to the outdoors with activated carbon filtration." },
  { id:"nate_696", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué el sensor de presión de un ducto debe estar a 2/3 de la longitud del ducto principal?", opciones:["Porque ahí llega el cable", "Para representar la presión promedio que garantiza que la caja VAV más lejana reciba suficiente aire", "Porque es el punto más fuerte", "Por norma de incendios"], respuesta_correcta:1, explicacion:"Es el 'punto de balance' ideal para el control de velocidad del ventilador (VFD)." , question: "Why should the duct static pressure sensor be located at two-thirds of the main duct length?", options: ["Because that is where the cable reaches", "To represent the average pressure that ensures the farthest VAV box receives sufficient air", "Because it is the strongest point", "Per fire code"], explanation: "It is the ideal balance point for fan speed control via a VFD (Variable Frequency Drive)." },
  { id:"nate_697", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué las plantas de fabricación de pastillas efervescentes usan deshumidificadores de desecante sólido?", opciones:["Porque son más baratos", "Porque pueden alcanzar humedades relativas bajísimas (menores al 10%) que un sistema de enfriamiento normal no puede", "Porque no usan compresor", "Porque limpian el aire"], respuesta_correcta:1, explicacion:"Si hay humedad, las pastillas efervescentes reaccionarían y explotarían dentro del empaque." , question: "Why do effervescent tablet manufacturing plants use solid desiccant dehumidifiers?", options: ["Because they are cheaper", "Because they can achieve extremely low relative humidity levels (below 10%) that a standard cooling system cannot", "Because they do not use a compressor", "Because they clean the air"], explanation: "If moisture is present, the effervescent tablets would react and burst inside the packaging." },
  { id:"nate_698", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras polvo dentro de una manejadora de aire DESPUÉS de los filtros HEPA. ¿Por qué?", opciones:["El filtro falló", "Fuga en los paneles de la AHU o en las juntas de acceso (el aire sucio es succionado por la presión negativa)", "El ventilador está sucio", "Es normal"], respuesta_correcta:1, explicacion:"La integridad del gabinete de la manejadora es tan importante como el filtro mismo." , question: "You find dust inside an air handling unit DOWNSTREAM of the HEPA filters. Why?", options: ["The filter failed", "Leaks in the AHU panels or access door gaskets (dirty air is being drawn in by negative pressure)", "The fan is dirty", "This is normal"], explanation: "The integrity of the air handler cabinet is just as important as the filter itself." },
  { id:"nate_699", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de bioseguridad nivel 4 (BSL-4), ¿qué sucede con el aire de extracción antes de salir al ambiente?", opciones:["Se suelta directamente", "Pasa por dos etapas de filtros HEPA en serie y un sistema de esterilización térmica", "Se mezcla con aire fresco", "Se guarda en tanques"], respuesta_correcta:1, explicacion:"Es el nivel máximo de seguridad biológica (Ebola, etc.). El aire debe estar 100% libre de vida patógena antes de salir." , question: "In a Biosafety Level 4 (BSL-4) facility, what happens to exhaust air before it is released to the environment?", options: ["It is released directly", "It passes through two stages of HEPA filters in series and a thermal sterilization system", "It is mixed with fresh air", "It is stored in tanks"], explanation: "It is the highest level of biological safety (Ebola, etc.). The air must be 100% free of pathogenic life before release." },
  { id:"nate_700", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Life Cycle Cost Analysis' (LCCA) que un técnico pro debe presentar a un cliente comercial?", opciones:["El precio de la instalación", "El costo total de un equipo sumando compra, instalación, mantenimiento y consumo de energía durante toda su vida útil", "La garantía del fabricante", "El costo de la grúa"], respuesta_correcta:1, explicacion:"A veces lo más barato hoy es lo más caro en 10 años. El LCCA ayuda al cliente a ver que la eficiencia energética es una inversión, no un gasto." , question: "What is a Life Cycle Cost Analysis (LCCA) that a professional technician should present to a commercial client?", options: ["The purchase price", "The total cost of equipment including purchase, installation, maintenance, and energy consumption over its entire useful life", "The manufacturer warranty", "The crane rental cost"], explanation: "Sometimes the cheapest option today is the most expensive over 10 years. LCCA helps the client see that energy efficiency is an investment, not an expense." },
  { id:"nate_701", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el objetivo principal de la Enmienda de Kigali al Protocolo de Montreal?", opciones:["Prohibir el R-22", "Reducir gradualmente el consumo y producción de HFCs (como el R-410A) debido a su alto potencial de calentamiento global", "Fijar el precio del gas", "Eliminar los compresores de pistón"], respuesta_correcta:1, explicacion:"Esta enmienda es la razón por la cual la industria está migrando del R-410A hacia el R-32 y R-454B." , question: "What is the main goal of the Kigali Amendment to the Montreal Protocol?", options: ["To ban R-22", "To gradually reduce the consumption and production of HFCs (such as R-410A) due to their high global warming potential", "To set gas prices", "To eliminate reciprocating compressors"], explanation: "This amendment is the reason the industry is migrating from R-410A to R-32 and R-454B." },
  { id:"nate_702", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un 'Arc Flash' y cuándo es más probable que ocurra?", opciones:["Una foto con flash", "Una liberación violenta de energía a través del aire por un cortocircuito, común al trabajar en tableros eléctricos vivos sin el equipo de protección adecuado", "Una falla del compresor", "Un tipo de soldadura"], respuesta_correcta:1, explicacion:"Puede alcanzar temperaturas superiores a la superficie del sol, causando quemaduras fatales y explosiones." , question: "What is an Arc Flash and when is it most likely to occur?", options: ["A photo with flash", "A violent release of energy through the air caused by a short circuit, common when working on live electrical panels without proper protective equipment", "A compressor failure", "A type of welding"], explanation: "It can reach temperatures higher than the surface of the sun, causing fatal burns and explosions." },
  { id:"nate_703", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras que el aire de suministro está a 55°F con 95% de humedad, pero el cliente se queja de que el cuarto está a 75°F y 70% de humedad. ¿Cuál es el problema?", opciones:["El equipo es muy chico", "Infiltración masiva de aire exterior húmedo o falta de sellado en los ductos en el ático", "Falta de gas", "El serpentín está sucio"], respuesta_correcta:1, explicacion:"Si el aire sale frío y seco del equipo pero llega húmedo al cuarto, está absorbiendo humedad del camino (ductos rotos) o de la estructura." , question: "You measure the supply air at 55°F with 95% humidity, but the client complains the room is at 75°F and 70% humidity. What is the problem?", options: ["The equipment is undersized", "Massive outdoor air infiltration or duct leaks in the attic", "Low refrigerant charge", "The coil is dirty"], explanation: "If the air leaves the equipment cold and dry but arrives humid at the room, it is picking up moisture along the way (broken ducts) or from the building envelope." },
  { id:"nate_704", categoria:"NATE_INDUSTRIAL", pregunta:"Encuentras que un condensador no arranca por un cable flojo, pero el cliente ya está convencido de que necesita un compresor nuevo. ¿Cuál es la acción ética correcta?", opciones:["Venderle el compresor, el cliente siempre tiene la razón", "Apretar el cable, cobrar el servicio justo y explicarle la verdad al cliente", "Apretar el cable y cobrar como si hubieras cambiado el compresor", "Decirle que no tiene arreglo"], respuesta_correcta:1, explicacion:"La integridad construye una reputación a largo plazo y una empresa sólida. Engañar al cliente destruye la marca ACVOLT." , question: "You find that a condenser will not start due to a loose wire, but the client is already convinced they need a new compressor. What is the ethical action?", options: ["Sell them the compressor; the customer is always right", "Tighten the wire, charge a fair service fee, and tell the client the truth", "Tighten the wire and charge as if you replaced the compressor", "Tell them it cannot be fixed"], explanation: "Integrity builds a long-term reputation and a solid business. Deceiving the client destroys the brand." },
  { id:"nate_705", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Mantenimiento Predictivo'?", opciones:["Limpiar cuando se ve sucio", "Usar datos (vibración, termografía, análisis de aceite) para predecir cuándo fallará una pieza antes de que suceda", "Arreglar lo que se rompe", "Cambiar filtros cada mes"], respuesta_correcta:1, explicacion:"A diferencia del preventivo (que es por tiempo), el predictivo ahorra dinero al no cambiar piezas que aún sirven pero detectando las que van a fallar." , question: "What is Predictive Maintenance?", options: ["Cleaning when it looks dirty", "Using data (vibration, thermography, oil analysis) to predict when a part will fail before it happens", "Fixing what breaks", "Changing filters every month"], explanation: "Unlike preventive maintenance (which is time-based), predictive maintenance saves money by not replacing parts that still work while detecting those about to fail." },
  { id:"nate_706", categoria:"NATE_INDUSTRIAL", pregunta:"¿Quién es la única persona autorizada para retirar un candado y etiqueta de seguridad (LOTO) de un interruptor?", opciones:["El dueño del edificio", "El técnico que lo colocó", "Cualquier compañero de trabajo", "El supervisor"], respuesta_correcta:1, explicacion:"Es una regla de vida o muerte para asegurar que nadie encienda la energía mientras el técnico sigue trabajando en el equipo." , question: "Who is the only person authorized to remove a Lockout/Tagout (LOTO) lock and tag from a disconnect?", options: ["The building owner", "The technician who placed it", "Any coworker", "The supervisor"], explanation: "This is a life-or-death rule to ensure no one energizes the equipment while the technician is still working on it." },
  { id:"nate_707", categoria:"NATE_INDUSTRIAL", pregunta:"En un auditorio con 500 personas, ¿qué tipo de carga domina el diseño del HVAC?", opciones:["Carga de las paredes", "Carga latente y sensible generada por el metabolismo de las personas", "Carga de las luces", "Infiltración por las puertas"], respuesta_correcta:1, explicacion:"Las personas son 'estufas húmedas'. En espacios concurridos, la carga humana supera cualquier otra ganancia de calor." , question: "In an auditorium with 500 people, what type of load dominates the HVAC design?", options: ["Envelope load from the walls", "Latent and sensible heat generated by the occupants' metabolism", "Lighting load", "Infiltration through the doors"], explanation: "People are essentially moist heaters. In crowded spaces, the occupant load exceeds any other heat gain." },
  { id:"nate_708", categoria:"NATE_INDUSTRIAL", pregunta:"Mides el refractómetro y encuentras una concentración de glicol del 60% en un Chiller. ¿Qué efecto tiene esto?", opciones:["Protege mejor", "Reduce la capacidad de transferencia de calor y aumenta el esfuerzo de las bombas (el fluido es demasiado espeso)", "Limpia el sistema", "No afecta"], respuesta_correcta:1, explicacion:"Mucho glicol es tan malo como poco. Debe mantenerse en el nivel de diseño (típicamente 25-35%)." , question: "You measure the refractometer and find a glycol concentration of 60% in a chiller. What effect does this have?", options: ["It provides better protection", "It reduces heat transfer capacity and increases pump effort (the fluid is too thick)", "It cleans the system", "It has no effect"], explanation: "Too much glycol is just as bad as too little. It must be maintained at the design level (typically 25-35%)." },
  { id:"nate_709", categoria:"NATE_INDUSTRIAL", pregunta:"¿De qué trata la norma ASHRAE 15?", opciones:["De la eficiencia de los ductos", "Estándar de seguridad para sistemas de refrigeración (clasificación de salas de máquinas y ventilación de emergencia)", "Del ahorro de agua", "De la ética del técnico"], respuesta_correcta:1, explicacion:"Dicta cómo deben diseñarse las salas de máquinas para que, si hay una fuga masiva, nadie muera." , question: "What does ASHRAE Standard 15 cover?", options: ["Duct efficiency", "Safety Standard for Refrigeration Systems (classification of machinery rooms and emergency ventilation)", "Water conservation", "Technician ethics"], explanation: "It dictates how machinery rooms must be designed so that in the event of a major leak, no one dies." },
  { id:"nate_710", categoria:"NATE_INDUSTRIAL", pregunta:"Un sistema Inverter causa interferencia en el sistema de sonido del cliente. ¿Qué le falta a la instalación?", opciones:["Gas", "Aterrizaje correcto y posiblemente un filtro EMI/EMC en la línea de potencia", "Un compresor nuevo", "Cambiar el estéreo"], respuesta_correcta:1, explicacion:"La conmutación de alta frecuencia genera ondas de radio que deben drenarse a tierra para no interferir con otros aparatos." , question: "An inverter system causes interference in the client's sound system. What is missing from the installation?", options: ["Gas", "Proper grounding and possibly an EMI/EMC filter on the power line", "A new compressor", "A different stereo"], explanation: "The high-frequency switching generates radio waves that must be drained to ground to prevent interference with other equipment." },
  { id:"nate_711", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cómo calculas el 'Simple Payback' de un equipo de alta eficiencia para un cliente?", opciones:["Viendo el precio en internet", "(Diferencia de costo entre equipos) / (Ahorro anual estimado en el recibo de luz)", "Dividiendo el precio entre 12 meses", "No se puede calcular"], respuesta_correcta:1, explicacion:"Le dice al cliente en cuántos años su ahorro en electricidad habrá pagado la diferencia de precio del equipo caro." , question: "How do you calculate the Simple Payback of a high-efficiency unit for a client?", options: ["By looking at the price online", "(Cost difference between units) / (Estimated annual savings on the electricity bill)", "By dividing the price by 12 months", "It cannot be calculated"], explanation: "It tells the client in how many years their electricity savings will have paid for the price difference of the more expensive unit." },
  { id:"nate_712", categoria:"NATE_INDUSTRIAL", pregunta:"Vas a trabajar en un sistema con R-290 (Propano). ¿Qué precaución de seguridad es la más crítica?", opciones:["Usar guantes de látex", "Asegurar ventilación constante y usar herramientas 'non-sparking' (que no generen chispas)", "Llevar un extintor de agua", "Cargar el gas muy rápido"], respuesta_correcta:1, explicacion:"El R-290 es altamente inflamable. Una chispa de un contactor o de una herramienta eléctrica puede causar una explosión." , question: "You are about to work on a system using R-290 (Propane). What is the most critical safety precaution?", options: ["Wear latex gloves", "Ensure constant ventilation and use non-sparking tools", "Carry a water fire extinguisher", "Charge the gas very quickly"], explanation: "R-290 is highly flammable. A spark from a contactor or an electric tool can cause an explosion." },
  { id:"nate_713", categoria:"NATE_INDUSTRIAL", pregunta:"Un Chiller centrífugo entra en 'Surge' (bombeo) al operar a baja carga en un día fresco. ¿Qué ajuste mecánico puede mitigar esto?", opciones:["Cerrar la válvula de expansión", "Ajustar las paletas de entrada (Inlet Guide Vanes) o usar un Hot Gas Bypass", "Subir la velocidad de las bombas", "Agregar más aceite"], respuesta_correcta:1, explicacion:"El sistema necesita mantener una masa mínima de gas fluyendo por el impulsor para evitar la inestabilidad." , question: "A centrifugal chiller enters Surge (pumping) when operating at low load on a cool day. What mechanical adjustment can mitigate this?", options: ["Close the expansion valve", "Adjust the Inlet Guide Vanes or use a Hot Gas Bypass", "Increase pump speed", "Add more oil"], explanation: "The system needs to maintain a minimum mass of gas flowing through the impeller to avoid instability." },
  { id:"nate_714", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se debe apoyar una tubería de refrigerante directamente sobre un soporte de acero sin aislamiento?", opciones:["Por estética", "Corrosión galvánica y transferencia de vibración/ruido a la estructura", "Porque se calienta", "Porque se ve chueco"], respuesta_correcta:1, explicacion:"El contacto entre metales diferentes causa corrosión. Debe usarse un aislante (clamp/cushion) entre el tubo y el soporte." , question: "Why should refrigerant piping not rest directly on a steel support without insulation?", options: ["For aesthetics", "Galvanic corrosion and vibration/noise transfer to the structure", "Because it heats up", "Because it looks crooked"], explanation: "Contact between dissimilar metals causes corrosion. An isolating clamp or cushion must be used between the pipe and the support." },
  { id:"nate_715", categoria:"NATE_INDUSTRIAL", pregunta:"Haces una prueba de ácido al aceite y sale positiva (roja). El compresor aún funciona. ¿Qué haces?", opciones:["Cambiar el compresor", "Instalar filtros de succión y de líquido para remover ácidos y cambiar el aceite", "Agregar más refrigerante", "Ignorarlo"], respuesta_correcta:1, explicacion:"Estás a tiempo de salvar el sistema antes de que el ácido destruya el barniz de los bobinados del motor." , question: "You perform an acid test on the oil and it comes back positive (red). The compressor still runs. What do you do?", options: ["Replace the compressor", "Install suction line and liquid line filter driers to remove acids and change the oil", "Add more refrigerant", "Ignore it"], explanation: "You have time to save the system before the acid destroys the motor winding varnish." },
  { id:"nate_716", categoria:"NATE_INDUSTRIAL", pregunta:"Notas que un técnico junior está recuperando refrigerante a la atmósfera 'porque no hay nadie viendo'. ¿Qué haces?", opciones:["Lo ignoras", "Detenerlo inmediatamente, explicarle el daño ambiental y la responsabilidad legal, y reportarlo si es reincidente", "Ayudarlo para acabar rápido", "Decirle que la próxima vez use una bolsa"], respuesta_correcta:1, explicacion:"El profesionalismo de ACVOLT depende de la ética colectiva. El daño al medio ambiente es irreversible y las multas son masivas." , question: "You notice a junior technician venting refrigerant to the atmosphere because no one is watching. What do you do?", options: ["Ignore it", "Stop them immediately, explain the environmental damage and legal liability, and report them if they are a repeat offender", "Help them finish faster", "Tell them to use a bag next time"], explanation: "Professionalism depends on collective ethics. Environmental damage is irreversible and the fines are massive." },
  { id:"nate_717", categoria:"NATE_INDUSTRIAL", pregunta:"En un sistema de agua helada, el Delta T es de 15°F (diseño era 10°F). El Chiller está trabajando al 100%. ¿Qué indica?", opciones:["Flujo de agua insuficiente (la bomba está moviendo menos agua de la necesaria)", "Mucho gas en el Chiller", "Filtros de aire sucios", "El agua está muy fría"], respuesta_correcta:0, explicacion:"Si el agua pasa más lento, tiene más tiempo de enfriarse, aumentando el Delta T pero reduciendo la capacidad total entregada." , question: "In a chilled water system, the Delta T is 15°F (design was 10°F). The chiller is running at 100%. What does this indicate?", options: ["Insufficient water flow (the pump is moving less water than required)", "Too much gas in the chiller", "Dirty air filters", "The water is too cold"], explanation: "If the water passes more slowly, it has more time to cool down, increasing the Delta T but reducing the total delivered capacity." },
  { id:"nate_718", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la mayor ventaja de un manómetro digital sobre uno analógico al cargar por Subcooling?", opciones:["Que tiene luz", "Calcula el Subcooling en tiempo real eliminando el error de lectura manual y tablas", "Es más resistente a los golpes", "No usa mangueras"], respuesta_correcta:1, explicacion:"La precisión digital asegura que el equipo quede exactamente con la carga que pide el fabricante." , question: "What is the greatest advantage of a digital manifold over an analog manifold when charging by subcooling?", options: ["It has a light", "It calculates subcooling in real time, eliminating manual reading errors and the need for PT charts", "It is more impact-resistant", "It does not use hoses"], explanation: "Digital precision ensures the equipment is charged to exactly what the manufacturer specifies." },
  { id:"nate_719", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es el 'Peak Demand' (Demanda Pico) y cómo lo controla un sistema BMS?", opciones:["La montaña más alta", "Es el consumo eléctrico más alto en un periodo de 15 min; el BMS apaga equipos no críticos para evitar multas de la compañía eléctrica", "Cuando todos los técnicos trabajan", "La presión más alta del día"], respuesta_correcta:1, explicacion:"Ahorra miles de dólares al evitar que todos los compresores arranquen exactamente al mismo tiempo." , question: "What is Peak Demand and how does a BMS control it?", options: ["The tallest mountain", "It is the highest electrical consumption in a 15-minute period; the BMS shuts off non-critical equipment to avoid utility demand charges", "When all technicians are working", "The highest pressure of the day"], explanation: "It saves thousands of dollars by preventing all compressors from starting at exactly the same time." },
  { id:"nate_720", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se está usando tubería de aluminio/polietileno (PEX-AL-PEX) en sistemas de calefacción hidrónica?", opciones:["Porque es transparente", "Combina la flexibilidad del plástico con la barrera de oxígeno del metal, evitando la corrosión del sistema", "Porque se puede soldar con estaño", "Es más pesada"], respuesta_correcta:1, explicacion:"Evita que el oxígeno entre al agua y oxide la caldera o las bombas de hierro." , question: "Why is aluminum/polyethylene composite piping (PEX-AL-PEX) being used in hydronic heating systems?", options: ["Because it is transparent", "It combines the flexibility of plastic with the oxygen barrier of metal, preventing system corrosion", "Because it can be soldered with tin", "It is heavier"], explanation: "It prevents oxygen from entering the water and corroding the boiler or iron circulation pumps." },
  { id:"nate_721", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el primer paso antes de entrar a un ático o sótano sin ventilación donde hubo una fuga masiva de refrigerante?", opciones:["Entrar rápido para acabar pronto", "Monitorear el nivel de oxígeno y ventilar mecánicamente el espacio", "Usar una linterna fuerte", "Ponerse una máscara de polvo"], respuesta_correcta:1, explicacion:"El refrigerante es más pesado que el aire y desplaza el oxígeno. Puedes morir asfixiado en segundos." , question: "What is the first step before entering an unventilated attic or basement where a massive refrigerant leak has occurred?", options: ["Enter quickly to finish fast", "Monitor the oxygen level and mechanically ventilate the space", "Use a strong flashlight", "Put on a dust mask"], explanation: "Refrigerant is heavier than air and displaces oxygen. You can suffocate in seconds." },
  { id:"nate_722", categoria:"NATE_INDUSTRIAL", pregunta:"Mides 320V DC en el bus de la tarjeta, pero al arrancar el compresor, el voltaje cae a 200V y da error. ¿Qué componente falló?", opciones:["El microprocesador", "Capacitores electrolíticos de filtrado (perdieron su capacidad de almacenamiento de energía)", "El ventilador", "El termostato"], respuesta_correcta:1, explicacion:"El capacitor debe mantener el voltaje durante el pico de arranque. Si está 'seco', el voltaje se desploma bajo carga." , question: "You measure 320V DC on the board bus, but when the compressor starts, the voltage drops to 200V and throws an error. What component has failed?", options: ["The microprocessor", "Electrolytic filter capacitors (they have lost their energy storage capacity)", "The fan", "The thermostat"], explanation: "The capacitor must maintain voltage during the startup peak. If it is dried out, the voltage collapses under load." },
  { id:"nate_723", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué significa que un plano sea 'As-Built'?", opciones:["Un dibujo de cómo se quería hacer", "Un plano que refleja exactamente cómo quedó instalado el equipo (con todos los cambios hechos en campo)", "Un plano de la competencia", "Un plano en 3D"], respuesta_correcta:1, explicacion:"Es vital para el mantenimiento futuro. Si un ducto se movió 2 metros, el As-Built debe mostrarlo." , question: "What does it mean for a drawing to be As-Built?", options: ["A drawing of how it was intended to be done", "A drawing that reflects exactly how the equipment was actually installed (with all field changes)", "A competitor's drawing", "A 3D drawing"], explanation: "It is vital for future maintenance. If a duct was moved 6 feet, the As-Built must show it." },
  { id:"nate_724", categoria:"NATE_INDUSTRIAL", pregunta:"Si un equipo tiene un COP de 3.5, ¿cuál es su eficiencia en porcentaje aproximado?", opciones:["35%", "350% (entrega 3.5 veces más energía de la que consume)", "100%", "5%"], respuesta_correcta:1, explicacion:"Esto es lo que hace a las bombas de calor superiores a cualquier resistencia eléctrica (que solo llega al 100%)." , question: "If a unit has a COP of 3.5, what is its approximate efficiency in percentage?", options: ["35%", "350% (it delivers 3.5 times more energy than it consumes)", "100%", "5%"], explanation: "This is what makes heat pumps superior to any electric resistance heater (which can only reach 100%)." },
  { id:"nate_725", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la regla de los '3 puntos de apoyo' al subir a un techo?", opciones:["Tener 3 escaleras", "Mantener siempre dos manos y un pie, o dos pies y una mano en contacto con la escalera", "Subir con 3 compañeros", "Apoyar la escalera en 3 lugares"], respuesta_correcta:1, explicacion:"Es la forma más segura de prevenir caídas accidentales." , question: "What is the Three Points of Contact rule when climbing to a roof?", options: ["Have 3 ladders", "Always keep two hands and one foot, or two feet and one hand, in contact with the ladder", "Climb with 3 coworkers", "Lean the ladder in 3 places"], explanation: "It is the safest way to prevent accidental falls." },
  { id:"nate_726", categoria:"NATE_INDUSTRIAL", pregunta:"Escuchas un sonido de 'silbido' o 'llanto' constante en la TXV. La mirilla está llena de burbujas. ¿Qué haces?", opciones:["Cambiar la TXV", "Agregar refrigerante (es ruido de flash gas por falta de carga)", "Cerrar la válvula", "Aceitar la válvula"], respuesta_correcta:1, explicacion:"El gas pasando por el orificio de la válvula genera ese silbido característico." , question: "You hear a constant whistling or crying sound at the TXV. The sight glass is full of bubbles. What do you do?", options: ["Replace the TXV", "Add refrigerant (it is flash gas noise due to low charge)", "Close the valve", "Lubricate the valve"], explanation: "Gas passing through the valve orifice generates that characteristic whistling sound." },
  { id:"nate_727", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué debes hacer con el aceite recuperado de un compresor quemado (burnout)?", opciones:["Tirarlo al drenaje", "Guardarlo en un contenedor sellado y entregarlo a un centro de manejo de residuos peligrosos", "Usarlo para lubricar bisagras", "Enterrarlo"], respuesta_correcta:1, explicacion:"Ese aceite contiene ácidos y metales pesados. Es altamente contaminante." , question: "What should you do with oil recovered from a burned-out compressor?", options: ["Pour it down the drain", "Store it in a sealed container and deliver it to a hazardous waste disposal facility", "Use it to lubricate hinges", "Bury it"], explanation: "That oil contains acids and heavy metals. It is highly contaminating." },
  { id:"nate_728", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un sensor de presión de aceite diferencial tiene un retardo de tiempo (típicamente 90 seg) antes de disparar?", opciones:["Para que el técnico no se asuste", "Para permitir que el compresor establezca la presión de aceite durante el arranque inicial", "Para ahorrar energía", "Porque es lento"], respuesta_correcta:1, explicacion:"Al arrancar, la presión es 0. El retardo evita que el equipo se apague antes de que la bomba de aceite alcance su presión operativa." , question: "Why does a differential oil pressure sensor have a time delay (typically 90 seconds) before tripping?", options: ["So the technician does not get alarmed", "To allow the compressor to establish oil pressure during initial startup", "To save energy", "Because it is slow"], explanation: "At startup, the pressure is zero. The delay prevents the unit from shutting down before the oil pump reaches its operating pressure." },
  { id:"nate_729", categoria:"NATE_INDUSTRIAL", pregunta:"¿Es posible tener un 'Superheat negativo'?", opciones:["Sí, cuando hace mucho frío", "No físicamente; indicaría que tienes líquido puro y el sensor o manómetro están mal calibrados", "Sí, en sistemas Inverter", "Sí, si hay exceso de aceite"], respuesta_correcta:1, explicacion:"El refrigerante no puede estar más frío que su temperatura de saturación a esa presión. Si el cálculo da negativo, tus herramientas están mintiendo." , question: "Is it possible to have a negative superheat?", options: ["Yes, when it is very cold", "Not physically; it would indicate that you have pure liquid and the sensor or gauge is miscalibrated", "Yes, in inverter systems", "Yes, if there is excess oil"], explanation: "Refrigerant cannot be colder than its saturation temperature at a given pressure. If the calculation yields a negative number, your instruments are lying." },
  { id:"nate_730", categoria:"NATE_INDUSTRIAL", pregunta:"¿En qué zona de EE.UU. es más efectivo un 'Swamp Cooler' (enfriador evaporativo)?", opciones:["Florida (Húmedo)", "Arizona (Seco)", "Nueva York (Frío)", "En todos lados igual"], respuesta_correcta:1, explicacion:"El enfriamiento evaporativo depende de la capacidad del aire para absorber agua. En climas secos, la temperatura puede bajar drásticamente." , question: "In which region of the United States is an evaporative cooler (Swamp Cooler) most effective?", options: ["Florida (Humid)", "Arizona (Dry)", "New York (Cold)", "Everywhere equally"], explanation: "Evaporative cooling depends on the air's ability to absorb water. In dry climates, the temperature can drop dramatically." },
  { id:"nate_731", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué no se debe usar el compresor del equipo para hacer vacío en el sistema?", opciones:["Porque es muy lento", "El compresor no está diseñado para funcionar en vacío; se puede quemar el bobinado por falta de enfriamiento y arco eléctrico", "Porque ensucia el aceite", "Porque no tiene fuerza"], respuesta_correcta:1, explicacion:"En vacío, el aire es tan ralo que no disipa calor y el voltaje puede saltar entre terminales (Efecto Corona)." , question: "Why should the system compressor never be used to pull a vacuum on the system?", options: ["Because it is too slow", "The compressor is not designed to operate under vacuum; the windings can burn due to lack of cooling and electric arcing", "Because it contaminates the oil", "Because it is not powerful enough"], explanation: "Under vacuum, the air is too thin to dissipate heat, and voltage can arc between terminals (Corona Effect)." },
  { id:"nate_732", categoria:"NATE_INDUSTRIAL", pregunta:"Un cliente quiere un equipo de 5 toneladas para un cuarto donde el Manual J dice que necesita 3 toneladas. ¿Qué le explicas?", opciones:["Que entre más grande mejor", "Que un equipo sobredimensionado causará humedad excesiva, ruidos y se dañará más rápido por arranques frecuentes", "Que le va a sobrar frío", "Que le cobras más caro"], respuesta_correcta:1, explicacion:"El 'short cycling' es el enemigo del confort y la durabilidad. Un técnico de ACVOLT vende soluciones, no solo fierros." , question: "A client wants a 5-ton unit for a room where Manual J calls for 3 tons. What do you explain?", options: ["Bigger is always better", "An oversized unit will cause excessive humidity, noise, and will wear out faster due to frequent short cycling", "They will have plenty of extra cooling", "You charge them more"], explanation: "Short cycling is the enemy of comfort and durability. A professional technician sells solutions, not just hardware." },
  { id:"nate_733", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué es un contactor de 'Bypass' en un variador de frecuencia (VFD)?", opciones:["Un repuesto", "Un circuito que permite arrancar el motor directamente desde la línea si el VFD falla", "Un sensor de velocidad", "Un cable extra"], respuesta_correcta:1, explicacion:"Garantiza que el edificio no se quede sin aire si la electrónica del variador se quema." , question: "What is a Bypass contactor in a Variable Frequency Drive (VFD)?", options: ["A spare part", "A circuit that allows starting the motor directly from the power line if the VFD fails", "A speed sensor", "An extra cable"], explanation: "It ensures the building does not lose air conditioning if the drive electronics burn out." },
  { id:"nate_734", categoria:"NATE_INDUSTRIAL", pregunta:"¿De qué trata la norma ASHRAE 90.1?", opciones:["De la calidad del aire", "Estándar de eficiencia energética mínima para edificios comerciales (excepto residenciales bajos)", "Del ruido de los equipos", "De la seguridad eléctrica"], respuesta_correcta:1, explicacion:"Es la biblia de la eficiencia en construcción comercial." , question: "What does ASHRAE Standard 90.1 cover?", options: ["Air quality", "Minimum energy efficiency standard for commercial buildings (excluding low-rise residential)", "Equipment noise", "Electrical safety"], explanation: "It is the bible of energy efficiency in commercial construction." },
  { id:"nate_735", categoria:"NATE_INDUSTRIAL", pregunta:"Ves que el aceite en el compresor desaparece cuando el equipo baja a mínima velocidad (Inverter) pero regresa al subir de velocidad. ¿Qué significa?", opciones:["Que falta aceite", "Velocidad de gas insuficiente para arrastrar el aceite en carga parcial; revisar diseño de tubería", "Que el aceite se evaporó", "Es normal en Inverters"], respuesta_correcta:1, explicacion:"Si el aceite no regresa, el compresor se quemará. Se requieren líneas más delgadas o trampas más eficientes." , question: "You see that the compressor oil disappears when the unit drops to minimum speed (Inverter) but returns when the speed increases. What does this mean?", options: ["There is not enough oil", "Insufficient gas velocity to carry oil back at part load; review the piping design", "The oil evaporated", "This is normal in inverter systems"], explanation: "If the oil does not return, the compressor will burn out. Smaller diameter lines or more effective oil traps are required." },
  { id:"nate_736", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede si mezclas Amoníaco (R-717) con Cloro (lejía)?", opciones:["Se limpia el sistema", "Se produce gas cloramina (altamente tóxico y explosivo)", "Se vuelve agua", "No pasa nada"], respuesta_correcta:1, explicacion:"Es una reacción química letal. Nunca deben estar en el mismo cuarto de servicio." , question: "What happens if you mix Ammonia (R-717) with Chlorine (bleach)?", options: ["It cleans the system", "It produces chloramine gas (highly toxic and explosive)", "It turns to water", "Nothing happens"], explanation: "It is a lethal chemical reaction. They must never be in the same service area." },
  { id:"nate_737", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la ventaja de un control SCR (Silicon Controlled Rectifier) en resistencias eléctricas?", opciones:["Que es más barato", "Proporciona un control de temperatura ultra-preciso y sin ruidos mecánicos al modular la potencia al 1%", "Que calienta más", "Que no usa cables"], respuesta_correcta:1, explicacion:"Es el estándar para deshumidificación de precisión en laboratorios." , question: "What is the advantage of an SCR (Silicon Controlled Rectifier) control for electric heaters?", options: ["It is cheaper", "It provides ultra-precise temperature control with no mechanical noise by modulating power down to 1%", "It heats more", "It does not use wires"], explanation: "It is the standard for precision dehumidification in laboratories." },
  { id:"nate_738", categoria:"NATE_INDUSTRIAL", pregunta:"Un condensador enfriado por aire tiene una presión de alta de 500 psig (R-410A) y el aire que sale del ventilador está FRÍO. ¿Qué pasa?", opciones:["El equipo es muy eficiente", "El serpentín está tan tapado de suciedad que el aire no está pasando a través de las aletas (no hay transferencia)", "Falta gas", "El compresor está fallando"], respuesta_correcta:1, explicacion:"Si el aire no sale caliente, es porque no pudo 'robarle' calor al refrigerante." , question: "An air-cooled condenser has a high-side pressure of 500 psig (R-410A) and the air exiting the fan is COLD. What is happening?", options: ["The equipment is very efficient", "The coil is so clogged with dirt that air is not passing through the fins (no heat transfer is occurring)", "Low refrigerant charge", "The compressor is failing"], explanation: "If the discharge air is not hot, it means it could not absorb heat from the refrigerant." },
  { id:"nate_739", categoria:"NATE_INDUSTRIAL", pregunta:"En un PM (Preventive Maintenance), ¿para qué se miden los Ohms de los calentadores de cárter?", opciones:["Para ver si están limpios", "Para asegurar que funcionarán en invierno y evitar que el compresor arranque inundado de líquido", "Para medir el voltaje", "Para que el cliente vea que trabajas"], respuesta_correcta:1, explicacion:"Un calentador quemado es la causa principal de fallas de compresor en el primer día de frío." , question: "During a PM (Preventive Maintenance), why do you measure the ohms of the crankcase heaters?", options: ["To see if they are clean", "To ensure they will work in winter and prevent the compressor from starting flooded with liquid", "To measure voltage", "To show the client you are working"], explanation: "A burned-out crankcase heater is the leading cause of compressor failure on the first cold day." },
  { id:"nate_740", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué un técnico maestro aún debe saber usar un psicrómetro de honda manual?", opciones:["Porque son más bonitos", "Como método de validación infalible si sospecha que sus sensores digitales están descalibrados", "Para hacer ejercicio", "Porque no usa pilas"], respuesta_correcta:1, explicacion:"La física de la evaporación no miente; los sensores electrónicos sí se descalibran." , question: "Why should a master technician still know how to use a sling psychrometer?", options: ["Because they look nice", "As a failsafe validation method if there is suspicion that digital sensors are out of calibration", "For exercise", "Because it does not use batteries"], explanation: "The physics of evaporation do not lie; electronic sensors can drift out of calibration." },
  { id:"nate_741", categoria:"NATE_INDUSTRIAL", pregunta:"Notas una vibración 'rítmica' (que sube y baja de intensidad cada 2 segundos) en un rack de 2 compresores iguales. ¿Cómo se llama?", opciones:["Vibración normal", "Efecto de pulsación o 'Beat Frequency' (frecuencias de vibración casi iguales que se interfieren)", "Compresor roto", "Falta de aceite"], respuesta_correcta:1, explicacion:"Ocurre cuando dos motores giran a velocidades casi idénticas. Se soluciona cambiando ligeramente la masa de uno o su soporte." , question: "You notice a rhythmic vibration (rising and falling in intensity every 2 seconds) on a rack with 2 identical compressors. What is it called?", options: ["Normal vibration", "Beat Frequency effect (nearly identical vibration frequencies interfering with each other)", "Broken compressor", "Low oil"], explanation: "It occurs when two motors spin at nearly identical speeds. It is solved by slightly changing the mass of one or its mounting." },
  { id:"nate_742", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es el nivel máximo de llenado seguro para un cilindro de recuperación de refrigerante?", opciones:["100%", "80% de su capacidad en peso", "50%", "Hasta que ya no entre más"], respuesta_correcta:1, explicacion:"Debe quedar un 20% de espacio para la expansión hidrostática del líquido si la temperatura sube. Un tanque al 100% puede explotar como una granada." , question: "What is the maximum safe fill level for a refrigerant recovery cylinder?", options: ["100%", "80% of its weight capacity", "50%", "Until nothing more fits"], explanation: "A 20% space must remain for hydrostatic liquid expansion if the temperature rises. A tank filled to 100% can explode like a grenade." },
  { id:"nate_743", categoria:"NATE_INDUSTRIAL", pregunta:"Usas un software de carga térmica pirateado para hacer un diseño oficial. ¿Qué riesgo corres?", opciones:["Ninguno, el resultado es el mismo", "Responsabilidad legal, falta de soporte técnico y posible error en los datos de actualización de equipos climáticos", "Que el software sea más rápido", "Que el cliente no te pague"], respuesta_correcta:1, explicacion:"Un profesional de ACVOLT usa herramientas legítimas para garantizar la precisión de su trabajo." , question: "You use pirated load calculation software to produce an official design. What risk do you run?", options: ["None, the result is the same", "Legal liability, lack of technical support, and potentially incorrect data from outdated equipment databases", "The software runs faster", "The client will not pay you"], explanation: "A professional technician uses legitimate tools to guarantee the accuracy of their work." },
  { id:"nate_744", categoria:"NATE_INDUSTRIAL", pregunta:"Aparece una mancha de humedad en el techo justo debajo de un ducto de suministro. ¿Qué le falta al ducto?", opciones:["Limpieza", "Aislamiento térmico o barrera de vapor (el aire del ático se condensa en el metal frío)", "Más aire", "Un soporte"], respuesta_correcta:1, explicacion:"Si el metal está por debajo del punto de rocío del ático, sudará y mojará el tablaroca." , question: "A moisture stain appears on the ceiling directly below a supply duct. What is the duct missing?", options: ["Cleaning", "Thermal insulation or vapor barrier (attic air is condensing on the cold metal)", "More airflow", "A support hanger"], explanation: "If the metal is below the dew point of the attic air, it will sweat and soak the drywall." },
  { id:"nate_745", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué es pecado soldar tubería de cobre sin circular nitrógeno a baja presión por dentro?", opciones:["Para que el tubo no se caliente", "Para evitar la formación de 'hojuelas de óxido negro' (hollín) que taparán la TXV y ensuciarán el aceite", "Porque el nitrógeno ayuda a que la soldadura pegue", "Por costumbre"], respuesta_correcta:1, explicacion:"El nitrógeno desplaza el oxígeno, impidiendo la oxidación interna del cobre al calentarse." , question: "Why is it considered a cardinal sin to braze copper pipe without flowing low-pressure nitrogen inside?", options: ["To keep the pipe from getting hot", "To prevent the formation of black oxide scale (soot) that will clog the TXV and contaminate the oil", "Because nitrogen helps the solder adhere", "Out of habit"], explanation: "Nitrogen displaces oxygen, preventing internal oxidation of the copper when heated." },
  { id:"nate_746", categoria:"NATE_INDUSTRIAL", pregunta:"Ves un borne (terminal) de un breaker mucho más caliente que los otros en la cámara térmica. ¿Qué significa?", opciones:["Que por ahí pasa más luz", "Conexión floja o resistencia alta (posible incendio inminente)", "Que el breaker es de buena calidad", "Es normal en verano"], respuesta_correcta:1, explicacion:"El calor es el primer síntoma de un mal contacto eléctrico." , question: "You see a breaker terminal significantly hotter than the others on a thermal imaging camera. What does this mean?", options: ["More current flows through it", "Loose connection or high resistance (potential imminent fire)", "The breaker is high quality", "It is normal in summer"], explanation: "Heat is the first symptom of a poor electrical connection." },
  { id:"nate_747", categoria:"NATE_INDUSTRIAL", pregunta:"¿Por qué se prohíbe el uso de humidificadores de ultrasonido en salas de servidores?", opciones:["Porque son ruidosos", "Porque dispersan los minerales del agua como un polvo blanco que se deposita dentro de los servidores", "Porque gastan mucha luz", "Porque no funcionan"], respuesta_correcta:1, explicacion:"Ese polvo es abrasivo y conductor, pudiendo causar cortocircuitos en las placas base de los servidores." , question: "Why are ultrasonic humidifiers prohibited in server rooms?", options: ["Because they are noisy", "Because they disperse water minerals as a white powder that deposits inside servers", "Because they use too much electricity", "Because they do not work"], explanation: "That powder is abrasive and conductive, potentially causing short circuits on server motherboards." },
  { id:"nate_748", categoria:"NATE_INDUSTRIAL", pregunta:"¿Qué sucede con el confort si el equipo tiene un SHF (Sensible Heat Factor) de 0.9 en un clima tropical?", opciones:["El cliente estará muy feliz", "El cuarto estará frío pero muy húmedo (el equipo no quita suficiente agua)", "El equipo se congelará", "No enfriará nada"], respuesta_correcta:1, explicacion:"Un SHF de 0.9 significa que el 90% de la potencia es para bajar temperatura y solo el 10% para quitar humedad. En el trópico necesitas al menos 0.7 o 0.75." , question: "What happens to comfort if the unit has an SHF (Sensible Heat Factor) of 0.9 in a tropical climate?", options: ["The client will be very happy", "The room will be cold but very humid (the unit is not removing enough moisture)", "The unit will freeze up", "It will not cool at all"], explanation: "An SHF of 0.9 means 90% of the capacity goes to lowering temperature and only 10% to removing moisture. In the tropics, you need at least 0.7 or 0.75." },
  { id:"nate_749", categoria:"NATE_INDUSTRIAL", pregunta:"¿Cuál es la responsabilidad final de un técnico egresado de ACVOLT Tech School?", opciones:["Solo arreglar el equipo", "Garantizar el confort humano y la seguridad de los procesos, protegiendo el medio ambiente y la inversión del cliente con ética y ciencia", "Cobrar lo más posible", "Instalar rápido"], respuesta_correcta:1, explicacion:"Es la definición de un Maestro en HVAC/R. Felicidades, has completado las 700 preguntas." , question: "What is the ultimate responsibility of a technician graduated from ACVOLT Tech School?", options: ["Only to fix equipment", "To ensure human comfort and process safety while protecting the environment and the client's investment with ethics and science", "To charge as much as possible", "To install quickly"], explanation: "That is the definition of an HVAC/R Master Technician. Congratulations, you have completed all 700 questions." },

]; // fin NATE_QUESTIONS

